实现大文件分片上传和断点续传是前端工程化中的经典高级场景。一个完整的、生产级别的方案需要**前端（Vue 3）** 与**后端（Node.js）** 的紧密配合。

下面我将为您提供一套**完整、可执行、开箱即用**的演示方案。包含前端 Vue 3 核心逻辑与后端 Node.js 测试服务器。

---

### 一、 核心原理简述
1. **文件分片 (Slice)**：利用 `File.prototype.slice()` 将大文件切割成多个固定大小的 Blob 对象（如 2MB/片）。
2. **唯一标识 (Hash)**：使用 `SparkMD5` 读取文件内容计算 Hash 值，作为文件的唯一身份证，用于断点续传时的校验。
3. **断点续传 (Verify)**：上传前发送 Hash 给后端，后端返回已上传的分片列表，前端过滤掉已上传的分片，实现“续传”。
4. **并发控制 (Concurrency)**：控制同时发送的 HTTP 请求数量，避免浏览器并发限制和服务器内存溢出。
5. **暂停/恢复 (AbortController)**：利用现代浏览器的 `AbortController` 中断进行中的 XHR/Fetch 请求。
6. **合并 (Merge)**：所有分片上传完成后，通知后端将临时分片按顺序合并为完整文件。

---

### 二、 环境准备

为了让您能够本地运行演示，请创建一个测试项目并安装依赖。

**1. 初始化项目并安装前端依赖**
```bash
npm create vite@latest vue-upload-demo -- --template vue
cd vue-upload-demo
npm install axios spark-md5
```

**2. 创建后端测试服务器并安装依赖**
在项目根目录新建 `server` 文件夹，并安装后端依赖：
```bash
mkdir server && cd server
npm init -y
npm install express multer fs-extra cors
```

---

### 三、 后端服务实现 (Node.js)

在 `server` 目录下创建 `index.js`。该脚本负责接收分片、校验断点、合并文件。

```javascript
// server/index.js
const express = require('express');
const multer = require('multer');
const path = require('path');
const fs = require('fs-extra');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

// 临时分片存储目录和最终文件存储目录
const TEMP_DIR = path.resolve(__dirname, 'temp');
const TARGET_DIR = path.resolve(__dirname, 'target');
fs.ensureDirSync(TEMP_DIR);
fs.ensureDirSync(TARGET_DIR);

const upload = multer({ dest: TEMP_DIR });

// 1. 验证断点续传（检查已上传的分片）
app.post('/verify', async (req, res) => {
  const { hash, filename } = req.body;
  const tempDir = path.join(TEMP_DIR, hash);
  const targetFilePath = path.join(TARGET_DIR, filename);

  // 如果最终文件已存在，直接返回秒传成功
  if (fs.existsSync(targetFilePath)) {
    return res.json({ code: 200, data: { uploaded: true, uploadedList: [] }, msg: '秒传成功' });
  }

  // 检查临时目录下的分片
  let uploadedList = [];
  if (fs.existsSync(tempDir)) {
    uploadedList = await fs.readdir(tempDir);
  }

  res.json({ code: 200, data: { uploaded: false, uploadedList }, msg: '获取已上传分片成功' });
});

// 2. 接收分片上传
app.post('/upload', upload.single('chunk'), async (req, res) => {
  const { hash, chunkIndex } = req.body;
  const { file } = req; // multer 解析出的文件

  const tempDir = path.join(TEMP_DIR, hash);
  await fs.ensureDir(tempDir);

  // 将分片移动到以 hash 命名的临时目录，并以 chunkIndex 命名
  const chunkPath = path.join(tempDir, chunkIndex);
  await fs.move(file.path, chunkPath, { overwrite: true });

  res.json({ code: 200, msg: '分片上传成功' });
});

// 3. 合并分片
app.post('/merge', async (req, res) => {
  const { hash, filename, size } = req.body;
  const tempDir = path.join(TEMP_DIR, hash);
  const targetFilePath = path.join(TARGET_DIR, filename);

  if (!fs.existsSync(tempDir)) {
    return res.status(400).json({ code: 400, msg: '分片不存在' });
  }

  // 读取分片并按索引排序
  const chunks = await fs.readdir(tempDir);
  chunks.sort((a, b) => Number(a) - Number(b));

  // 使用流 (Stream) 合并文件，防止大文件撑爆内存
  const writeStream = fs.createWriteStream(targetFilePath);

  for (const chunkName of chunks) {
    const chunkPath = path.join(tempDir, chunkName);
    const readStream = fs.createReadStream(chunkPath);
    await new Promise((resolve) => {
      readStream.pipe(writeStream, { end: false });
      readStream.on('end', resolve);
    });
  }

  writeStream.end();

  // 合并完成后清理临时目录
  await fs.remove(tempDir);

  res.json({ code: 200, msg: '文件合并成功' });
});

const PORT = 3000;
app.listen(PORT, () => {
  console.log(`Server is running on http://localhost:${PORT}`);
});
```
**启动后端**：在 `server` 目录下运行 `node index.js`。

---

### 四、 前端核心实现 (Vue 3)

使用 Vue 3 `<script setup>` 语法，包含 Hash 计算、并发控制、进度追踪和暂停/恢复功能。
替换 `src/App.vue` 的内容：

```vue
<template>
  <div class="upload-container">
    <h2>大文件分片上传 & 断点续传 (Vue 3)</h2>

    <div class="control-panel">
      <input type="file" @change="handleFileChange" :disabled="status === 'uploading' || status === 'calculating'" />
      <button @click="handleUpload" :disabled="!file || status === 'uploading' || status === 'calculating'">
        {{ status === 'paused' ? '继续上传' : '开始上传' }}
      </button>
      <button @click="handlePause" :disabled="status !== 'uploading'" class="btn-pause">暂停</button>
    </div>

    <div v-if="file" class="file-info">
      <p>文件名: {{ file.name }} ({{ formatSize(file.size) }})</p>
      <p>文件 Hash: {{ hash || '计算中...' }}</p>
      <p>状态: {{ statusText }}</p>
    </div>

    <div class="progress-bar-container" v-if="status !== 'idle'">
      <div class="progress-bar" :style="{ width: totalProgress + '%' }"></div>
      <span class="progress-text">{{ totalProgress }}%</span>
    </div>
  </div>
</template>

<script setup>
import { ref, computed } from 'vue';
import axios from 'axios';
import SparkMD5 from 'spark-md5';

// ================= 状态定义 =================
const file = ref(null);
const hash = ref('');
const status = ref('idle'); // idle, calculating, uploading, paused, success, error
const progressList = ref([]); // 每个分片的进度数组
const abortControllerList = ref([]); // 用于暂停请求的 AbortController 列表

const CHUNK_SIZE = 2 * 1024 * 1024; // 2MB
const MAX_CONCURRENT = 3; // 最大并发数
const BASE_URL = 'http://localhost:3000';

// ================= 计算属性 =================
const totalProgress = computed(() => {
  if (progressList.value.length === 0) return 0;
  const sum = progressList.value.reduce((acc, cur) => acc + cur, 0);
  return ((sum / progressList.value.length) * 100).toFixed(2);
});

const statusText = computed(() => {
  const map = {
    idle: '等待上传',
    calculating: '正在计算文件 Hash...',
    uploading: '上传中...',
    paused: '已暂停',
    success: '上传成功',
    error: '上传失败'
  };
  return map[status.value] || '未知';
});

// ================= 核心逻辑 =================

// 1. 文件选择
const handleFileChange = (e) => {
  const targetFile = e.target.files[0];
  if (!targetFile) return;
  file.value = targetFile;
  status.value = 'idle';
  hash.value = '';
  progressList.value = [];
};

// 2. 计算文件 Hash (增量计算，防止大文件撑爆内存)
const calculateHash = (file) => {
  return new Promise((resolve) => {
    const blobSlice = File.prototype.slice;
    const chunks = Math.ceil(file.size / CHUNK_SIZE);
    let currentChunk = 0;
    const spark = new SparkMD5.ArrayBuffer();
    const reader = new FileReader();

    reader.onload = (e) => {
      spark.append(e.target.result);
      currentChunk++;
      if (currentChunk < chunks) {
        loadNext();
      } else {
        resolve(spark.end());
      }
    };

    const loadNext = () => {
      const start = currentChunk * CHUNK_SIZE;
      const end = Math.min(start + CHUNK_SIZE, file.size);
      const chunk = blobSlice.call(file, start, end);
      reader.readAsArrayBuffer(chunk);
    };
    loadNext();
  });
};

// 3. 创建分片
const createChunks = (file) => {
  const chunks = [];
  let cur = 0;
  let index = 0;
  while (cur < file.size) {
    chunks.push({
      chunk: file.slice(cur, cur + CHUNK_SIZE),
      index: index++
    });
    cur += CHUNK_SIZE;
  }
  return chunks;
};

// 4. 验证断点续传
const verifyUpload = async (hash, filename) => {
  const { data } = await axios.post(`${BASE_URL}/verify`, { hash, filename });
  return data.data;
};

// 5. 并发控制调度器
const sendRequest = (requestList, limit = MAX_CONCURRENT) => {
  return new Promise((resolve, reject) => {
    let currentIndex = 0;
    let activeCount = 0;
    let isPaused = false;

    const next = () => {
      if (isPaused) return; // 暂停时停止调度
      if (currentIndex >= requestList.length) {
        if (activeCount === 0) resolve();
        return;
      }
      while (activeCount < limit && currentIndex < requestList.length) {
        const request = requestList[currentIndex++];
        activeCount++;
        request()
          .then(() => {
            activeCount--;
            next();
          })
          .catch((err) => {
            // 忽略主动取消的错误
            if (axios.isCancel(err)) {
              activeCount--;
              return; 
            }
            reject(err);
          });
      }
    };

    // 暴露暂停方法给外部
    sendRequest.pause = () => { isPaused = true; };
    next();
  });
};

// 6. 主上传流程
const handleUpload = async () => {
  if (!file.value) return;

  try {
    // 步骤 A: 计算 Hash
    if (!hash.value) {
      status.value = 'calculating';
      hash.value = await calculateHash(file.value);
    }

    status.value = 'uploading';
    abortControllerList.value = [];

    // 步骤 B: 验证断点续传
    const { uploaded, uploadedList } = await verifyUpload(hash.value, file.value.name);
    if (uploaded) {
      status.value = 'success';
      alert('秒传成功！');
      return;
    }

    // 步骤 C: 创建分片并过滤已上传的
    const chunks = createChunks(file.value);
    progressList.value = new Array(chunks.length).fill(0);

    const needUploadChunks = chunks.filter((_, index) => {
      // 如果后端返回了已上传的分片索引，则过滤掉
      return !uploadedList.includes(String(index));
    });

    // 步骤 D: 构建请求列表
    const requestList = needUploadChunks.map(({ chunk, index }) => {
      return () => {
        const formData = new FormData();
        formData.append('chunk', chunk);
        formData.append('hash', hash.value);
        formData.append('chunkIndex', String(index));

        const controller = new AbortController();
        abortControllerList.value.push(controller);

        return axios.post(`${BASE_URL}/upload`, formData, {
          signal: controller.signal,
          onUploadProgress: (progressEvent) => {
            if (progressEvent.total) {
              const percent = (progressEvent.loaded / progressEvent.total) * 100;
              // 更新对应分片的进度
              progressList.value[index] = percent;
            }
          }
        });
      };
    });

    // 步骤 E: 并发上传
    await sendRequest(requestList);

    // 步骤 F: 通知后端合并
    await axios.post(`${BASE_URL}/merge`, {
      hash: hash.value,
      filename: file.value.name,
      size: file.value.size
    });

    status.value = 'success';
    alert('上传并合并成功！');

  } catch (error) {
    if (axios.isCancel(error)) {
      console.log('上传已暂停');
    } else {
      console.error('上传失败', error);
      status.value = 'error';
    }
  }
};

// 7. 暂停上传
const handlePause = () => {
  status.value = 'paused';
  // 取消所有进行中的网络请求
  abortControllerList.value.forEach(controller => controller.abort());
  abortControllerList.value = [];
  // 停止并发调度器
  if (sendRequest.pause) sendRequest.pause();
};

// ================= 工具函数 =================
const formatSize = (bytes) => {
  if (bytes === 0) return '0 B';
  const k = 1024;
  const sizes = ['B', 'KB', 'MB', 'GB', 'TB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
};
</script>

<style scoped>
.upload-container {
  max-width: 600px;
  margin: 50px auto;
  font-family: sans-serif;
  padding: 20px;
  border: 1px solid #ddd;
  border-radius: 8px;
  box-shadow: 0 4px 6px rgba(0,0,0,0.05);
}
.control-panel {
  display: flex;
  gap: 10px;
  margin-bottom: 20px;
  align-items: center;
}
button {
  padding: 8px 16px;
  background-color: #409eff;
  color: white;
  border: none;
  border-radius: 4px;
  cursor: pointer;
}
button:disabled {
  background-color: #a0cfff;
  cursor: not-allowed;
}
.btn-pause {
  background-color: #e6a23c;
}
.file-info {
  font-size: 14px;
  color: #666;
  margin-bottom: 20px;
  line-height: 1.6;
}
.progress-bar-container {
  width: 100%;
  height: 20px;
  background-color: #f0f0f0;
  border-radius: 10px;
  overflow: hidden;
  position: relative;
}
.progress-bar {
  height: 100%;
  background-color: #67c23a;
  transition: width 0.3s ease;
}
.progress-text {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: 12px;
  color: #333;
  font-weight: bold;
}
</style>
```

