### 2. YUV to RGB Converter
Hikvision's PlayM4 decoder outputs raw **YV12** frames. We must convert this to an RGB `BufferedImage` for Swing.

```java
import java.awt.image.BufferedImage;
import java.awt.image.DataBufferByte;

public class YuvToRgbConverter {
    public static BufferedImage yv12ToRgb(byte[] yv12, int width, int height) {
        BufferedImage img = new BufferedImage(width, height, BufferedImage.TYPE_3BYTE_BGR);
        byte[] rgb = ((DataBufferByte) img.getRaster().getDataBuffer()).getData();

        int frameSize = width * height;
        int qFrameSize = frameSize / 4;

        for (int j = 0; j < height; j++) {
            for (int i = 0; i < width; i++) {
                int yIndex = j * width + i;
                int vIndex = frameSize + (j / 2) * (width / 2) + (i / 2); 
                int uIndex = frameSize + qFrameSize + (j / 2) * (width / 2) + (i / 2); 

                int Y = (yv12[yIndex] & 0xff) - 16;
                int V = (yv12[vIndex] & 0xff) - 128;
                int U = (yv12[uIndex] & 0xff) - 128;

                if (Y < 0) Y = 0;

                int R = (298 * Y + 409 * V + 128) >> 8;
                int G = (298 * Y - 100 * U - 208 * V + 128) >> 8;
                int B = (298 * Y + 516 * U + 128) >> 8;

                R = Math.max(0, Math.min(255, R));
                G = Math.max(0, Math.min(255, G));
                B = Math.max(0, Math.min(255, B));

                int rgbIndex = yIndex * 3;
                rgb[rgbIndex] = (byte) B;
                rgb[rgbIndex + 1] = (byte) G;
                rgb[rgbIndex + 2] = (byte) R;
            }
        }
        return img;
    }
}
```

### 3. Main Swing Application
This class handles the GUI, SDK initialization, and bridges the native callbacks to the Swing Event Dispatch Thread (EDT).

```java
import com.sun.jna.Pointer;
import com.sun.jna.ptr.IntByReference;
import javax.swing.*;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.nio.charset.StandardCharsets;

public class HikvisionLinuxPlayer {

    private static int userId = -1;
    private static int realPlayHandle = -1;
    private static int playPort = -1;
    private static VideoPanel videoPanel;

    public static void main(String[] args) {
        // 1. Initialize Swing GUI
        SwingUtilities.invokeLater(() -> {
            JFrame frame = new JFrame("Hikvision Linux Swing Player");
            frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
            frame.setSize(800, 600);

            videoPanel = new VideoPanel();
            frame.add(videoPanel, BorderLayout.CENTER);

            frame.setLocationRelativeTo(null);
            frame.setVisible(true);
        });

        // 2. Initialize SDK
        if (!HCNetSDK.INSTANCE.NET_DVR_Init()) {
            System.err.println("Failed to initialize HCNetSDK");
            return;
        }

        // Set SDK search path and log path (Optional but recommended)
        // HCNetSDK.INSTANCE.NET_DVR_SetSDKInitCfg(...); 

        // 3. Login to Camera
        HCNetSDK.NET_DVR_USER_LOGIN_INFO loginInfo = new HCNetSDK.NET_DVR_USER_LOGIN_INFO();
        System.arraycopy("192.168.1.64".getBytes(StandardCharsets.UTF_8), 0, loginInfo.sDeviceAddress, 0, "192.168.1.64".length());
        loginInfo.wPort = 8000;
        System.arraycopy("admin".getBytes(StandardCharsets.UTF_8), 0, loginInfo.sUserName, 0, "admin".length());
        System.arraycopy("password123".getBytes(StandardCharsets.UTF_8), 0, loginInfo.sPassword, 0, "password123".length());
        loginInfo.bUseAsynLogin = false;
        loginInfo.write();

        HCNetSDK.NET_DVR_DEVICEINFO_V40 deviceInfo = new HCNetSDK.NET_DVR_DEVICEINFO_V40();
        userId = HCNetSDK.INSTANCE.NET_DVR_Login_V40(loginInfo, deviceInfo);

        if (userId < 0) {
            System.err.println("Login failed, Error Code: " + HCNetSDK.INSTANCE.NET_DVR_GetLastError());
            return;
        }
        System.out.println("Login successful, UserID: " + userId);

        // 4. Start RealPlay Preview
        HCNetSDK.NET_DVR_PREVIEWINFO previewInfo = new HCNetSDK.NET_DVR_PREVIEWINFO();
        previewInfo.lChannel = 1;
        previewInfo.dwStreamType = 0; // 0: Main Stream, 1: Sub Stream
        previewInfo.dwLinkMode = 0;   // 0: TCP, 1: UDP
        previewInfo.hHwnd = null;     // Crucial: Null on Linux
        previewInfo.bBlocked = true;
        previewInfo.write();

        // Define Data Callback
        HCNetSDK.FRealDataCallBack_V30 dataCallBack = (lRealHandle, dwDataType, pBuffer, dwBufSize, pUser) -> {
            if (dwDataType == 1) { // NET_DVR_SYSHEAD
                IntByReference portRef = new IntByReference();
                if (PlayM4.INSTANCE.PlayM4_GetPort(portRef)) {
                    playPort = portRef.getValue();
                    byte[] sysHead = pBuffer.getByteArray(0, dwBufSize);
                    PlayM4.INSTANCE.PlayM4_OpenStream(playPort, sysHead, dwBufSize, 1024 * 1024);

                    // Set Decoding Callback to get YUV frames
                    PlayM4.INSTANCE.PlayM4_SetDecCallBack(playPort, decCallBack);
                }
            } else if (dwDataType == 2) { // NET_DVR_STREAMDATA
                if (playPort != -1) {
                    byte[] streamData = pBuffer.getByteArray(0, dwBufSize);
                    PlayM4.INSTANCE.PlayM4_InputData(playPort, streamData, dwBufSize);
                }
            }
        };

        realPlayHandle = HCNetSDK.INSTANCE.NET_DVR_RealPlay_V40(userId, previewInfo, dataCallBack, null);
        if (realPlayHandle < 0) {
            System.err.println("RealPlay failed, Error Code: " + HCNetSDK.INSTANCE.NET_DVR_GetLastError());
            cleanup();
            return;
        }
        System.out.println("RealPlay started successfully.");

        // Keep main thread alive
        try { Thread.sleep(Long.MAX_VALUE); } catch (InterruptedException e) { e.printStackTrace(); }
    }

    // PlayM4 Decoding Callback (Runs on Native Thread)
    private static final PlayM4.DecCallBack decCallBack = (nPort, pBuf, nSize, pFrameInfo, nUser, nReserved2) -> {
        if (pBuf != null && nSize > 0 && pFrameInfo != null) {
            pFrameInfo.read(); // Read struct from native memory
            int width = pFrameInfo.nWidth;
            int height = pFrameInfo.nHeight;

            if (width > 0 && height > 0) {
                byte[] yuvData = pBuf.getByteArray(0, nSize);
                BufferedImage rgbImage = YuvToRgbConverter.yv12ToRgb(yuvData, width, height);

                // Update Swing UI safely on EDT
                SwingUtilities.invokeLater(() -> videoPanel.setImage(rgbImage));
            }
        }
    };

    private static void cleanup() {
        if (realPlayHandle >= 0) HCNetSDK.INSTANCE.NET_DVR_StopRealPlay(realPlayHandle);
        if (playPort != -1) {
            PlayM4.INSTANCE.PlayM4_CloseStream(playPort);
            PlayM4.INSTANCE.PlayM4_FreePort(playPort);
        }
        if (userId >= 0) HCNetSDK.INSTANCE.NET_DVR_Logout(userId);
        HCNetSDK.INSTANCE.NET_DVR_Cleanup();
    }

    // Custom JPanel for Video Rendering
    static class VideoPanel extends JPanel {
        private BufferedImage currentImage;

        public synchronized void setImage(BufferedImage img) {
            this.currentImage = img;
            repaint();
        }

        @Override
        protected void paintComponent(Graphics g) {
            super.paintComponent(g);
            BufferedImage img;
            synchronized (this) { img = currentImage; }

            if (img != null) {
                // Draw image scaled to panel size
                g.drawImage(img, 0, 0, getWidth(), getHeight(), null);
            } else {
                g.setColor(Color.BLACK);
                g.fillRect(0, 0, getWidth(), getHeight());
                g.setColor(Color.WHITE);
                g.setFont(new Font("Arial", Font.BOLD, 16));
                g.drawString("Waiting for video stream...", 20, 30);
            }
        }
    }
}
```

### Execution Instructions on Linux
1. **Compile the Code**: Ensure your classpath includes the JNA jar.
2. **Set Library Path**: The JVM must be able to find the Hikvision `.so` files.
   ```bash
   export LD_LIBRARY_PATH=/path/to/hikvision/sdk/lib:$LD_LIBRARY_PATH
   ```
3. **Run the Application**:
   ```bash
   java -cp .:jna-5.13.0.jar HikvisionLinuxPlayer
   ```

### Important Architectural Notes
* **Thread Safety**: The `FRealDataCallBack_V30` and `DecCallBack` execute on native C-threads managed by the SDK. We use `SwingUtilities.invokeLater()` to safely push the decoded `BufferedImage` to the Swing Event Dispatch Thread (EDT).
* **Memory Management**: JNA's `Pointer.getByteArray()` creates a copy of the native memory into Java's heap. For ultra-high resolution (e.g., 4K @ 60fps), consider using JavaCV/FFmpeg instead of manual YUV conversion to leverage hardware acceleration, though the above YV12 converter is highly optimized for standard 1080p/4MP streams.
* **Struct Alignment**: Hikvision occasionally updates struct padding in newer SDK releases. If `NET_DVR_Login_V40` throws an `IllegalArgumentException` or `Error`, verify the `@FieldOrder` and byte array padding sizes against the `HCNetSDK.h` header file included in your specific SDK download.

