<script>
/* =========================================================
   STREET RUNNER — single-file HTML5 open-world action game
   ========================================================= */

const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
const mini = document.getElementById('minimap');
const mctx = mini.getContext('2d');

let W = 0, H = 0;
function resize() {
  W = canvas.width = window.innerWidth;
  H = canvas.height = window.innerHeight;
}
window.addEventListener('resize', resize); resize();

/* ---------- World ---------- */
const WORLD = { w: 4000, h: 4000 };
const TILE = 80;

// Procedural city: grid of blocks with roads between
const BLOCK = 400; // block size
const ROAD = 80;   // road width
const buildings = [];
const trees = [];

function genWorld() {
  for (let x = 0; x < WORLD.w; x += BLOCK) {
    for (let y = 0; y < WORLD.h; y += BLOCK) {
      // inner building area inside each block
      const bx = x + ROAD/2 + 10;
      const by = y + ROAD/2 + 10;
      const bw = BLOCK - ROAD - 20;
      const bh = BLOCK - ROAD - 20;
      // subdivide block into 1-4 buildings
      const splits = 1 + Math.floor(Math.random()*3);
      if (splits === 1) {
        buildings.push({x:bx, y:by, w:bw, h:bh, color:randBuildingColor()});
      } else if (splits === 2) {
        if (Math.random() < 0.5) {
          buildings.push({x:bx, y:by, w:bw/2-5, h:bh, color:randBuildingColor()});
          buildings.push({x:bx+bw/2+5, y:by, w:bw/2-5, h:bh, color:randBuildingColor()});
        } else {
          buildings.push({x:bx, y:by, w:bw, h:bh/2-5, color:randBuildingColor()});
          buildings.push({x:bx, y:by+bh/2+5, w:bw, h:bh/2-5, color:randBuildingColor()});
        }
      } else {
        buildings.push({x:bx, y:by, w:bw/2-5, h:bh/2-5, color:randBuildingColor()});
        buildings.push({x:bx+bw/2+5, y:by, w:bw/2-5, h:bh/2-5, color:randBuildingColor()});
        buildings.push({x:bx, y:by+bh/2+5, w:bw/2-5, h:bh/2-5, color:randBuildingColor()});
        buildings.push({x:bx+bw/2+5, y:by+bh/2+5, w:bw/2-5, h:bh/2-5, color:randBuildingColor()});
      }
      // occasional trees on sidewalks
      if (Math.random() < 0.4) {
        trees.push({x: x + ROAD/4, y: y + BLOCK/2, r: 14});
      }
      if (Math.random() < 0.4) {
        trees.push({x: x + BLOCK - ROAD/4, y: y + BLOCK/3, r: 14});
      }
    }
  }
}
function randBuildingColor() {
  const cols = ['#6b6258','#7a6a55','#5a5a66','#8a7a60','#6e5a4a','#555a66','#7a6e5a'];
  return cols[Math.floor(Math.random()*cols.length)];
}
genWorld();

/* ---------- Collision helpers ---------- */
function rectCircle(rx, ry, rw, rh, cx, cy, cr) {
  const nx = Math.max(rx, Math.min(cx, rx+rw));
  const ny = Math.max(ry, Math.min(cy, ry+rh));
  const dx = cx-nx, dy = cy-ny;
  return dx*dx + dy*dy < cr*cr;
}
function collidesBuildings(x, y, r) {
  for (const b of buildings) {
    if (x+r < b.x || x-r > b.x+b.w || y+r < b.y || y-r > b.y+b.h) continue;
    if (rectCircle(b.x, b.y, b.w, b.h, x, y, r)) return b;
  }
  return null;
}
function clampWorld(e) {
  e.x = Math.max(e.r, Math.min(WORLD.w - e.r, e.x));
  e.y = Math.max(e.r, Math.min(WORLD.h - e.r, e.y));
}

/* ---------- Entities ---------- */
const player = {
  x: WORLD.w/2, y: WORLD.h/2, r: 14,
  speed: 180, angle: 0,
  hp: 100, maxHp: 100,
  ammo: 30, money: 0,
  inVehicle: null,
  shootCd: 0,
  color: '#3aa0ff'
};

const npcs = [];
const vehicles = [];
const bullets = [];
const particles = [];

function spawnNPC(x, y, opts={}) {
  const n = {
    x, y, r: 13, speed: 70 + Math.random()*40,
    angle: Math.random()*Math.PI*2,
    hp: 40, maxHp: 40,
    hostile: opts.hostile || false,
    inVehicle: null,
    wanderT: 0,
    shootCd: 0,
    color: opts.hostile ? '#d94848' : '#c9a86a',
    type: 'npc'
  };
  npcs.push(n);
  return n;
}

function spawnVehicle(x, y, opts={}) {
  const colors = ['#c0392b','#2980b9','#27ae60','#f39c12','#8e44ad','#16a085','#34495e'];
  const v = {
    x, y, w: 50, h: 26, r: 22,
    angle: Math.random()*Math.PI*2,
    speed: 0, maxSpeed: 320, accel: 260,
    hp: 200, maxHp: 200,
    color: opts.color || colors[Math.floor(Math.random()*colors.length)],
    driver: null,
    owner: opts.owner || null, // NPC who "owns" it
    type: 'vehicle'
  };
  vehicles.push(v);
  return v;
}

// Populate world
for (let i = 0; i < 60; i++) {
  let x, y, tries = 0;
  do {
    x = 100 + Math.random()*(WORLD.w-200);
    y = 100 + Math.random()*(WORLD.h-200);
    tries++;
  } while (collidesBuildings(x, y, 20) && tries < 20);
  const hostile = Math.random() < 0.35;
  spawnNPC(x, y, {hostile});
}
// Vehicles, some owned by NPCs
for (let i = 0; i < 25; i++) {
  let x, y, tries = 0;
  do {
    x = 100 + Math.random()*(WORLD.w-200);
    y = 100 + Math.random()*(WORLD.h-200);
    tries++;
  } while (collidesBuildings(x, y, 30) && tries < 20);
  const v = spawnVehicle(x, y);
  // 40% chance an NPC is the driver/owner
  if (Math.random() < 0.4 && npcs.length) {
    const owner = npcs[Math.floor(Math.random()*npcs.length)];
    if (!owner.inVehicle) {
      owner.inVehicle = v;
      v.driver = owner;
      v.owner = owner;
      owner.x = v.x; owner.y = v.y;
    }
  }
}

/* ---------- Missions ---------- */
const missions = [
  {
    title: "First Blood",
    desc: "Eliminate 3 hostile gang members.",
    target: 3, progress: 0, type: 'kill',
    reward: 200,
