}
updateMissionUI();

/* ---------- Input ---------- */
const input = { mx:0, my:0, ax:0, ay:0, shoot:false, action:false };
const keys = {};
window.addEventListener('keydown', e => {
  keys[e.key.toLowerCase()] = true;
  if (e.key.toLowerCase() === 'e') tryAction();
