// Joystick handling
function setupJoy(joyId, stickId, out) {
  const joy = document.getElementById(joyId);
  const stick = document.getElementById(stickId);
  let active = false, id = null, cx=0, cy=0;
  const maxR = 45;
  function start(e) {
    const t = e.changedTouches ? e.changedTouches[0] : e;
    const rect = joy.getBoundingClientRect();
    cx = rect.left + rect.width/2; cy = rect.top + rect.height/2;
    active = true; id = e.changedTouches ? t.identifier : 'mouse';
    move(e);
    e.preventDefault();
  }
  function move(e) {
    if (!active) return;
    let t;
    if (e.changedTouches) {
      for (const tt of e.changedTouches) if (tt.identifier === id) { t = tt; break; }
      if (!t) return;
    } else t = e;
    let dx = t.clientX - cx, dy = t.clientY - cy;
    const d = Math.hypot(dx, dy);
    if (d > maxR) { dx = dx/d*maxR; dy = dy/d*maxR; }
    stick.style.transform = `translate(${dx}px, ${dy}px)`;
    out.x = dx/maxR; out.y = dy/maxR;
    e.preventDefault();
  }
  function end(e) {
    if (e.changedTouches) {
      let found = false;
      for (const tt of e.changedTouches) if (tt.identifier === id) found = true;
      if (!found) return;
    }
    active = false; id = null;
    stick.style.transform = '';
    out.x = 0; out.y = 0;
  }
  joy.addEventListener('touchstart', start, {passive:false});
  joy.addEventListener('touchmove', move, {passive:false});
  joy.addEventListener('touchend', end);
  joy.addEventListener('touchcancel', end);
  joy.addEventListener('mousedown', start);
  window.addEventListener('mousemove', move);
  window.addEventListener('mouseup', end);
}
setupJoy('joyL', 'stickL', { set x(v){input.mx=v}, set y(v){input.my=v}, get x(){return input.mx}, get y(){return input.my} });
setupJoy('joyR', 'stickR', { set x(v){input.ax=v}, set y(v){input.ay=v}, get x(){return input.ax}, get y(){return input.ay} });

// Buttons
function bindBtn(id, onDown, onUp) {
  const el = document.getElementById(id);
  const d = e => { onDown && onDown(); e.preventDefault(); };
  const u = e => { onUp && onUp(); e.preventDefault(); };
  el.addEventListener('touchstart', d, {passive:false});
  el.addEventListener('touchend', u);
  el.addEventListener('mousedown', d);
  el.addEventListener('mouseup', u);
  el.addEventListener('mouseleave', u);
}
bindBtn('btnShoot', ()=>input.shoot=true, ()=>input.shoot=false);
bindBtn('btnAction', ()=>tryAction());
bindBtn('btnMission', ()=>{ currentMission = Math.min(missions.length-1, currentMission+1); updateMissionUI(); });

/* ---------- Actions ---------- */
function tryAction() {
  if (player.inVehicle) {
    // exit vehicle
    const v = player.inVehicle;
    player.inVehicle = null;
    v.driver = null;
    player.x = v.x + Math.cos(v.angle + Math.PI/2) * 40;
    player.y = v.y + Math.sin(v.angle + Math.PI/2) * 40;
    toast("Exited vehicle");
    return;
  }
  // try enter nearest vehicle
  let best = null, bd = 60*60;
  for (const v of vehicles) {
    const dx = v.x - player.x, dy = v.y - player.y;
    const d = dx*dx + dy*dy;
    if (d < bd) { bd = d; best = v; }
  }
  if (best) {
    if (best.driver && best.driver !== player) {
      // steal! kick out NPC
      const npc = best.driver;
      npc.inVehicle = null;
      npc.hostile = true;
      npc.x = best.x + Math.cos(best.angle + Math.PI/2) * 40;
      npc.y = best.y + Math.sin(best.angle + Math.PI/2) * 40;
      toast("Vehicle stolen!");
      advanceMission('steal');
    }
    player.inVehicle = best;
    best.driver = player;
    toast("Entered vehicle");
  }
}

/* ---------- Combat ---------- */
function shoot(shooter, tx, ty, fromPlayer) {
  const dx = tx - shooter.x, dy = ty - shooter.y;
  const d = Math.hypot(dx, dy) || 1;
  bullets.push({
    x: shooter.x + dx/d*20, y: shooter.y + dy/d*20,
    vx: dx/d*700, vy: dy/d*700,
    life: 1.2, fromPlayer, dmg: fromPlayer ? 20 : 10
  });
  // muzzle flash
  for (let i = 0; i < 4; i++) {
    particles.push({
      x: shooter.x + dx/d*22, y: shooter.y + dy/d*22,
      vx: (Math.random()-0.5)*100, vy: (Math.random()-0.5)*100,
      life: 0.2, color: '#ffdd55', size: 3
    });
  }
}

function damage(target, dmg) {
  target.hp -= dmg;
  if (target.hp <= 0) {
    if (target === player) {
      document.getElementById('gameover').style.display = 'flex';
      running = false;
    } else {
      // NPC death
      if (target.hostile) advanceMission('kill');
      player.money += target.hostile ? 50 : -100;
      // drop particles
      for (let i = 0; i < 12; i++) {
        particles.push({
          x: target.x, y: target.y,
          vx: (Math.random()-0.5)*200, vy: (Math.random()-0.5)*200,
          life: 0.6, color: '#aa2222', size: 3
        });
      }
      // if in vehicle, exit
      if (target.inVehicle) {
        target.inVehicle.driver = null;
        target.inVehicle = null;
      }
      const idx = npcs.indexOf(target);
      if (idx >= 0) npcs.splice(idx, 1);
    }
  }
}

/* ---------- Toast ---------- */
let toastTimer = 0;
function toast(msg) {
  const el = document.getElementById('toast');
  el.textContent = msg;
  el.classList.add('show');
  toastTimer = 2.0;
}

/* ---------- Update ---------- */
let last = performance.now();
let running = true;

function update(dt) {
  // Player input
  let mx = input.mx, my = input.my;
  if (keys['w']) my -= 1;
  if (keys['s']) my += 1;
  if (keys['a']) mx -= 1;
  if (keys['d']) mx += 1;
  const mlen = Math.hypot(mx, my);
  if (mlen > 1) { mx/=mlen; my/=mlen; }

  if (player.inVehicle) {
    const v = player.inVehicle;
    // right stick / mouse for steering+throttle
    let ax = input.ax, ay = input.ay;
    if (mouseAim.active) {
      const wx = mouseAim.x - W/2, wy = mouseAim.y - H/2;
      const l = Math.hypot(wx, wy) || 1;
      ax = wx/l; ay = wy/l;
    }
    // forward = vehicle angle; use ax component along forward for throttle, perpendicular for steering
    const fx = Math.cos(v.angle), fy = Math.sin(v.angle);
    const forward = ax*fx + ay*fy;
    const right = -ax*fy + ay*fx;
    v.speed += forward * v.accel * dt;
    v.speed *= 0.98; // friction
    v.speed = Math.max(-v.maxSpeed*0.5, Math.min(v.maxSpeed, v.speed));
    // steering scales with speed
    v.angle += right * 2.5 * dt * Math.min(1, Math.abs(v.speed)/100);
    const nx = v.x + fx * v.speed * dt;
    const ny = v.y + fy * v.speed * dt;
    if (!collidesBuildings(nx, ny, v.r)) { v.x = nx; v.y = ny; }
    else { v.speed *= -0.3; }
    clampWorld(v);
    player.x = v.x; player.y = v.y; player.angle = v.angle;
    // track distance for mission
    const moved = Math.abs(v.speed) * dt;
    advanceMission('drive', moved);
    // shoot from vehicle
    player.shootCd -= dt;
    if (input.shoot && player.shootCd <= 0 && player.ammo > 0) {
      let tx, ty;
      if (mouseAim.active) {
        tx = player.x + (mouseAim.x - W/2);
        ty = player.y + (mouseAim.y - H/2);
      } else {
        tx = player.x + fx*100; ty = player.y + fy*100;
      }
      shoot(player, tx, ty, true);
      player.ammo--;
      player.shootCd = 0.18;
    }
  } else {
    // on foot
    const nx = player.x + mx * player.speed * dt;
    const ny = player.y + my * player.speed * dt;
    if (!collidesBuildings(nx, player.y, player.r)) player.x = nx;
    if (!collidesBuildings(player.x, ny, player.r)) player.y = ny;
    clampWorld(player);
    // aim
    if (mouseAim.active) {
      player.angle = Math.atan2(mouseAim.y - H/2, mouseAim.x - W/2);
    } else if (Math.hypot(input.ax, input.ay) > 0.2) {
      player.angle = Math.atan2(input.ay, input.ax);
    } else if (mlen > 0.1) {
      player.angle = Math.atan2(my, mx);
    }
    // shoot
    player.shootCd -= dt;
    if (input.shoot && player.shootCd <= 0 && player.ammo > 0) {
      const tx = player.x + Math.cos(player.angle)*100;
      const ty = player.y + Math.sin(player.angle)*100;
      shoot(player, tx, ty, true);
      player.ammo--;
      player.shootCd = 0.18;
    }
  }

  // NPCs
  for (const n of npcs) {
    if (n.inVehicle) {
      // NPC driver: simple AI - drive toward player if hostile, else wander
      const v = n.inVehicle;
      const dx = player.x - v.x, dy = player.y - v.y;
      const dist = Math.hypot(dx, dy);
      let targetAngle;
      if (n.hostile && dist < 600) {
        targetAngle = Math.atan2(dy, dx);
        v.speed += v.accel * dt * 0.7;
      } else {
        n.wanderT -= dt;
        if (n.wanderT <= 0) { n.wanderAngle = Math.random()*Math.PI*2; n.wanderT = 2 + Math.random()*3; }
        targetAngle = n.wanderAngle;
        v.speed += v.accel * dt * 0.3;
      }
      v.speed = Math.min(v.maxSpeed*0.7, v.speed);
      v.speed *= 0.98;
      let da = targetAngle - v.angle;
      while (da > Math.PI) da -= Math.PI*2;
      while (da < -Math.PI) da += Math.PI*2;
      v.angle += Math.max(-2*dt, Math.min(2*dt, da));
      const fx = Math.cos(v.angle), fy = Math.sin(v.angle);
      const nx = v.x + fx * v.speed * dt;
      const ny = v.y + fy * v.speed * dt;
      if (!collidesBuildings(nx, ny, v.r)) { v.x = nx; v.y = ny; }
      else { v.speed *= -0.3; n.wanderT = 0; }
      clampWorld(v);
      n.x = v.x; n.y = v.y;
      // shoot at player if hostile and close
      n.shootCd -= dt;
      if (n.hostile && dist < 400 && n.shootCd <= 0) {
        shoot(n, player.x, player.y, false);
        n.shootCd = 0.8 + Math.random()*0.6;
      }
    } else {
      // on foot
      const dx = player.x - n.x, dy = player.y - n.y;
      const dist = Math.hypot(dx, dy);
      // become hostile if player is shooting nearby or very close
      if (!n.hostile && dist < 120 && input.shoot) n.hostile = true;
      let tx = n.x, ty = n.y;
      if (n.hostile && dist < 500) {
        // chase
        tx = n.x + dx/dist * n.speed * dt;
        ty = n.y + dy/dist * n.speed * dt;
        n.angle = Math.atan2(dy, dx);
        n.shootCd -= dt;
        if (dist < 350 && n.shootCd <= 0) {
          shoot(n, player.x, player.y, false);
          n.shootCd = 1.0 + Math.random()*0.8;
        }
      } else {
        n.wanderT -= dt;
        if (n.wanderT <= 0) {
          n.wanderAngle = Math.random()*Math.PI*2;
          n.wanderT = 2 + Math.random()*3;
        }
        tx = n.x + Math.cos(n.wanderAngle) * n.speed * 0.5 * dt;
        ty = n.y + Math.sin(n.wanderAngle) * n.speed * 0.5 * dt;
        n.angle = n.wanderAngle;
      }
      if (!collidesBuildings(tx, n.y, n.r)) n.x = tx;
      if (!collidesBuildings(n.x, ty, n.r)) n.y = ty;
      clampWorld(n);
    }
  }

  // Bullets
  for (let i = bullets.length-1; i >= 0; i--) {
    const b = bullets[i];
    b.x += b.vx * dt; b.y += b.vy * dt; b.life -= dt;
    if (b.life <= 0) { bullets.splice(i,1); continue; }
    if (collidesBuildings(b.x, b.y, 2)) {
      for (let k=0;k<5;k++) particles.push({x:b.x,y:b.y,vx:(Math.random()-0.5)*150,vy:(Math.random()-0.5)*150,life:0.3,color:'#aaa',size:2});
      bullets.splice(i,1); continue;
    }
    if (b.fromPlayer) {
      // hit NPCs
      let hit = false;
      for (const n of npcs) {
        const dx = n.x-b.x, dy = n.y-b.y;
        if (dx*dx+dy*dy < n.r*n.r) { damage(n, b.dmg); hit = true; break; }
      }
      if (!hit) {
        for (const v of vehicles) {
          if (v === player.inVehicle) continue;
          const dx = v.x-b.x, dy = v.y-b.y;
          if (dx*dx+dy*dy < v.r*v.r) { v.hp -= b.dmg; hit = true; if (v.hp<=0) explodeVehicle(v); break; }
        }
      }
      if (hit) bullets.splice(i,1);
    } else {
      // hit player
      if (player.inVehicle) {
        const v = player.inVehicle;
        const dx = v.x-b.x, dy = v.y-b.y;
        if (dx*dx+dy*dy < v.r*v.r) { v.hp -= b.dmg; if (v.hp<=0) explodeVehicle(v); bullets.splice(i,1); continue; }
      }
      const dx = player.x-b.x, dy = player.y-b.y;
      if (dx*dx+dy*dy < player.r*player.r) { damage(player, b.dmg); bullets.splice(i,1); }
    }
  }

  // Particles
  for (let i = particles.length-1; i >= 0; i--) {
    const p = particles[i];
    p.x += p.vx*dt; p.y += p.vy*dt; p.life -= dt;
    if (p.life <= 0) particles.splice(i,1);
  }

  // HUD
  document.getElementById('hp').textContent = Math.max(0, Math.round(player.hp));
  document.getElementById('ammo').textContent = player.ammo;
  document.getElementById('money').textContent = player.money;

  if (toastTimer > 0) {
    toastTimer -= dt;
    if (toastTimer <= 0) document.getElementById('toast').classList.remove('show');
  }
}

function explodeVehicle(v) {
  for (let i = 0; i < 30; i++) {
    particles.push({
      x: v.x, y: v.y,
      vx: (Math.random()-0.5)*400, vy: (Math.random()-0.5)*400,
      life: 0.8, color: Math.random()<0.5?'#ff7722':'#ffcc33', size: 4
    });
  }
  if (v.driver === player) {
    damage(player, 60);
    player.inVehicle = null;
  } else if (v.driver) {
    damage(v.driver, 200);
    v.driver.inVehicle = null;
  }
  v.driver = null;
  const idx = vehicles.indexOf(v);
  if (idx >= 0) vehicles.splice(idx, 1);
}

/* ---------- Render ---------- */
function render() {
  // camera
  const camX = player.x - W/2;
  const camY = player.y - H/2;

  // background (grass/ground)
  ctx.fillStyle = '#3a4a3a';
  ctx.fillRect(0, 0, W, H);

  // roads (draw grid)
  ctx.fillStyle = '#2a2a2a';
  for (let x = 0; x < WORLD.w; x += BLOCK) {
    ctx.fillRect(x - camX, -camY, ROAD, WORLD.h);
  }
  for (let y = 0; y < WORLD.h; y += BLOCK) {
    ctx.fillRect(-camX, y - camY, WORLD.w, ROAD);
  }
  // road lines
  ctx.strokeStyle = '#d9c85a';
  ctx.lineWidth = 2;
  ctx.setLineDash([15, 15]);
  for (let x = 0; x < WORLD.w; x += BLOCK) {
    ctx.beginPath();
    ctx.moveTo(x + ROAD/2 - camX, -camY);
    ctx.lineTo(x + ROAD/2 - camX, WORLD.h - camY);
    ctx.stroke();
  }
  for (let y = 0; y < WORLD.h; y += BLOCK) {
    ctx.beginPath();
    ctx.moveTo(-camX, y + ROAD/2 - camY);
    ctx.lineTo(WORLD.w - camX, y + ROAD/2 - camY);
    ctx.stroke();
  }
  ctx.setLineDash([]);

  // buildings
  for (const b of buildings) {
    if (b.x + b.w < camX || b.x > camX+W || b.y + b.h < camY || b.y > camY+H) continue;
    ctx.fillStyle = b.color;
    ctx.fillRect(b.x - camX, b.y - camY, b.w, b.h);
    ctx.strokeStyle = 'rgba(0,0,0,0.4)';
    ctx.lineWidth = 2;
    ctx.strokeRect(b.x - camX, b.y - camY, b.w, b.h);
    // windows
    ctx.fillStyle = 'rgba(255,220,120,0.35)';
    for (let wx = b.x + 10; wx < b.x + b.w - 10; wx += 20) {
      for (let wy = b.y + 10; wy < b.y + b.h - 10; wy += 20) {
        ctx.fillRect(wx - camX, wy - camY, 8, 8);
      }
    }
  }

  // trees
  for (const t of trees) {
    if (t.x < camX-20 || t.x > camX+W+20 || t.y < camY-20 || t.y > camY+H+20) continue;
    ctx.fillStyle = 'rgba(0,0,0,0.3)';
    ctx.beginPath(); ctx.arc(t.x - camX + 3, t.y - camY + 3, t.r, 0, Math.PI*2); ctx.fill();
    ctx.fillStyle = '#2d5a2d';
    ctx.beginPath(); ctx.arc(t.x - camX, t.y - camY, t.r, 0, Math.PI*2); ctx.fill();
  }

  // vehicles
  for (const v of vehicles) {
    if (v.x < camX-60 || v.x > camX+W+60 || v.y < camY-60 || v.y > camY+H+60) continue;
    ctx.save();
    ctx.translate(v.x - camX, v.y - camY);
    ctx.rotate(v.angle);
    // shadow
    ctx.fillStyle = 'rgba(0,0,0,0.35)';
    ctx.fillRect(-v.w/2+3, -v.h/2+3, v.w, v.h);
    // body
    ctx.fillStyle = v.color;
    ctx.fillRect(-v.w/2, -v.h/2, v.w, v.h);
    // windshield
    ctx.fillStyle = 'rgba(80,120,160,0.7)';
    ctx.fillRect(v.w/2 - 14, -v.h/2 + 3, 10, v.h - 6);
    ctx.fillRect(-v.w/2 + 4, -v.h/2 + 3, 8, v.h - 6);
    // outline
    ctx.strokeStyle = 'rgba(0,0,0,0.5)';
    ctx.lineWidth = 2;
    ctx.strokeRect(-v.w/2, -v.h/2, v.w, v.h);
    ctx.restore();
    // hp bar if damaged
    if (v.hp < v.maxHp) {
      const w = 40;
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      ctx.fillRect(v.x - camX - w/2, v.y - camY - 30, w, 5);
      ctx.fillStyle = '#4ade80';
      ctx.fillRect(v.x - camX - w/2, v.y - camY - 30, w * (v.hp/v.maxHp), 5);
    }
    // marker if owned and player near
    if (v.owner && v.driver === v.owner) {
      const dx = v.x - player.x, dy = v.y - player.y;
      if (dx*dx+dy*dy < 80*80) {
        ctx.fillStyle = '#ffd54a';
        ctx.font = 'bold 12px Arial';
        ctx.textAlign = 'center';
        ctx.fillText('[ACT] Steal', v.x - camX, v.y - camY - 36);
      }
    } else if (!v.driver) {
      const dx = v.x - player.x, dy = v.y - player.y;
      if (dx*dx+dy*dy < 80*80) {
        ctx.fillStyle = '#8fd';
        ctx.font = 'bold 12px Arial';
        ctx.textAlign = 'center';
        ctx.fillText('[ACT] Enter', v.x - camX, v.y - camY - 36);
      }
    }
  }

  // NPCs
  for (const n of npcs) {
    if (n.x < camX-30 || n.x > camX+W+30 || n.y < camY-30 || n.y > camY+H+30) continue;
    if (n.inVehicle) continue; // drawn inside vehicle
    ctx.save();
    ctx.translate(n.x - camX, n.y - camY);
    // shadow
    ctx.fillStyle = 'rgba(0,0,0,0.35)';
    ctx.beginPath(); ctx.arc(2, 2, n.r, 0, Math.PI*2); ctx.fill();
    // body
    ctx.fillStyle = n.color;
    ctx.beginPath(); ctx.arc(0, 0, n.r, 0, Math.PI*2); ctx.fill();
    ctx.strokeStyle = n.hostile ? '#ff3333' : '#000';
    ctx.lineWidth = 2;
    ctx.stroke();
    // facing
    ctx.rotate(n.angle);
    ctx.fillStyle = '#000';
    ctx.fillRect(n.r-2, -2, 6, 4);
    ctx.restore();
    // hp bar
    if (n.hp < n.maxHp) {
      const w = 30;
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      ctx.fillRect(n.x - camX - w/2, n.y - camY - 22, w, 4);
      ctx.fillStyle = n.hostile ? '#ff5555' : '#4ade80';
      ctx.fillRect(n.x - camX - w/2, n.y - camY - 22, w * (n.hp/n.maxHp), 4);
    }
  }

  // Player (if on foot)
  if (!player.inVehicle) {
    ctx.save();
    ctx.translate(player.x - camX, player.y - camY);
    ctx.fillStyle = 'rgba(0,0,0,0.35)';
    ctx.beginPath(); ctx.arc(2, 2, player.r, 0, Math.PI*2); ctx.fill();
    ctx.fillStyle = player.color;
    ctx.beginPath(); ctx.arc(0, 0, player.r, 0, Math.PI*2); ctx.fill();
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 2;
    ctx.stroke();
    ctx.rotate(player.angle);
    ctx.fillStyle = '#222';
    ctx.fillRect(player.r-2, -3, 10, 6); // gun
    ctx.restore();
  } else {
    // highlight player's vehicle
    const v = player.inVehicle;
    ctx.save();
    ctx.translate(v.x - camX, v.y - camY);
    ctx.strokeStyle = '#ffd54a';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.arc(0, 0, v.r + 6, 0, Math.PI*2);
    ctx.stroke();
    ctx.restore();
  }

  // Bullets
  for (const b of bullets) {
    ctx.fillStyle = b.fromPlayer ? '#ffee66' : '#ff6666';
    ctx.beginPath();
    ctx.arc(b.x - camX, b.y - camY, 3, 0, Math.PI*2);
    ctx.fill();
  }

  // Particles
  for (const p of particles) {
    ctx.globalAlpha = Math.max(0, p.life);
    ctx.fillStyle = p.color;
    ctx.fillRect(p.x - camX - p.size/2, p.y - camY - p.size/2, p.size, p.size);
  }
  ctx.globalAlpha = 1;

  // Crosshair
  if (!player.inVehicle && mouseAim.active) {
    ctx.strokeStyle = 'rgba(255,255,255,0.7)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(mouseAim.x, mouseAim.y, 10, 0, Math.PI*2);
    ctx.moveTo(mouseAim.x-15, mouseAim.y); ctx.lineTo(mouseAim.x-5, mouseAim.y);
    ctx.moveTo(mouseAim.x+5, mouseAim.y); ctx.lineTo(mouseAim.x+15, mouseAim.y);
    ctx.moveTo(mouseAim.x, mouseAim.y-15); ctx.lineTo(mouseAim.x, mouseAim.y-5);
    ctx.moveTo(mouseAim.x, mouseAim.y+5); ctx.lineTo(mouseAim.x, mouseAim.y+15);
    ctx.stroke();
  }

  // Minimap
  renderMinimap();
}

function renderMinimap() {
  const s = mini.width / WORLD.w;
  mctx.fillStyle = '#1a2a1a';
  mctx.fillRect(0, 0, mini.width, mini.height);
  // roads
  mctx.fillStyle = '#333';
  for (let x = 0; x < WORLD.w; x += BLOCK) mctx.fillRect(x*s, 0, ROAD*s, mini.height);
  for (let y = 0; y < WORLD.h; y += BLOCK) mctx.fillRect(0, y*s, mini.width, ROAD*s);
  // buildings
  mctx.fillStyle = '#666';
  for (const b of buildings) mctx.fillRect(b.x*s, b.y*s, Math.max(1,b.w*s), Math.max(1,b.h*s));
  // vehicles
  for (const v of vehicles) {
    mctx.fillStyle = v === player.inVehicle ? '#ffd54a' : '#888';
    mctx.fillRect(v.x*s-1, v.y*s-1, 3, 3);
  }
  // NPCs
  for (const n of npcs) {
    mctx.fillStyle = n.hostile ? '#ff4444' : '#aaa';
    mctx.fillRect(n.x*s-1, n.y*s-1, 2, 2);
  }
  // player
  mctx.fillStyle = '#3aa0ff';
  mctx.beginPath();
  mctx.arc(player.x*s, player.y*s, 3, 0, Math.PI*2);
  mctx.fill();
  // view rect
  const camX = player.x - W/2, camY = player.y - H/2;
  mctx.strokeStyle = 'rgba(255,255,255,0.5)';
  mctx.lineWidth = 1;
  mctx.strokeRect(camX*s, camY*s, W*s, H*s);
}

/* ---------- Main loop ---------- */
function loop(now) {
  const dt = Math.min(0.05, (now - last) / 1000);
  last = now;
  if (running) update(dt);
  render();
  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);

toast("Welcome! Complete missions to earn cash.");
</script>
</body>
</html>
```

## How to Play

**Mobile (touch):**
- **Left joystick** — move on foot / steer & throttle in vehicle
- **Right joystick** — aim (on foot) / additional steering (in vehicle)
- **FIRE** — shoot
- **ACT** — enter/exit vehicles, steal NPC-driven cars
- **NEXT MSN** — skip to next mission

**Desktop:**
- **WASD** — move / drive
- **Mouse** — aim · **Left click** — shoot
- **E** — enter/exit/steal vehicle
- **Q** — skip mission

## Features Implemented

| System | Details |
|---|---|
| **Large map** | 4000×4000 procedurally generated city with blocks, roads, buildings, trees |
| **Virtual joysticks** | Dual analog sticks with multi-touch support |
| **NPC combat** | Hostile (red) and civilian NPCs with AI, shooting, health bars |
| **Vehicle driving** | Arcade physics: acceleration, steering, friction, collisions |
| **Stealable cars** | ~40% of vehicles have NPC drivers — approach and press ACT to carjack |
| **Mission system** | 5 progressive missions (kills, thefts, driving distance) with cash rewards |
| **Minimap** | Real-time overview showing player, NPCs, vehicles, and viewport |
| **HUD** | Health, ammo, money, active mission tracker |
| **Effects** | Muzzle flash, blood, explosions, bullet impacts |

The game is fully self-contained — no external assets or libraries required.

# 3D Space Gravity Game

Below is a complete, self-contained HTML file. Save it as `space.html` and open it in any modern browser (Chrome, Firefox, Edge). It uses **Three.js** (loaded from CDN) for 3D rendering and implements real Newtonian gravity: **F = G·M·m / r²**.

## How to Play
| Key | Action |
|---|---|
| `↑` / `↓` or `W` / `S` | Increase / decrease thrust (speed) |
| `←` / `→` or `A` / `D` | Yaw (turn left/right) |
| `Q` / `E` | Pitch (nose up/down) |
| `R` | Reset ship |

**Goal:** Fly close to planets to be captured by their gravity, or burn hard to escape. Crashing at high speed ends the run.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8" />
<title>Gravity Drift — 3D Space Flight</title>
<style>
  html, body { margin:0; padding:0; overflow:hidden; background:#000; color:#9ef;
               font-family: "Consolas", monospace; }
  #hud {
    position: fixed; top: 12px; left: 12px; padding: 10px 14px;
    background: rgba(0,20,40,0.55); border: 1px solid #0af3;
    border-radius: 6px; font-size: 13px; line-height: 1.55;
    pointer-events: none; text-shadow: 0 0 4px #0af;
  }
  #hud b { color:#fff; }
  #msg {
    position: fixed; top: 40%; left: 0; right: 0; text-align: center;
    font-size: 42px; color:#f66; text-shadow: 0 0 12px #f00;
    pointer-events: none; display:none;
  }
  #help {
    position: fixed; bottom: 10px; left: 12px; font-size: 12px;
    color:#6cf8; pointer-events:none;
  }
</style>
</head>
<body>
<div id="hud">
  <div>Speed: <b id="spd">0</b> u/s</div>
  <div>Thrust: <b id="thr">0</b></div>
  <div>Nearest: <b id="near">—</b></div>
  <div>Gravity pull: <b id="gforce">0</b></div>
  <div>Visited: <b id="vis">0</b> / <b id="tot">0</b></div>
</div>
<div id="msg"></div>
<div id="help">↑/↓ or W/S : thrust &nbsp;|&nbsp; ←/→ or A/D : yaw &nbsp;|&nbsp; Q/E : pitch &nbsp;|&nbsp; R : reset</div>

<script src="https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.min.js"></script>
<script>
/* =========================================================
   Gravity Drift — Newtonian 3D space flight
   Physics: a_ship = Σ ( G * M_planet / r^2 ) * r_hat  +  thrust
   ========================================================= */

const G = 800;                 // gravitational constant (tuned for gameplay)
const MAX_THRUST = 60;         // max player thrust acceleration
const THRUST_STEP = 1.2;       // how fast thrust ramps
const YAW_SPEED = 1.2;
const PITCH_SPEED = 1.2;
const CRASH_SPEED = 35;        // impact speed that destroys the ship

// ---------- Scene setup ----------
const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x000010, 0.0008);

const camera = new THREE.PerspectiveCamera(
  70, innerWidth/innerHeight, 0.1, 10000);
const renderer = new THREE.WebGLRenderer({ antialias:true });
renderer.setPixelRatio(devicePixelRatio);
renderer.setSize(innerWidth, innerHeight);
document.body.appendChild(renderer.domElement);

scene.add(new THREE.AmbientLight(0x334466, 0.6));
const sun = new THREE.PointLight(0xffffff, 1.6, 0, 1.2);
sun.position.set(0,0,0);
scene.add(sun);

// ---------- Starfield ----------
(function makeStars(){
  const geo = new THREE.BufferGeometry();
  const N = 4000, pos = new Float32Array(N*3), col = new Float32Array(N*3);
  for (let i=0;i<N;i++){
    const r = 2000 + Math.random()*3000;
    const t = Math.random()*Math.PI*2;
    const p = Math.acos(2*Math.random()-1);
    pos[i*3]   = r*Math.sin(p)*Math.cos(t);
    pos[i*3+1] = r*Math.sin(p)*Math.sin(t);
    pos[i*3+2] = r*Math.cos(p);
    const c = 0.6 + Math.random()*0.4;
    col[i*3]=c; col[i*3+1]=c; col[i*3+2]=c+Math.random()*0.2;
  }
  geo.setAttribute('position', new THREE.BufferAttribute(pos,3));
  geo.setAttribute('color',    new THREE.BufferAttribute(col,3));
  const mat = new THREE.PointsMaterial({size:2.2, vertexColors:true,
                                        sizeAttenuation:false});
  scene.add(new THREE.Points(geo, mat));
})();

// ---------- Central star ----------
const starGeo = new THREE.SphereGeometry(40, 48, 48);
const starMat = new THREE.MeshBasicMaterial({ color: 0xffcc66 });
const starMesh = new THREE.Mesh(starGeo, starMat);
scene.add(starMesh);
// glow
const glow = new THREE.Mesh(
  new THREE.SphereGeometry(55, 32, 32),
  new THREE.MeshBasicMaterial({ color:0xffaa33, transparent:true, opacity:0.25 })
);
scene.add(glow);

// ---------- Planets ----------
const planets = [];
const planetDefs = [
  { name:"Pyra",   r:14, dist:180,  mass:2200, color:0xff5533, speed:0.15 },
  { name:"Aqua",   r:18, dist:300,  mass:4500, color:0x3399ff, speed:0.10 },
  { name:"Verdant",r:22, dist:460,  mass:7000, color:0x44cc66, speed:0.07 },
  { name:"Kronos", r:34, dist:700,  mass:18000,color:0xccaa55, speed:0.045, ring:true },
  { name:"Nyx",    r:12, dist:900,  mass:1500, color:0x8866cc, speed:0.035 },
  { name:"Glacius",r:26, dist:1150, mass:9000, color:0xaaddff, speed:0.028 },
];
planetDefs.forEach((d,i)=>{
  const mesh = new THREE.Mesh(
    new THREE.SphereGeometry(d.r, 40, 40),
    new THREE.MeshStandardMaterial({ color:d.color, roughness:0.8, metalness:0.1 })
  );
  const angle = (i/planetDefs.length)*Math.PI*2;
  mesh.position.set(Math.cos(angle)*d.dist, 0, Math.sin(angle)*d.dist);
  scene.add(mesh);

  // orbit ring
  const ringGeo = new THREE.RingGeometry(d.dist-0.5, d.dist+0.5, 200);
  const ringMat = new THREE.MeshBasicMaterial({
    color:0x335577, side:THREE.DoubleSide, transparent:true, opacity:0.25 });
  const ring = new THREE.Mesh(ringGeo, ringMat);
  ring.rotation.x = Math.PI/2;
  scene.add(ring);

  // Saturn-like ring
  if (d.ring){
    const sr = new THREE.Mesh(
      new THREE.RingGeometry(d.r*1.4, d.r*2.2, 64),
      new THREE.MeshBasicMaterial({ color:0xddcc88, side:THREE.DoubleSide,
                                    transparent:true, opacity:0.7 })
    );
    sr.rotation.x = Math.PI/2.3;
    mesh.add(sr);
  }

  planets.push({
    mesh, name:d.name, radius:d.r, mass:d.mass,
    dist:d.dist, angle, speed:d.speed, visited:false
  });
});
document.getElementById('tot').textContent = planets.length;

// ---------- Ship ----------
const ship = new THREE.Group();
const body = new THREE.Mesh(
  new THREE.ConeGeometry(1.5, 6, 8),
  new THREE.MeshStandardMaterial({ color:0xccccdd, metalness:0.7, roughness:0.3 })
);
body.rotation.x = Math.PI/2; // point forward (-Z)
ship.add(body);
const wing = new THREE.Mesh(
  new THREE.BoxGeometry(6, 0.3, 2),
  new THREE.MeshStandardMaterial({ color:0x556688, metalness:0.5 })
);
ship.add(wing);
// engine glow
const engineGlow = new THREE.Mesh(
  new THREE.SphereGeometry(1.2, 16, 16),
  new THREE.MeshBasicMaterial({ color:0x66ccff, transparent:true, opacity:0.0 })
);
engineGlow.position.z = 3.2;
ship.add(engineGlow);

ship.position.set(120, 20, 0);
scene.add(ship);

// ship state
const state = {
  vel: new THREE.Vector3(0, 0, -18), // initial orbital-ish velocity
  thrust: 0,
  alive: true
};

// ---------- Input ----------
const keys = {};
addEventListener('keydown', e => { keys[e.code] = true;
  if (e.code==='KeyR') resetShip(); });
addEventListener('keyup',   e => { keys[e.code] = false; });

function resetShip(){
  ship.position.set(120, 20, 0);
  ship.rotation.set(0,0,0);
  state.vel.set(0,0,-18);
  state.thrust = 0;
  state.alive = true;
  document.getElementById('msg').style.display='none';
}

// ---------- Main loop ----------
const clock = new THREE.Clock();
const tmpV = new THREE.Vector3();

function updatePlanets(dt){
  planets.forEach(p=>{
    p.angle += p.speed * dt;
    p.mesh.position.set(
      Math.cos(p.angle)*p.dist,
      0,
      Math.sin(p.angle)*p.dist
    );
    p.mesh.rotation.y += dt*0.3;
  });
}

function physicsStep(dt){
  if (!state.alive) return;

  // --- rotation ---
  if (keys['ArrowLeft']  || keys['KeyA']) ship.rotation.y +=  YAW_SPEED*dt;
  if (keys['ArrowRight'] || keys['KeyD']) ship.rotation.y += -YAW_SPEED*dt;
  if (keys['KeyQ']) ship.rotation.x +=  PITCH_SPEED*dt;
  if (keys['KeyE']) ship.rotation.x += -PITCH_SPEED*dt;

  // --- thrust ---
  if (keys['ArrowUp']   || keys['KeyW']) state.thrust = Math.min(MAX_THRUST, state.thrust + THRUST_STEP);
  else if (keys['ArrowDown'] || keys['KeyS']) state.thrust = Math.max(0, state.thrust - THRUST_STEP);
  else state.thrust *= 0.985; // slight drag when idle

  // forward direction in world space (ship looks down -Z locally)
  const forward = new THREE.Vector3(0,0,-1).applyQuaternion(ship.quaternion);

  // --- gravity from every planet + central star ---
  const acc = new THREE.Vector3();
  let nearest = null, nearestDist = Infinity, totalG = 0;

  // central star gravity
  tmpV.copy(starMesh.position).sub(ship.position);
  let r = tmpV.length();
  if (r < 40){ crash("Burned up in the star!"); return; }
  const aStar = G * 25000 / (r*r);
  acc.add(tmpV.normalize().multiplyScalar(aStar));
  totalG += aStar;

  planets.forEach(p=>{
    tmpV.copy(p.mesh.position).sub(ship.position);
    r = tmpV.length();
    if (r < nearestDist){ nearestDist = r; nearest = p; }
    const a = G * p.mass / (r*r);
    acc.add(tmpV.normalize().multiplyScalar(a));
    totalG += a;

    // collision
    if (r < p.radius + 1.5){
      const impactSpeed = state.vel.length();
      if (impactSpeed > CRASH_SPEED){
        crash(`Crashed into ${p.name} at ${impactSpeed.toFixed(1)} u/s`);
      } else {
        // soft landing / capture
        if (!p.visited){
          p.visited = true;
          document.getElementById('vis').textContent =
            planets.filter(x=>x.visited).length;
          flash(`Captured by ${p.name}!`);
        }
        // stick to surface, kill velocity
        state.vel.set(0,0,0);
        const surf = tmpV.normalize().multiplyScalar(p.radius + 2);
        ship.position.copy(p.mesh.position).sub(surf);
      }
      return;
    }
  });

  // --- apply thrust ---
  acc.add(forward.multiplyScalar(state.thrust));

  // --- integrate (semi-implicit Euler) ---
  state.vel.add(acc.multiplyScalar(dt));
  ship.position.add(tmpV.copy(state.vel).multiplyScalar(dt));

  // engine glow scales with thrust
  engineGlow.material.opacity = 0.3 + 0.7*(state.thrust/MAX_THRUST);
  engineGlow.scale.setScalar(0.6 + 1.4*(state.thrust/MAX_THRUST));

  // --- HUD ---
  document.getElementById('spd').textContent  = state.vel.length().toFixed(1);
  document.getElementById('thr').textContent  = state.thrust.toFixed(1);
  document.getElementById('gforce').textContent = totalG.toFixed(2);
  if (nearest){
    document.getElementById('near').textContent =
      `${nearest.name} (${nearestDist.toFixed(0)} u)`;
  }
}

function crash(reason){
  state.alive = false;
  const m = document.getElementById('msg');
  m.textContent = reason + "  — press R to restart";
  m.style.display = 'block';
}
function flash(text){
  const m = document.getElementById('msg');
  m.style.color = '#6f6'; m.style.textShadow='0 0 12px #0f0';
  m.textContent = text; m.style.display='block';
  setTimeout(()=>{ m.style.display='none';
    m.style.color='#f66'; m.style.textShadow='0 0 12px #f00'; }, 1500);
}

// ---------- Camera follow ----------
function updateCamera(){
  const back = new THREE.Vector3(0, 3, 14).applyQuaternion(ship.quaternion);
  const target = ship.position.clone().add(back);
  camera.position.lerp(target, 0.15);
  camera.lookAt(ship.position);
}

// ---------- Resize ----------
addEventListener('resize', ()=>{
  camera.aspect = innerWidth/innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});

// ---------- Animate ----------
function animate(){
  requestAnimationFrame(animate);
  const dt = Math.min(clock.getDelta(), 0.05);
  updatePlanets(dt);
  physicsStep(dt);
  updateCamera();
  starMesh.rotation.y += dt*0.05;
  renderer.render(scene, camera);
}
animate();
</script>
</body>
</html>
```

## Physics Notes

1. **Newtonian gravity** — each body exerts acceleration `a = G·M / r²` on the ship, summed vectorially. This produces realistic slingshots, orbits, and escape trajectories.
2. **Semi-implicit Euler integration** — velocity is updated before position, which is more stable than explicit Euler for orbital mechanics.
3. **Escape vs. capture** — orbital velocity at distance `r` from mass `M` is roughly `√(GM/r)`. If your speed exceeds `√(2GM/r)` (escape velocity), you break free. Otherwise you're captured.
4. **Soft landing** — approaching a planet below `CRASH_SPEED` (35 u/s) counts as a capture; above it, you crash.

## Gameplay Tips
- Approach planets **tangentially** at moderate speed to enter orbit.
- Burn **prograde** (forward along your velocity) near closest approach for a gravity-assist slingshot.
- The gas giant **Kronos** has enormous mass — use it to fling yourself to the outer system.
- Try to visit all 6 planets without crashing!

