    inset: 0;
    background: rgba(0,0,0,0.9);
    display: none;
    align-items: center;
    justify-content: center;
    z-index: 1500;
    padding: 20px;
  }
  .lightbox.show { display: flex; }
  .lightbox img { max-width: 90%; max-height: 90vh; border-radius: 8px; }
  .lightbox-close {
    position: absolute;
    top: 20px;
    right: 20px;
    background: rgba(255,255,255,0.2);
    border: none;
    color: white;
    width: 40px;
    height: 40px;
    border-radius: 50%;
    font-size: 20px;
    cursor: pointer;
  }

  @media (max-width: 768px) {
    .header-inner { flex-wrap: wrap; }
    nav { order: 3; width: 100%; }
    .msg-container { grid-template-columns: 1fr; height: auto; }
    .msg-sidebar { max-height: 200px; }
    .hero { padding: 32px 24px; }
    .hero h1 { font-size: 26px; }
  }
</style>
</head>
<body>

<header>
  <div class="header-inner">
    <div class="logo" onclick="switchPage('home')">✦ Nova</div>
    <nav id="mainNav">
      <button class="active" data-page="home">Home</button>
      <button data-page="articles">Articles</button>
      <button data-page="photos">Photos</button>
      <button data-page="videos">Videos</button>
      <button data-page="social">Social</button>
      <button data-page="profile">Profile</button>
    </nav>
    <div class="header-actions" id="headerActions">
      <!-- Dynamic: login/register or avatar -->
    </div>
  </div>
</header>

<main>
  <!-- HOME -->
  <section class="page active" id="page-home">
    <div class="hero">
      <h1>Welcome to Nova Blog</h1>
      <p>Share your stories, photos, and videos with a vibrant community. Connect, create, and inspire.</p>
    </div>
    <h2 class="page-title">Featured Articles</h2>
    <p class="page-subtitle">Hand-picked stories from our community</p>
    <div class="grid grid-3" id="featuredArticles"></div>
  </section>

  <!-- ARTICLES -->
  <section class="page" id="page-articles">
    <h2 class="page-title">My Articles</h2>
    <p class="page-subtitle">Thoughts, tutorials, and stories I've written</p>
    <div class="grid grid-3" id="articlesList"></div>
  </section>

  <!-- PHOTOS -->
  <section class="page" id="page-photos">
    <h2 class="page-title">My Photos</h2>
    <p class="page-subtitle">Moments captured through my lens</p>
    <div class="grid grid-4" id="photosList"></div>
  </section>

  <!-- VIDEOS -->
  <section class="page" id="page-videos">
    <h2 class="page-title">My Videos</h2>
    <p class="page-subtitle">Watch my latest video content</p>
    <div class="grid grid-3" id="videosList"></div>
  </section>

  <!-- SOCIAL -->
  <section class="page" id="page-social">
    <h2 class="page-title">Social Circle</h2>
    <p class="page-subtitle">Updates from people you follow</p>
    <div id="socialFeed"></div>
  </section>

  <!-- PROFILE -->
  <section class="page" id="page-profile">
    <div class="profile-header">
      <div class="profile-avatar" id="profileAvatar">N</div>
      <div class="profile-name" id="profileName">Guest User</div>
      <div class="profile-bio" id="profileBio">Welcome to my blog! Click login to get started.</div>
      <div class="profile-stats">
        <div class="stat-item">
          <div class="stat-num" id="statFollowers">0</div>
          <div class="stat-label">Followers</div>
        </div>
        <div class="stat-item">
          <div class="stat-num" id="statFollowing">0</div>
          <div class="stat-label">Following</div>
        </div>
        <div class="stat-item">
          <div class="stat-num" id="statPosts">0</div>
          <div class="stat-label">Posts</div>
        </div>
      </div>
      <button class="btn btn-primary" id="followBtn" onclick="toggleFollow()">Follow</button>
      <button class="btn btn-outline" style="margin-left:8px" onclick="openMessages()">Message</button>
    </div>
    <h3 style="margin-bottom:16px">Recent Activity</h3>
    <div class="grid grid-3" id="profileActivity"></div>
  </section>
</main>

<!-- Login Modal -->
<div class="modal-overlay" id="loginModal">
  <div class="modal">
    <button class="modal-close" onclick="closeModal('loginModal')">&times;</button>
    <h2>Welcome Back</h2>
    <p class="subtitle">Sign in to continue to Nova</p>
    <form onsubmit="handleLogin(event)">
      <div class="form-group">
        <label>Email</label>
        <input type="email" id="loginEmail" required placeholder="you@example.com" />
      </div>
      <div class="form-group">
        <label>Password</label>
        <input type="password" id="loginPassword" required placeholder="••••••••" />
      </div>
      <button type="submit" class="btn btn-primary btn-block">Sign In</button>
    </form>
    <div class="form-footer">
      Don't have an account? <a onclick="switchModal('loginModal','registerModal')">Sign up</a>
    </div>
  </div>
</div>

<!-- Register Modal -->
<div class="modal-overlay" id="registerModal">
  <div class="modal">
    <button class="modal-close" onclick="closeModal('registerModal')">&times;</button>
    <h2>Create Account</h2>
    <p class="subtitle">Join the Nova community today</p>
    <form onsubmit="handleRegister(event)">
      <div class="form-group">
        <label>Full Name</label>
        <input type="text" id="regName" required placeholder="Jane Doe" />
      </div>
      <div class="form-group">
        <label>Email</label>
        <input type="email" id="regEmail" required placeholder="you@example.com" />
      </div>
      <div class="form-group">
        <label>Password</label>
        <input type="password" id="regPassword" required minlength="6" placeholder="At least 6 characters" />
      </div>
      <div class="form-group">
        <label>Bio (optional)</label>
        <textarea id="regBio" placeholder="Tell us about yourself..."></textarea>
      </div>
      <button type="submit" class="btn btn-primary btn-block">Create Account</button>
    </form>
    <div class="form-footer">
      Already have an account? <a onclick="switchModal('registerModal','loginModal')">Sign in</a>
    </div>
  </div>
</div>

<!-- Messages Modal -->
<div class="modal-overlay" id="messagesModal">
  <div class="modal wide">
    <button class="modal-close" onclick="closeModal('messagesModal')">&times;</button>
    <h2 style="margin-bottom:16px">Private Messages</h2>
    <div class="msg-container">
      <div class="msg-sidebar">
        <div class="msg-sidebar-header">Conversations</div>
        <div id="contactsList"></div>
      </div>
      <div class="msg-main" id="msgMain">
        <div class="msg-empty">Select a conversation to start messaging</div>
      </div>
    </div>
  </div>
</div>

<!-- Lightbox -->
<div class="lightbox" id="lightbox" onclick="closeLightbox()">
  <button class="lightbox-close">&times;</button>
  <img id="lightboxImg" src="" alt="" />
</div>

<script>
/* ============ DATA ============ */
const ARTICLES = [
  { id:1, title:"The Art of Minimalist Design", tag:"Design", excerpt:"Exploring how less truly becomes more in modern digital interfaces.", img:"https://picsum.photos/seed/a1/600/400", likes:124, comments:18, date:"Mar 15" },
  { id:2, title:"Building Scalable Web Apps", tag:"Development", excerpt:"A deep dive into architecture patterns that grow with your user base.", img:"https://picsum.photos/seed/a2/600/400", likes:89, comments:12, date:"Mar 12" },
  { id:3, title:"Photography in Golden Hour", tag:"Photography", excerpt:"Tips for capturing stunning images during the magic hour.", img:"https://picsum.photos/seed/a3/600/400", likes:256, comments:34, date:"Mar 10" },
  { id:4, title:"Mindful Productivity Habits", tag:"Lifestyle", excerpt:"How to stay focused without burning out in a distracted world.", img:"https://picsum.photos/seed/a4/600/400", likes:178, comments:22, date:"Mar 8" },
  { id:5, title:"The Future of AI in Creative Work", tag:"Technology", excerpt:"Balancing human creativity with machine intelligence.", img:"https://picsum.photos/seed/a5/600/400", likes:312, comments:45, date:"Mar 5" },
  { id:6, title:"Traveling Solo Through Japan", tag:"Travel", excerpt:"A two-week journey through temples, cities, and countryside.", img:"https://picsum.photos/seed/a6/600/400", likes:421, comments:67, date:"Mar 2" }
];

const PHOTOS = Array.from({length:12}, (_,i) => ({
  id:i+1,
  src:`https://picsum.photos/seed/p${i+1}/500/500`,
  caption:["Mountain sunrise","City lights","Ocean waves","Forest path","Desert dunes","Autumn leaves","Snow peaks","Flower field","Street art","Cafe corner","Bridge view","Night sky"][i]
}));

const VIDEOS = [
  { id:1, title:"Morning Routine for Creators", thumb:"https://picsum.photos/seed/v1/600/400", duration:"8:24", views:"12K" },
  { id:2, title:"Behind the Scenes: Photo Shoot", thumb:"https://picsum.photos/seed/v2/600/400", duration:"12:05", views:"8.4K" },
  { id:3, title:"Coding a Blog from Scratch", thumb:"https://picsum.photos/seed/v3/600/400", duration:"24:18", views:"45K" },
  { id:4, title:"Travel Vlog: Kyoto in Spring", thumb:"https://picsum.photos/seed/v4/600/400", duration:"15:42", views:"23K" },
  { id:5, title:"Design Principles Explained", thumb:"https://picsum.photos/seed/v5/600/400", duration:"10:30", views:"18K" },
  { id:6, title:"Q&A: Your Questions Answered", thumb:"https://picsum.photos/seed/v6/600/400", duration:"18:55", views:"9.2K" }
];

const SOCIAL_POSTS = [
  { author:"Alex Chen", avatar:"A", time:"2h ago", content:"Just finished a 10k run through the park! 🏃‍♂️ Feeling amazing.", img:"https://picsum.photos/seed/s1/800/500", likes:42 },
  { author:"Maya Rodriguez", avatar:"M", time:"5h ago", content:"New recipe alert: homemade sourdough bread. Three days of patience totally worth it! 🍞", img:null, likes:87 },
  { author:"Jordan Lee", avatar:"J", time:"1d ago", content:"Sunset from my balcony tonight was unreal. Sometimes you don't need to travel far.", img:"https://picsum.photos/seed/s2/800/500", likes:156 },
  { author:"Sam Patel", avatar:"S", time:"2d ago", content:"Just launched my new portfolio website! Check it out and let me know what you think. 🚀", img:null, likes:203 }
];

const CONTACTS = [
  { id:1, name:"Alex Chen", avatar:"A", lastMsg:"Hey! How's the project going?", time:"2m" },
  { id:2, name:"Maya Rodriguez", avatar:"M", lastMsg:"Thanks for the feedback!", time:"1h" },
  { id:3, name:"Jordan Lee", avatar:"J", lastMsg:"See you tomorrow 👋", time:"3h" },
  { id:4, name:"Sam Patel", avatar:"S", lastMsg:"That sounds great!", time:"1d" }
];

/* ============ STATE ============ */
let state = {
  user: JSON.parse(localStorage.getItem('nova_user') || 'null'),
  likedArticles: JSON.parse(localStorage.getItem('nova_likes') || '[]'),
  messages: JSON.parse(localStorage.getItem('nova_msgs') || '{}'),
  following: JSON.parse(localStorage.getItem('nova_following') || 'false'),
  followers: parseInt(localStorage.getItem('nova_followers') || '1247'),
  activeContact: null
};

/* ============ NAVIGATION ============ */
function switchPage(page) {
  document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
  document.getElementById('page-' + page).classList.add('active');
  document.querySelectorAll('#mainNav button').forEach(b => {
    b.classList.toggle('active', b.dataset.page === page);
  });
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

document.querySelectorAll('#mainNav button').forEach(btn => {
  btn.addEventListener('click', () => switchPage(btn.dataset.page));
});

/* ============ RENDER ============ */
function renderArticles(containerId, items) {
  const c = document.getElementById(containerId);
  c.innerHTML = items.map(a => `
    <div class="card" onclick="showToast('Opening: ${a.title.replace(/'/g,"\\'")}')">
      <img class="card-img" src="${a.img}" alt="${a.title}" loading="lazy" />
      <div class="card-body">
        <span class="card-tag">${a.tag}</span>
        <div class="card-title">${a.title}</div>
        <div class="card-excerpt">${a.excerpt}</div>
        <div class="card-meta">
          <span>${a.date}</span>
          <div class="card-actions">
            <button class="${state.likedArticles.includes(a.id)?'liked':''}" onclick="event.stopPropagation();toggleLike(${a.id},this)">
              ♥ <span>${a.likes + (state.likedArticles.includes(a.id)?1:0)}</span>
            </button>
            <button>💬 ${a.comments}</button>
          </div>
        </div>
      </div>
    </div>
  `).join('');
}

function renderPhotos() {
  const c = document.getElementById('photosList');
  c.innerHTML = PHOTOS.map(p => `
    <div class="photo-card" onclick="openLightbox('${p.src}')">
      <img src="${p.src}" alt="${p.caption}" loading="lazy" />
      <div class="photo-overlay">${p.caption}</div>
    </div>
  `).join('');
}

function renderVideos() {
  const c = document.getElementById('videosList');
  c.innerHTML = VIDEOS.map(v => `
    <div class="card video-card" onclick="showToast('Playing: ${v.title.replace(/'/g,"\\'")}')">
      <div style="position:relative">
        <img class="card-img" src="${v.thumb}" alt="${v.title}" loading="lazy" />
        <div class="play-icon">▶</div>
        <div class="duration">${v.duration}</div>
      </div>
      <div class="card-body">
        <div class="card-title">${v.title}</div>
        <div class="card-meta">
          <span>${v.views} views</span>
        </div>
      </div>
    </div>
  `).join('');
}

function renderSocial() {
  const c = document.getElementById('socialFeed');
  c.innerHTML = SOCIAL_POSTS.map((p,i) => `
    <div class="post">
      <div class="post-header">
        <div class="avatar">${p.avatar}</div>
        <div class="post-author">
          <strong>${p.author}</strong>
          <small>${p.time}</small>
        </div>
      </div>
      <div class="post-content">
        ${p.content}
        ${p.img ? `<img src="${p.img}" alt="post" loading="lazy" />` : ''}
      </div>
      <div class="post-actions">
        <button onclick="this.classList.toggle('liked');this.style.color=this.classList.contains('liked')?'var(--accent)':''">♥ Like (${p.likes})</button>
        <button>💬 Comment</button>
        <button>↗ Share</button>
      </div>
    </div>
  `).join('');
}

function renderProfile() {
  const u = state.user;
  document.getElementById('profileAvatar').innerHTML = u
    ? (u.avatar ? `<img src="${u.avatar}" />` : u.name.charAt(0).toUpperCase())
    : 'N';
  document.getElementById('profileName').textContent = u ? u.name : 'Guest User';
  document.getElementById('profileBio').textContent = u ? (u.bio || 'No bio yet.') : 'Welcome to my blog! Click login to get started.';
  document.getElementById('statFollowers').textContent = state.followers.toLocaleString();
  document.getElementById('statFollowing').textContent = u ? '342' : '0';
  document.getElementById('statPosts').textContent = ARTICLES.length + PHOTOS.length + VIDEOS.length;
  document.getElementById('followBtn').textContent = state.following ? 'Following ✓' : 'Follow';
  document.getElementById('followBtn').className = state.following ? 'btn btn-outline' : 'btn btn-primary';

  // Activity: mix of articles and photos
  const activity = [
    ...ARTICLES.slice(0,2).map(a => ({type:'article', data:a})),
    ...PHOTOS.slice(0,1).map(p => ({type:'photo', data:p}))
  ];
  const c = document.getElementById('profileActivity');
  c.innerHTML = activity.map(item => {
    if (item.type === 'article') {
      return `<div class="card"><img class="card-img" src="${item.data.img}" /><div class="card-body"><span class="card-tag">${item.data.tag}</span><div class="card-title">${item.data.title}</div></div></div>`;
    } else {
      return `<div class="photo-card"><img src="${item.data.src}" /><div class="photo-overlay">${item.data.caption}</div></div>`;
    }
  }).join('');
}

function renderHeaderActions() {
  const c = document.getElementById('headerActions');
  if (state.user) {
    c.innerHTML = `
      <button class="btn btn-ghost" onclick="openMessages()" title="Messages">✉</button>
      <div style="position:relative">
        <div class="avatar" onclick="toggleAvatarMenu(event)">
          ${state.user.avatar ? `<img src="${state.user.avatar}" />` : state.user.name.charAt(0).toUpperCase()}
        </div>
        <div class="avatar-menu" id="avatarMenu">
          <div class="profile-info">
            <strong>${state.user.name}</strong>
            <small>${state.user.email}</small>
          </div>
          <button onclick="switchPage('profile');closeAvatarMenu()">👤 My Profile</button>
          <button onclick="openMessages();closeAvatarMenu()">✉ Messages</button>
          <button onclick="handleLogout()">🚪 Sign Out</button>
        </div>
      </div>
    `;
  } else {
    c.innerHTML = `
      <button class="btn btn-ghost" onclick="openModal('loginModal')">Log In</button>
      <button class="btn btn-primary" onclick="openModal('registerModal')">Sign Up</button>
    `;
  }
}

/* ============ AUTH ============ */
function handleLogin(e) {
  e.preventDefault();
  const email = document.getElementById('loginEmail').value;
  const password = document.getElementById('loginPassword').value;
  const users = JSON.parse(localStorage.getItem('nova_users') || '[]');
  const user = users.find(u => u.email === email && u.password === password);
  if (user) {
    state.user = user;
    localStorage.setItem('nova_user', JSON.stringify(user));
    closeModal('loginModal');
    renderHeaderActions();
    renderProfile();
    showToast('Welcome back, ' + user.name + '!', 'success');
  } else {
    // Demo: auto-login with any credentials
    const demoUser = { name: email.split('@')[0], email, bio: 'Nova blog member', avatar: null };
    state.user = demoUser;
    localStorage.setItem('nova_user', JSON.stringify(demoUser));
    closeModal('loginModal');
    renderHeaderActions();
    renderProfile();
    showToast('Signed in as ' + demoUser.name, 'success');
  }
}

function handleRegister(e) {
  e.preventDefault();
  const user = {
    name: document.getElementById('regName').value,
    email: document.getElementById('regEmail').value,
    password: document.getElementById('regPassword').value,
    bio: document.getElementById('regBio').value || 'New to Nova!',
    avatar: null
  };
  const users = JSON.parse(localStorage.getItem('nova_users') || '[]');
  if (users.find(u => u.email === user.email)) {
    showToast('Email already registered', 'error');
    return;
  }
  users.push(user);
  localStorage.setItem('nova_users', JSON.stringify(users));
  state.user = user;
  localStorage.setItem('nova_user', JSON.stringify(user));
  closeModal('registerModal');
  renderHeaderActions();
  renderProfile();
  showToast('Account created! Welcome, ' + user.name, 'success');
}

function handleLogout() {
  state.user = null;
  localStorage.removeItem('nova_user');
  closeAvatarMenu();
  renderHeaderActions();
  renderProfile();
  switchPage('home');
  showToast('Signed out successfully');
}

/* ============ INTERACTIONS ============ */
function toggleLike(id, btn) {
  const idx = state.likedArticles.indexOf(id);
  if (idx > -1) {
    state.likedArticles.splice(idx, 1);
    btn.classList.remove('liked');
  } else {
    state.likedArticles.push(id);
    btn.classList.add('liked');
  }
  localStorage.setItem('nova_likes', JSON.stringify(state.likedArticles));
  const span = btn.querySelector('span');
  const article = ARTICLES.find(a => a.id === id);
  span.textContent = article.likes + (state.likedArticles.includes(id) ? 1 : 0);
}

function toggleFollow() {
  if (!state.user) {
    openModal('loginModal');
    showToast('Please sign in to follow', 'error');
    return;
  }
  state.following = !state.following;
  state.followers += state.following ? 1 : -1;
  localStorage.setItem('nova_following', state.following);
  localStorage.setItem('nova_followers', state.followers);
  renderProfile();
  showToast(state.following ? 'Following!' : 'Unfollowed');
}

/* ============ MESSAGES ============ */
function openMessages() {
  if (!state.user) {
    openModal('loginModal');
    showToast('Please sign in to message', 'error');
    return;
  }
  renderContacts();
  openModal('messagesModal');
}

function renderContacts() {
  const c = document.getElementById('contactsList');
  c.innerHTML = CONTACTS.map(ct => {
    const lastMsg = (state.messages[ct.id] || []).slice(-1)[0];
    const preview = lastMsg ? lastMsg.text : ct.lastMsg;
    return `
      <div class="msg-contact ${state.activeContact===ct.id?'active':''}" onclick="selectContact(${ct.id})">
        <div class="avatar">${ct.avatar}</div>
        <div class="msg-contact-info">
          <strong>${ct.name}</strong>
          <small>${preview}</small>
        </div>
      </div>
    `;
  }).join('');
}

function selectContact(id) {
  state.activeContact = id;
  renderContacts();
  renderConversation();
}

function renderConversation() {
  const contact = CONTACTS.find(c => c.id === state.activeContact);
  if (!contact) return;
  const msgs = state.messages[contact.id] || [];
  const main = document.getElementById('msgMain');
  main.innerHTML = `
    <div class="msg-header">
      <div class="avatar">${contact.avatar}</div>
      <div>
        <strong>${contact.name}</strong>
        <div style="font-size:12px;color:var(--muted)">Online</div>
      </div>
    </div>
    <div class="msg-body" id="msgBody">
      ${msgs.length === 0 ? `<div style="text-align:center;color:var(--muted);padding:40px">No messages yet. Say hello! 👋</div>` :
        msgs.map(m => `
          <div class="msg-bubble ${m.sent?'sent':'received'}">
            ${m.text}
            <div class="msg-time">${m.time}</div>
          </div>
        `).join('')
      }
    </div>
    <div class="msg-input-area">
      <input type="text" id="msgInput" placeholder="Type a message..." onkeypress="if(event.key==='Enter')sendMessage()" />
      <button class="btn btn-primary" onclick="sendMessage()">Send</button>
    </div>
  `;
  const body = document.getElementById('msgBody');
  body.scrollTop = body.scrollHeight;
}

function sendMessage() {
  const input = document.getElementById('msgInput');
  const text = input.value.trim();
  if (!text || !state.activeContact) return;
  if (!state.messages[state.activeContact]) state.messages[state.activeContact] = [];
  const now = new Date();
  const time = now.getHours().toString().padStart(2,'0') + ':' + now.getMinutes().toString().padStart(2,'0');
  state.messages[state.activeContact].push({ text, sent: true, time });
  localStorage.setItem('nova_msgs', JSON.stringify(state.messages));
  input.value = '';
  renderConversation();
  renderContacts();

  // Auto-reply demo
  setTimeout(() => {
    const replies = ["That's interesting!","Thanks for sharing 😊","I'll think about it.","Sounds good!","Tell me more!","Haha, nice one!"];
    const reply = replies[Math.floor(Math.random()*replies.length)];
    state.messages[state.activeContact].push({ text: reply, sent: false, time });
    localStorage.setItem('nova_msgs', JSON.stringify(state.messages));
    if (document.getElementById('messagesModal').classList.contains('show')) {
      renderConversation();
      renderContacts();
    }
  }, 1200);
}

/* ============ MODALS ============ */
function openModal(id) { document.getElementById(id).classList.add('show'); }
function closeModal(id) { document.getElementById(id).classList.remove('show'); }
function switchModal(from, to) { closeModal(from); openModal(to); }

document.querySelectorAll('.modal-overlay').forEach(o => {
  o.addEventListener('click', e => { if (e.target === o) o.classList.remove('show'); });
});

/* ============ AVATAR MENU ============ */
function toggleAvatarMenu(e) {
  e.stopPropagation();
  document.getElementById('avatarMenu').classList.toggle('show');
}
function closeAvatarMenu() {
  const m = document.getElementById('avatarMenu');
  if (m) m.classList.remove('show');
}
document.addEventListener('click', closeAvatarMenu);

/* ============ LIGHTBOX ============ */
