from datetime import datetime
from flask import Flask, request, jsonify, render_template_string

app = Flask(__name__)
DB_NAME = 'inventory_system.db'

# ==========================================
# Database Initialization
# ==========================================
def get_db():
    conn = sqlite3.connect(DB_NAME)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS inventory (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            barcode TEXT UNIQUE,
            name TEXT NOT NULL,
            category TEXT,
            quantity INTEGER DEFAULT 0,
            min_threshold INTEGER DEFAULT 0,
            price REAL DEFAULT 0.0,
            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )
    ''')

    # Insert mock data for demonstration if table is empty
    cursor.execute("SELECT COUNT(*) FROM inventory")
    if cursor.fetchone()[0] == 0:
        mock_data = [
            ('8901234567890', 'Wireless Mouse', 'Electronics', 45, 10, 25.99),
            ('5901234123457', 'Mechanical Keyboard', 'Electronics', 8, 10, 89.50),
            ('4006381333931', 'Ergonomic Chair', 'Furniture', 15, 5, 199.00),
            ('012345678905', 'Notebook A5', 'Stationery', 3, 20, 4.99),
            ('9780201379624', 'Programming Book', 'Books', 12, 5, 45.00)
        ]
        cursor.executemany('''
            INSERT INTO inventory (barcode, name, category, quantity, min_threshold, price)
            VALUES (?, ?, ?, ?, ?, ?)
        ''', mock_data)

    conn.commit()
    conn.close()

