@app.route('/')
def index():
    return render_template_string(HTML_TEMPLATE)

@app.route('/api/items', methods=['GET'])
def get_items():
    conn = get_db()
    items = conn.execute("SELECT * FROM inventory ORDER BY updated_at DESC").fetchall()
    conn.close()
    return jsonify([dict(ix) for ix in items])

@app.route('/api/items', methods=['POST'])
def add_item():
    data = request.json
    conn = get_db()
    try:
        conn.execute('''
            INSERT INTO inventory (barcode, name, category, quantity, min_threshold, price)
            VALUES (?, ?, ?, ?, ?, ?)
        ''', (data['barcode'], data['name'], data['category'], data['quantity'], data['min_threshold'], data['price']))
        conn.commit()
        return jsonify({"message": "Item added successfully"}), 201
    except sqlite3.IntegrityError:
        return jsonify({"error": "Barcode already exists"}), 400
    finally:
        conn.close()

@app.route('/api/items/<int:item_id>', methods=['PUT'])
def update_item(item_id):
    data = request.json
    conn = get_db()
    conn.execute('''
        UPDATE inventory 
        SET barcode=?, name=?, category=?, quantity=?, min_threshold=?, price=?, updated_at=CURRENT_TIMESTAMP
        WHERE id=?
    ''', (data['barcode'], data['name'], data['category'], data['quantity'], data['min_threshold'], data['price'], item_id))
    conn.commit()
    conn.close()
    return jsonify({"message": "Item updated successfully"})

@app.route('/api/items/<int:item_id>', methods=['DELETE'])
def delete_item(item_id):
    conn = get_db()
    conn.execute("DELETE FROM inventory WHERE id=?", (item_id,))
    conn.commit()
    conn.close()
    return jsonify({"message": "Item deleted successfully"})

@app.route('/api/reports', methods=['GET'])
def generate_report():
    conn = get_db()
    total_items = conn.execute("SELECT SUM(quantity) FROM inventory").fetchone()[0] or 0
    total_value = conn.execute("SELECT SUM(quantity * price) FROM inventory").fetchone()[0] or 0.0
    low_stock = conn.execute("SELECT * FROM inventory WHERE quantity <= min_threshold").fetchall()
    conn.close()

    return jsonify({
        "summary": {
            "total_units": total_items,
            "total_value": round(total_value, 2),
            "low_stock_count": len(low_stock)
        },
        "low_stock_items": [dict(ix) for ix in low_stock]
    })

