        // --- API Calls ---
        async function fetchItems() {
            const res = await fetch('/api/items');
            items = await res.json();
            renderTable();
            updateDashboard();
        }

        async function saveItem(e) {
            e.preventDefault();
            const id = document.getElementById('item-id').value;
            const payload = {
                barcode: document.getElementById('item-barcode').value,
                name: document.getElementById('item-name').value,
                category: document.getElementById('item-category').value,
                price: parseFloat(document.getElementById('item-price').value),
                quantity: parseInt(document.getElementById('item-quantity').value),
                min_threshold: parseInt(document.getElementById('item-threshold').value)
            };

            const url = id ? `/api/items/${id}` : '/api/items';
            const method = id ? 'PUT' : 'POST';

            const res = await fetch(url, {
                method: method,
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify(payload)
            });

            if (res.ok) {
                showToast(id ? 'Item updated!' : 'Item added!');
                closeModal('item-modal');
                fetchItems();
            } else {
                const err = await res.json();
                showToast(err.error || 'Error saving item', true);
            }
        }

        async function deleteItem(id) {
            if (!confirm('Are you sure you want to delete this item?')) return;
            await fetch(`/api/items/${id}`, { method: 'DELETE' });
            showToast('Item deleted');
            fetchItems();
        }

        // --- UI Rendering ---
        function renderTable() {
            const tbody = document.getElementById('inventory-table-body');
            tbody.innerHTML = items.map(item => {
                const isLow = item.quantity <= item.min_threshold;
                const rowClass = isLow ? 'bg-red-50' : '';
                const qtyClass = isLow ? 'text-red-600 font-bold' : 'text-gray-800';

                return `
                    <tr class="${rowClass} hover:bg-gray-50">
                        <td class="px-6 py-4 whitespace-nowrap text-sm font-mono text-gray-500">${item.barcode}</td>
                        <td class="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">${item.name}</td>
                        <td class="px-6 py-4 whitespace-nowrap text-sm text-gray-500">${item.category || '-'}</td>
                        <td class="px-6 py-4 whitespace-nowrap text-sm ${qtyClass}">
                            ${item.quantity} <span class="text-gray-400 font-normal">/ ${item.min_threshold}</span>
                            ${isLow ? '<i class="fas fa-exclamation-triangle text-red-500 ml-2" title="Low Stock"></i>' : ''}
                        </td>
                        <td class="px-6 py-4 whitespace-nowrap text-sm text-gray-500">$${item.price.toFixed(2)}</td>
                        <td class="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
