                        </td>
                    </tr>
                `;
            }).join('');
        }

        function updateDashboard() {
            const totalUnits = items.reduce((sum, i) => sum + i.quantity, 0);
            const totalValue = items.reduce((sum, i) => sum + (i.quantity * i.price), 0);
            const lowStock = items.filter(i => i.quantity <= i.min_threshold).length;

            document.getElementById('dash-total-units').innerText = totalUnits;
            document.getElementById('dash-total-value').innerText = `$${totalValue.toFixed(2)}`;
            document.getElementById('dash-low-stock').innerText = lowStock;
        }

