        function openScannerModal() {
            document.getElementById('scanner-modal').classList.remove('hidden');
            html5QrCode = new Html5Qrcode("reader");
            html5QrCode.start(
                { facingMode: "environment" },
                { fps: 10, qrbox: { width: 250, height: 150 } },
                onScanSuccess,
                onScanFailure
            ).catch(err => {
                showToast("Camera access denied or not available. Use USB scanner or manual entry.", true);
                stopScanner();
            });
        }

        function stopScanner() {
            if (html5QrCode && html5QrCode.isScanning) {
                html5QrCode.stop().then(() => {
                    html5QrCode.clear();
                    closeModal('scanner-modal');
                }).catch(err => console.log(err));
            } else {
                closeModal('scanner-modal');
            }
        }

        function onScanSuccess(decodedText) {
            stopScanner();
            handleScannedCode(decodedText);
        }

        function onScanFailure(error) { /* Ignore continuous scan failures */ }

        function handleQuickScan() {
            const input = document.getElementById('usb-scanner-input');
            const code = input.value.trim();
            if (code) {
                handleScannedCode(code);
                input.value = '';
            }
        }

        function handleScannedCode(code) {
            const item = items.find(i => i.barcode === code);
            if (item) {
                if (confirm(`Found: ${item.name}\nCurrent Qty: ${item.quantity}\n\nDo you want to add 1 to stock? (Cancel to edit)`)) {
                    quickUpdateQty(item.id, item.quantity + 1, item);
                } else {
                    openItemModal(item);
                }
            } else {
                if (confirm(`Barcode ${code} not found.\n\nDo you want to add it as a new item?`)) {
                    openItemModal();
                    document.getElementById('item-barcode').value = code;
                }
            }
        }

        async function quickUpdateQty(id, newQty, item) {
            const payload = { ...item, quantity: newQty };
            await fetch(`/api/items/${id}`, {
                method: 'PUT',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify(payload)
            });
            showToast(`Updated ${item.name} qty to ${newQty}`);
            fetchItems();
        }

        // --- Reports ---
        async function openReportModal() {
            const res = await fetch('/api/reports');
            const data = await res.json();

            let html = `
                <div class="grid grid-cols-3 gap-4 mb-6">
                    <div class="bg-blue-50 p-4 rounded-lg text-center">
                        <div class="text-2xl font-bold text-blue-600">${data.summary.total_units}</div>
                        <div class="text-sm text-gray-600">Total Units</div>
                    </div>
