                        <div class="text-sm text-gray-600">Low Stock Items</div>
                    </div>
                </div>
            `;

            if (data.low_stock_items.length > 0) {
                html += `<h3 class="text-lg font-bold text-red-600 mb-2"><i class="fas fa-exclamation-triangle mr-2"></i>Restock Required</h3>`;
                html += `<ul class="divide-y divide-gray-200 border rounded-lg">`;
                data.low_stock_items.forEach(i => {
                    html += `
                        <li class="p-3 flex justify-between items-center">
                            <div>
                                <span class="font-medium">${i.name}</span>
