                            </div>
                            <div class="text-red-600 font-bold">
                                ${i.quantity} / ${i.min_threshold}
                            </div>
                        </li>
                    `;
                });
                html += `</ul>`;
            } else {
                html += `<div class="text-center text-green-600 py-4"><i class="fas fa-check-circle text-3xl mb-2"></i><br>All items are sufficiently stocked!</div>`;
            }

            document.getElementById('report-content').innerHTML = html;
            document.getElementById('report-modal').classList.remove('hidden');
        }

        // --- Utilities ---
        function showToast(msg, isError = false) {
            const toast = document.getElementById('toast');
            toast.innerText = msg;
            toast.className = `fixed bottom-5 right-5 px-6 py-3 rounded-lg shadow-lg z-50 text-white ${isError ? 'bg-red-600' : 'bg-gray-800'}`;
            setTimeout(() => { toast.className += ' hidden'; }, 3000);
        }
    </script>
</body>
</html>
"""

