            background: linear-gradient(135deg, #0a0a1a 0%, #1a0a2e 50%, #0a1a2e 100%);
            position: relative;
            overflow: hidden;
        }

        #lobby-screen::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: 
                radial-gradient(circle at 20% 50%, rgba(120, 0, 255, 0.1) 0%, transparent 50%),
                radial-gradient(circle at 80% 20%, rgba(0, 200, 255, 0.1) 0%, transparent 50%),
                radial-gradient(circle at 50% 80%, rgba(255, 0, 100, 0.05) 0%, transparent 50%);
            pointer-events: none;
        }

        .lobby-title {
            font-size: 4rem;
            font-weight: 900;
            text-transform: uppercase;
            letter-spacing: 8px;
            margin-bottom: 10px;
            background: linear-gradient(90deg, #00d4ff, #7b2fff, #ff2d95);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
            text-shadow: none;
            position: relative;
            z-index: 1;
        }

        .lobby-subtitle {
            font-size: 1.1rem;
            color: #8888aa;
            margin-bottom: 50px;
            letter-spacing: 3px;
            text-transform: uppercase;
            position: relative;
            z-index: 1;
        }

        .lobby-container {
            display: flex;
            gap: 30px;
            position: relative;
            z-index: 1;
        }

        .lobby-panel {
            background: rgba(20, 20, 40, 0.8);
            border: 1px solid rgba(100, 100, 200, 0.3);
            border-radius: 16px;
            padding: 35px;
            width: 350px;
            backdrop-filter: blur(10px);
            transition: all 0.3s ease;
        }

        .lobby-panel:hover {
            border-color: rgba(100, 100, 255, 0.6);
            box-shadow: 0 0 30px rgba(100, 100, 255, 0.1);
        }

        .lobby-panel h2 {
            font-size: 1.4rem;
            margin-bottom: 25px;
            color: #00d4ff;
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .lobby-panel h2 .icon {
            font-size: 1.6rem;
        }

        .input-group {
            margin-bottom: 20px;
        }

        .input-group label {
            display: block;
            font-size: 0.85rem;
            color: #8888aa;
            margin-bottom: 8px;
            text-transform: uppercase;
            letter-spacing: 1px;
        }

        .input-group input, .input-group select {
            width: 100%;
            padding: 12px 16px;
            background: rgba(10, 10, 30, 0.8);
            border: 1px solid rgba(100, 100, 200, 0.3);
            border-radius: 8px;
            color: #ffffff;
            font-size: 1rem;
            transition: all 0.3s ease;
            outline: none;
        }

        .input-group input:focus, .input-group select:focus {
            border-color: #00d4ff;
            box-shadow: 0 0 15px rgba(0, 212, 255, 0.2);
        }

        .btn {
            width: 100%;
            padding: 14px 24px;
            border: none;
            border-radius: 8px;
            font-size: 1rem;
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 2px;
            cursor: pointer;
            transition: all 0.3s ease;
            position: relative;
            overflow: hidden;
        }

        .btn-primary {
            background: linear-gradient(135deg, #00d4ff, #7b2fff);
            color: white;
        }

        .btn-primary:hover {
            transform: translateY(-2px);
            box-shadow: 0 8px 25px rgba(0, 212, 255, 0.3);
        }

        .btn-secondary {
            background: linear-gradient(135deg, #ff2d95, #ff6b35);
            color: white;
        }

        .btn-secondary:hover {
            transform: translateY(-2px);
            box-shadow: 0 8px 25px rgba(255, 45, 149, 0.3);
        }

        .room-list {
            max-height: 200px;
            overflow-y: auto;
            margin-bottom: 20px;
        }

        .room-item {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 12px 16px;
            background: rgba(10, 10, 30, 0.6);
            border: 1px solid rgba(100, 100, 200, 0.2);
            border-radius: 8px;
            margin-bottom: 8px;
            cursor: pointer;
            transition: all 0.2s ease;
        }

        .room-item:hover {
            border-color: #00d4ff;
            background: rgba(0, 212, 255, 0.05);
        }

        .room-item .room-name {
            font-weight: 600;
            color: #ffffff;
        }

        .room-item .room-players {
            font-size: 0.85rem;
            color: #00d4ff;
        }

        .room-item .room-status {
            font-size: 0.75rem;
            padding: 3px 8px;
            border-radius: 4px;
            background: rgba(0, 255, 100, 0.2);
            color: #00ff64;
        }

        /* ============================================
           GAME SCREEN STYLES
           ============================================ */
        #game-screen {
            display: none;
            height: 100vh;
            width: 100vw;
            position: relative;
            background: #111118;
        }

        /* Game Canvas */
        #game-canvas {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            cursor: crosshair;
        }

        /* HUD Overlay */
        .hud-overlay {
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            pointer-events: none;
            z-index: 10;
        }

        .hud-overlay > * {
            pointer-events: auto;
        }

        /* Top Bar - Scoreboard */
        .top-bar {
            position: absolute;
            top: 0;
            left: 50%;
            transform: translateX(-50%);
            display: flex;
            align-items: center;
            gap: 20px;
            padding: 10px 30px;
            background: rgba(0, 0, 0, 0.7);
            border-bottom-left-radius: 12px;
            border-bottom-right-radius: 12px;
            backdrop-filter: blur(5px);
        }

        .team-score {
            display: flex;
            align-items: center;
            gap: 15px;
        }

        .score-value {
            font-size: 2rem;
            font-weight: 900;
        }

        .score-red { color: #ff4444; }
        .score-blue { color: #4488ff; }

        .score-divider {
            font-size: 1.5rem;
            color: #555;
        }

        .game-timer {
            font-size: 1.2rem;
            font-weight: 700;
            color: #ffcc00;
            padding: 5px 15px;
            background: rgba(255, 204, 0, 0.1);
            border-radius: 6px;
            border: 1px solid rgba(255, 204, 0, 0.3);
        }

        /* Player Stats - Bottom Left */
        .player-stats {
            position: absolute;
            bottom: 20px;
            left: 20px;
            display: flex;
            flex-direction: column;
            gap: 10px;
        }

        .health-bar-container {
            width: 250px;
            height: 24px;
            background: rgba(0, 0, 0, 0.7);
            border-radius: 12px;
            overflow: hidden;
            border: 1px solid rgba(255, 255, 255, 0.1);
        }

        .health-bar {
            height: 100%;
            background: linear-gradient(90deg, #00ff64, #00cc50);
            border-radius: 12px;
            transition: width 0.3s ease;
            position: relative;
        }

        .health-bar.low {
            background: linear-gradient(90deg, #ff4444, #ff6644);
        }

        .health-bar.medium {
            background: linear-gradient(90deg, #ffaa00, #ffcc00);
        }

        .health-text {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            font-size: 0.75rem;
            font-weight: 700;
            text-shadow: 0 1px 2px rgba(0,0,0,0.8);
        }

        .ammo-display {
            display: flex;
            align-items: center;
            gap: 10px;
            padding: 8px 16px;
            background: rgba(0, 0, 0, 0.7);
            border-radius: 8px;
            border: 1px solid rgba(255, 255, 255, 0.1);
        }

        .ammo-current {
            font-size: 1.8rem;
            font-weight: 900;
            color: #ffffff;
        }

        .ammo-separator {
            font-size: 1.2rem;
            color: #666;
        }

        .ammo-reserve {
            font-size: 1.2rem;
            color: #888;
        }

        /* Weapon Selector - Bottom Center */
        .weapon-selector {
            position: absolute;
            bottom: 20px;
            left: 50%;
            transform: translateX(-50%);
            display: flex;
            gap: 8px;
            padding: 10px 15px;
            background: rgba(0, 0, 0, 0.7);
            border-radius: 12px;
            backdrop-filter: blur(5px);
        }

        .weapon-slot {
            width: 70px;
            height: 70px;
            background: rgba(30, 30, 50, 0.8);
            border: 2px solid rgba(100, 100, 200, 0.3);
            border-radius: 10px;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            transition: all 0.2s ease;
            position: relative;
        }

        .weapon-slot:hover {
            border-color: rgba(100, 100, 255, 0.6);
        }

        .weapon-slot.active {
            border-color: #00d4ff;
            background: rgba(0, 212, 255, 0.1);
            box-shadow: 0 0 15px rgba(0, 212, 255, 0.3);
        }

        .weapon-slot .weapon-icon {
            font-size: 1.5rem;
            margin-bottom: 4px;
        }

        .weapon-slot .weapon-name {
            font-size: 0.6rem;
            color: #aaa;
            text-transform: uppercase;
        }

        .weapon-slot .weapon-key {
            position: absolute;
            top: 4px;
            right: 6px;
            font-size: 0.6rem;
            color: #666;
            font-weight: 700;
        }

        /* Minimap - Top Right */
        .minimap-container {
            position: absolute;
            top: 60px;
            right: 20px;
            width: 180px;
            height: 180px;
            background: rgba(0, 0, 0, 0.7);
            border: 1px solid rgba(100, 100, 200, 0.3);
            border-radius: 10px;
            overflow: hidden;
        }

        #minimap-canvas {
            width: 100%;
            height: 100%;
        }

        /* Kill Feed - Top Right */
        .kill-feed {
            position: absolute;
            top: 60px;
            right: 220px;
            display: flex;
            flex-direction: column;
            gap: 4px;
            max-width: 300px;
        }

        .kill-entry {
            display: flex;
            align-items: center;
            gap: 8px;
            padding: 6px 12px;
            background: rgba(0, 0, 0, 0.6);
            border-radius: 6px;
            font-size: 0.8rem;
            animation: fadeIn 0.3s ease;
            white-space: nowrap;
        }

        @keyframes fadeIn {
            from { opacity: 0; transform: translateX(20px); }
            to { opacity: 1; transform: translateX(0); }
        }

        .kill-entry .killer { color: #ff4444; font-weight: 600; }
        .kill-entry .victim { color: #4488ff; font-weight: 600; }
        .kill-entry .weapon-used { color: #888; font-size: 0.7rem; }

        /* Chat Panel - Bottom Right */
        .chat-panel {
            position: absolute;
            bottom: 20px;
            right: 20px;
            width: 320px;
            height: 280px;
            background: rgba(0, 0, 0, 0.7);
            border: 1px solid rgba(100, 100, 200, 0.2);
            border-radius: 12px;
            display: flex;
            flex-direction: column;
            backdrop-filter: blur(5px);
        }

        .chat-header {
            padding: 10px 15px;
            border-bottom: 1px solid rgba(100, 100, 200, 0.2);
            font-size: 0.85rem;
            font-weight: 600;
            color: #00d4ff;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .chat-messages {
            flex: 1;
            overflow-y: auto;
            padding: 10px 15px;
            display: flex;
            flex-direction: column;
            gap: 6px;
        }

        .chat-message {
            font-size: 0.8rem;
            line-height: 1.4;
        }

        .chat-message .sender {
            font-weight: 600;
            margin-right: 6px;
        }

        .chat-message .sender.team-red { color: #ff6666; }
        .chat-message .sender.team-blue { color: #6699ff; }
        .chat-message .sender.system { color: #ffcc00; }

        .chat-input-container {
            padding: 10px;
            border-top: 1px solid rgba(100, 100, 200, 0.2);
        }

        .chat-input-container input {
            width: 100%;
            padding: 8px 12px;
            background: rgba(10, 10, 30, 0.8);
            border: 1px solid rgba(100, 100, 200, 0.3);
            border-radius: 6px;
            color: #ffffff;
            font-size: 0.85rem;
            outline: none;
        }

        .chat-input-container input:focus {
            border-color: #00d4ff;
        }

        /* Scoreboard Overlay */
        .scoreboard-overlay {
            display: none;
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            width: 700px;
            background: rgba(10, 10, 25, 0.95);
            border: 1px solid rgba(100, 100, 200, 0.3);
            border-radius: 16px;
            padding: 30px;
            backdrop-filter: blur(10px);
            z-index: 100;
        }

        .scoreboard-overlay.visible {
            display: block;
        }

        .scoreboard-title {
            text-align: center;
            font-size: 1.5rem;
            font-weight: 700;
            margin-bottom: 20px;
            color: #00d4ff;
        }

        .scoreboard-table {
            width: 100%;
            border-collapse: collapse;
        }

        .scoreboard-table th {
            padding: 10px 15px;
            text-align: left;
            font-size: 0.75rem;
            text-transform: uppercase;
            color: #666;
            border-bottom: 1px solid rgba(100, 100, 200, 0.2);
        }

        .scoreboard-table td {
            padding: 10px 15px;
            font-size: 0.9rem;
            border-bottom: 1px solid rgba(100, 100, 200, 0.1);
        }

        .scoreboard-table tr.team-red td:first-child {
            border-left: 3px solid #ff4444;
        }

        .scoreboard-table tr.team-blue td:first-child {
            border-left: 3px solid #4488ff;
        }

        .scoreboard-table tr.self {
            background: rgba(0, 212, 255, 0.05);
        }

        /* Crosshair */
        .crosshair {
            position: absolute;
            pointer-events: none;
            z-index: 50;
        }

        /* Damage Indicator */
        .damage-indicator {
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            pointer-events: none;
            z-index: 5;
            opacity: 0;
            transition: opacity 0.1s ease;
        }

        .damage-indicator.active {
            opacity: 1;
            background: radial-gradient(ellipse at center, transparent 50%, rgba(255, 0, 0, 0.3) 100%);
        }

        /* Hit Marker */
        .hit-marker {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            pointer-events: none;
            z-index: 51;
            opacity: 0;
            font-size: 1.5rem;
            color: #ff4444;
        }

        .hit-marker.show {
            animation: hitMarkerAnim 0.3s ease forwards;
        }

        @keyframes hitMarkerAnim {
            0% { opacity: 1; transform: translate(-50%, -50%) scale(1.5); }
            100% { opacity: 0; transform: translate(-50%, -50%) scale(1); }
        }

        /* Respawn Screen */
        .respawn-screen {
            display: none;
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: rgba(0, 0, 0, 0.8);
            z-index: 200;
            flex-direction: column;
            align-items: center;
            justify-content: center;
        }

        .respawn-screen.visible {
            display: flex;
        }

        .respawn-text {
            font-size: 2rem;
            font-weight: 700;
            color: #ff4444;
            margin-bottom: 10px;
        }

        .respawn-timer {
            font-size: 3rem;
            font-weight: 900;
            color: #ffffff;
        }

        /* Notification */
        .notification {
            position: absolute;
            top: 100px;
            left: 50%;
            transform: translateX(-50%);
            padding: 10px 25px;
            background: rgba(0, 0, 0, 0.8);
            border: 1px solid rgba(255, 204, 0, 0.5);
            border-radius: 8px;
            font-size: 0.9rem;
            color: #ffcc00;
            opacity: 0;
            transition: opacity 0.3s ease;
            z-index: 60;
        }

        .notification.visible {
            opacity: 1;
        }

        /* Scrollbar Styles */
        ::-webkit-scrollbar {
            width: 4px;
        }

        ::-webkit-scrollbar-track {
            background: transparent;
        }

        ::-webkit-scrollbar-thumb {
            background: rgba(100, 100, 200, 0.3);
            border-radius: 2px;
        }

        /* Player name tags */
        .player-nametag {
            position: absolute;
            font-size: 0.7rem;
            font-weight: 600;
            text-align: center;
            pointer-events: none;
            text-shadow: 0 1px 3px rgba(0,0,0,0.8);
            z-index: 15;
        }

        /* Muzzle flash effect */
        .muzzle-flash {
            position: absolute;
            width: 20px;
            height: 20px;
            border-radius: 50%;
            background: radial-gradient(circle, #ffff00, #ff8800, transparent);
            pointer-events: none;
            z-index: 20;
            opacity: 0;
        }

        .muzzle-flash.active {
            animation: flashAnim 0.1s ease forwards;
        }

        @keyframes flashAnim {
            0% { opacity: 1; transform: scale(1); }
            100% { opacity: 0; transform: scale(2); }
        }

        /* Game over screen */
        .game-over-screen {
            display: none;
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: rgba(0, 0, 0, 0.9);
            z-index: 300;
            flex-direction: column;
            align-items: center;
            justify-content: center;
        }

        .game-over-screen.visible {
            display: flex;
        }

        .game-over-title {
            font-size: 3rem;
            font-weight: 900;
            margin-bottom: 20px;
        }

        .game-over-title.victory {
            color: #00ff64;
        }

        .game-over-title.defeat {
            color: #ff4444;
        }

        .game-over-stats {
            display: flex;
            gap: 40px;
            margin-bottom: 30px;
        }

        .game-over-stat {
            text-align: center;
        }

        .game-over-stat .stat-value {
            font-size: 2.5rem;
            font-weight: 900;
            color: #00d4ff;
        }

        .game-over-stat .stat-label {
            font-size: 0.8rem;
            color: #888;
            text-transform: uppercase;
        }
    </style>
</head>
<body>
    <!-- ============================================
         LOBBY SCREEN
         ============================================ -->
    <div id="lobby-screen">
        <h1 class="lobby-title">Arena Strike</h1>
        <p class="lobby-subtitle">Multiplayer Tactical Shooter</p>

        <div class="lobby-container">
            <!-- Create Room Panel -->
            <div class="lobby-panel">
                <h2><span class="icon">⚔️</span> Create Room</h2>
                <div class="input-group">
                    <label>Player Name</label>
                    <input type="text" id="player-name" placeholder="Enter your name" value="Player1">
                </div>
                <div class="input-group">
                    <label>Room Name</label>
                    <input type="text" id="room-name" placeholder="Enter room name" value="Battle Arena">
                </div>
                <div class="input-group">
                    <label>Map</label>
                    <select id="map-select">
                        <option value="dust">Dust Valley</option>
                        <option value="urban">Urban Warfare</option>
                        <option value="forest">Dark Forest</option>
                    </select>
                </div>
                <div class="input-group">
                    <label>Max Players</label>
                    <select id="max-players">
                        <option value="4">4 Players</option>
                        <option value="6" selected>6 Players</option>
                        <option value="8">8 Players</option>
                    </select>
                </div>
                <button class="btn btn-primary" onclick="createRoom()">Create & Join</button>
            </div>

            <!-- Join Room Panel -->
            <div class="lobby-panel">
                <h2><span class="icon">🎮</span> Join Room</h2>
                <div class="input-group">
                    <label>Player Name</label>
                    <input type="text" id="join-player-name" placeholder="Enter your name" value="Player2">
                </div>
                <div class="room-list" id="room-list">
                    <!-- Rooms will be populated dynamically -->
                </div>
                <button class="btn btn-secondary" onclick="quickMatch()">Quick Match</button>
            </div>
        </div>
    </div>

    <!-- ============================================
         GAME SCREEN
         ============================================ -->
    <div id="game-screen">
        <!-- Main Game Canvas -->
        <canvas id="game-canvas"></canvas>

        <!-- Minimap Canvas -->
        <div class="minimap-container">
            <canvas id="minimap-canvas"></canvas>
        </div>

        <!-- HUD Overlay -->
        <div class="hud-overlay">
            <!-- Top Bar -->
            <div class="top-bar">
                <div class="team-score">
                    <span class="score-value score-red" id="red-score">0</span>
                    <span class="score-divider">VS</span>
                    <span class="score-value score-blue" id="blue-score">0</span>
                </div>
                <div class="game-timer" id="game-timer">5:00</div>
            </div>

            <!-- Player Stats -->
            <div class="player-stats">
                <div class="health-bar-container">
                    <div class="health-bar" id="health-bar" style="width: 100%">
                        <span class="health-text" id="health-text">100 HP</span>
                    </div>
                </div>
                <div class="ammo-display">
                    <span class="ammo-current" id="ammo-current">30</span>
                    <span class="ammo-separator">/</span>
                    <span class="ammo-reserve" id="ammo-reserve">120</span>
                </div>
            </div>

            <!-- Weapon Selector -->
            <div class="weapon-selector" id="weapon-selector">
                <div class="weapon-slot active" data-weapon="0" onclick="selectWeapon(0)">
                    <span class="weapon-key">1</span>
                    <span class="weapon-icon">🔫</span>
                    <span class="weapon-name">Pistol</span>
                </div>
                <div class="weapon-slot" data-weapon="1" onclick="selectWeapon(1)">
                    <span class="weapon-key">2</span>
                    <span class="weapon-icon">🔫</span>
                    <span class="weapon-name">Rifle</span>
                </div>
                <div class="weapon-slot" data-weapon="2" onclick="selectWeapon(2)">
                    <span class="weapon-key">3</span>
                    <span class="weapon-icon">💥</span>
                    <span class="weapon-name">Shotgun</span>
                </div>
                <div class="weapon-slot" data-weapon="3" onclick="selectWeapon(3)">
                    <span class="weapon-key">4</span>
                    <span class="weapon-icon">🎯</span>
                    <span class="weapon-name">Sniper</span>
                </div>
            </div>

            <!-- Kill Feed -->
            <div class="kill-feed" id="kill-feed"></div>

            <!-- Chat Panel -->
            <div class="chat-panel">
                <div class="chat-header">
                    <span>💬 Team Chat</span>
                    <span style="font-size: 0.7rem; color: #666;">Press Enter to chat</span>
                </div>
                <div class="chat-messages" id="chat-messages"></div>
                <div class="chat-input-container">
                    <input type="text" id="chat-input" placeholder="Type a message..." 
