            'They\'re on the right side!', 'GG', 'One more round!'
        ];

        // ============================================
        // INITIALIZATION
        // ============================================

        /**
         * Initialize the lobby screen with mock room data
         */
        function initLobby() {
            const roomList = document.getElementById('room-list');
            roomList.innerHTML = '';

            mockRooms.forEach(room => {
                const roomItem = document.createElement('div');
                roomItem.className = 'room-item';
                roomItem.innerHTML = `
                    <div>
                        <div class="room-name">${room.name}</div>
                        <div class="room-players">${room.players}/${room.maxPlayers} players • ${room.map}</div>
                    </div>
                    <span class="room-status" style="${room.status === 'full' ? 'background: rgba(255,50,50,0.2); color: #ff5555;' : ''}">
                        ${room.status === 'full' ? 'Full' : 'Open'}
                    </span>
                `;
                if (room.status !== 'full') {
                    roomItem.onclick = () => joinRoom(room);
                }
                roomList.appendChild(roomItem);
            });
        }

        /**
         * Create a new room and start the game
         */
        function createRoom() {
            const name = document.getElementById('player-name').value || 'Player1';
            player.name = name;
            startGame();
        }

        /**
         * Join an existing room
         */
        function joinRoom(room) {
            const name = document.getElementById('join-player-name').value || 'Player2';
            player.name = name;
            startGame();
        }

        /**
         * Quick match - auto join a room
         */
        function quickMatch() {
            const name = document.getElementById('join-player-name').value || 'Player2';
            player.name = name;
            startGame();
        }

        /**
         * Transition from lobby to game screen
         */
        function startGame() {
            document.getElementById('lobby-screen').style.display = 'none';
            document.getElementById('game-screen').style.display = 'block';

            initGame();
        }

        /**
         * Initialize the game - set up canvas, players, and start game loop
         */
        function initGame() {
            // Set up main canvas
            canvas = document.getElementById('game-canvas');
            ctx = canvas.getContext('2d');
            resizeCanvas();

            // Set up minimap canvas
            minimapCanvas = document.getElementById('minimap-canvas');
            minimapCtx = minimapCanvas.getContext('2d');
            minimapCanvas.width = 180;
            minimapCanvas.height = 180;

            // Reset game state
            gameState = {
                running: true,
                paused: false,
                timeRemaining: 300,
                redScore: 0,
                blueScore: 0,
                scoreLimit: 30
            };

            // Reset player
            const spawnPoint = SPAWN_POINTS.red[0];
            player.x = spawnPoint.x;
            player.y = spawnPoint.y;
            player.health = PLAYER_MAX_HEALTH;
            player.kills = 0;
            player.deaths = 0;
            player.assists = 0;
            player.alive = true;
            player.currentWeapon = 0;
            player.weapons = WEAPONS.map(w => ({ ...w, currentAmmo: w.ammo, reserveAmmo: w.maxAmmo }));
            player.isReloading = false;

            // Create AI players (simulated other players)
            createAIPlayers();

            // Clear bullets and effects
            bullets = [];
            effects = [];
            chatMessages = [];
            killFeedEntries = [];

            // Set up event listeners
            setupEventListeners();

            // Add system message
            addChatMessage('System', 'Game started! Good luck!', 'system');
            addChatMessage('System', `Room: Battle Arena | Map: Dust Valley`, 'system');

            // Start game loop
            if (animFrameId) cancelAnimationFrame(animFrameId);
            gameLoop();

            // Start game timer
            startGameTimer();

            // Start AI chat simulation
            startAIChatSimulation();
        }

        /**
         * Create AI-controlled players to simulate multiplayer
         */
        function createAIPlayers() {
            otherPlayers = [];

            // Create 2 teammates (red team)
            for (let i = 0; i < 2; i++) {
                const spawn = SPAWN_POINTS.red[i + 1];
                otherPlayers.push({
                    id: `ai_red_${i}`,
                    name: aiNames[i],
                    x: spawn.x + Math.random() * 100,
                    y: spawn.y + Math.random() * 100,
                    angle: 0,
                    health: PLAYER_MAX_HEALTH,
                    team: 'red',
                    kills: 0,
                    deaths: 0,
                    assists: 0,
                    currentWeapon: Math.floor(Math.random() * 4),
                    alive: true,
                    respawnTimer: 0,
                    targetX: 0,
                    targetY: 0,
                    moveTimer: 0,
                    shootTimer: 0,
                    lastShotTime: 0,
                    speed: 2.5 + Math.random() * 1.5
                });
            }

            // Create 3 enemies (blue team)
            for (let i = 0; i < 3; i++) {
                const spawn = SPAWN_POINTS.blue[i];
                otherPlayers.push({
                    id: `ai_blue_${i}`,
                    name: aiNames[i + 3],
                    x: spawn.x + Math.random() * 100,
                    y: spawn.y + Math.random() * 100,
                    angle: 0,
                    health: PLAYER_MAX_HEALTH,
                    team: 'blue',
                    kills: 0,
                    deaths: 0,
                    assists: 0,
                    currentWeapon: Math.floor(Math.random() * 4),
                    alive: true,
                    respawnTimer: 0,
                    targetX: 0,
                    targetY: 0,
                    moveTimer: 0,
                    shootTimer: 0,
                    lastShotTime: 0,
                    speed: 2.5 + Math.random() * 1.5
                });
