</style>
</head>
<body>

<!-- Header -->
<header class="header">
  <div class="logo" onclick="switchTab('designer')">
    <div class="logo-icon">🏠</div>
    <span>FurniSpace</span>
  </div>
  <div class="header-actions">
    <button class="header-btn" onclick="openModal('plansModal')">
      📐 My Plans
    </button>
    <button class="header-btn" onclick="openModal('accountModal')">
      👤 Account
    </button>
    <button class="header-btn" onclick="openModal('cartModal')" style="position:relative">
      🛒 Cart
      <span class="cart-badge hidden" id="cartBadge">0</span>
    </button>
  </div>
</header>

<!-- Navigation -->
<nav class="nav-tabs">
  <div class="nav-tab active" data-tab="designer" onclick="switchTab('designer')">
    🎨 Room Designer
  </div>
  <div class="nav-tab" data-tab="catalog" onclick="switchTab('catalog')">
    🪑 Full Catalog
  </div>
</nav>

<!-- Main Content -->
<div class="main-container">
  <!-- Sidebar -->
  <aside class="sidebar" id="sidebar">
    <div class="sidebar-header">
      <h3>🪑 Furniture Catalog</h3>
      <input type="text" class="search-box" placeholder="Search furniture..." oninput="filterFurniture(this.value)">
    </div>
    <div class="category-pills" id="categoryPills"></div>
    <div class="furniture-list" id="furnitureList"></div>
  </aside>

  <!-- Room Designer -->
  <main class="room-area">
    <div class="room-toolbar">
      <div class="toolbar-group">
        <div class="room-size-selector">
          <span style="font-size:13px;font-weight:700;">Room:</span>
          <select id="roomSizeSelect" onchange="changeRoomSize(this.value)">
            <option value="800x600">Standard (8m × 6m)</option>
            <option value="1000x700">Large (10m × 7m)</option>
            <option value="600x500">Small (6m × 5m)</option>
            <option value="1200x800">XL (12m × 8m)</option>
          </select>
        </div>
      </div>
      <div class="toolbar-group">
        <button class="tool-btn" onclick="toggleGrid()" id="gridBtn">
          ⊞ Grid
        </button>
        <button class="tool-btn" onclick="clearRoom()" >
          🗑️ Clear
        </button>
        <button class="tool-btn" onclick="savePlan()">
          💾 Save Plan
        </button>
        <button class="tool-btn" onclick="openShareModal()">
