      <div class="room-size-info" id="roomInfo">800 × 600 px | 20 items placed</div>
    </div>
    <div class="room-canvas-wrapper" id="roomWrapper">
      <div class="room-canvas" id="roomCanvas"
           ondragover="handleDragOver(event)"
           ondrop="handleDrop(event)"
           ondragleave="handleDragLeave(event)">
        <div class="room-label">🏠 Virtual Room Preview</div>
        <div class="room-dimensions" id="roomDims">8m × 6m</div>
        <div class="drop-indicator" id="dropIndicator"></div>

        <!-- Wall decorations -->
        <div class="wall-element door" style="bottom:-4px;left:100px;" title="Door"></div>
        <div class="wall-element window-el" style="top:-3px;left:200px;" title="Window"></div>
        <div class="wall-element window-el" style="top:-3px;left:500px;" title="Window"></div>
