<script>
// ==================== DATA ====================
const FURNITURE_DATA = [
  // Living Room
  { id: 'sofa-1', name: 'Modern Sofa', category: 'Living Room', icon: '🛋️', color: '#8B7355', w: 160, h: 70, price: 899 },
