  { id: 'rug', name: 'Area Rug', category: 'Living Room', icon: '🟫', color: '#C19A6B', w: 160, h: 120, price: 249 },

  // Bedroom
  { id: 'bed-king', name: 'King Bed', category: 'Bedroom', icon: '🛏️', color: '#7B68AE', w: 160, h: 180, price: 1199 },
  { id: 'bed-queen', name: 'Queen Bed', category: 'Bedroom', icon: '🛏️', color: '#9370DB', w: 140, h: 160, price: 899 },
  { id: 'bed-single', name: 'Single Bed', category: 'Bedroom', icon: '🛏️', color: '#B0A0D0', w: 90, h: 160, price: 549 },
  { id: 'nightstand', name: 'Nightstand', category: 'Bedroom', icon: '🪵', color: '#A0522D', w: 45, h: 40, price: 179 },
  { id: 'wardrobe', name: 'Wardrobe', category: 'Bedroom', icon: '🚪', color: '#8B7355', w: 120, h: 55, price: 799 },
  { id: 'dresser', name: 'Dresser', category: 'Bedroom', icon: '🗄️', color: '#CD853F', w: 110, h: 45, price: 549 },
  { id: 'vanity', name: 'Vanity Table', category: 'Bedroom', icon: '🪞', color: '#DDA0DD', w: 90, h: 40, price: 399 },

  // Kitchen & Dining
  { id: 'dining-table', name: 'Dining Table', category: 'Kitchen', icon: '🍽️', color: '#DEB887', w: 140, h: 80, price: 699 },
  { id: 'dining-chair', name: 'Dining Chair', category: 'Kitchen', icon: '🪑', color: '#A0522D', w: 40, h: 40, price: 149 },
  { id: 'bar-stool', name: 'Bar Stool', category: 'Kitchen', icon: '🪑', color: '#696969', w: 35, h: 35, price: 119 },
  { id: 'kitchen-island', name: 'Kitchen Island', category: 'Kitchen', icon: '🏝️', color: '#F5F5DC', w: 120, h: 60, price: 899 },
  { id: 'buffet', name: 'Buffet Cabinet', category: 'Kitchen', icon: '🗄️', color: '#8B7355', w: 130, h: 45, price: 599 },

  // Office
  { id: 'office-desk', name: 'Office Desk', category: 'Office', icon: '🖥️', color: '#4A4A4A', w: 120, h: 60, price: 499 },
  { id: 'office-chair', name: 'Office Chair', category: 'Office', icon: '💺', color: '#2F4F4F', w: 50, h: 50, price: 349 },
  { id: 'filing-cabinet', name: 'Filing Cabinet', category: 'Office', icon: '🗄️', color: '#808080', w: 45, h: 55, price: 199 },
  { id: 'standing-desk', name: 'Standing Desk', category: 'Office', icon: '🖥️', color: '#556B2F', w: 130, h: 65, price: 699 },
  { id: 'monitor-stand', name: 'Monitor Stand', category: 'Office', icon: '🖥️', color: '#333', w: 50, h: 25, price: 79 },

  // Bathroom
  { id: 'bathtub', name: 'Bathtub', category: 'Bathroom', icon: '🛁', color: '#E0E0E0', w: 140, h: 65, price: 899 },
  { id: 'toilet', name: 'Toilet', category: 'Bathroom', icon: '🚽', color: '#F5F5F5', w: 40, h: 55, price: 299 },
  { id: 'sink-vanity', name: 'Sink Vanity', category: 'Bathroom', icon: '🚰', color: '#B0C4DE', w: 90, h: 45, price: 449 },
  { id: 'shower', name: 'Shower Enclosure', category: 'Bathroom', icon: '🚿', color: '#ADD8E6', w: 80, h: 80, price: 699 },

  // Outdoor
  { id: 'patio-table', name: 'Patio Table', category: 'Outdoor', icon: '☂️', color: '#228B22', w: 100, h: 100, price: 399 },
  { id: 'patio-chair', name: 'Patio Chair', category: 'Outdoor', icon: '🪑', color: '#2E8B57', w: 50, h: 50, price: 179 },
  { id: 'hammock', name: 'Hammock', category: 'Outdoor', icon: '🏖️', color: '#F4A460', w: 140, h: 50, price: 199 },
  { id: 'planter', name: 'Large Planter', category: 'Outdoor', icon: '🪴', color: '#8B4513', w: 40, h: 40, price: 89 },
  { id: 'bbq-grill', name: 'BBQ Grill', category: 'Outdoor', icon: '🔥', color: '#333', w: 80, h: 50, price: 599 },
];

const CATEGORIES = ['All', 'Living Room', 'Bedroom', 'Kitchen', 'Office', 'Bathroom', 'Outdoor'];

// ==================== STATE ====================
let state = {
  user: null,
  cart: [],
  placedItems: [],
  savedPlans: [],
  activeCategory: 'All',
  searchQuery: '',
  selectedItemId: null,
  gridVisible: true,
  roomWidth: 800,
  roomHeight: 600,
  viewMode: false,
  dragData: null,
  nextItemId: 1,
};

// ==================== INIT ====================
function init() {
  loadState();
  renderCategories();
  renderFurnitureList();
  updateCartBadge();
  renderPlacedItems();
  updateRoomInfo();
  checkSharedLink();
  renderAccount();
}

function loadState() {
  try {
    const saved = localStorage.getItem('furnispace_state');
    if (saved) {
      const parsed = JSON.parse(saved);
      state.user = parsed.user || null;
      state.cart = parsed.cart || [];
      state.savedPlans = parsed.savedPlans || [];
      state.nextItemId = parsed.nextItemId || 1;
    }
  } catch(e) {}
}

function saveState() {
  try {
    localStorage.setItem('furnispace_state', JSON.stringify({
      user: state.user,
      cart: state.cart,
      savedPlans: state.savedPlans,
      nextItemId: state.nextItemId,
    }));
  } catch(e) {}
}

// ==================== CATEGORIES ====================
function renderCategories() {
  const container = document.getElementById('categoryPills');
  container.innerHTML = CATEGORIES.map(cat => `
    <div class="category-pill ${state.activeCategory === cat ? 'active' : ''}"
         onclick="selectCategory('${cat}')">
      ${getCategoryEmoji(cat)} ${cat}
    </div>
  `).join('');
}

function getCategoryEmoji(cat) {
  const map = { 'All': '🏠', 'Living Room': '🛋️', 'Bedroom': '🛏️', 'Kitchen': '🍽️', 'Office': '🖥️', 'Bathroom': '🛁', 'Outdoor': '🌿' };
  return map[cat] || '📦';
}

function selectCategory(cat) {
  state.activeCategory = cat;
  renderCategories();
  renderFurnitureList();
}

// ==================== FURNITURE LIST ====================
function renderFurnitureList() {
  const container = document.getElementById('furnitureList');
  let items = FURNITURE_DATA;

  if (state.activeCategory !== 'All') {
    items = items.filter(i => i.category === state.activeCategory);
  }

  if (state.searchQuery) {
    const q = state.searchQuery.toLowerCase();
    items = items.filter(i => i.name.toLowerCase().includes(q) || i.category.toLowerCase().includes(q));
  }

  if (items.length === 0) {
    container.innerHTML = `
      <div class="empty-state">
        <div class="empty-icon">🔍</div>
        <p>No furniture found</p>
      </div>
    `;
    return;
  }

  container.innerHTML = items.map(item => `
    <div class="furniture-item"
         draggable="true"
         ondragstart="handleDragStart(event, '${item.id}')"
         ondragend="handleDragEnd(event)">
      <div class="furniture-preview" style="background:${item.color}20;">
        ${item.icon}
      </div>
      <div class="furniture-info">
        <div class="furniture-name">${item.name}</div>
        <div class="furniture-dims">${item.w}×${item.h}px · ${item.category}</div>
        <div class="furniture-price">$${item.price.toLocaleString()}</div>
      </div>
      <button class="add-cart-btn" onclick="event.stopPropagation();addToCart('${item.id}')" title="Add to cart">
        +
      </button>
    </div>
  `).join('');
}

function filterFurniture(query) {
  state.searchQuery = query;
  renderFurnitureList();
}

// ==================== DRAG & DROP ====================
function handleDragStart(e, itemId) {
  state.dragData = itemId;
  e.dataTransfer.setData('text/plain', itemId);
  e.dataTransfer.effectAllowed = 'copy';

  const item = FURNITURE_DATA.find(i => i.id === itemId);
  if (item) {
    const ghost = document.createElement('div');
    ghost.className = 'drag-ghost';
    ghost.style.width = item.w + 'px';
    ghost.style.height = item.h + 'px';
    ghost.style.background = item.color + '40';
    ghost.textContent = item.icon;
    ghost.style.fontSize = '28px';
    document.body.appendChild(ghost);
    e.dataTransfer.setDragImage(ghost, item.w/2, item.h/2);
    setTimeout(() => ghost.remove(), 0);
  }
}

function handleDragEnd(e) {
  state.dragData = null;
  document.getElementById('dropIndicator').style.display = 'none';
}

function handleDragOver(e) {
  e.preventDefault();
  e.dataTransfer.dropEffect = 'copy';

  const itemId = state.dragData || e.dataTransfer.types.includes('text/plain') ? state.dragData : null;
  if (!itemId) return;

  const item = FURNITURE_DATA.find(i => i.id === itemId);
  if (!item) return;

  const canvas = document.getElementById('roomCanvas');
  const rect = canvas.getBoundingClientRect();
  const x = Math.round((e.clientX - rect.left) / 10) * 10;
  const y = Math.round((e.clientY - rect.top) / 10) * 10;

  const indicator = document.getElementById('dropIndicator');
  indicator.style.display = 'block';
  indicator.style.left = Math.max(0, Math.min(x - item.w/2, state.roomWidth - item.w)) + 'px';
  indicator.style.top = Math.max(0, Math.min(y - item.h/2, state.roomHeight - item.h)) + 'px';
  indicator.style.width = item.w + 'px';
  indicator.style.height = item.h + 'px';
}

function handleDragLeave(e) {
  document.getElementById('dropIndicator').style.display = 'none';
}

function handleDrop(e) {
  e.preventDefault();
  document.getElementById('dropIndicator').style.display = 'none';

  const itemId = e.dataTransfer.getData('text/plain') || state.dragData;
  if (!itemId) return;

  const item = FURNITURE_DATA.find(i => i.id === itemId);
  if (!item) return;

  const canvas = document.getElementById('roomCanvas');
  const rect = canvas.getBoundingClientRect();
  let x = e.clientX - rect.left - item.w / 2;
  let y = e.clientY - rect.top - item.h / 2;

  // Snap to grid
  x = Math.round(x / 10) * 10;
  y = Math.round(y / 10) * 10;

  // Clamp
  x = Math.max(0, Math.min(x, state.roomWidth - item.w));
  y = Math.max(0, Math.min(y, state.roomHeight - item.h));

  const placedItem = {
    uid: 'placed_' + state.nextItemId++,
    id: item.id,
    name: item.name,
    icon: item.icon,
    color: item.color,
    w: item.w,
    h: item.h,
    x: x,
    y: y,
    rotation: 0,
    price: item.price,
  };

  state.placedItems.push(placedItem);
  renderPlacedItems();
  updateRoomInfo();
  showToast(`${item.icon} ${item.name} placed!`, 'success');
}

// ==================== PLACED ITEMS ====================
function renderPlacedItems() {
  const canvas = document.getElementById('roomCanvas');

  // Remove old placed items
  canvas.querySelectorAll('.placed-furniture').forEach(el => el.remove());

  state.placedItems.forEach(item => {
    const el = document.createElement('div');
    el.className = 'placed-furniture' + (state.selectedItemId === item.uid ? ' selected' : '');
    el.style.left = item.x + 'px';
    el.style.top = item.y + 'px';
    el.style.width = item.w + 'px';
    el.style.height = item.h + 'px';
    el.style.background = item.color + '30';
    el.style.transform = `rotate(${item.rotation || 0}deg)`;
    el.dataset.uid = item.uid;

    el.innerHTML = `
      <span class="item-icon">${item.icon}</span>
      <span class="item-label">${item.name}</span>
      <button class="delete-btn" onclick="event.stopPropagation();removePlacedItem('${item.uid}')" title="Remove">✕</button>
      <button class="rotate-handle" onclick="event.stopPropagation();rotateItem('${item.uid}')" title="Rotate">↻</button>
    `;

    // Click to select
    el.addEventListener('mousedown', (e) => {
      if (e.target.classList.contains('delete-btn') || e.target.classList.contains('rotate-handle')) return;
      selectItem(item.uid);
      startDragPlaced(e, item.uid);
    });

    canvas.appendChild(el);
  });
}

function selectItem(uid) {
  state.selectedItemId = uid;
  renderPlacedItems();
}

function removePlacedItem(uid) {
  const item = state.placedItems.find(i => i.uid === uid);
  state.placedItems = state.placedItems.filter(i => i.uid !== uid);
  if (state.selectedItemId === uid) state.selectedItemId = null;
  renderPlacedItems();
  updateRoomInfo();
  if (item) showToast(`${item.icon} ${item.name} removed`, '');
}

function rotateItem(uid) {
  const item = state.placedItems.find(i => i.uid === uid);
  if (item) {
    item.rotation = ((item.rotation || 0) + 90) % 360;
    renderPlacedItems();
  }
}

// Drag placed items within room
function startDragPlaced(e, uid) {
  e.preventDefault();
  const item = state.placedItems.find(i => i.uid === uid);
  if (!item) return;

  const canvas = document.getElementById('roomCanvas');
  const canvasRect = canvas.getBoundingClientRect();
  const startX = e.clientX;
  const startY = e.clientY;
  const origX = item.x;
  const origY = item.y;

  function onMove(ev) {
    const dx = ev.clientX - startX;
    const dy = ev.clientY - startY;
    let newX = origX + dx;
    let newY = origY + dy;

    // Snap
    newX = Math.round(newX / 10) * 10;
    newY = Math.round(newY / 10) * 10;

    // Clamp
    newX = Math.max(0, Math.min(newX, state.roomWidth - item.w));
    newY = Math.max(0, Math.min(newY, state.roomHeight - item.h));

    item.x = newX;
    item.y = newY;

    const el = canvas.querySelector(`[data-uid="${uid}"]`);
    if (el) {
      el.style.left = newX + 'px';
      el.style.top = newY + 'px';
    }
  }

  function onUp() {
    document.removeEventListener('mousemove', onMove);
    document.removeEventListener('mouseup', onUp);
    updateRoomInfo();
  }

  document.addEventListener('mousemove', onMove);
  document.addEventListener('mouseup', onUp);
}

// ==================== ROOM CONTROLS ====================
function changeRoomSize(val) {
  const [w, h] = val.split('x').map(Number);
  state.roomWidth = w;
  state.roomHeight = h;

  const canvas = document.getElementById('roomCanvas');
  canvas.style.width = w + 'px';
  canvas.style.height = h + 'px';

  const wm = (w / 100).toFixed(0);
  const hm = (h / 100).toFixed(0);
  document.getElementById('roomDims').textContent = `${wm}m × ${hm}m`;

  // Clamp placed items
  state.placedItems.forEach(item => {
    item.x = Math.min(item.x, w - item.w);
    item.y = Math.min(item.y, h - item.h);
  });

  renderPlacedItems();
  updateRoomInfo();
}

function toggleGrid() {
  state.gridVisible = !state.gridVisible;
  const canvas = document.getElementById('roomCanvas');
  const btn = document.getElementById('gridBtn');

  if (state.gridVisible) {
    canvas.style.backgroundImage = `
      linear-gradient(rgba(0,0,0,0.03) 1px, transparent 1px),
      linear-gradient(90deg, rgba(0,0,0,0.03) 1px, transparent 1px)`;
    btn.classList.add('active');
  } else {
    canvas.style.backgroundImage = 'none';
    btn.classList.remove('active');
  }
}

function clearRoom() {
  if (state.placedItems.length === 0) return;
  if (confirm('Clear all furniture from the room?')) {
    state.placedItems = [];
    state.selectedItemId = null;
    renderPlacedItems();
    updateRoomInfo();
    showToast('Room cleared', '');
  }
}

function updateRoomInfo() {
  document.getElementById('roomInfo').textContent =
    `${state.roomWidth} × ${state.roomHeight} px | ${state.placedItems.length} items placed`;
}

// ==================== CART ====================
function addToCart(itemId) {
  const item = FURNITURE_DATA.find(i => i.id === itemId);
  if (!item) return;

  const existing = state.cart.find(c => c.id === itemId);
  if (existing) {
    existing.qty++;
  } else {
    state.cart.push({ id: itemId, qty: 1 });
  }

  updateCartBadge();
  saveState();
  showToast(`${item.icon} ${item.name} added to cart!`, 'success');
}

function removeFromCart(itemId) {
  state.cart = state.cart.filter(c => c.id !== itemId);
  updateCartBadge();
  renderCart();
  saveState();
}

function updateCartQty(itemId, delta) {
  const item = state.cart.find(c => c.id === itemId);
  if (!item) return;
  item.qty += delta;
  if (item.qty <= 0) {
    removeFromCart(itemId);
    return;
  }
  updateCartBadge();
  renderCart();
  saveState();
}

function clearCart() {
  if (confirm('Clear all items from cart?')) {
    state.cart = [];
    updateCartBadge();
    renderCart();
    saveState();
    showToast('Cart cleared', '');
  }
}

function updateCartBadge() {
  const badge = document.getElementById('cartBadge');
  const total = state.cart.reduce((sum, c) => sum + c.qty, 0);
  badge.textContent = total;
  badge.classList.toggle('hidden', total === 0);
}

function renderCart() {
  const body = document.getElementById('cartBody');
  const footer = document.getElementById('cartFooter');

  if (state.cart.length === 0) {
    body.innerHTML = `
      <div class="empty-state">
        <div class="empty-icon">🛒</div>
        <p>Your cart is empty</p>
        <p style="font-size:12px;margin-top:8px;">Browse the catalog and add items</p>
      </div>
    `;
    footer.style.display = 'none';
    return;
  }

  let subtotal = 0;
  let html = '';

  state.cart.forEach(cartItem => {
    const item = FURNITURE_DATA.find(i => i.id === cartItem.id);
    if (!item) return;
    const lineTotal = item.price * cartItem.qty;
    subtotal += lineTotal;

    html += `
      <div class="cart-item">
        <div class="cart-item-icon" style="background:${item.color}20;">${item.icon}</div>
        <div class="cart-item-info">
          <div class="cart-item-name">${item.name}</div>
          <div class="cart-item-price">$${item.price.toLocaleString()} × ${cartItem.qty} = $${lineTotal.toLocaleString()}</div>
        </div>
        <div class="cart-qty">
          <button class="qty-btn" onclick="updateCartQty('${item.id}', -1)">−</button>
          <span class="qty-num">${cartItem.qty}</span>
          <button class="qty-btn" onclick="updateCartQty('${item.id}', 1)">+</button>
        </div>
        <button class="cart-remove" onclick="removeFromCart('${item.id}')">🗑️</button>
      </div>
    `;
  });

  const tax = Math.round(subtotal * 0.08);
  const shipping = subtotal > 1000 ? 0 : 49;
  const total = subtotal + tax + shipping;

  html += `
    <div class="cart-summary">
      <div class="cart-summary-row">
        <span>Subtotal (${state.cart.reduce((s,c) => s+c.qty, 0)} items)</span>
        <span>$${subtotal.toLocaleString()}</span>
      </div>
      <div class="cart-summary-row">
        <span>Tax (8%)</span>
        <span>$${tax.toLocaleString()}</span>
      </div>
      <div class="cart-summary-row">
        <span>Shipping ${shipping === 0 ? '🎉 FREE' : ''}</span>
        <span>${shipping === 0 ? 'FREE' : '$' + shipping}</span>
      </div>
      ${shipping > 0 ? '<div style="font-size:11px;color:var(--success);font-weight:600;margin-bottom:8px;">💡 Free shipping on orders over $1,000!</div>' : ''}
      <div class="cart-summary-row total">
        <span>Total</span>
        <span>$${total.toLocaleString()}</span>
      </div>
    </div>
  `;

  body.innerHTML = html;
  footer.style.display = 'flex';
}

function checkout() {
  if (!state.user) {
    closeModal('cartModal');
    openModal('loginModal');
    showToast('Please sign in to checkout', 'error');
    return;
  }

  const total = calculateTotal();
  showToast(`🎉 Order placed! Total: $${total.toLocaleString()}`, 'success');
  state.cart = [];
  updateCartBadge();
  renderCart();
  saveState();
  setTimeout(() => closeModal('cartModal'), 1500);
}

function calculateTotal() {
  let subtotal = 0;
  state.cart.forEach(cartItem => {
    const item = FURNITURE_DATA.find(i => i.id === cartItem.id);
    if (item) subtotal += item.price * cartItem.qty;
  });
  const tax = Math.round(subtotal * 0.08);
  const shipping = subtotal > 1000 ? 0 : 49;
  return subtotal + tax + shipping;
}

// ==================== SAVE/LOAD PLANS ====================
function savePlan() {
  if (!state.user) {
    openModal('loginModal');
    showToast('Please sign in to save plans', 'error');
    return;
  }

  if (state.placedItems.length === 0) {
    showToast('Room is empty! Add some furniture first.', 'error');
    return;
  }

  const name = prompt('Enter a name for this plan:', `My Room Design ${state.savedPlans.length + 1}`);
  if (!name) return;

  const plan = {
    id: 'plan_' + Date.now(),
    name: name,
    date: new Date().toISOString(),
    items: JSON.parse(JSON.stringify(state.placedItems)),
    roomWidth: state.roomWidth,
    roomHeight: state.roomHeight,
  };

  state.savedPlans.push(plan);
  saveState();
  showToast(`💾 Plan "${name}" saved!`, 'success');
}

function loadPlan(planId) {
  const plan = state.savedPlans.find(p => p.id === planId);
  if (!plan) return;

  state.placedItems = JSON.parse(JSON.stringify(plan.items));
  state.roomWidth = plan.roomWidth || 800;
  state.roomHeight = plan.roomHeight || 600;

  document.getElementById('roomSizeSelect').value = `${state.roomWidth}x${state.roomHeight}`;
  changeRoomSize(`${state.roomWidth}x${state.roomHeight}`);

  renderPlacedItems();
  updateRoomInfo();
  closeModal('plansModal');
  showToast(`📐 Plan "${plan.name}" loaded!`, 'success');
}

function deletePlan(planId) {
  if (!confirm('Delete this plan?')) return;
  state.savedPlans = state.savedPlans.filter(p => p.id !== planId);
  saveState();
  renderPlans();
  showToast('Plan deleted', '');
}

function renderPlans() {
  const body = document.getElementById('plansBody');

  if (state.savedPlans.length === 0) {
    body.innerHTML = `
      <div class="empty-state">
        <div class="empty-icon">📐</div>
        <p>No saved plans yet</p>
        <p style="font-size:12px;margin-top:8px;">Design a room and click "Save Plan"</p>
      </div>
    `;
    return;
  }

  body.innerHTML = state.savedPlans.map(plan => {
    const date = new Date(plan.date).toLocaleDateString('en-US', {
      year: 'numeric', month: 'short', day: 'numeric'
    });
    const itemCount = plan.items.length;
    const totalValue = plan.items.reduce((sum, item) => sum + (item.price || 0), 0);

    return `
      <div class="plan-card">
        <div class="plan-info">
          <h4>📐 ${plan.name}</h4>
          <p>${date} · ${itemCount} items · $${totalValue.toLocaleString()} value</p>
        </div>
        <div class="plan-actions">
          <button class="plan-action-btn" onclick="loadPlan('${plan.id}')">📂 Load</button>
          <button class="plan-action-btn" onclick="sharePlanDirect('${plan.id}')">🔗 Share</button>
          <button class="plan-action-btn delete" onclick="deletePlan('${plan.id}')">🗑️</button>
        </div>
      </div>
    `;
  }).join('');
}

// ==================== SHARING ====================
function openShareModal() {
  if (state.placedItems.length === 0) {
    showToast('Room is empty! Add furniture first.', 'error');
    return;
  }
  document.getElementById('sharePlanName').value = `My Room Design`;
  document.getElementById('shareLinkResult').style.display = 'none';
  openModal('shareModal');
}

function generateShareLink() {
  const name = document.getElementById('sharePlanName').value || 'Shared Design';

  const shareData = {
    name: name,
    items: state.placedItems,
    roomWidth: state.roomWidth,
    roomHeight: state.roomHeight,
  };

  const encoded = btoa(encodeURIComponent(JSON.stringify(shareData)));
  const link = `${window.location.origin}${window.location.pathname}?view=${encoded}`;

  document.getElementById('shareLinkInput').value = link;
  document.getElementById('shareLinkResult').style.display = 'block';
  showToast('🔗 Share link generated!', 'success');
}

function copyShareLink() {
  const input = document.getElementById('shareLinkInput');
  input.select();
  document.execCommand('copy');

  if (navigator.clipboard) {
    navigator.clipboard.writeText(input.value);
  }

  showToast('📋 Link copied to clipboard!', 'success');
}

function sharePlanDirect(planId) {
  const plan = state.savedPlans.find(p => p.id === planId);
  if (!plan) return;

  const shareData = {
    name: plan.name,
    items: plan.items,
    roomWidth: plan.roomWidth,
    roomHeight: plan.roomHeight,
  };

  const encoded = btoa(encodeURIComponent(JSON.stringify(shareData)));
  const link = `${window.location.origin}${window.location.pathname}?view=${encoded}`;

  const tempInput = document.createElement('input');
  tempInput.value = link;
  document.body.appendChild(tempInput);
  tempInput.select();
  document.execCommand('copy');
  tempInput.remove();

  if (navigator.clipboard) {
    navigator.clipboard.writeText(link);
  }

  showToast(`🔗 Share link for "${plan.name}" copied!`, 'success');
}

function checkSharedLink() {
  const params = new URLSearchParams(window.location.search);
  const viewData = params.get('view');

  if (viewData) {
    try {
      const decoded = JSON.parse(decodeURIComponent(atob(viewData)));
      state.viewMode = true;
      state.placedItems = decoded.items || [];
      state.roomWidth = decoded.roomWidth || 800;
      state.roomHeight = decoded.roomHeight || 600;

      document.getElementById('viewBanner').style.display = 'block';
      document.getElementById('viewPlanName').textContent = decoded.name || 'Shared Design';
      document.getElementById('roomSizeSelect').value = `${state.roomWidth}x${state.roomHeight}`;

      changeRoomSize(`${state.roomWidth}x${state.roomHeight}`);
      renderPlacedItems();
      updateRoomInfo();
    } catch(e) {
      console.error('Invalid share link');
    }
  }
}

function exitViewMode() {
  state.viewMode = false;
  state.placedItems = [];
  document.getElementById('viewBanner').style.display = 'none';
  window.history.replaceState({}, '', window.location.pathname);
  renderPlacedItems();
  updateRoomInfo();
  showToast('Start designing your own room!', 'success');
}

// ==================== ACCOUNT ====================
function renderAccount() {
  const body = document.getElementById('accountBody');

  if (!state.user) {
    body.innerHTML = `
      <div class="empty-state">
        <div class="empty-icon">👤</div>
        <p>Not signed in</p>
        <button class="btn btn-primary" onclick="closeModal('accountModal');openModal('loginModal')" style="margin-top:16px;">
          Sign In / Register
        </button>
      </div>
    `;
    return;
  }

  const initial = state.user.username.charAt(0).toUpperCase();
  const planCount = state.savedPlans.length;
  const cartCount = state.cart.reduce((s, c) => s + c.qty, 0);
  const cartValue = state.cart.reduce((sum, c) => {
    const item = FURNITURE_DATA.find(i => i.id === c.id);
    return sum + (item ? item.price * c.qty : 0);
  }, 0);

  body.innerHTML = `
    <div class="account-info">
      <div class="avatar">${initial}</div>
      <div class="account-name">${state.user.username}</div>
      <div class="account-email">${state.user.email}</div>
      <div class="stats-row">
        <div class="stat">
          <div class="stat-num">${planCount}</div>
          <div class="stat-label">Saved Plans</div>
        </div>
        <div class="stat">
          <div class="stat-num">${cartCount}</div>
          <div class="stat-label">Cart Items</div>
        </div>
        <div class="stat">
          <div class="stat-num">$${cartValue.toLocaleString()}</div>
          <div class="stat-label">Cart Value</div>
        </div>
      </div>
    </div>
    <div style="margin-top:20px;">
      <button class="btn btn-danger btn-block" onclick="handleLogout()">
        🚪 Sign Out
      </button>
    </div>
  `;
}

function handleLogin() {
  const username = document.getElementById('loginUsername').value.trim();
  const email = document.getElementById('loginEmail').value.trim();

  if (!username || !email) {
    showToast('Please enter username and email', 'error');
    return;
  }

  state.user = { username, email };
  saveState();
  closeModal('loginModal');
  renderAccount();
  showToast(`👋 Welcome, ${username}!`, 'success');
}

function handleLogout() {
  if (!confirm('Sign out?')) return;
  state.user = null;
  saveState();
  renderAccount();
  showToast('Signed out', '');
}

// ==================== EXPORT ====================
function exportImage() {
  if (state.placedItems.length === 0) {
    showToast('Room is empty!', 'error');
    return;
  }

  // Create a simple text-based export
  let exportText = `FurniSpace Room Design Export\n`;
  exportText += `============================\n`;
  exportText += `Room Size: ${state.roomWidth/100}m × ${state.roomHeight/100}m\n`;
  exportText += `Items: ${state.placedItems.length}\n\n`;

  let totalValue = 0;
  state.placedItems.forEach((item, i) => {
    exportText += `${i+1}. ${item.name} - Position: (${item.x}, ${item.y}) - $${item.price}\n`;
    totalValue += item.price;
  });

  exportText += `\nTotal Furniture Value: $${totalValue.toLocaleString()}\n`;

  const blob = new Blob([exportText], { type: 'text/plain' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'furnispace-design.txt';
  a.click();
  URL.revokeObjectURL(url);

  showToast('📷 Design exported!', 'success');
}

// ==================== MODALS ====================
function openModal(id) {
  document.getElementById(id).classList.add('active');

  if (id === 'cartModal') renderCart();
  if (id === 'plansModal') renderPlans();
  if (id === 'accountModal') renderAccount();
}

function closeModal(id) {
  document.getElementById(id).classList.remove('active');
}

// Close modal on overlay click
document.querySelectorAll('.modal-overlay').forEach(overlay => {
  overlay.addEventListener('click', (e) => {
    if (e.target === overlay) {
      overlay.classList.remove('active');
    }
  });
});

// ==================== TABS ====================
function switchTab(tab) {
  document.querySelectorAll('.nav-tab').forEach(t => t.classList.remove('active'));
  document.querySelector(`[data-tab="${tab}"]`).classList.add('active');
}

// ==================== TOAST ====================
function showToast(message, type = '') {
  const container = document.getElementById('toastContainer');
  const toast = document.createElement('div');
  toast.className = `toast ${type}`;
  toast.textContent = message;
  container.appendChild(toast);
  setTimeout(() => toast.remove(), 3000);
}

// ==================== KEYBOARD SHORTCUTS ====================
document.addEventListener('keydown', (e) => {
  if (e.key === 'Delete' || e.key === 'Backspace') {
    if (state.selectedItemId && !['INPUT', 'TEXTAREA'].includes(document.activeElement.tagName)) {
      e.preventDefault();
      removePlacedItem(state.selectedItemId);
    }
  }
  if (e.key === 'Escape') {
    state.selectedItemId = null;
    renderPlacedItems();
    document.querySelectorAll('.modal-overlay.active').forEach(m => m.classList.remove('active'));
  }
  if (e.key === 'r' && state.selectedItemId && !['INPUT', 'TEXTAREA'].includes(document.activeElement.tagName)) {
    rotateItem(state.selectedItemId);
  }
});

// Click on canvas to deselect
document.getElementById('roomCanvas').addEventListener('click', (e) => {
  if (e.target === document.getElementById('roomCanvas') || e.target.classList.contains('room-label') || e.target.classList.contains('room-dimensions')) {
    state.selectedItemId = null;
    renderPlacedItems();
  }
});

// ==================== INIT ====================
init();

// Set grid button initial state
document.getElementById('gridBtn').classList.add('active');
</script>
</body>
</html>
```

## Key Features

### 🪑 Furniture Catalog
- **35+ furniture items** across 6 categories (Living Room, Bedroom, Kitchen, Office, Bathroom, Outdoor)
- **Search & filter** by category or keyword
- Each item shows icon, dimensions, and price

### 🎨 Room Designer
- **Drag-and-drop** furniture from the sidebar into the virtual room
- **Snap-to-grid** alignment for precise placement
- **Move, rotate, and delete** placed items with interactive handles
- **4 room sizes** (Small to XL)
- Toggle grid visibility

### 💾 Save & Share
- **Save plans** to your account with custom names
- **Load saved plans** anytime
- **Generate shareable links** — recipients see your exact room layout
- **View mode** for shared links with option to start your own design

### 🛒 Shopping Cart
- Add items from catalog with one click
- **Quantity controls** (increase/decrease/remove)
- **Automatic price calculation** with subtotal, 8% tax, and shipping
- **Free shipping** on orders over $1,000
- Full checkout flow

### 👤 User Accounts
- Sign in/register system (localStorage-based)
- Account dashboard with stats (plans, cart items, cart value)
- Persistent data across sessions

### ⌨️ Keyboard Shortcuts
- **Delete/Backspace** — remove selected item
- **R** — rotate selected item
- **Escape** — deselect / close modals

# Online Music Theory Learning Website

Below is a complete, self-contained HTML file that implements an interactive music theory learning website. It uses the **Web Audio API** to synthesize piano-like tones in real time (no external audio files needed), so you can simply save it as `index.html` and open it in any modern browser.

## Features

1. **Theory Pages** — Introduction to scales (Major, Natural Minor, Harmonic Minor, Pentatonic) and chords (Major, Minor, Diminished, Augmented, Dominant 7th) with interval formulas.
2. **Audio Examples** — Click any scale or chord card to hear it played.
3. **Practice Mode** — The system gives you a target chord; you click piano keys to build it. The app validates your answer (supports inversions and any octave).

## Complete Code

```html
