<body>

<header>
  <h1>🎵 Music Theory Lab</h1>
  <nav>
    <button data-tab="scales" class="active">Scales</button>
    <button data-tab="chords">Chords</button>
    <button data-tab="practice">Practice</button>
  </nav>
</header>

<main>

  <!-- SCALES -->
  <section id="scales" class="section active">
    <h2>Scales — The Building Blocks of Melody</h2>
    <p class="lead">
      A <b>scale</b> is an ordered set of pitches arranged by interval pattern.
      Scales define the tonal "color" of a piece. Below are four foundational scales.
      Click <i>Play</i> to hear each one ascending from C4.
    </p>
    <div class="grid" id="scaleGrid"></div>
  </section>

  <!-- CHORDS -->
  <section id="chords" class="section">
    <h2>Chords — Stacked Intervals</h2>
    <p class="lead">
      A <b>chord</b> is three or more notes sounded together. Chords are built by stacking
      specific intervals above a root. The quality (major, minor, etc.) determines the
      emotional character. Click <i>Play</i> to hear each chord rooted on C4.
    </p>
    <div class="grid" id="chordGrid"></div>
  </section>

  <!-- PRACTICE -->
  <section id="practice" class="section">
    <h2>Practice — Build the Chord</h2>
    <p class="lead">
      The system will give you a target chord. Click piano keys to select the notes that
      form that chord (any octave, any inversion). Press <b>Check</b> to validate.
    </p>

    <div class="practice-panel">
      <div class="target">
        <div>
          <div class="label">Target chord</div>
          <div class="name" id="targetName">—</div>
        </div>
        <button class="btn" id="newTarget">New Target</button>
        <button class="btn secondary" id="hearTarget">Hear It</button>
      </div>

      <div class="piano" id="piano"></div>
      <div class="selected-notes" id="selectedNotes">Selected: (none)</div>

      <div class="controls">
        <button class="btn" id="checkBtn">Check Answer</button>
        <button class="btn secondary" id="clearBtn">Clear</button>
        <button class="btn secondary" id="playSelBtn">Play Selection</button>
      </div>

      <div class="feedback" id="feedback"></div>
    </div>
  </section>

</main>

<footer>Built with the Web Audio API · No external audio files required</footer>

<script>
/* =========================================================
   1. AUDIO ENGINE — Web Audio API piano-like synthesizer
   ========================================================= */
let audioCtx = null;
function getCtx() {
  if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
  if (audioCtx.state === 'suspended') audioCtx.resume();
  return audioCtx;
}

// MIDI note number -> frequency
function mtof(m) { return 440 * Math.pow(2, (m - 69) / 12); }

// Play a single note with a piano-ish envelope (multiple detuned oscillators + filter)
function playNote(midi, startTime = 0, duration = 0.9, velocity = 0.7) {
  const ctx = getCtx();
  const t0 = ctx.currentTime + startTime;
  const freq = mtof(midi);

  const master = ctx.createGain();
  master.gain.value = 0;
  const filter = ctx.createBiquadFilter();
  filter.type = 'lowpass';
  filter.frequency.value = Math.min(8000, freq * 8);
  filter.Q.value = 0.6;
  filter.connect(master).connect(ctx.destination);

  // Three oscillators for richness
  const types = ['triangle', 'sine', 'sine'];
  const detunes = [0, -6, 7];
  const gains = [0.55, 0.35, 0.2];
  types.forEach((type, i) => {
    const osc = ctx.createOscillator();
    osc.type = type;
    osc.frequency.value = freq * (i === 2 ? 2 : 1); // 3rd osc = octave harmonic
    osc.detune.value = detunes[i];
    const g = ctx.createGain();
    g.gain.value = gains[i] * velocity;
    osc.connect(g).connect(filter);
    osc.start(t0);
    osc.stop(t0 + duration + 0.2);
  });

  // ADSR envelope
  const peak = 0.35 * velocity;
  master.gain.setValueAtTime(0, t0);
  master.gain.linearRampToValueAtTime(peak, t0 + 0.01);       // attack
  master.gain.exponentialRampToValueAtTime(peak * 0.6, t0 + 0.15); // decay
  master.gain.exponentialRampToValueAtTime(0.0001, t0 + duration); // release
}

// Play a sequence of notes (scale or chord)
function playSequence(midiNotes, { gap = 0.35, duration = 0.5, simultaneous = false } = {}) {
  midiNotes.forEach((n, i) => {
    playNote(n, simultaneous ? 0 : i * gap, simultaneous ? 1.2 : duration);
  });
}

/* =========================================================
   2. MUSIC THEORY DATA
   ========================================================= */
const NOTE_NAMES = ['C','C#','D','D#','E','F','F#','G','G#','A','A#','B'];

const SCALES = [
  {
    name: 'Major Scale (Ionian)',
    intervals: [0,2,4,5,7,9,11,12],
    formula: 'W - W - H - W - W - W - H',
    desc: 'Bright, happy, and stable. The most common scale in Western music.'
  },
  {
    name: 'Natural Minor (Aeolian)',
    intervals: [0,2,3,5,7,8,10,12],
    formula: 'W - H - W - W - H - W - W',
    desc: 'Darker and more melancholic than major. The relative minor scale.'
  },
  {
    name: 'Harmonic Minor',
    intervals: [0,2,3,5,7,8,11,12],
    formula: 'W - H - W - W - H - 1½ - H',
    desc: 'Minor with a raised 7th, giving an exotic, classical flavor.'
  },
  {
    name: 'Major Pentatonic',
    intervals: [0,2,4,7,9,12],
    formula: 'W - W - m3 - W - m3',
    desc: 'Five-note scale used in folk, blues, rock, and pop worldwide.'
  }
];

const CHORDS = [
  {
    name: 'Major Triad',
    intervals: [0,4,7],
    formula: 'R - M3 - P5',
    desc: 'Stable, bright, and consonant. Built from root, major 3rd, perfect 5th.'
  },
  {
    name: 'Minor Triad',
    intervals: [0,3,7],
    formula: 'R - m3 - P5',
    desc: 'Sad or somber. Root, minor 3rd, perfect 5th.'
  },
  {
    name: 'Diminished Triad',
    intervals: [0,3,6],
    formula: 'R - m3 - d5',
    desc: 'Tense and unstable. Two stacked minor thirds.'
  },
  {
    name: 'Augmented Triad',
    intervals: [0,4,8],
    formula: 'R - M3 - A5',
    desc: 'Dreamy and unresolved. Two stacked major thirds.'
  },
  {
    name: 'Dominant 7th',
    intervals: [0,4,7,10],
    formula: 'R - M3 - P5 - m7',
    desc: 'Bluesy and driving. Major triad plus a minor 7th; wants to resolve.'
  }
];

/* =========================================================
   3. RENDER THEORY CARDS
   ========================================================= */
function renderScaleCards() {
  const grid = document.getElementById('scaleGrid');
  grid.innerHTML = '';
  SCALES.forEach((s, idx) => {
    const rootMidi = 60; // C4
    const notes = s.intervals.map(i => NOTE_NAMES[(rootMidi + i) % 12]);
    const card = document.createElement('div');
    card.className = 'card';
    card.innerHTML = `
      <h4>${s.name}</h4>
      <div class="formula">${s.formula}</div>
      <p><b>Notes (from C):</b> ${notes.join(' – ')}</p>
      <p>${s.desc}</p>
      <button class="btn" data-play-scale="${idx}">▶ Play</button>
    `;
    grid.appendChild(card);
  });
  grid.querySelectorAll('[data-play-scale]').forEach(btn => {
    btn.addEventListener('click', () => {
      const s = SCALES[+btn.dataset.playScale];
      playSequence(s.intervals.map(i => 60 + i));
    });
  });
}

function renderChordCards() {
  const grid = document.getElementById('chordGrid');
  grid.innerHTML = '';
  CHORDS.forEach((c, idx) => {
    const rootMidi = 60;
    const notes = c.intervals.map(i => NOTE_NAMES[(rootMidi + i) % 12]);
    const card = document.createElement('div');
    card.className = 'card';
    card.innerHTML = `
      <h4>${c.name}</h4>
      <div class="formula">${c.formula}</div>
      <p><b>Notes (from C):</b> ${notes.join(' – ')}</p>
      <p>${c.desc}</p>
      <button class="btn" data-play-chord="${idx}">▶ Play</button>
    `;
    grid.appendChild(card);
  });
  grid.querySelectorAll('[data-play-chord]').forEach(btn => {
    btn.addEventListener('click', () => {
      const c = CHORDS[+btn.dataset.playChord];
      playSequence(c.intervals.map(i => 60 + i), { simultaneous: true });
    });
  });
}

/* =========================================================
   4. PRACTICE MODE — Piano + Validation
   ========================================================= */
const PIANO_START = 48; // C3
const PIANO_END   = 72; // C5 (2 octaves)
const selected = new Set(); // set of MIDI numbers

function buildPiano() {
  const piano = document.getElementById('piano');
  piano.innerHTML = '';
  const whites = [];
  const blacks = [];
  for (let m = PIANO_START; m <= PIANO_END; m++) {
    const pc = m % 12;
    const isBlack = [1,3,6,8,10].includes(pc);
    const key = document.createElement('div');
    key.className = 'key ' + (isBlack ? 'black' : 'white');
    key.dataset.midi = m;
    const octave = Math.floor(m / 12) - 1;
    key.innerHTML = `<span>${NOTE_NAMES[pc]}${octave}</span>`;
    key.addEventListener('click', () => toggleKey(m, key));
    if (isBlack) blacks.push({ midi: m, el: key });
    else whites.push({ midi: m, el: key });
  }
  // Append whites first
  whites.forEach(w => piano.appendChild(w.el));
  // Position blacks absolutely based on white-key index
  const whiteCount = whites.length;
  const whiteWidthPct = 100 / whiteCount;
  blacks.forEach(b => {
    // Find the white key just before this black key
    const prevWhiteIdx = whites.findIndex(w => w.midi > b.midi) - 1;
    const leftPct = (prevWhiteIdx + 1) * whiteWidthPct - (whiteWidthPct * 0.3);
    b.el.style.left = leftPct + '%';
    b.el.style.width = (whiteWidthPct * 0.6) + '%';
    piano.appendChild(b.el);
  });
}

function toggleKey(midi, el) {
  if (selected.has(midi)) {
    selected.delete(midi);
    el.classList.remove('selected');
  } else {
    selected.add(midi);
    el.classList.add('selected');
    playNote(midi, 0, 0.6);
  }
  updateSelectedDisplay();
}

function updateSelectedDisplay() {
  const arr = [...selected].sort((a,b) => a-b);
  const names = arr.map(m => {
    const oct = Math.floor(m/12) - 1;
    return NOTE_NAMES[m%12] + oct;
  });
  document.getElementById('selectedNotes').textContent =
    'Selected: ' + (names.length ? names.join(', ') : '(none)');
}

function clearSelection() {
  selected.clear();
  document.querySelectorAll('.key.selected').forEach(k => k.classList.remove('selected'));
  updateSelectedDisplay();
  hideFeedback();
}

/* ---------- Target generation & validation ---------- */
let currentTarget = null;

function newTarget() {
  const chord = CHORDS[Math.floor(Math.random() * CHORDS.length)];
  const rootPc = Math.floor(Math.random() * 12);
  currentTarget = {
    rootPc,
    chord,
    label: `${NOTE_NAMES[rootPc]} ${chord.name}`
  };
  document.getElementById('targetName').textContent = currentTarget.label;
  clearSelection();
}

function hearTarget() {
  if (!currentTarget) return;
  const notes = currentTarget.chord.intervals.map(i => 60 + ((currentTarget.rootPc + i) % 12));
  playSequence(notes, { simultaneous: true, duration: 1.2 });
}

function checkAnswer() {
  if (!currentTarget) return;
  const fb = document.getElementById('feedback');
  if (selected.size === 0) {
    fb.className = 'feedback err';
    fb.textContent = '⚠ Please select at least one note.';
    return;
  }

  // Reduce selected notes to pitch classes
  const selectedPcs = new Set([...selected].map(m => m % 12));
  const targetPcs = new Set(
    currentTarget.chord.intervals.map(i => (currentTarget.rootPc + i) % 12)
  );

  const ok =
    selectedPcs.size === targetPcs.size &&
    [...selectedPcs].every(pc => targetPcs.has(pc));

  if (ok) {
    fb.className = 'feedback ok';
    fb.textContent = `✅ Correct! You built a ${currentTarget.label}.`;
    // Celebrate by playing it
    const notes = [...selected].sort((a,b)=>a-b);
    playSequence(notes, { simultaneous: true, duration: 1.2 });
  } else {
    fb.className = 'feedback err';
    const expected = [...targetPcs].map(pc => NOTE_NAMES[pc]).join(', ');
    fb.textContent = `❌ Not quite. Expected pitch classes: { ${expected} }. Try again!`;
  }
}

function hideFeedback() {
  const fb = document.getElementById('feedback');
  fb.className = 'feedback';
  fb.textContent = '';
}

/* =========================================================
   5. TAB NAVIGATION
   ========================================================= */
document.querySelectorAll('nav button').forEach(btn => {
  btn.addEventListener('click', () => {
    document.querySelectorAll('nav button').forEach(b => b.classList.remove('active'));
    document.querySelectorAll('.section').forEach(s => s.classList.remove('active'));
    btn.classList.add('active');
    document.getElementById(btn.dataset.tab).classList.add('active');
  });
});

/* =========================================================
   6. INIT
   ========================================================= */
renderScaleCards();
renderChordCards();
buildPiano();
newTarget();

document.getElementById('newTarget').addEventListener('click', newTarget);
document.getElementById('hearTarget').addEventListener('click', hearTarget);
document.getElementById('checkBtn').addEventListener('click', checkAnswer);
document.getElementById('clearBtn').addEventListener('click', clearSelection);
document.getElementById('playSelBtn').addEventListener('click', () => {
  const notes = [...selected].sort((a,b)=>a-b);
  if (notes.length) playSequence(notes, { simultaneous: true });
});

// Unlock audio on first user interaction (browser autoplay policy)
document.body.addEventListener('click', () => getCtx(), { once: true });
</script>
</body>
</html>
```

## How to Run

1. Copy the code above into a file named `index.html`.
2. Double-click the file (or open it in Chrome / Edge / Firefox / Safari).
3. Click anywhere once to unlock audio (browser autoplay policy), then explore.

## How the Validation Works

The practice checker uses **pitch-class set equality**, which means:

- It reduces every selected note to its pitch class (e.g., C4, C5, C3 → all become `C`).
- It compares the set of selected pitch classes against the set required by the target chord.
- Therefore, **inversions** (e.g., E–G–C for C major) and **doubled notes across octaves** are all accepted as correct — exactly as a real music teacher would grade them.

