import os
import sqlite3
from functools import wraps
from werkzeug.utils import secure_filename
from werkzeug.security import generate_password_hash, check_password_hash
from flask import (
    Flask, render_template, request, redirect, url_for,
    session, flash, g, send_from_directory
)

app = Flask(__name__)
app.secret_key = "change-this-secret-key-in-production"

BASE_DIR = os.path.dirname(os.path.abspath(__file__))
DB_PATH = os.path.join(BASE_DIR, "menu.db")
UPLOAD_FOLDER = os.path.join(BASE_DIR, "uploads")
ALLOWED_EXTENSIONS = {"png", "jpg", "jpeg", "gif", "webp"}
app.config["UPLOAD_FOLDER"] = UPLOAD_FOLDER
app.config["MAX_CONTENT_LENGTH"] = 8 * 1024 * 1024  # 8 MB

os.makedirs(UPLOAD_FOLDER, exist_ok=True)


# ---------- Database helpers ----------
def get_db():
    if "db" not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
        g.db.execute("PRAGMA foreign_keys = ON")
    return g.db


@app.teardown_appcontext
def close_db(exc):
    db = g.pop("db", None)
    if db is not None:
        db.close()


def init_db():
    db = sqlite3.connect(DB_PATH)
    db.execute("PRAGMA foreign_keys = ON")
    db.executescript("""
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE NOT NULL,
            password_hash TEXT NOT NULL,
            role TEXT NOT NULL CHECK(role IN ('chef','manager','customer'))
        );
        CREATE TABLE IF NOT EXISTS categories (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT UNIQUE NOT NULL
        );
        CREATE TABLE IF NOT EXISTS menu_items (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            description TEXT,
            price REAL NOT NULL,
            image_filename TEXT,
            category_id INTEGER NOT NULL,
            chef_id INTEGER NOT NULL,
            status TEXT NOT NULL DEFAULT 'pending'
                CHECK(status IN ('pending','approved','rejected')),
            manager_note TEXT,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (category_id) REFERENCES categories(id),
            FOREIGN KEY (chef_id) REFERENCES users(id)
        );
    """)
    # Seed data
    cur = db.cursor()
    if cur.execute("SELECT COUNT(*) FROM users").fetchone()[0] == 0:
        users = [
            ("chef_gordon", generate_password_hash("chef123"), "chef"),
            ("manager_anna", generate_password_hash("mgr123"), "manager"),
            ("customer", generate_password_hash("cust123"), "customer"),
        ]
        cur.executemany(
            "INSERT INTO users(username,password_hash,role) VALUES(?,?,?)", users
        )
    if cur.execute("SELECT COUNT(*) FROM categories").fetchone()[0] == 0:
        cur.executemany(
            "INSERT INTO categories(name) VALUES(?)",
            [("Appetizer",), ("Main Course",), ("Dessert",), ("Beverage",)],
        )
    db.commit()
    db.close()


# ---------- Auth helpers ----------
def login_required(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        if "user_id" not in session:
            flash("Please log in first.", "warning")
            return redirect(url_for("login"))
        return f(*args, **kwargs)
    return wrapper


def role_required(role):
    def decorator(f):
        @wraps(f)
        def wrapper(*args, **kwargs):
            if session.get("role") != role:
                flash("You do not have permission to access this page.", "danger")
                return redirect(url_for("index"))
            return f(*args, **kwargs)
        return wrapper
    return decorator


def allowed_file(filename):
    return "." in filename and filename.rsplit(".", 1)[1].lower() in ALLOWED_EXTENSIONS


# ---------- Routes ----------
@app.route("/")
def index():
    role = session.get("role")
    if role == "chef":
        return redirect(url_for("chef_dashboard"))
    if role == "manager":
        return redirect(url_for("manager_dashboard"))
    return redirect(url_for("customer_menu"))


@app.route("/login", methods=["GET", "POST"])
def login():
    if request.method == "POST":
        username = request.form.get("username", "").strip()
        password = request.form.get("password", "")
        db = get_db()
        user = db.execute(
            "SELECT * FROM users WHERE username = ?", (username,)
        ).fetchone()
        if user and check_password_hash(user["password_hash"], password):
            session["user_id"] = user["id"]
            session["username"] = user["username"]
            session["role"] = user["role"]
            flash(f"Welcome back, {user['username']}!", "success")
            return redirect(url_for("index"))
        flash("Invalid username or password.", "danger")
    return render_template("login.html")


@app.route("/logout")
def logout():
    session.clear()
    flash("You have been logged out.", "info")
    return redirect(url_for("login"))


# ----- Chef -----
@app.route("/chef")
@login_required
@role_required("chef")
def chef_dashboard():
    db = get_db()
    items = db.execute(
        """SELECT m.*, c.name AS category_name
           FROM menu_items m JOIN categories c ON m.category_id = c.id
           WHERE m.chef_id = ? ORDER BY m.created_at DESC""",
        (session["user_id"],),
    ).fetchall()
    return render_template("chef_dashboard.html", items=items)


@app.route("/chef/upload", methods=["GET", "POST"])
@login_required
@role_required("chef")
def upload_menu():
    db = get_db()
    if request.method == "POST":
        name = request.form.get("name", "").strip()
        description = request.form.get("description", "").strip()
        price = request.form.get("price", "").strip()
        category_id = request.form.get("category_id")
        new_category = request.form.get("new_category", "").strip()
        file = request.files.get("image")

        if not name or not price:
            flash("Name and price are required.", "danger")
            return redirect(url_for("upload_menu"))
        try:
            price_val = float(price)
        except ValueError:
            flash("Price must be a number.", "danger")
            return redirect(url_for("upload_menu"))

        # Handle category
        if new_category:
            db.execute(
                "INSERT OR IGNORE INTO categories(name) VALUES(?)", (new_category,)
            )
            db.commit()
            cat = db.execute(
                "SELECT id FROM categories WHERE name = ?", (new_category,)
            ).fetchone()
            category_id = cat["id"]
        if not category_id:
            flash("Please select or create a category.", "danger")
            return redirect(url_for("upload_menu"))

        # Handle image
        image_filename = None
        if file and file.filename and allowed_file(file.filename):
            image_filename = secure_filename(file.filename)
            # Avoid overwrite collisions
            base, ext = os.path.splitext(image_filename)
            counter = 1
            while os.path.exists(
                os.path.join(app.config["UPLOAD_FOLDER"], image_filename)
            ):
                image_filename = f"{base}_{counter}{ext}"
                counter += 1
            file.save(os.path.join(app.config["UPLOAD_FOLDER"], image_filename))

        db.execute(
            """INSERT INTO menu_items
               (name, description, price, image_filename, category_id, chef_id, status)
               VALUES (?,?,?,?,?,?, 'pending')""",
            (name, description, price_val, image_filename, category_id, session["user_id"]),
        )
        db.commit()
        flash("Menu item submitted for review.", "success")
        return redirect(url_for("chef_dashboard"))

    categories = db.execute("SELECT * FROM categories ORDER BY name").fetchall()
    return render_template("upload_menu.html", categories=categories)


@app.route("/chef/delete/<int:item_id>")
@login_required
@role_required("chef")
def delete_menu(item_id):
    db = get_db()
    item = db.execute(
        "SELECT * FROM menu_items WHERE id = ? AND chef_id = ?",
        (item_id, session["user_id"]),
    ).fetchone()
    if item:
        if item["image_filename"]:
            path = os.path.join(app.config["UPLOAD_FOLDER"], item["image_filename"])
            if os.path.exists(path):
                os.remove(path)
        db.execute("DELETE FROM menu_items WHERE id = ?", (item_id,))
        db.commit()
        flash("Menu item deleted.", "info")
    return redirect(url_for("chef_dashboard"))


# ----- Manager -----
@app.route("/manager")
@login_required
@role_required("manager")
def manager_dashboard():
    db = get_db()
    items = db.execute(
        """SELECT m.*, c.name AS category_name, u.username AS chef_name
           FROM menu_items m
           JOIN categories c ON m.category_id = c.id
           JOIN users u ON m.chef_id = u.id
           ORDER BY CASE m.status WHEN 'pending' THEN 0 ELSE 1 END,
                    m.created_at DESC"""
    ).fetchall()
    return render_template("manager_dashboard.html", items=items)


@app.route("/manager/review/<int:item_id>", methods=["GET", "POST"])
@login_required
@role_required("manager")
def review_menu(item_id):
    db = get_db()
    item = db.execute(
        """SELECT m.*, c.name AS category_name, u.username AS chef_name
           FROM menu_items m
           JOIN categories c ON m.category_id = c.id
           JOIN users u ON m.chef_id = u.id
           WHERE m.id = ?""",
        (item_id,),
    ).fetchone()
    if not item:
        flash("Item not found.", "danger")
        return redirect(url_for("manager_dashboard"))

    if request.method == "POST":
        action = request.form.get("action")
        note = request.form.get("note", "").strip()
        new_status = "approved" if action == "approve" else "rejected"
        db.execute(
            "UPDATE menu_items SET status = ?, manager_note = ? WHERE id = ?",
            (new_status, note, item_id),
        )
        db.commit()
        flash(f"Item {new_status}.", "success")
        return redirect(url_for("manager_dashboard"))

    return render_template("review_menu.html", item=item)


# ----- Customer (public) -----
@app.route("/menu")
def customer_menu():
    db = get_db()
    rows = db.execute(
        """SELECT m.*, c.name AS category_name
           FROM menu_items m JOIN categories c ON m.category_id = c.id
           WHERE m.status = 'approved'
           ORDER BY c.name, m.name"""
    ).fetchall()
    # Group by category
    grouped = {}
    for r in rows:
        grouped.setdefault(r["category_name"], []).append(r)
    return render_template("customer_menu.html", grouped=grouped)


@app.route("/uploads/<path:filename>")
def uploaded_file(filename):
    return send_from_directory(app.config["UPLOAD_FOLDER"], filename)


# ---------- Main ----------
if __name__ == "__main__":
    init_db()
    app.run(debug=True, host="127.0.0.1", port=5000)
```

