            border: 2px dashed #0f3460;
            border-radius: 10px;
            text-align: center;
            cursor: pointer;
            transition: all 0.3s;
        }

        .upload-area:hover,
        .upload-area.dragover {
            border-color: #e94560;
            background: rgba(233, 69, 96, 0.05);
        }

        .upload-area .upload-icon {
            font-size: 32px;
            margin-bottom: 8px;
        }

        .upload-area p {
            font-size: 12px;
            color: #a0a0b0;
        }

        /* ========== Canvas Area ========== */
        .canvas-area {
            flex: 1;
            display: flex;
            flex-direction: column;
            overflow: hidden;
        }

        .canvas-toolbar {
            padding: 10px 20px;
            background: #16213e;
            border-bottom: 1px solid #0f3460;
            display: flex;
            align-items: center;
            gap: 12px;
            flex-wrap: wrap;
        }

        .canvas-container {
            flex: 1;
            display: flex;
            align-items: center;
            justify-content: center;
            overflow: auto;
            padding: 20px;
            position: relative;
            background:
                linear-gradient(45deg, #111 25%, transparent 25%),
                linear-gradient(-45deg, #111 25%, transparent 25%),
                linear-gradient(45deg, transparent 75%, #111 75%),
                linear-gradient(-45deg, transparent 75%, #111 75%);
            background-size: 20px 20px;
            background-position: 0 0, 0 10px, 10px -10px, -10px 0px;
            background-color: #1a1a2e;
        }

        .canvas-wrapper {
            position: relative;
            display: inline-block;
            box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
            border-radius: 4px;
            overflow: hidden;
        }

        .canvas-wrapper canvas {
            display: block;
            cursor: crosshair;
        }

        /* ========== Empty State ========== */
        .empty-state {
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            height: 100%;
            color: #a0a0b0;
        }

        .empty-state .empty-icon {
            font-size: 64px;
            margin-bottom: 16px;
            opacity: 0.5;
        }

        .empty-state h2 {
            font-size: 20px;
            margin-bottom: 8px;
        }

        .empty-state p {
            font-size: 14px;
        }

        /* ========== Annotation List Panel ========== */
        .annotation-panel {
            width: 260px;
            background: #16213e;
            border-left: 2px solid #0f3460;
            display: flex;
            flex-direction: column;
            flex-shrink: 0;
        }

        .annotation-panel-header {
            padding: 12px 16px;
            border-bottom: 1px solid #0f3460;
        }

        .annotation-panel-header h3 {
            font-size: 14px;
            color: #a0a0b0;
        }

        .annotation-list {
            flex: 1;
            overflow-y: auto;
            padding: 8px;
        }

        .annotation-list::-webkit-scrollbar {
            width: 6px;
        }

        .annotation-list::-webkit-scrollbar-track {
            background: #16213e;
        }

        .annotation-list::-webkit-scrollbar-thumb {
            background: #0f3460;
            border-radius: 3px;
        }

        .annotation-entry {
            background: #0f3460;
            border-radius: 8px;
            padding: 10px;
            margin-bottom: 8px;
            border: 1px solid transparent;
            transition: border-color 0.2s;
        }

        .annotation-entry.selected {
            border-color: #e94560;
        }

        .annotation-entry-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            margin-bottom: 6px;
        }

        .annotation-entry-index {
            font-size: 11px;
            color: #e94560;
            font-weight: 700;
        }

        .annotation-entry input[type="text"] {
            width: 100%;
            background: #16213e;
            border: 1px solid #1a4a7a;
            color: #e0e0e0;
            padding: 6px 8px;
            border-radius: 4px;
            font-size: 12px;
            outline: none;
            margin-bottom: 6px;
        }

        .annotation-entry input[type="text"]:focus {
            border-color: #e94560;
        }

        .annotation-entry-controls {
            display: flex;
            gap: 6px;
            align-items: center;
        }

        .annotation-entry-controls label {
            font-size: 11px;
            color: #a0a0b0;
        }

        .annotation-entry-controls input[type="number"] {
            width: 50px;
            background: #16213e;
            border: 1px solid #1a4a7a;
            color: #e0e0e0;
            padding: 4px 6px;
            border-radius: 4px;
            font-size: 11px;
            outline: none;
        }

        .annotation-entry-controls input[type="color"] {
            width: 28px;
            height: 24px;
            border: none;
            border-radius: 4px;
            cursor: pointer;
            background: transparent;
        }

        .annotation-entry .delete-annotation {
            background: none;
            border: none;
            color: #e74c3c;
            cursor: pointer;
            font-size: 14px;
            padding: 2px 6px;
            border-radius: 4px;
        }

        .annotation-entry .delete-annotation:hover {
            background: rgba(231, 76, 60, 0.2);
        }

        /* ========== Status Bar ========== */
        .status-bar {
            background: #0f3460;
            padding: 6px 20px;
            font-size: 12px;
            color: #a0a0b0;
            display: flex;
            justify-content: space-between;
            flex-shrink: 0;
        }

        /* ========== Modal / Overlay ========== */
        .modal-overlay {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: rgba(0, 0, 0, 0.7);
            display: flex;
            align-items: center;
            justify-content: center;
            z-index: 1000;
        }

        .modal-overlay.hidden {
            display: none;
        }

        .modal {
            background: #16213e;
            border-radius: 12px;
            padding: 32px;
            text-align: center;
            max-width: 400px;
        }

        .modal h2 {
            margin-bottom: 12px;
            color: #e94560;
        }

        .modal p {
            margin-bottom: 20px;
            color: #a0a0b0;
        }

        .progress-bar {
            width: 100%;
            height: 8px;
            background: #0f3460;
            border-radius: 4px;
            overflow: hidden;
            margin-bottom: 12px;
        }

        .progress-bar-fill {
            height: 100%;
            background: #e94560;
            border-radius: 4px;
            transition: width 0.3s;
            width: 0%;
        }

        /* ========== Tooltip ========== */
        .tooltip {
            position: relative;
        }

        .tooltip::after {
            content: attr(data-tooltip);
            position: absolute;
            bottom: 100%;
            left: 50%;
            transform: translateX(-50%);
            background: #333;
            color: #fff;
            padding: 4px 8px;
            border-radius: 4px;
            font-size: 11px;
            white-space: nowrap;
            opacity: 0;
            pointer-events: none;
            transition: opacity 0.2s;
        }

        .tooltip:hover::after {
            opacity: 1;
        }

        /* ========== Responsive ========== */
        @media (max-width: 900px) {
            .sidebar {
                width: 160px;
            }
            .annotation-panel {
                width: 200px;
            }
        }
    </style>
</head>
<body>
    <div class="app-container">
        <!-- ========== Header ========== -->
        <div class="header">
            <h1>🖼️ Batch Image Annotation Tool</h1>
            <div class="toolbar">
                <label>Font:</label>
                <select id="fontFamily">
                    <option value="Arial">Arial</option>
                    <option value="Helvetica">Helvetica</option>
                    <option value="Times New Roman">Times New Roman</option>
                    <option value="Courier New">Courier New</option>
                    <option value="Georgia">Georgia</option>
                    <option value="Verdana">Verdana</option>
                    <option value="Impact">Impact</option>
                </select>

                <label>Size:</label>
                <input type="number" id="fontSize" value="24" min="8" max="200">

                <label>Color:</label>
                <input type="color" id="fontColor" value="#ffffff">

                <label>BG:</label>
                <input type="color" id="bgColor" value="#000000">

                <label>
                    <input type="checkbox" id="bgEnabled" checked> BG
                </label>

                <label>
                    <input type="checkbox" id="boldEnabled"> <b>B</b>
                </label>

                <button class="btn btn-primary" id="addTextBtn" disabled>
                    ✏️ Add Text (Click on Image)
                </button>

                <button class="btn btn-success" id="downloadAllBtn" disabled>
                    📦 Download All
                </button>

                <button class="btn btn-danger" id="clearAllBtn" disabled>
                    🗑️ Clear All
                </button>
            </div>
        </div>

        <!-- ========== Main Content ========== -->
        <div class="main-content">
            <!-- Sidebar: Image List -->
            <div class="sidebar">
                <div class="sidebar-header">
                    <h3>Images</h3>
                    <span class="image-count" id="imageCount">0</span>
                </div>
                <div class="image-list" id="imageList">
                    <!-- Image items will be rendered here -->
                </div>
                <div class="upload-area" id="uploadArea">
                    <div class="upload-icon">📁</div>
                    <p>Click or drag images here</p>
                    <p style="font-size:11px; margin-top:4px; color:#666;">Supports JPG, PNG, GIF, WebP</p>
                </div>
                <input type="file" id="fileInput" multiple accept="image/*" style="display:none;">
            </div>

            <!-- Canvas Area -->
            <div class="canvas-area">
                <div class="canvas-toolbar" id="canvasToolbar" style="display:none;">
                    <span style="font-size:13px; color:#a0a0b0;" id="currentImageName">No image selected</span>
                    <span style="font-size:12px; color:#666;" id="currentImageSize"></span>
                    <div style="flex:1;"></div>
                    <button class="btn btn-secondary" id="undoBtn" title="Undo last annotation">↩️ Undo</button>
                    <button class="btn btn-secondary" id="clearCurrentBtn">🧹 Clear Annotations</button>
                </div>
                <div class="canvas-container" id="canvasContainer">
                    <!-- Empty state or canvas will be shown here -->
                    <div class="empty-state" id="emptyState">
                        <div class="empty-icon">🖼️</div>
                        <h2>No Images Loaded</h2>
                        <p>Upload images from the left panel to start annotating</p>
                    </div>
                </div>
            </div>

            <!-- Annotation Panel -->
            <div class="annotation-panel">
                <div class="annotation-panel-header">
                    <h3>📝 Annotations</h3>
                </div>
                <div class="annotation-list" id="annotationList">
                    <div class="empty-state" style="padding:40px 20px;">
                        <p style="font-size:12px;">Select an image and click on it to add annotations</p>
                    </div>
                </div>
            </div>
        </div>

        <!-- ========== Status Bar ========== -->
        <div class="status-bar">
            <span id="statusText">Ready</span>
            <span id="statusRight">Click on image to place annotation | Drag to reposition</span>
        </div>
    </div>

    <!-- ========== Download Progress Modal ========== -->
    <div class="modal-overlay hidden" id="downloadModal">
        <div class="modal">
            <h2>📦 Preparing Download</h2>
            <p id="downloadStatus">Processing images...</p>
            <div class="progress-bar">
                <div class="progress-bar-fill" id="progressBarFill"></div>
            </div>
        </div>
    </div>

    <script>
    /**
     * ============================================================
     * Batch Image Annotation Tool - Main Application Logic
     * ============================================================
     * 
     * Architecture:
     * - images[]: Array of image data objects
     *   { id, name, file, imgElement, annotations[] }
     * - annotations[]: Array of annotation objects per image
     *   { id, text, x, y, fontSize, fontFamily, fontColor, bgColor, bgEnabled, bold }
     * - Canvas rendering: Draw image + annotations on each repaint
     * - Drag support: Click annotation to select, drag to move
     */

    // ==================== State ====================
    let images = [];              // All loaded images
    let currentImageIndex = -1;   // Currently selected image index
    let isAddingText = false;     // Whether we're in "add text" mode
    let draggingAnnotation = null; // Currently dragged annotation
    let dragOffset = { x: 0, y: 0 };
    let selectedAnnotationId = null;
    let annotationIdCounter = 0;

    // ==================== DOM References ====================
    const fileInput = document.getElementById('fileInput');
    const uploadArea = document.getElementById('uploadArea');
    const imageList = document.getElementById('imageList');
    const imageCount = document.getElementById('imageCount');
    const canvasContainer = document.getElementById('canvasContainer');
    const emptyState = document.getElementById('emptyState');
    const canvasToolbar = document.getElementById('canvasToolbar');
    const currentImageName = document.getElementById('currentImageName');
    const currentImageSize = document.getElementById('currentImageSize');
    const annotationListEl = document.getElementById('annotationList');
    const addTextBtn = document.getElementById('addTextBtn');
    const downloadAllBtn = document.getElementById('downloadAllBtn');
    const clearAllBtn = document.getElementById('clearAllBtn');
    const undoBtn = document.getElementById('undoBtn');
    const clearCurrentBtn = document.getElementById('clearCurrentBtn');
    const statusText = document.getElementById('statusText');
    const downloadModal = document.getElementById('downloadModal');
    const downloadStatus = document.getElementById('downloadStatus');
    const progressBarFill = document.getElementById('progressBarFill');

    // Toolbar inputs
    const fontFamilyInput = document.getElementById('fontFamily');
    const fontSizeInput = document.getElementById('fontSize');
    const fontColorInput = document.getElementById('fontColor');
    const bgColorInput = document.getElementById('bgColor');
    const bgEnabledInput = document.getElementById('bgEnabled');
    const boldEnabledInput = document.getElementById('boldEnabled');

    // ==================== Canvas Setup ====================
    let canvas = null;
    let ctx = null;

    /**
     * Initialize the canvas element inside the canvas container
     */
    function initCanvas() {
        canvas = document.createElement('canvas');
        ctx = canvas.getContext('2d');
        canvas.style.display = 'none';

        // Canvas event listeners
        canvas.addEventListener('mousedown', onCanvasMouseDown);
        canvas.addEventListener('mousemove', onCanvasMouseMove);
        canvas.addEventListener('mouseup', onCanvasMouseUp);
        canvas.addEventListener('mouseleave', onCanvasMouseUp);

        canvasContainer.appendChild(canvas);
    }

    initCanvas();

    // ==================== File Upload ====================

    // Click to upload
    uploadArea.addEventListener('click', () => fileInput.click());

    // Drag and drop
    uploadArea.addEventListener('dragover', (e) => {
        e.preventDefault();
        uploadArea.classList.add('dragover');
    });

    uploadArea.addEventListener('dragleave', () => {
        uploadArea.classList.remove('dragover');
    });

    uploadArea.addEventListener('drop', (e) => {
        e.preventDefault();
        uploadArea.classList.remove('dragover');
        const files = Array.from(e.dataTransfer.files).filter(f => f.type.startsWith('image/'));
        if (files.length > 0) {
            loadImages(files);
        }
    });

    // File input change
    fileInput.addEventListener('change', (e) => {
        const files = Array.from(e.target.files);
        if (files.length > 0) {
            loadImages(files);
        }
        fileInput.value = ''; // Reset so same file can be re-uploaded
    });

    /**
     * Load image files and add them to the images array
     * @param {File[]} files - Array of image files
     */
    function loadImages(files) {
        let loadedCount = 0;
        const total = files.length;

        files.forEach((file) => {
            const reader = new FileReader();
            reader.onload = (e) => {
                const img = new Image();
                img.onload = () => {
                    const imageData = {
                        id: Date.now() + Math.random(),
                        name: file.name,
                        file: file,
                        dataUrl: e.target.result,
                        imgElement: img,
                        annotations: []
                    };
                    images.push(imageData);
                    loadedCount++;

                    if (loadedCount === total) {
                        renderImageList();
                        updateButtons();
                        // Auto-select first image if none selected
                        if (currentImageIndex === -1 && images.length > 0) {
                            selectImage(0);
                        }
                        statusText.textContent = `Loaded ${total} image(s). Total: ${images.length}`;
                    }
                };
                img.src = e.target.result;
            };
            reader.readAsDataURL(file);
        });
    }

    // ==================== Image List Rendering ====================

    /**
     * Render the sidebar image list
     */
    function renderImageList() {
        imageList.innerHTML = '';
        imageCount.textContent = images.length;

        images.forEach((imgData, index) => {
            const item = document.createElement('div');
            item.className = 'image-item' + (index === currentImageIndex ? ' active' : '');
            item.innerHTML = `
                <img src="${imgData.dataUrl}" alt="${imgData.name}">
                <div class="image-item-info">
                    <div class="image-item-name" title="${imgData.name}">${imgData.name}</div>
                    <div class="image-item-annotations">${imgData.annotations.length} annotation(s)</div>
                </div>
                <button class="remove-btn" title="Remove image">✕</button>
            `;

            // Click to select image
            item.addEventListener('click', (e) => {
                if (!e.target.classList.contains('remove-btn')) {
                    selectImage(index);
                }
            });

            // Remove button
            item.querySelector('.remove-btn').addEventListener('click', (e) => {
                e.stopPropagation();
                removeImage(index);
            });

            imageList.appendChild(item);
        });
    }

    /**
     * Select an image by index and display it on the canvas
     * @param {number} index - Index in the images array
     */
    function selectImage(index) {
        if (index < 0 || index >= images.length) return;

        currentImageIndex = index;
        const imgData = images[index];

        // Show canvas, hide empty state
        emptyState.style.display = 'none';
        canvas.style.display = 'block';
        canvasToolbar.style.display = 'flex';

        // Set canvas size to match image
        canvas.width = imgData.imgElement.naturalWidth;
        canvas.height = imgData.imgElement.naturalHeight;

        // Scale canvas display if too large
        fitCanvasToContainer();

        // Update info
        currentImageName.textContent = imgData.name;
        currentImageSize.textContent = `${canvas.width} × ${canvas.height}`;

        // Reset state
        isAddingText = false;
        addTextBtn.textContent = '✏️ Add Text (Click on Image)';
        selectedAnnotationId = null;
        draggingAnnotation = null;

        // Render
        renderCanvas();
        renderAnnotationList();
        renderImageList();
        updateButtons();
    }

    /**
     * Fit the canvas display size within the container while maintaining aspect ratio
     */
    function fitCanvasToContainer() {
        const containerRect = canvasContainer.getBoundingClientRect();
        const maxW = containerRect.width - 40;
        const maxH = containerRect.height - 40;

        const imgData = images[currentImageIndex];
        const imgW = imgData.imgElement.naturalWidth;
        const imgH = imgData.imgElement.naturalHeight;

        const scale = Math.min(maxW / imgW, maxH / imgH, 1);

        canvas.style.width = (imgW * scale) + 'px';
        canvas.style.height = (imgH * scale) + 'px';
    }

    // Refit on window resize
    window.addEventListener('resize', () => {
        if (currentImageIndex >= 0) {
            fitCanvasToContainer();
        }
    });

    /**
     * Remove an image from the list
     * @param {number} index - Index to remove
     */
    function removeImage(index) {
        images.splice(index, 1);

        if (images.length === 0) {
            currentImageIndex = -1;
            canvas.style.display = 'none';
            canvasToolbar.style.display = 'none';
            emptyState.style.display = 'flex';
            annotationListEl.innerHTML = `
                <div class="empty-state" style="padding:40px 20px;">
                    <p style="font-size:12px;">Select an image and click on it to add annotations</p>
                </div>
            `;
        } else if (currentImageIndex >= images.length) {
            selectImage(images.length - 1);
        } else if (currentImageIndex === index) {
            selectImage(Math.min(index, images.length - 1));
        } else if (currentImageIndex > index) {
            currentImageIndex--;
        }

        renderImageList();
        updateButtons();
        statusText.textContent = `Image removed. ${images.length} remaining.`;
    }

    // ==================== Canvas Rendering ====================

    /**
     * Render the current image and all its annotations onto the canvas
     */
    function renderCanvas() {
        if (currentImageIndex < 0) return;

        const imgData = images[currentImageIndex];
        const img = imgData.imgElement;

        // Clear and draw image
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, 0, 0);

        // Draw each annotation
        imgData.annotations.forEach((ann) => {
            drawAnnotation(ann, ann.id === selectedAnnotationId);
        });
    }

    /**
     * Draw a single annotation on the canvas
     * @param {Object} ann - Annotation object
     * @param {boolean} isSelected - Whether this annotation is selected
     */
    function drawAnnotation(ann, isSelected) {
        const fontWeight = ann.bold ? 'bold' : 'normal';
        ctx.font = `${fontWeight} ${ann.fontSize}px "${ann.fontFamily}"`;
        ctx.textBaseline = 'top';

        const text = ann.text;
        const metrics = ctx.measureText(text);
        const textWidth = metrics.width;
        const textHeight = ann.fontSize * 1.2;

        // Draw background if enabled
        if (ann.bgEnabled) {
            const padding = 4;
            ctx.fillStyle = ann.bgColor;
            ctx.fillRect(
                ann.x - padding,
                ann.y - padding,
                textWidth + padding * 2,
                textHeight + padding * 2
            );
        }

        // Draw text
        ctx.fillStyle = ann.fontColor;
        ctx.fillText(text, ann.x, ann.y);

        // Draw selection border
        if (isSelected) {
            const padding = 6;
            ctx.strokeStyle = '#e94560';
            ctx.lineWidth = 2;
            ctx.setLineDash([5, 3]);
            ctx.strokeRect(
                ann.x - padding,
                ann.y - padding,
                textWidth + padding * 2,
                textHeight + padding * 2
            );
            ctx.setLineDash([]);

            // Draw corner handles
            const handleSize = 6;
            ctx.fillStyle = '#e94560';
            const corners = [
                [ann.x - padding, ann.y - padding],
                [ann.x + textWidth + padding - handleSize, ann.y - padding],
                [ann.x - padding, ann.y + textHeight + padding - handleSize],
                [ann.x + textWidth + padding - handleSize, ann.y + textHeight + padding - handleSize]
            ];
            corners.forEach(([cx, cy]) => {
                ctx.fillRect(cx, cy, handleSize, handleSize);
            });
        }
    }

    // ==================== Canvas Mouse Events ====================

    /**
     * Get mouse position relative to the canvas in image coordinates
     */
    function getCanvasCoords(e) {
        const rect = canvas.getBoundingClientRect();
        const scaleX = canvas.width / rect.width;
        const scaleY = canvas.height / rect.height;
        return {
            x: (e.clientX - rect.left) * scaleX,
            y: (e.clientY - rect.top) * scaleY
        };
    }

    /**
     * Find annotation at given coordinates (top-most first)
     */
    function findAnnotationAt(x, y) {
        if (currentImageIndex < 0) return null;
        const imgData = images[currentImageIndex];

        // Search in reverse order (top-most annotation first)
        for (let i = imgData.annotations.length - 1; i >= 0; i--) {
            const ann = imgData.annotations[i];
            const fontWeight = ann.bold ? 'bold' : 'normal';
            ctx.font = `${fontWeight} ${ann.fontSize}px "${ann.fontFamily}"`;
            const metrics = ctx.measureText(ann.text);
            const textWidth = metrics.width;
            const textHeight = ann.fontSize * 1.2;
            const padding = 6;

            if (
                x >= ann.x - padding &&
                x <= ann.x + textWidth + padding &&
                y >= ann.y - padding &&
                y <= ann.y + textHeight + padding
            ) {
                return ann;
            }
        }
        return null;
    }

    function onCanvasMouseDown(e) {
        if (currentImageIndex < 0) return;
        const coords = getCanvasCoords(e);

        if (isAddingText) {
            // Add new annotation at click position
            const text = prompt('Enter annotation text:', 'Sample Text');
            if (text && text.trim()) {
                const ann = {
                    id: ++annotationIdCounter,
                    text: text.trim(),
                    x: coords.x,
                    y: coords.y,
                    fontSize: parseInt(fontSizeInput.value) || 24,
                    fontFamily: fontFamilyInput.value,
                    fontColor: fontColorInput.value,
                    bgColor: bgColorInput.value,
                    bgEnabled: bgEnabledInput.checked,
                    bold: boldEnabledInput.checked
                };
                images[currentImageIndex].annotations.push(ann);
                selectedAnnotationId = ann.id;
                renderCanvas();
                renderAnnotationList();
                renderImageList();
                statusText.textContent = `Annotation added: "${ann.text}"`;
            }
            // Stay in add-text mode for convenience
            return;
        }

        // Check if clicking on an existing annotation
        const ann = findAnnotationAt(coords.x, coords.y);
        if (ann) {
            selectedAnnotationId = ann.id;
            draggingAnnotation = ann;
            dragOffset.x = coords.x - ann.x;
            dragOffset.y = coords.y - ann.y;
            canvas.style.cursor = 'grabbing';
            renderCanvas();
            renderAnnotationList();
        } else {
            selectedAnnotationId = null;
            renderCanvas();
            renderAnnotationList();
        }
    }

    function onCanvasMouseMove(e) {
        if (currentImageIndex < 0) return;
        const coords = getCanvasCoords(e);

        if (draggingAnnotation) {
            // Move the annotation
            draggingAnnotation.x = coords.x - dragOffset.x;
            draggingAnnotation.y = coords.y - dragOffset.y;
            renderCanvas();
            return;
        }

        // Update cursor based on hover
        if (!isAddingText) {
            const ann = findAnnotationAt(coords.x, coords.y);
            canvas.style.cursor = ann ? 'grab' : 'crosshair';
        }
    }

    function onCanvasMouseUp(e) {
        if (draggingAnnotation) {
            draggingAnnotation = null;
            canvas.style.cursor = isAddingText ? 'crosshair' : 'default';
            renderAnnotationList();
            statusText.textContent = 'Annotation repositioned';
        }
    }

    // ==================== Annotation List Panel ====================

    /**
     * Render the annotation list for the current image
     */
    function renderAnnotationList() {
        if (currentImageIndex < 0) {
            annotationListEl.innerHTML = `
                <div class="empty-state" style="padding:40px 20px;">
                    <p style="font-size:12px;">No image selected</p>
                </div>
            `;
            return;
        }

        const imgData = images[currentImageIndex];

        if (imgData.annotations.length === 0) {
            annotationListEl.innerHTML = `
                <div class="empty-state" style="padding:40px 20px;">
                    <p style="font-size:12px;">No annotations yet.<br>Click "Add Text" then click on the image.</p>
                </div>
            `;
            return;
        }

        annotationListEl.innerHTML = '';

        imgData.annotations.forEach((ann, index) => {
            const entry = document.createElement('div');
            entry.className = 'annotation-entry' + (ann.id === selectedAnnotationId ? ' selected' : '');
            entry.innerHTML = `
                <div class="annotation-entry-header">
                    <span class="annotation-entry-index">#${index + 1}</span>
                    <button class="delete-annotation" title="Delete annotation">🗑️</button>
                </div>
                <input type="text" value="${escapeHtml(ann.text)}" data-ann-id="${ann.id}" class="ann-text-input">
                <div class="annotation-entry-controls">
                    <label>Size:</label>
                    <input type="number" value="${ann.fontSize}" min="8" max="200" data-ann-id="${ann.id}" class="ann-size-input">
                    <label>Color:</label>
                    <input type="color" value="${ann.fontColor}" data-ann-id="${ann.id}" class="ann-color-input">
                    <label>BG:</label>
                    <input type="color" value="${ann.bgColor}" data-ann-id="${ann.id}" class="ann-bg-input">
                </div>
            `;

            // Click to select
            entry.addEventListener('click', (e) => {
                if (e.target.tagName !== 'INPUT' && e.target.tagName !== 'BUTTON') {
                    selectedAnnotationId = ann.id;
                    renderCanvas();
                    renderAnnotationList();
                }
            });

            // Text change
            entry.querySelector('.ann-text-input').addEventListener('input', (e) => {
                ann.text = e.target.value;
                renderCanvas();
                renderImageList();
            });

            // Size change
            entry.querySelector('.ann-size-input').addEventListener('input', (e) => {
                ann.fontSize = parseInt(e.target.value) || 24;
                renderCanvas();
            });

            // Color change
            entry.querySelector('.ann-color-input').addEventListener('input', (e) => {
                ann.fontColor = e.target.value;
                renderCanvas();
            });

            // BG color change
            entry.querySelector('.ann-bg-input').addEventListener('input', (e) => {
                ann.bgColor = e.target.value;
                renderCanvas();
            });

            // Delete
            entry.querySelector('.delete-annotation').addEventListener('click', () => {
                imgData.annotations = imgData.annotations.filter(a => a.id !== ann.id);
                if (selectedAnnotationId === ann.id) selectedAnnotationId = null;
                renderCanvas();
                renderAnnotationList();
                renderImageList();
                statusText.textContent = 'Annotation deleted';
            });

            annotationListEl.appendChild(entry);
        });
    }

    // ==================== Toolbar Actions ====================

    // Add Text mode toggle
    addTextBtn.addEventListener('click', () => {
        isAddingText = !isAddingText;
        if (isAddingText) {
            addTextBtn.textContent = '🚫 Cancel Add Mode';
            addTextBtn.classList.remove('btn-primary');
            addTextBtn.classList.add('btn-danger');
            canvas.style.cursor = 'crosshair';
            statusText.textContent = 'Click anywhere on the image to place a text annotation';
        } else {
            addTextBtn.textContent = '✏️ Add Text (Click on Image)';
            addTextBtn.classList.remove('btn-danger');
            addTextBtn.classList.add('btn-primary');
            canvas.style.cursor = 'default';
            statusText.textContent = 'Add mode cancelled';
        }
    });

    // Undo last annotation
    undoBtn.addEventListener('click', () => {
        if (currentImageIndex < 0) return;
        const imgData = images[currentImageIndex];
        if (imgData.annotations.length > 0) {
            const removed = imgData.annotations.pop();
            if (selectedAnnotationId === removed.id) selectedAnnotationId = null;
            renderCanvas();
            renderAnnotationList();
            renderImageList();
            statusText.textContent = `Undone: "${removed.text}"`;
        }
    });

    // Clear current image annotations
    clearCurrentBtn.addEventListener('click', () => {
        if (currentImageIndex < 0) return;
        if (confirm('Clear all annotations on this image?')) {
            images[currentImageIndex].annotations = [];
            selectedAnnotationId = null;
            renderCanvas();
            renderAnnotationList();
            renderImageList();
            statusText.textContent = 'All annotations cleared for this image';
        }
    });

    // Clear all images
    clearAllBtn.addEventListener('click', () => {
        if (confirm('Remove ALL images and annotations? This cannot be undone.')) {
            images = [];
            currentImageIndex = -1;
            canvas.style.display = 'none';
            canvasToolbar.style.display = 'none';
            emptyState.style.display = 'flex';
            renderImageList();
            renderAnnotationList();
            updateButtons();
            statusText.textContent = 'All images cleared';
        }
    });

    // ==================== Batch Download ====================

    downloadAllBtn.addEventListener('click', async () => {
        if (images.length === 0) return;

        // Show progress modal
        downloadModal.classList.remove('hidden');
        downloadStatus.textContent = 'Preparing images...';
        progressBarFill.style.width = '0%';

        try {
            const zip = new JSZip();
            const total = images.length;

            for (let i = 0; i < total; i++) {
                const imgData = images[i];
                downloadStatus.textContent = `Processing ${i + 1} of ${total}: ${imgData.name}`;
                progressBarFill.style.width = ((i / total) * 100) + '%';

                // Create an offscreen canvas for export at full resolution
                const exportCanvas = document.createElement('canvas');
                const exportCtx = exportCanvas.getContext('2d');
                exportCanvas.width = imgData.imgElement.naturalWidth;
                exportCanvas.height = imgData.imgElement.naturalHeight;

                // Draw image
                exportCtx.drawImage(imgData.imgElement, 0, 0);

                // Draw annotations
                imgData.annotations.forEach((ann) => {
                    const fontWeight = ann.bold ? 'bold' : 'normal';
                    exportCtx.font = `${fontWeight} ${ann.fontSize}px "${ann.fontFamily}"`;
                    exportCtx.textBaseline = 'top';

                    const metrics = exportCtx.measureText(ann.text);
                    const textWidth = metrics.width;
                    const textHeight = ann.fontSize * 1.2;

                    if (ann.bgEnabled) {
                        const padding = 4;
                        exportCtx.fillStyle = ann.bgColor;
                        exportCtx.fillRect(
                            ann.x - padding,
                            ann.y - padding,
                            textWidth + padding * 2,
                            textHeight + padding * 2
                        );
                    }

                    exportCtx.fillStyle = ann.fontColor;
                    exportCtx.fillText(ann.text, ann.x, ann.y);
                });

                // Convert to blob
                const blob = await new Promise((resolve) => {
                    exportCanvas.toBlob(resolve, 'image/png');
                });

                // Add to zip - ensure unique filename
                let fileName = imgData.name;
                if (!fileName.toLowerCase().endsWith('.png')) {
                    // Replace extension with .png
                    const lastDot = fileName.lastIndexOf('.');
                    if (lastDot > 0) {
                        fileName = fileName.substring(0, lastDot) + '.png';
                    } else {
                        fileName = fileName + '.png';
                    }
                }

                zip.file(fileName, blob);

                // Small delay to allow UI update
                await new Promise(r => setTimeout(r, 50));
            }

            downloadStatus.textContent = 'Creating ZIP file...';
            progressBarFill.style.width = '90%';

            const zipBlob = await zip.generateAsync({ type: 'blob' });

            progressBarFill.style.width = '100%';
            downloadStatus.textContent = 'Download starting...';

            // Trigger download
            saveAs(zipBlob, `annotated_images_${Date.now()}.zip`);

            statusText.textContent = `Downloaded ${total} annotated image(s)`;

            // Hide modal after short delay
            setTimeout(() => {
                downloadModal.classList.add('hidden');
            }, 1000);

        } catch (err) {
            console.error('Download error:', err);
            downloadStatus.textContent = 'Error: ' + err.message;
            setTimeout(() => {
                downloadModal.classList.add('hidden');
            }, 3000);
        }
    });

    // ==================== Utility Functions ====================

    /**
     * Update button enabled/disabled states based on current state
     */
    function updateButtons() {
        const hasImages = images.length > 0;
        const hasCurrentImage = currentImageIndex >= 0;

        addTextBtn.disabled = !hasCurrentImage;
        downloadAllBtn.disabled = !hasImages;
        clearAllBtn.disabled = !hasImages;
        undoBtn.disabled = !hasCurrentImage;
        clearCurrentBtn.disabled = !hasCurrentImage;
    }

    /**
     * Escape HTML special characters to prevent XSS
     * @param {string} str - Raw string
     * @returns {string} Escaped string
     */
    function escapeHtml(str) {
        const div = document.createElement('div');
        div.textContent = str;
        return div.innerHTML.replace(/"/g, '&quot;');
    }

    // ==================== Keyboard Shortcuts ====================

    document.addEventListener('keydown', (e) => {
        // Delete selected annotation
        if ((e.key === 'Delete' || e.key === 'Backspace') && selectedAnnotationId !== null) {
            // Don't delete if user is typing in an input
            if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') return;

            if (currentImageIndex >= 0) {
                const imgData = images[currentImageIndex];
                imgData.annotations = imgData.annotations.filter(a => a.id !== selectedAnnotationId);
                selectedAnnotationId = null;
                renderCanvas();
                renderAnnotationList();
                renderImageList();
                statusText.textContent = 'Annotation deleted';
            }
        }

        // Escape to cancel add mode
        if (e.key === 'Escape' && isAddingText) {
            addTextBtn.click();
        }

        // Ctrl+Z to undo
        if (e.ctrlKey && e.key === 'z') {
            if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') return;
            e.preventDefault();
            undoBtn.click();
        }
    });

    // ==================== Initialize ====================
    updateButtons();
    statusText.textContent = 'Ready — Upload images to get started';

    </script>
</body>
</html>
```

## How to Use

1. **Save** the code above as `index.html`
2. **Open** it in any modern browser (Chrome, Firefox, Edge, Safari)
3. **Upload images** by clicking the upload area or dragging files onto it

## Feature Summary

| Feature | Description |
|---|---|
| **Multi-image upload** | Drag & drop or click to upload multiple images (JPG, PNG, GIF, WebP) |
| **Text annotations** | Click "Add Text" then click anywhere on the image to place text |
| **Drag to reposition** | Click and drag any annotation to move it freely |
| **Per-annotation styling** | Edit text, font size, text color, and background color per annotation |
| **Global toolbar** | Set default font family, size, color, bold, and background before adding |
| **Annotation panel** | Right sidebar lists all annotations with inline editing |
| **Undo** | Remove the last annotation (button or `Ctrl+Z`) |
| **Delete** | Remove individual annotations or press `Delete` key when selected |
| **Batch download** | Exports all annotated images as a `.zip` file at full resolution |
| **Keyboard shortcuts** | `Delete` removes selected, `Escape` cancels add mode, `Ctrl+Z` undoes |

# Video Subtitle Adding Tool

A complete web-based tool for adding styled subtitles to videos with timeline markers, customization options, and export capability.

## Architecture

- **Backend**: Python + Flask + MoviePy + Pillow
- **Frontend**: HTML5 + CSS3 + Vanilla JavaScript
- **Features**: Upload, timeline markers, font/color/position/opacity controls, semi-transparent backgrounds, export

## Project Structure

```
subtitle_tool/
├── app.py              # Flask backend
├── requirements.txt    # Dependencies
├── templates/
│   └── index.html      # Frontend UI
├── static/
│   ├── style.css
│   └── app.js
├── uploads/            # Uploaded videos
└── outputs/            # Exported videos
```

## 1. `requirements.txt`

```txt
Flask==3.0.0
moviepy==1.0.3
Pillow==10.1.0
numpy==1.26.2
```

