- **Windows**: Download from https://ffmpeg.org and add to PATH
- **macOS**: `brew install ffmpeg`
- **Linux**: `sudo apt install ffmpeg`

## 2. `app.py`

```python
import os
import json
import uuid
from pathlib import Path
from flask import Flask, request, jsonify, send_file, render_template, send_from_directory
from moviepy.editor import VideoFileClip, CompositeVideoClip, ImageClip
from PIL import Image, ImageDraw, ImageFont
import numpy as np

app = Flask(__name__)
app.config['MAX_CONTENT_LENGTH'] = 500 * 1024 * 1024  # 500MB

BASE_DIR = Path(__file__).parent
UPLOAD_DIR = BASE_DIR / "uploads"
OUTPUT_DIR = BASE_DIR / "outputs"
FONT_DIR = BASE_DIR / "fonts"

UPLOAD_DIR.mkdir(exist_ok=True)
OUTPUT_DIR.mkdir(exist_ok=True)
FONT_DIR.mkdir(exist_ok=True)

# Download a default font if none exists
DEFAULT_FONT = FONT_DIR / "default.ttf"
if not DEFAULT_FONT.exists():
    try:
        import urllib.request
        urllib.request.urlretrieve(
            "https://github.com/google/fonts/raw/main/ofl/roboto/Roboto-Regular.ttf",
            DEFAULT_FONT
        )
    except Exception:
        DEFAULT_FONT = None


def get_font(font_name, size):
    """Load font by name, fallback to default."""
    font_path = FONT_DIR / font_name
    if not font_path.exists():
        font_path = DEFAULT_FONT
    try:
        return ImageFont.truetype(str(font_path), size) if font_path else ImageFont.load_default()
    except Exception:
        return ImageFont.load_default()


def render_subtitle_frame(text, video_size, style):
    """Render a single subtitle frame as a numpy RGBA array."""
    width, height = video_size
    img = Image.new("RGBA", (width, height), (0, 0, 0, 0))
    draw = ImageDraw.Draw(img)

    font = get_font(style.get("font", "default.ttf"), int(style.get("fontSize", 36)))

    # Measure text
    bbox = draw.textbbox((0, 0), text, font=font)
    text_w = bbox[2] - bbox[0]
    text_h = bbox[3] - bbox[1]

    padding = 12
    box_w = text_w + padding * 2
    box_h = text_h + padding * 2

    # Position: bottom / top / center
    position = style.get("position", "bottom")
    x = (width - box_w) // 2
    if position == "bottom":
        y = height - box_h - 40
    elif position == "top":
        y = 40
    else:  # center
        y = (height - box_h) // 2

    # Parse colors
    def hex_to_rgb(h):
        h = h.lstrip("#")
        return tuple(int(h[i:i+2], 16) for i in (0, 2, 4))

    bg_color = hex_to_rgb(style.get("bgColor", "#000000"))
    fg_color = hex_to_rgb(style.get("textColor", "#FFFFFF"))
    bg_opacity = float(style.get("bgOpacity", 0.6))

    # Draw semi-transparent background
    bg_img = Image.new("RGBA", (box_w, box_h), (*bg_color, int(255 * bg_opacity)))
    img.paste(bg_img, (x, y), bg_img)

    # Draw text
    draw.text((x + padding, y + padding), text, font=font, fill=(*fg_color, 255))

    return np.array(img)


@app.route("/")
def index():
    return render_template("index.html")


@app.route("/uploads/<path:filename>")
def serve_upload(filename):
    return send_from_directory(UPLOAD_DIR, filename)


@app.route("/fonts")
def list_fonts():
    fonts = [f.name for f in FONT_DIR.glob("*.ttf")] + [f.name for f in FONT_DIR.glob("*.otf")]
    return jsonify(fonts)


@app.route("/upload", methods=["POST"])
def upload():
    if "video" not in request.files:
        return jsonify({"error": "No video file"}), 400
    file = request.files["video"]
    ext = Path(file.filename).suffix.lower()
    if ext not in {".mp4", ".mov", ".avi", ".mkv", ".webm"}:
        return jsonify({"error": "Unsupported format"}), 400

    video_id = str(uuid.uuid4())[:8]
    filename = f"{video_id}{ext}"
    save_path = UPLOAD_DIR / filename
    file.save(save_path)

    clip = VideoFileClip(str(save_path))
    info = {
        "id": video_id,
        "filename": filename,
        "duration": clip.duration,
        "width": clip.w,
        "height": clip.h,
        "url": f"/uploads/{filename}"
    }
    clip.close()
    return jsonify(info)


@app.route("/export", methods=["POST"])
def export():
    data = request.json
    filename = data.get("filename")
    subtitles = data.get("subtitles", [])

    src_path = UPLOAD_DIR / filename
    if not src_path.exists():
        return jsonify({"error": "Video not found"}), 404

    video = VideoFileClip(str(src_path))
    video_size = (video.w, video.h)

    subtitle_clips = []
    for sub in subtitles:
        text = sub.get("text", "").strip()
        if not text:
            continue
        start = float(sub.get("start", 0))
        end = float(sub.get("end", video.duration))
        style = sub.get("style", {})

        frame = render_subtitle_frame(text, video_size, style)
        img_clip = (ImageClip(frame, ismask=False, transparent=True)
                    .set_duration(end - start)
                    .set_start(start))
        subtitle_clips.append(img_clip)

    final = CompositeVideoClip([video] + subtitle_clips, size=video_size)

    out_name = f"subtitled_{Path(filename).stem}.mp4"
    out_path = OUTPUT_DIR / out_name
    final.write_videofile(
        str(out_path),
        codec="libx264",
        audio_codec="aac",
        fps=video.fps or 24,
        logger=None
    )
    video.close()
    final.close()

    return jsonify({"url": f"/download/{out_name}", "filename": out_name})


@app.route("/download/<path:filename>")
def download(filename):
    return send_file(OUTPUT_DIR / filename, as_attachment=True)


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000, debug=True)
```

