## 5. `static/app.js`

```javascript
const state = {
  video: null,
  filename: null,
  duration: 0,
  subtitles: [],
  currentSubId: null,
  fonts: []
};

const $ = id => document.getElementById(id);

function showStatus(msg, type = "info") {
  const s = $("status");
  s.textContent = msg;
  s.className = "status show " + type;
  setTimeout(() => s.className = "status", 3500);
}

async function loadFonts() {
  const res = await fetch("/fonts");
  state.fonts = await res.json();
  const sel = $("subFont");
  sel.innerHTML = state.fonts.map(f => `<option value="${f}">${f}</option>`).join("");
}

$("uploadBtn").onclick = () => $("videoInput").click();

$("videoInput").onchange = async e => {
  const file = e.target.files[0];
  if (!file) return;
  showStatus("Uploading...");
  const fd = new FormData();
  fd.append("video", file);
  try {
    const res = await fetch("/upload", { method: "POST", body: fd });
    const data = await res.json();
    if (!res.ok) throw new Error(data.error);
    state.filename = data.filename;
    state.duration = data.duration;
    $("video").src = data.url;
    $("videoName").textContent = file.name;
    $("duration").textContent = data.duration.toFixed(2);
    $("addSubBtn").disabled = false;
    $("exportBtn").disabled = false;
    showStatus("Video loaded!", "success");
  } catch (err) {
    showStatus("Upload failed: " + err.message, "error");
  }
};

const video = $("video");
video.ontimeupdate = () => {
  $("currentTime").textContent = video.currentTime.toFixed(2);
  const pct = (video.currentTime / state.duration) * 100;
  $("timelineProgress").style.width = pct + "%";
  $("timelineCursor").style.left = pct + "%";
  highlightActiveSubtitle();
};

$("playBtn").onclick = () => {
  if (video.paused) video.play(); else video.pause();
};

$("timelineTrack").onclick = e => {
  const rect = e.currentTarget.getBoundingClientRect();
  const pct = (e.clientX - rect.left) / rect.width;
  video.currentTime = pct * state.duration;
};

$("addSubBtn").onclick = () => {
  const start = video.currentTime;
  const end = Math.min(start + 3, state.duration);
  const sub = {
    id: Date.now(),
    text: "New subtitle",
    start, end,
    style: {
      font: state.fonts[0] || "default.ttf",
      fontSize: 36,
      textColor: "#FFFFFF",
      bgColor: "#000000",
      bgOpacity: 0.6,
      position: "bottom"
    }
  };
  state.subtitles.push(sub);
  renderSubtitles();
  selectSubtitle(sub.id);
};

function renderSubtitles() {
  const list = $("subtitleList");
  list.innerHTML = state.subtitles.map(s => `
    <div class="subtitle-item ${s.id === state.currentSubId ? 'active' : ''}"
         data-id="${s.id}">
      <div>${escapeHtml(s.text)}</div>
      <div class="meta">${s.start.toFixed(2)}s → ${s.end.toFixed(2)}s</div>
    </div>
  `).join("") || "<p style='color:#888'>No subtitles yet.</p>";

  list.querySelectorAll(".subtitle-item").forEach(el => {
    el.onclick = () => selectSubtitle(parseInt(el.dataset.id));
  });

  renderTimelineMarkers();
}

function renderTimelineMarkers() {
  const container = $("timelineMarkers");
  container.innerHTML = state.subtitles.map(s => {
    const left = (s.start / state.duration) * 100;
    const width = ((s.end - s.start) / state.duration) * 100;
    return `<div class="timeline-marker ${s.id === state.currentSubId ? 'active' : ''}"
                 style="left:${left}%;width:${width}%" data-id="${s.id}"></div>`;
  }).join("");
  container.querySelectorAll(".timeline-marker").forEach(el => {
    el.onclick = e => {
      e.stopPropagation();
      selectSubtitle(parseInt(el.dataset.id));
      video.currentTime = state.subtitles.find(s => s.id === parseInt(el.dataset.id)).start;
    };
  });
}

function selectSubtitle(id) {
  state.currentSubId = id;
  const sub = state.subtitles.find(s => s.id === id);
  if (!sub) return;
  $("styleEditor").style.display = "block";
  $("subText").value = sub.text;
  $("subStart").value = sub.start.toFixed(2);
  $("subEnd").value = sub.end.toFixed(2);
  $("subFont").value = sub.style.font;
  $("subSize").value = sub.style.fontSize;
  $("subColor").value = sub.style.textColor;
  $("subBg").value = sub.style.bgColor;
  $("subOpacity").value = sub.style.bgOpacity;
  $("opacityVal").textContent = sub.style.bgOpacity;
  $("subPosition").value = sub.style.position;
  renderSubtitles();
}

function highlightActiveSubtitle() {
  const t = video.currentTime;
  const active = state.subtitles.find(s => t >= s.start && t <= s.end);
  document.querySelectorAll(".timeline-marker").forEach(el => {
    const id = parseInt(el.dataset.id);
    el.classList.toggle("active", active && active.id === id);
  });
}

["subText","subStart","subEnd","subFont","subSize","subColor","subBg","subOpacity","subPosition"]
  .forEach(id => $(id).oninput = updateCurrentSubtitle);

function updateCurrentSubtitle() {
  const sub = state.subtitles.find(s => s.id === state.currentSubId);
  if (!sub) return;
  sub.text = $("subText").value;
  sub.start = parseFloat($("subStart").value) || 0;
  sub.end = parseFloat($("subEnd").value) || state.duration;
  sub.style = {
    font: $("subFont").value,
    fontSize: parseInt($("subSize").value),
    textColor: $("subColor").value,
    bgColor: $("subBg").value,
    bgOpacity: parseFloat($("subOpacity").value),
    position: $("subPosition").value
  };
  $("opacityVal").textContent = sub.style.bgOpacity.toFixed(2);
  renderSubtitles();
}

$("saveSubBtn").onclick = () => {
  showStatus("Subtitle saved", "success");
};

$("deleteSubBtn").onclick = () => {
  state.subtitles = state.subtitles.filter(s => s.id !== state.currentSubId);
  state.currentSubId = null;
  $("styleEditor").style.display = "none";
  renderSubtitles();
};

$("exportBtn").onclick = async () => {
  if (!state.filename) return;
  showStatus("Rendering video... this may take a while");
  $("exportBtn").disabled = true;
  try {
    const res = await fetch("/export", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ filename: state.filename, subtitles: state.subtitles })
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.error);
    showStatus("Export complete! Downloading...", "success");
    const a = document.createElement("a");
    a.href = data.url;
    a.download = data.filename;
    a.click();
  } catch (err) {
    showStatus("Export failed: " + err.message, "error");
  } finally {
    $("exportBtn").disabled = false;
  }
};

function escapeHtml(s) {
  return s.replace(/[&<>"']/g, c => ({
    "&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"
  }[c]));
}

loadFonts();
```

## How to Run

```bash
# 1. Create project folder and place all files
mkdir subtitle_tool && cd subtitle_tool
# (create the files above in their respective locations)

# 2. Install dependencies
pip install -r requirements.txt

# 3. Ensure FFmpeg is installed and in PATH
ffmpeg -version

# 4. Run the server
python app.py
```

Open **http://localhost:5000** in your browser.

## Usage Workflow

1. **Upload** a video file (MP4, MOV, AVI, MKV, WebM)
2. **Play** the video and pause at the desired start time
3. Click **"Add Subtitle at Current Time"** — a 3-second subtitle is created
4. **Edit** the subtitle in the right panel:
   - Text content
   - Start/end times
   - Font family and size
   - Text and background colors
   - Background opacity (semi-transparent box)
   - Position (top / center / bottom)
5. **Timeline markers** show all subtitles visually — click to jump
6. Click **"Export Video"** to burn subtitles into a new MP4 file

## Key Technical Highlights

| Feature | Implementation |
|---|---|
| Semi-transparent backgrounds | PIL `Image.new("RGBA")` with alpha channel composited via `Image.paste` |
| Timeline visualization | CSS-positioned divs with percentage-based widths |
| Subtitle rendering | Per-subtitle `ImageClip` with RGBA numpy arrays |
| Video compositing | MoviePy `CompositeVideoClip` overlays all subtitle clips |
| Font handling | Auto-downloads Roboto as fallback; supports custom `.ttf`/`.otf` in `/fonts` |

## Adding Custom Fonts

Drop any `.ttf` or `.otf` file into the `fonts/` directory — it will appear automatically in the font dropdown on next page load.

