## server.js

```javascript
/**
 * Multiplayer Shooting Game Server
 * Handles real-time synchronization, game state, and player management
 */

const express = require('express');
const http = require('http');
const { Server } = require('socket.io');
const path = require('path');

const app = express();
const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: '*' }
});

// Serve static files
app.use(express.static(path.join(__dirname, 'public')));

// ============ GAME CONFIGURATION ============
const CONFIG = {
  MAP_WIDTH: 2400,
  MAP_HEIGHT: 1800,
  PLAYER_SPEED: 4,
  PLAYER_RADIUS: 20,
  PLAYER_MAX_HP: 100,
  BULLET_SPEED: 12,
  BULLET_RADIUS: 5,
  BULLET_DAMAGE: 15,
  BULLET_LIFETIME: 80,       // frames before bullet disappears
  FIRE_RATE: 200,             // ms between shots
  RESPAWN_TIME: 3000,         // ms before respawn
  HEALTH_PACK_INTERVAL: 10000,// ms between health pack spawns
  HEALTH_PACK_HEAL: 30,
  HEALTH_PACK_RADIUS: 15,
  MAX_HEALTH_PACKS: 5
};

// ============ GAME STATE ============
let players = {};       // { socketId: playerData }
let bullets = [];       // active bullets
let healthPacks = [];   // health packs on map
let gameLoop = null;
let healthPackTimer = null;

// ============ UTILITY FUNCTIONS ============

/** Generate random position within map bounds */
function randomPosition() {
  return {
    x: Math.random() * (CONFIG.MAP_WIDTH - 100) + 50,
    y: Math.random() * (CONFIG.MAP_HEIGHT - 100) + 50
  };
}

/** Calculate distance between two points */
function distance(a, b) {
  return Math.sqrt((a.x - b.x) ** 2 + (a.y - b.y) ** 2);
}

/** Generate a unique bullet ID */
let bulletIdCounter = 0;
function nextBulletId() {
  return ++bulletIdCounter;
}

/** Generate a unique health pack ID */
let healthPackIdCounter = 0;
function nextHealthPackId() {
  return ++healthPackIdCounter;
}

/** Spawn a health pack at random location */
function spawnHealthPack() {
  if (healthPacks.length >= CONFIG.MAX_HEALTH_PACKS) return;
  const pos = randomPosition();
  healthPacks.push({
    id: nextHealthPackId(),
    x: pos.x,
    y: pos.y,
    radius: CONFIG.HEALTH_PACK_RADIUS,
    heal: CONFIG.HEALTH_PACK_HEAL
  });
}

/** Create a new player object */
function createPlayer(socketId, name) {
  const pos = randomPosition();
  return {
    id: socketId,
    name: name || `Player_${socketId.slice(0, 4)}`,
    x: pos.x,
    y: pos.y,
    radius: CONFIG.PLAYER_RADIUS,
    hp: CONFIG.PLAYER_MAX_HP,
    maxHp: CONFIG.PLAYER_MAX_HP,
    angle: 0,
    kills: 0,
    deaths: 0,
    alive: true,
    lastShot: 0,
    input: { up: false, down: false, left: false, right: false },
    color: `hsl(${Math.random() * 360}, 70%, 50%)`
  };
}

/** Get scoreboard data sorted by kills */
function getScoreboard() {
  return Object.values(players)
    .map(p => ({
      id: p.id,
      name: p.name,
      kills: p.kills,
      deaths: p.deaths,
      hp: p.alive ? p.hp : 0,
      alive: p.alive
    }))
    .sort((a, b) => b.kills - a.kills);
}

/** Broadcast updated game state to all players */
function broadcastState() {
  const state = {
    players: Object.values(players).map(p => ({
      id: p.id,
      name: p.name,
      x: p.x,
      y: p.y,
      radius: p.radius,
      hp: p.hp,
      maxHp: p.maxHp,
      angle: p.angle,
      alive: p.alive,
      color: p.color
    })),
    bullets: bullets.map(b => ({
      id: b.id,
      x: b.x,
      y: b.y,
      radius: b.radius,
      angle: b.angle,
      ownerId: b.ownerId
    })),
    healthPacks: healthPacks.map(h => ({
      id: h.id,
      x: h.x,
      y: h.y,
      radius: h.radius
    })),
    scoreboard: getScoreboard(),
    mapWidth: CONFIG.MAP_WIDTH,
    mapHeight: CONFIG.MAP_HEIGHT
  };
  io.emit('gameState', state);
}

// ============ GAME LOOP ============

function updateGame() {
  // Update player positions based on input
  for (const id in players) {
    const p = players[id];
    if (!p.alive) continue;

    let dx = 0, dy = 0;
    if (p.input.up) dy -= 1;
    if (p.input.down) dy += 1;
    if (p.input.left) dx -= 1;
    if (p.input.right) dx += 1;

    // Normalize diagonal movement
    if (dx !== 0 && dy !== 0) {
      const len = Math.sqrt(dx * dx + dy * dy);
      dx /= len;
      dy /= len;
    }

    p.x += dx * CONFIG.PLAYER_SPEED;
    p.y += dy * CONFIG.PLAYER_SPEED;

    // Clamp to map bounds
    p.x = Math.max(p.radius, Math.min(CONFIG.MAP_WIDTH - p.radius, p.x));
    p.y = Math.max(p.radius, Math.min(CONFIG.MAP_HEIGHT - p.radius, p.y));
  }

  // Update bullets
  for (let i = bullets.length - 1; i >= 0; i--) {
    const b = bullets[i];
    b.x += Math.cos(b.angle) * CONFIG.BULLET_SPEED;
    b.y += Math.sin(b.angle) * CONFIG.BULLET_SPEED;
    b.life--;

    // Remove if out of bounds or expired
    if (
      b.life <= 0 ||
      b.x < 0 || b.x > CONFIG.MAP_WIDTH ||
      b.y < 0 || b.y > CONFIG.MAP_HEIGHT
    ) {
      bullets.splice(i, 1);
      continue;
    }

    // Check collision with players
    for (const id in players) {
      const p = players[id];
      if (!p.alive || p.id === b.ownerId) continue;

      if (distance(b, p) < b.radius + p.radius) {
        // Hit!
        p.hp -= CONFIG.BULLET_DAMAGE;
        bullets.splice(i, 1);

        if (p.hp <= 0) {
          p.hp = 0;
          p.alive = false;
          p.deaths++;

          // Credit the kill
          if (players[b.ownerId]) {
            players[b.ownerId].kills++;
          }

          // Respawn after delay
          const deadPlayerId = p.id;
          setTimeout(() => {
            if (players[deadPlayerId]) {
              const pos = randomPosition();
              players[deadPlayerId].x = pos.x;
              players[deadPlayerId].y = pos.y;
              players[deadPlayerId].hp = CONFIG.PLAYER_MAX_HP;
              players[deadPlayerId].alive = true;
              io.to(deadPlayerId).emit('respawn');
            }
          }, CONFIG.RESPAWN_TIME);

          // Notify all about the kill
          io.emit('killFeed', {
            killer: players[b.ownerId] ? players[b.ownerId].name : 'Unknown',
            victim: p.name,
            timestamp: Date.now()
          });
        }

        // Notify the hit player
        io.to(p.id).emit('hit', { hp: p.hp, damage: CONFIG.BULLET_DAMAGE });
        break;
      }
    }
  }

  // Check health pack pickups
  for (let i = healthPacks.length - 1; i >= 0; i--) {
    const h = healthPacks[i];
    for (const id in players) {
      const p = players[id];
      if (!p.alive) continue;

      if (distance(h, p) < h.radius + p.radius) {
        p.hp = Math.min(p.maxHp, p.hp + h.heal);
        healthPacks.splice(i, 1);
        io.to(p.id).emit('heal', { hp: p.hp, amount: h.heal });
        break;
      }
    }
  }

  // Broadcast state to all clients
  broadcastState();
}

// ============ SOCKET.IO EVENT HANDLERS ============

io.on('connection', (socket) => {
  console.log(`Player connected: ${socket.id}`);

  // Player joins the game
  socket.on('join', (data) => {
    const name = (data && data.name) ? data.name.trim().slice(0, 16) : `Player_${socket.id.slice(0, 4)}`;
    players[socket.id] = createPlayer(socket.id, name);
    console.log(`${name} joined the game`);

    // Send initial config to the new player
    socket.emit('init', {
      playerId: socket.id,
      mapWidth: CONFIG.MAP_WIDTH,
      mapHeight: CONFIG.MAP_HEIGHT,
      config: {
        playerRadius: CONFIG.PLAYER_RADIUS,
        bulletRadius: CONFIG.BULLET_RADIUS,
        fireRate: CONFIG.FIRE_RATE,
        respawnTime: CONFIG.RESPAWN_TIME
      }
    });

    // Notify others
    socket.broadcast.emit('playerJoined', {
      id: socket.id,
      name: name
    });

    // Send current scoreboard
    io.emit('scoreboard', getScoreboard());
  });

  // Handle player input (movement)
  socket.on('input', (data) => {
    if (!players[socket.id]) return;
    players[socket.id].input = data;
  });

  // Handle player aiming
  socket.on('aim', (data) => {
    if (!players[socket.id]) return;
    players[socket.id].angle = data.angle;
  });

  // Handle shooting
  socket.on('shoot', (data) => {
    const p = players[socket.id];
    if (!p || !p.alive) return;

    const now = Date.now();
    if (now - p.lastShot < CONFIG.FIRE_RATE) return;
    p.lastShot = now;

    // Create bullet at player position, traveling toward aim angle
    const bullet = {
      id: nextBulletId(),
      x: p.x + Math.cos(p.angle) * (p.radius + 5),
      y: p.y + Math.sin(p.angle) * (p.radius + 5),
      radius: CONFIG.BULLET_RADIUS,
      angle: p.angle,
      ownerId: socket.id,
      life: CONFIG.BULLET_LIFETIME
    };
    bullets.push(bullet);
  });

  // Handle chat messages
  socket.on('chat', (data) => {
    if (!players[socket.id]) return;
    const message = (data.message || '').trim().slice(0, 200);
    if (!message) return;

    io.emit('chat', {
      sender: players[socket.id].name,
      message: message,
      timestamp: Date.now()
    });
  });

  // Handle disconnection
  socket.on('disconnect', () => {
    const p = players[socket.id];
    if (p) {
      console.log(`${p.name} disconnected`);
      io.emit('playerLeft', { id: socket.id, name: p.name });
      delete players[socket.id];
      io.emit('scoreboard', getScoreboard());
    }
  });
});

// ============ START SERVER ============

const PORT = process.env.PORT || 3000;

server.listen(PORT, () => {
  console.log(`\n========================================`);
  console.log(`  Multiplayer Shooter Server Running`);
  console.log(`  Open http://localhost:${PORT} in browser`);
  console.log(`  Open multiple tabs to test multiplayer`);
  console.log(`========================================\n`);

  // Start game loop at ~60 FPS
  gameLoop = setInterval(updateGame, 1000 / 60);

  // Spawn health packs periodically
  spawnHealthPack();
  spawnHealthPack();
  healthPackTimer = setInterval(spawnHealthPack, CONFIG.HEALTH_PACK_INTERVAL);
});
