## public/game.js

```javascript
/**
 * Multiplayer Shooting Game - Client Side
 * Handles rendering, input, and network communication
 */

// ============ SOCKET CONNECTION ============
const socket = io();

// ============ GAME STATE ============
let myId = null;
let gameStarted = false;
let gameState = {
  players: [],
  bullets: [],
  healthPacks: [],
  scoreboard: [],
  mapWidth: 2400,
  mapHeight: 1800
};

let config = {
  playerRadius: 20,
  bulletRadius: 5,
  fireRate: 200,
  respawnTime: 3000
};

// ============ INPUT STATE ============
const keys = { up: false, down: false, left: false, right: false };
let mouseX = 0, mouseY = 0;
let mouseDown = false;
let isChatting = false;
let showScoreboard = false;

// ============ CAMERA ============
const camera = { x: 0, y: 0 };

// ============ CANVAS SETUP ============
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
const minimapCanvas = document.getElementById('minimap');
const minimapCtx = minimapCanvas.getContext('2d');

function resizeCanvas() {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
}
window.addEventListener('resize', resizeCanvas);
resizeCanvas();

// ============ DOM ELEMENTS ============
const loginScreen = document.getElementById('login-screen');
const gameScreen = document.getElementById('game-screen');
const nameInput = document.getElementById('player-name');
const joinBtn = document.getElementById('join-btn');
const healthBar = document.getElementById('health-bar');
const healthText = document.getElementById('health-text');
const killsDisplay = document.getElementById('kills');
const deathsDisplay = document.getElementById('deaths');
const scoreboardEl = document.getElementById('scoreboard');
const scoreboardBody = document.getElementById('scoreboard-body');
const killFeedEl = document.getElementById('kill-feed');
const chatMessages = document.getElementById('chat-messages');
const chatInput = document.getElementById('chat-input');
const deathScreen = document.getElementById('death-screen');
const respawnTimer = document.getElementById('respawn-timer');
const notificationsEl = document.getElementById('notifications');

// ============ LOGIN ============
function joinGame() {
  const name = nameInput.value.trim() || `Player_${Math.random().toString(36).slice(2, 6)}`;
  socket.emit('join', { name });
  loginScreen.style.display = 'none';
  gameScreen.style.display = 'block';
  gameStarted = true;
}

joinBtn.addEventListener('click', joinGame);
nameInput.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') joinGame();
});

// ============ SOCKET EVENTS ============

socket.on('init', (data) => {
  myId = data.playerId;
  gameState.mapWidth = data.mapWidth;
  gameState.mapHeight = data.mapHeight;
  config = { ...config, ...data.config };
  addNotification('Welcome to the battlefield!', 'info');
});

socket.on('gameState', (state) => {
  gameState = state;
  updateHUD();
});

socket.on('hit', (data) => {
  addNotification(`-${data.damage} HP`, 'damage');
});

socket.on('heal', (data) => {
  addNotification(`+${data.amount} HP`, 'heal');
});

socket.on('killFeed', (data) => {
  addKillFeedEntry(data.killer, data.victim);
});

socket.on('chat', (data) => {
  addChatMessage(data.sender, data.message);
});

socket.on('playerJoined', (data) => {
  addNotification(`${data.name} joined the game`, 'info');
});

socket.on('playerLeft', (data) => {
  addNotification(`${data.name} left the game`, 'info');
});

socket.on('respawn', () => {
  deathScreen.style.display = 'none';
});

socket.on('scoreboard', (data) => {
  gameState.scoreboard = data;
});

// ============ INPUT HANDLERS ============

document.addEventListener('keydown', (e) => {
  if (isChatting) {
    if (e.key === 'Escape') {
      chatInput.blur();
      isChatting = false;
    }
    return;
  }

  switch (e.key.toLowerCase()) {
    case 'w': case 'arrowup':    keys.up = true; break;
    case 's': case 'arrowdown':  keys.down = true; break;
    case 'a': case 'arrowleft':  keys.left = true; break;
    case 'd': case 'arrowright': keys.right = true; break;
    case 'tab':
      e.preventDefault();
      showScoreboard = true;
      scoreboardEl.style.display = 'block';
      break;
    case 'enter':
      e.preventDefault();
      chatInput.focus();
      isChatting = true;
      break;
  }

  // Send input state to server
  socket.emit('input', { ...keys });
});

document.addEventListener('keyup', (e) => {
  switch (e.key.toLowerCase()) {
    case 'w': case 'arrowup':    keys.up = false; break;
    case 's': case 'arrowdown':  keys.down = false; break;
    case 'a': case 'arrowleft':  keys.left = false; break;
    case 'd': case 'arrowright': keys.right = false; break;
    case 'tab':
      showScoreboard = false;
      scoreboardEl.style.display = 'none';
      break;
  }

  socket.emit('input', { ...keys });
});

canvas.addEventListener('mousemove', (e) => {
  mouseX = e.clientX;
  mouseY = e.clientY;

  // Calculate aim angle relative to player position on screen
  const me = getMyPlayer();
  if (me) {
    const screenX = me.x - camera.x;
    const screenY = me.y - camera.y;
    const angle = Math.atan2(mouseY - screenY, mouseX - screenX);
    socket.emit('aim', { angle });
  }
});

canvas.addEventListener('mousedown', (e) => {
  if (e.button === 0) {
    mouseDown = true;
    shoot();
  }
});

canvas.addEventListener('mouseup', (e) => {
  if (e.button === 0) mouseDown = false;
});

// Prevent context menu on right click
canvas.addEventListener('contextmenu', (e) => e.preventDefault());

// Chat input handling
chatInput.addEventListener('focus', () => { isChatting = true; });
chatInput.addEventListener('blur', () => { isChatting = false; });
chatInput.addEventListener('keydown', (e) => {
  e.stopPropagation();
  if (e.key === 'Enter') {
    const msg = chatInput.value.trim();
    if (msg) {
      socket.emit('chat', { message: msg });
      chatInput.value = '';
    }
    chatInput.blur();
    isChatting = false;
  }
  if (e.key === 'Escape') {
    chatInput.blur();
    isChatting = false;
  }
});

// ============ SHOOTING ============
let lastShotTime = 0;

function shoot() {
  if (!gameStarted) return;
  const me = getMyPlayer();
  if (!me || !me.alive) return;

  const now = Date.now();
  if (now - lastShotTime < config.fireRate) return;
  lastShotTime = now;

  socket.emit('shoot', {});
}

// Auto-fire when holding mouse button
setInterval(() => {
  if (mouseDown && gameStarted && !isChatting) {
    shoot();
  }
}, 50);

// ============ HELPER FUNCTIONS ============

function getMyPlayer() {
  return gameState.players.find(p => p.id === myId);
}

function updateHUD() {
  const me = getMyPlayer();
  if (!me) return;

  // Health bar
  const hpPercent = (me.hp / me.maxHp) * 100;
  healthBar.style.width = `${hpPercent}%`;

  // Color based on health
  if (hpPercent > 60) {
    healthBar.style.background = 'linear-gradient(90deg, #44ff44, #88ff88)';
  } else if (hpPercent > 30) {
    healthBar.style.background = 'linear-gradient(90deg, #ffaa00, #ffdd44)';
  } else {
    healthBar.style.background = 'linear-gradient(90deg, #ff4444, #ff8888)';
  }

  healthText.textContent = `${Math.ceil(me.hp)} / ${me.maxHp}`;

  // K/D
  const myScore = gameState.scoreboard.find(s => s.id === myId);
  if (myScore) {
    killsDisplay.textContent = `Kills: ${myScore.kills}`;
    deathsDisplay.textContent = `Deaths: ${myScore.deaths}`;
  }

  // Death screen
  if (!me.alive) {
    deathScreen.style.display = 'flex';
  }

  // Update scoreboard
  updateScoreboard();
}

function updateScoreboard() {
  scoreboardBody.innerHTML = '';
  gameState.scoreboard.forEach((entry, index) => {
    const tr = document.createElement('tr');
    if (entry.id === myId) tr.classList.add('self');
    tr.innerHTML = `
      <td>${index + 1}</td>
      <td>${escapeHtml(entry.name)}</td>
      <td style="color:#6bcb77">${entry.kills}</td>
      <td style="color:#ff6b6b">${entry.deaths}</td>
      <td>${entry.alive ? '🟢 Alive' : '🔴 Dead'}</td>
    `;
    scoreboardBody.appendChild(tr);
  });
}

function addKillFeedEntry(killer, victim) {
  const entry = document.createElement('div');
  entry.className = 'kill-entry';
  entry.innerHTML = `<span class="killer">${escapeHtml(killer)}</span> ☠ <span class="victim">${escapeHtml(victim)}</span>`;
  killFeedEl.appendChild(entry);

  // Remove after 5 seconds
  setTimeout(() => {
    if (entry.parentNode) entry.parentNode.removeChild(entry);
  }, 5000);

  // Keep only last 5 entries
  while (killFeedEl.children.length > 5) {
    killFeedEl.removeChild(killFeedEl.firstChild);
  }
}

function addChatMessage(sender, message) {
  const msgEl = document.createElement('div');
  msgEl.className = 'chat-msg';
  msgEl.innerHTML = `<span class="sender">${escapeHtml(sender)}:</span> ${escapeHtml(message)}`;
  chatMessages.appendChild(msgEl);
  chatMessages.scrollTop = chatMessages.scrollHeight;

  // Remove old messages
  while (chatMessages.children.length > 50) {
    chatMessages.removeChild(chatMessages.firstChild);
  }

  // Auto-hide after 10 seconds
  setTimeout(() => {
    msgEl.style.opacity = '0';
    msgEl.style.transition = 'opacity 1s';
    setTimeout(() => {
      if (msgEl.parentNode) msgEl.parentNode.removeChild(msgEl);
    }, 1000);
  }, 10000);
}

function addNotification(text, type) {
  const notif = document.createElement('div');
  notif.className = `notification ${type}`;
  notif.textContent = text;
  notificationsEl.appendChild(notif);

  setTimeout(() => {
    if (notif.parentNode) notif.parentNode.removeChild(notif);
  }, 3000);
}

function escapeHtml(str) {
  const div = document.createElement('div');
  div.textContent = str;
  return div.innerHTML;
}

// ============ RENDERING ============

function render() {
  if (!gameStarted) {
    requestAnimationFrame(render);
    return;
  }

  const me = getMyPlayer();

  // Update camera to follow player
  if (me) {
    camera.x = me.x - canvas.width / 2;
    camera.y = me.y - canvas.height / 2;
  }

  // Clear canvas
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw background
  drawBackground();

  // Draw grid
  drawGrid();

  // Draw map border
  drawMapBorder();

  // Draw health packs
  drawHealthPacks();

  // Draw bullets
  drawBullets();

  // Draw players
  drawPlayers();

  // Draw minimap
  drawMinimap();

  requestAnimationFrame(render);
}

function drawBackground() {
  ctx.fillStyle = '#1a1a2e';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
}

function drawGrid() {
  const gridSize = 80;
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.05)';
  ctx.lineWidth = 1;

  const startX = -(camera.x % gridSize);
  const startY = -(camera.y % gridSize);

  ctx.beginPath();
  for (let x = startX; x < canvas.width; x += gridSize) {
    ctx.moveTo(x, 0);
    ctx.lineTo(x, canvas.height);
  }
  for (let y = startY; y < canvas.height; y += gridSize) {
    ctx.moveTo(0, y);
    ctx.lineTo(canvas.width, y);
  }
  ctx.stroke();
}

function drawMapBorder() {
  ctx.strokeStyle = '#ff4444';
  ctx.lineWidth = 4;
  ctx.strokeRect(-camera.x, -camera.y, gameState.mapWidth, gameState.mapHeight);

  // Draw danger zone outside map
  ctx.fillStyle = 'rgba(255, 0, 0, 0.05)';
  // Top
  if (camera.y < 0) {
    ctx.fillRect(0, 0, canvas.width, -camera.y);
  }
  // Bottom
  if (camera.y + canvas.height > gameState.mapHeight) {
    const y = gameState.mapHeight - camera.y;
    ctx.fillRect(0, y, canvas.width, canvas.height - y);
  }
  // Left
  if (camera.x < 0) {
    ctx.fillRect(0, 0, -camera.x, canvas.height);
  }
  // Right
  if (camera.x + canvas.width > gameState.mapWidth) {
    const x = gameState.mapWidth - camera.x;
    ctx.fillRect(x, 0, canvas.width - x, canvas.height);
  }
}

function drawHealthPacks() {
  gameState.healthPacks.forEach(h => {
    const sx = h.x - camera.x;
    const sy = h.y - camera.y;

    // Skip if off screen
    if (sx < -50 || sx > canvas.width + 50 || sy < -50 || sy > canvas.height + 50) return;

    // Glow effect
    const gradient = ctx.createRadialGradient(sx, sy, 0, sx, sy, h.radius * 2);
    gradient.addColorStop(0, 'rgba(0, 255, 100, 0.3)');
    gradient.addColorStop(1, 'rgba(0, 255, 100, 0)');
    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.arc(sx, sy, h.radius * 2, 0, Math.PI * 2);
    ctx.fill();

    // Cross shape
    ctx.fillStyle = '#44ff88';
    ctx.fillRect(sx - h.radius * 0.7, sy - h.radius * 0.2, h.radius * 1.4, h.radius * 0.4);
    ctx.fillRect(sx - h.radius * 0.2, sy - h.radius * 0.7, h.radius * 0.4, h.radius * 1.4);

    // Border
    ctx.strokeStyle = '#88ffaa';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(sx, sy, h.radius, 0, Math.PI * 2);
    ctx.stroke();
  });
}

function drawBullets() {
  gameState.bullets.forEach(b => {
    const sx = b.x - camera.x;
    const sy = b.y - camera.y;

    // Skip if off screen
    if (sx < -20 || sx > canvas.width + 20 || sy < -20 || sy > canvas.height + 20) return;

    // Bullet trail
    const trailLen = 15;
    const tx = sx - Math.cos(b.angle) * trailLen;
    const ty = sy - Math.sin(b.angle) * trailLen;

    const gradient = ctx.createLinearGradient(tx, ty, sx, sy);
    gradient.addColorStop(0, 'rgba(255, 200, 50, 0)');
    gradient.addColorStop(1, 'rgba(255, 200, 50, 0.8)');

    ctx.strokeStyle = gradient;
    ctx.lineWidth = b.radius * 1.5;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(tx, ty);
    ctx.lineTo(sx, sy);
    ctx.stroke();

    // Bullet head
    ctx.fillStyle = '#ffdd44';
    ctx.beginPath();
    ctx.arc(sx, sy, b.radius, 0, Math.PI * 2);
    ctx.fill();

    // Glow
    ctx.shadowColor = '#ffaa00';
    ctx.shadowBlur = 10;
    ctx.fill();
    ctx.shadowBlur = 0;
  });
}

function drawPlayers() {
  gameState.players.forEach(p => {
    if (!p.alive) return;

    const sx = p.x - camera.x;
    const sy = p.y - camera.y;

    // Skip if off screen
    if (sx < -100 || sx > canvas.width + 100 || sy < -100 || sy > canvas.height + 100) return;

    const isMe = p.id === myId;

    // Player body shadow
    ctx.fillStyle = 'rgba(0, 0, 0, 0.3)';
    ctx.beginPath();
    ctx.ellipse(sx + 3, sy + 5, p.radius, p.radius * 0.6, 0, 0, Math.PI * 2);
    ctx.fill();

    // Player body
    ctx.fillStyle = p.color;
    ctx.beginPath();
    ctx.arc(sx, sy, p.radius, 0, Math.PI * 2);
    ctx.fill();

    // Player border
    ctx.strokeStyle = isMe ? '#ffffff' : 'rgba(255, 255, 255, 0.5)';
    ctx.lineWidth = isMe ? 3 : 2;
    ctx.stroke();

    // Gun barrel (aim direction)
    const gunLen = p.radius + 15;
    const gunX = sx + Math.cos(p.angle) * gunLen;
    const gunY = sy + Math.sin(p.angle) * gunLen;

    ctx.strokeStyle = '#888';
    ctx.lineWidth = 6;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(sx + Math.cos(p.angle) * p.radius * 0.5, sy + Math.sin(p.angle) * p.radius * 0.5);
    ctx.lineTo(gunX, gunY);
    ctx.stroke();

    // Gun tip
    ctx.fillStyle = '#aaa';
    ctx.beginPath();
    ctx.arc(gunX, gunY, 4, 0, Math.PI * 2);
    ctx.fill();

    // Health bar above player
    const barWidth = p.radius * 2.5;
    const barHeight = 5;
    const barX = sx - barWidth / 2;
    const barY = sy - p.radius - 18;
    const hpPercent = p.hp / p.maxHp;

    // Background
    ctx.fillStyle = 'rgba(0, 0, 0, 0.7)';
    ctx.fillRect(barX - 1, barY - 1, barWidth + 2, barHeight + 2);

    // Health fill
    let hpColor;
    if (hpPercent > 0.6) hpColor = '#44ff44';
    else if (hpPercent > 0.3) hpColor = '#ffaa00';
    else hpColor = '#ff4444';

    ctx.fillStyle = hpColor;
    ctx.fillRect(barX, barY, barWidth * hpPercent, barHeight);

    // Player name
    ctx.fillStyle = isMe ? '#ffffff' : '#cccccc';
    ctx.font = 'bold 12px Arial';
    ctx.textAlign = 'center';
    ctx.fillText(p.name, sx, barY - 6);
  });
}

function drawMinimap() {
  const mw = minimapCanvas.width;
  const mh = minimapCanvas.height;
  const scaleX = mw / gameState.mapWidth;
  const scaleY = mh / gameState.mapHeight;

  // Clear
  minimapCtx.fillStyle = 'rgba(0, 0, 0, 0.8)';
  minimapCtx.fillRect(0, 0, mw, mh);

  // Border
  minimapCtx.strokeStyle = 'rgba(255, 255, 255, 0.3)';
  minimapCtx.lineWidth = 1;
  minimapCtx.strokeRect(0, 0, mw, mh);

  // Health packs
  gameState.healthPacks.forEach(h => {
    minimapCtx.fillStyle = '#44ff88';
    minimapCtx.fillRect(h.x * scaleX - 2, h.y * scaleY - 2, 4, 4);
  });

  // Players
  gameState.players.forEach(p => {
    if (!p.alive) return;
    const isMe = p.id === myId;
    minimapCtx.fillStyle = isMe ? '#ffffff' : p.color;
    minimapCtx.beginPath();
    minimapCtx.arc(p.x * scaleX, p.y * scaleY, isMe ? 4 : 3, 0, Math.PI * 2);
    minimapCtx.fill();
  });

  // Camera viewport
  minimapCtx.strokeStyle = 'rgba(255, 255, 255, 0.4)';
  minimapCtx.lineWidth = 1;
  minimapCtx.strokeRect(
    camera.x * scaleX,
    camera.y * scaleY,
    canvas.width * scaleX,
    canvas.height * scaleY
  );
}

// ============ RESPAWN TIMER ============
let respawnInterval = null;

socket.on('gameState', (state) => {
  const me = state.players.find(p => p.id === myId);
  if (me && !me.alive && deathScreen.style.display !== 'none') {
    if (!respawnInterval) {
      let countdown = 3;
      respawnTimer.textContent = countdown;
      respawnInterval = setInterval(() => {
        countdown--;
        respawnTimer.textContent = Math.max(0, countdown);
        if (countdown <= 0) {
          clearInterval(respawnInterval);
          respawnInterval = null;
        }
      }, 1000);
    }
  }
});

// ============ START GAME LOOP ============
requestAnimationFrame(render);
```

## How to Run

1. **Install dependencies:**
```bash
cd multiplayer-shooter
npm install
```

2. **Start the server:**
```bash
npm start
```

3. **Open in browser:**
   - Navigate to `http://localhost:3000`
   - Open **multiple browser tabs** or windows to simulate multiple players
   - Each tab is a separate player

## Features Implemented

| Feature | Description |
|---------|-------------|
| **Real-time Sync** | Socket.IO handles 60 FPS state synchronization between all players |
| **Movement** | WASD/Arrow keys with diagonal normalization |
| **Shooting** | Mouse aim + click/hold to fire with rate limiting |
| **Health System** | 100 HP, 15 damage per bullet, health packs spawn periodically |
| **Death & Respawn** | 3-second respawn timer with random position |
| **Kill Feed** | Shows who killed whom in real-time |
| **Scoreboard** | Press TAB to see kills/deaths for all players |
| **Chat** | Press Enter to type messages, visible to all players |
| **Minimap** | Bottom-right corner shows all players and health packs |
| **Camera** | Smooth follow camera centered on your player |
| **HUD** | Health bar, K/D counter, notifications |
| **Visual Effects** | Bullet trails, glow effects, health pack animations |

