        // ============================================================
        //  File Upload: Watermark Audio
        // ============================================================
        const wmAudioInput = document.getElementById('wmAudioInput');
        const wmUploadArea = document.getElementById('wmUploadArea');

        wmAudioInput.addEventListener('change', async function (e) {
            const file = e.target.files[0];
            if (!file) return;

            showStatus('info', 'Decoding watermark audio...');
            wmUploadArea.classList.add('has-file');
            document.getElementById('wmFileInfo').textContent =
                `📄 ${file.name} (${(file.size / 1024 / 1024).toFixed(2)} MB)`;

            try {
