            }
        });

        // ============================================================
        //  Preview Text-to-Speech
        // ============================================================
        function previewTextWatermark() {
            const text = document.getElementById('watermarkText').value.trim();
            if (!text) {
                showStatus('error', 'Please enter watermark text.');
                return;
            }
            // Cancel any ongoing speech
            speechSynthesis.cancel();
            const utterance = new SpeechSynthesisUtterance(text);
            utterance.rate = parseFloat(document.getElementById('speechRate').value);
            utterance.pitch = parseFloat(document.getElementById('speechPitch').value);
            speechSynthesis.speak(utterance);
        }

        // ============================================================
        //  Text-to-Speech → AudioBuffer (using MediaRecorder + SpeechSynthesis)
        // ============================================================
        function textToAudioBuffer(text, rate, pitch) {
            return new Promise((resolve, reject) => {
                // We'll use an OfflineAudioContext approach:
                // 1. Use SpeechSynthesis to speak
                // 2. Capture via MediaStreamDestination
                // Since SpeechSynthesis can't be directly routed to Web Audio,
                // we'll use a workaround: generate a simple tone-based encoding
                // OR use the oscillator to create a "spoken" representation.
                //
                // Best approach for browser: Use SpeechSynthesis + MediaRecorder
                // But MediaRecorder captures from MediaStream, not SpeechSynthesis directly.
                //
                // Alternative: We'll create an AudioBuffer with a synthesized beep pattern
                // that represents the text, OR we use a more practical approach:
                // Generate speech audio using an OfflineAudioContext with oscillators
                // to create a recognizable audio signature.
                //
                // MOST PRACTICAL: Use the Web Speech API to generate speech,
                // capture it via an AudioContext destination trick.
                // Since this is tricky cross-browser, let's generate a synthetic
                // audio watermark from text using frequency encoding.

                // We'll create a simple but effective audio watermark:
                // Convert text characters to a sequence of tones
                const sampleRate = mainAudioBuffer ? mainAudioBuffer.sampleRate : 44100;
                const chars = text.split('');
                const toneDuration = 0.08; // seconds per character tone
                const gapDuration = 0.02;  // gap between tones
                const totalDuration = chars.length * (toneDuration + gapDuration) + 0.2;
                const totalSamples = Math.ceil(totalDuration * sampleRate);

                const offlineCtx = new OfflineAudioContext(1, totalSamples, sampleRate);

                // Base frequency
                const baseFreq = 800 * rate;

                chars.forEach((char, i) => {
                    const charCode = char.charCodeAt(0);
                    // Map character to frequency (200Hz - 2000Hz range)
                    const freq = 200 + (charCode % 95) * (1800 / 95) * pitch;
                    const startTime = 0.1 + i * (toneDuration + gapDuration);

                    const osc = offlineCtx.createOscillator();
                    const gain = offlineCtx.createGain();

                    osc.type = 'sine';
                    osc.frequency.value = freq;

                    // Envelope
                    gain.gain.setValueAtTime(0, startTime);
                    gain.gain.linearRampToValueAtTime(0.6, startTime + 0.01);
                    gain.gain.setValueAtTime(0.6, startTime + toneDuration - 0.01);
                    gain.gain.linearRampToValueAtTime(0, startTime + toneDuration);

                    osc.connect(gain);
                    gain.connect(offlineCtx.destination);

                    osc.start(startTime);
                    osc.stop(startTime + toneDuration);
                });

                // Also add a pleasant chime at start and end
                [0, totalDuration - 0.15].forEach(t => {
                    const osc = offlineCtx.createOscillator();
                    const gain = offlineCtx.createGain();
                    osc.type = 'sine';
                    osc.frequency.value = 1200;
                    gain.gain.setValueAtTime(0, t);
                    gain.gain.linearRampToValueAtTime(0.3, t + 0.02);
                    gain.gain.linearRampToValueAtTime(0, t + 0.15);
                    osc.connect(gain);
                    gain.connect(offlineCtx.destination);
                    osc.start(t);
                    osc.stop(t + 0.15);
                });

                offlineCtx.startRendering().then(buffer => {
                    resolve(buffer);
                }).catch(reject);
            });
        }

        // ============================================================
        //  Check if Ready to Process
        // ============================================================
        function checkReady() {
            const hasMain = mainAudioBuffer !== null;
            let hasWm = false;

            if (currentTab === 'textTab') {
                hasWm = document.getElementById('watermarkText').value.trim().length > 0;
            } else {
                hasWm = wmAudioBuffer !== null;
            }

            document.getElementById('processBtn').disabled = !(hasMain && hasWm);
        }

        // Listen for text input changes
        document.getElementById('watermarkText').addEventListener('input', checkReady);

        // ============================================================
        //  Calculate Watermark Start Time
        // ============================================================
        function getWatermarkStartTime(mainDuration, wmDuration) {
            switch (selectedPosition) {
                case 'beginning':
                    return 0;
                case 'quarter':
                    return mainDuration * 0.25 - wmDuration / 2;
                case 'middle':
                    return (mainDuration - wmDuration) / 2;
                case 'three-quarter':
                    return mainDuration * 0.75 - wmDuration / 2;
                case 'end':
                    return mainDuration - wmDuration;
                case 'custom':
                    return parseFloat(document.getElementById('customPosSeconds').value) || 0;
                default:
                    return 0;
            }
        }

        // ============================================================
        //  Update Watermark Position Indicator on Waveform
        // ============================================================
        function updateWatermarkIndicator() {
            if (!mainAudioBuffer) return;

            const indicator = document.getElementById('watermarkIndicator');
            const container = document.getElementById('mainWaveformContainer');
            const containerWidth = container.offsetWidth;
            const mainDuration = mainAudioBuffer.duration;

            // Estimate watermark duration
            let wmDuration = 1; // default estimate
            if (currentTab === 'audioTab' && wmAudioBuffer) {
                wmDuration = wmAudioBuffer.duration;
            } else if (currentTab === 'textTab') {
                const text = document.getElementById('watermarkText').value.trim();
                const rate = parseFloat(document.getElementById('speechRate').value);
                wmDuration = text.length * 0.1 / rate + 0.4;
            }

            const startTime = getWatermarkStartTime(mainDuration, wmDuration);
            const clampedStart = Math.max(0, startTime);
            const clampedEnd = Math.min(mainDuration, startTime + wmDuration);

            const leftPercent = (clampedStart / mainDuration) * 100;
            const widthPercent = ((clampedEnd - clampedStart) / mainDuration) * 100;

            indicator.style.left = leftPercent + '%';
            indicator.style.width = Math.max(widthPercent, 0.5) + '%';
        }

        // ============================================================
        //  Draw Waveform
        // ============================================================
        function drawWaveform(buffer, canvasId) {
            const canvas = document.getElementById(canvasId);
            const ctx = canvas.getContext('2d');
            const dpr = window.devicePixelRatio || 1;

            canvas.width = canvas.offsetWidth * dpr;
            canvas.height = canvas.offsetHeight * dpr;
            ctx.scale(dpr, dpr);

            const width = canvas.offsetWidth;
            const height = canvas.offsetHeight;
            const data = buffer.getChannelData(0);
            const step = Math.ceil(data.length / width);
            const amp = height / 2;

            ctx.clearRect(0, 0, width, height);

            // Draw gradient waveform
            const gradient = ctx.createLinearGradient(0, 0, width, 0);
            gradient.addColorStop(0, '#7b2ff7');
            gradient.addColorStop(0.5, '#00d2ff');
            gradient.addColorStop(1, '#7b2ff7');

            ctx.strokeStyle = gradient;
            ctx.lineWidth = 1;
            ctx.beginPath();

            for (let i = 0; i < width; i++) {
                let min = 1.0, max = -1.0;
                for (let j = 0; j < step; j++) {
                    const datum = data[(i * step) + j] || 0;
                    if (datum < min) min = datum;
                    if (datum > max) max = datum;
                }
                ctx.moveTo(i, (1 + min) * amp);
                ctx.lineTo(i, (1 + max) * amp);
            }
            ctx.stroke();

            // Center line
            ctx.strokeStyle = 'rgba(255,255,255,0.1)';
            ctx.beginPath();
            ctx.moveTo(0, amp);
            ctx.lineTo(width, amp);
            ctx.stroke();
        }

        // ============================================================
        //  Main Processing: Mix Audio
        // ============================================================
        async function processAudio() {
            if (!mainAudioBuffer) {
                showStatus('error', 'Please upload a main audio file first.');
                return;
            }

            const processBtn = document.getElementById('processBtn');
            const downloadBtn = document.getElementById('downloadBtn');
            processBtn.disabled = true;
            downloadBtn.disabled = true;

            showProgress(true, 0, 'Preparing watermark...');

            try {
                // Step 1: Get watermark buffer
                let wmBuffer;
                if (currentTab === 'textTab') {
                    const text = document.getElementById('watermarkText').value.trim();
                    const rate = parseFloat(document.getElementById('speechRate').value);
                    const pitch = parseFloat(document.getElementById('speechPitch').value);
                    showProgress(true, 10, 'Generating text watermark audio...');
                    wmBuffer = await textToAudioBuffer(text, rate, pitch);
                } else {
                    if (!wmAudioBuffer) {
                        showStatus('error', 'Please upload a watermark audio file.');
                        processBtn.disabled = false;
                        showProgress(false);
                        return;
                    }
                    wmBuffer = wmAudioBuffer;
                }

                showProgress(true, 30, 'Mixing audio...');

                // Step 2: Create offline context for mixing
                const sampleRate = mainAudioBuffer.sampleRate;
                const numChannels = mainAudioBuffer.numberOfChannels;
                const mainDuration = mainAudioBuffer.duration;
                const totalDuration = mainDuration; // Output same length as main
                const totalSamples = Math.ceil(totalDuration * sampleRate);

                const offlineCtx = new OfflineAudioContext(numChannels, totalSamples, sampleRate);

                // Step 3: Add main audio source
                const mainSource = offlineCtx.createBufferSource();
                mainSource.buffer = mainAudioBuffer;
                const mainGain = offlineCtx.createGain();
                mainGain.gain.value = parseInt(document.getElementById('mainVolume').value) / 100;
                mainSource.connect(mainGain);
                mainGain.connect(offlineCtx.destination);
                mainSource.start(0);

                // Step 4: Add watermark(s)
                const wmVolume = parseInt(document.getElementById('wmVolume').value) / 100;
                const repeatWm = document.getElementById('repeatWm').checked;
                const repeatInterval = parseInt(document.getElementById('repeatInterval').value);

                if (repeatWm) {
                    // Place watermark at regular intervals
                    let t = 0;
                    while (t < totalDuration) {
                        const wmSource = offlineCtx.createBufferSource();
                        wmSource.buffer = wmBuffer;
                        const wmGain = offlineCtx.createGain();
                        wmGain.gain.value = wmVolume;
                        wmSource.connect(wmGain);
                        wmGain.connect(offlineCtx.destination);
                        wmSource.start(t);
                        t += repeatInterval;
                    }
                } else {
                    // Single placement
                    const startTime = getWatermarkStartTime(mainDuration, wmBuffer.duration);
                    const clampedStart = Math.max(0, Math.min(startTime, totalDuration - 0.01));

                    const wmSource = offlineCtx.createBufferSource();
                    wmSource.buffer = wmBuffer;
                    const wmGain = offlineCtx.createGain();
                    wmGain.gain.value = wmVolume;
                    wmSource.connect(wmGain);
                    wmGain.connect(offlineCtx.destination);
                    wmSource.start(clampedStart);
                }

                showProgress(true, 60, 'Rendering mixed audio...');

                // Step 5: Render
                resultBuffer = await offlineCtx.startRendering();

                showProgress(true, 85, 'Encoding WAV file...');

                // Step 6: Encode to WAV
                const wavBlob = encodeWAV(resultBuffer);

                // Clean up old blob URL
                if (resultBlobUrl) URL.revokeObjectURL(resultBlobUrl);
                resultBlobUrl = URL.createObjectURL(wavBlob);

                // Step 7: Show result player
                const resultPlayer = document.getElementById('resultAudioPlayer');
                resultPlayer.src = resultBlobUrl;
                document.getElementById('resultPlayerWrapper').style.display = 'block';

                showProgress(true, 100, 'Done!');
                setTimeout(() => showProgress(false), 1500);

                showStatus('success', `✅ Watermarked audio created! Duration: ${resultBuffer.duration.toFixed(2)}s, Size: ${(wavBlob.size / 1024 / 1024).toFixed(2)} MB`);
                downloadBtn.disabled = false;

            } catch (err) {
                showStatus('error', 'Processing failed: ' + err.message);
                console.error(err);
                showProgress(false);
            }

            processBtn.disabled = false;
        }

        // ============================================================
        //  WAV Encoder
        // ============================================================
        function encodeWAV(buffer) {
            const numChannels = buffer.numberOfChannels;
            const sampleRate = buffer.sampleRate;
            const format = 1; // PCM
            const bitDepth = 16;

            const bytesPerSample = bitDepth / 8;
            const blockAlign = numChannels * bytesPerSample;

            const samples = buffer.length;
            const dataSize = samples * blockAlign;
            const headerSize = 44;
            const totalSize = headerSize + dataSize;

            const arrayBuffer = new ArrayBuffer(totalSize);
            const view = new DataView(arrayBuffer);

            // Helper to write strings
            function writeString(offset, str) {
                for (let i = 0; i < str.length; i++) {
                    view.setUint8(offset + i, str.charCodeAt(i));
                }
            }

            // RIFF header
            writeString(0, 'RIFF');
            view.setUint32(4, totalSize - 8, true);
            writeString(8, 'WAVE');

            // fmt chunk
            writeString(12, 'fmt ');
            view.setUint32(16, 16, true);           // chunk size
            view.setUint16(20, format, true);        // PCM
            view.setUint16(22, numChannels, true);
            view.setUint32(24, sampleRate, true);
            view.setUint32(28, sampleRate * blockAlign, true);
            view.setUint16(32, blockAlign, true);
            view.setUint16(34, bitDepth, true);

            // data chunk
            writeString(36, 'data');
            view.setUint32(40, dataSize, true);

            // Interleave channels and write samples
            const channels = [];
            for (let ch = 0; ch < numChannels; ch++) {
                channels.push(buffer.getChannelData(ch));
            }

            let offset = 44;
            for (let i = 0; i < samples; i++) {
                for (let ch = 0; ch < numChannels; ch++) {
                    let sample = channels[ch][i];
                    // Clamp
                    sample = Math.max(-1, Math.min(1, sample));
                    // Convert to 16-bit int
                    sample = sample < 0 ? sample * 0x8000 : sample * 0x7FFF;
                    view.setInt16(offset, sample, true);
                    offset += 2;
                }
            }

            return new Blob([arrayBuffer], { type: 'audio/wav' });
        }

        // ============================================================
        //  Download Result
        // ============================================================
        function downloadResult() {
            if (!resultBlobUrl) return;

            const a = document.createElement('a');
            a.href = resultBlobUrl;
            a.download = 'watermarked_audio.wav';
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
        }

        // ============================================================
        //  UI Helpers
        // ============================================================
        function showProgress(visible, percent, text) {
            const container = document.getElementById('progressContainer');
            const bar = document.getElementById('progressBar');
            const txt = document.getElementById('progressText');

            if (visible) {
                container.classList.add('visible');
                bar.style.width = percent + '%';
                if (text) txt.textContent = text;
            } else {
                container.classList.remove('visible');
            }
        }

        function showStatus(type, message) {
            const el = document.getElementById('statusMsg');
            el.className = 'status-msg visible ' + type;
            el.textContent = message;
        }

        // ============================================================
        //  Window Resize: Redraw Waveform
        // ============================================================
        window.addEventListener('resize', () => {
            if (mainAudioBuffer) {
                drawWaveform(mainAudioBuffer, 'mainWaveformCanvas');
                updateWatermarkIndicator();
            }
        });

        // ============================================================
        //  Initialize
        // ============================================================
        checkReady();
    </script>
</body>
</html>
```

## How to Use

1. **Save** the code above as `audio-watermark.html`
2. **Open** it in any modern browser (Chrome, Firefox, Edge, Safari)
3. **Follow the 4 steps** in the interface:

| Step | Action |
|------|--------|
| **Step 1** | Upload your main audio file (MP3, WAV, OGG, etc.) |
| **Step 2** | Choose watermark type — **Text** (generates tonal audio signature from your text) or **Audio** (upload a short audio clip) |
| **Step 3** | Set position (beginning/middle/end/custom), volume levels, and optionally enable repeat |
| **Step 4** | Click **"Create Watermarked Audio"** then **"Download WAV"** |

## Key Features

- **🔒 100% Client-Side** — No server uploads; all processing uses the Web Audio API
- **📊 Waveform Visualization** — See your audio waveform with a purple overlay showing watermark placement
- **✏️ Text Watermark** — Converts text into a unique tonal audio signature using frequency encoding
- **🎤 Audio Watermark** — Mix in any short audio clip as a watermark
- **📍 6 Position Options** — Beginning, 25%, Middle, 75%, End, or Custom (seconds)
- **🔁 Repeat Mode** — Optionally repeat the watermark at configurable intervals
- **🎚️ Independent Volume** — Separate volume controls for main audio and watermark
- **💾 WAV Export** — Downloads the result as a standard 16-bit PCM WAV file

# Audio Segmentation Labeling Tool

Below is a complete, single-file web application. Save it as `audio-labeler.html` and open it in any modern browser (Chrome/Edge/Firefox). No installation or server required.

## Features

- **Upload** audio via file picker or drag-and-drop (MP3, WAV, OGG, FLAC, M4A)
