            load() {
                try {
                    const data = localStorage.getItem(this.storageKey);
                    return data ? JSON.parse(data) : this.getSampleData();
                } catch (e) {
                    return this.getSampleData();
                }
            }

            save() {
                localStorage.setItem(this.storageKey, JSON.stringify(this.products));
            }

            getSampleData() {
                return [
                    { id: 1, name: 'Wireless Bluetooth Headphones', sku: 'ELEC-001', category: 'Electronics', price: 79.99, quantity: 45, threshold: 10, description: 'High-quality wireless headphones with noise cancellation' },
                    { id: 2, name: 'Organic Green Tea (100 bags)', sku: 'FOOD-012', category: 'Food & Beverage', price: 12.50, quantity: 8, threshold: 15, description: 'Premium organic green tea' },
                    { id: 3, name: 'Running Shoes - Size 10', sku: 'SPRT-045', category: 'Sports', price: 129.99, quantity: 3, threshold: 5, description: 'Lightweight running shoes' },
                    { id: 4, name: 'Cotton T-Shirt (Medium)', sku: 'CLTH-089', category: 'Clothing', price: 24.99, quantity: 120, threshold: 20, description: '100% cotton crew neck t-shirt' },
                    { id: 5, name: 'LED Desk Lamp', sku: 'HOME-023', category: 'Home & Garden', price: 45.00, quantity: 0, threshold: 8, description: 'Adjustable LED desk lamp with USB charging' },
                    { id: 6, name: 'JavaScript: The Good Parts', sku: 'BOOK-007', category: 'Books', price: 29.99, quantity: 35, threshold: 10, description: 'Classic programming book by Douglas Crockford' },
                    { id: 7, name: 'USB-C Charging Cable (2m)', sku: 'ELEC-034', category: 'Electronics', price: 9.99, quantity: 200, threshold: 50, description: 'Durable braided USB-C cable' },
                    { id: 8, name: 'Stainless Steel Water Bottle', sku: 'SPRT-012', category: 'Sports', price: 19.99, quantity: 5, threshold: 10, description: 'Insulated 750ml water bottle' },
                ];
            }

            getAll() {
                return [...this.products];
            }

            getById(id) {
                return this.products.find(p => p.id === id);
            }

            add(product) {
                const newId = this.products.length > 0 ? Math.max(...this.products.map(p => p.id)) + 1 : 1;
                const newProduct = { ...product, id: newId };
                this.products.push(newProduct);
                this.save();
                return newProduct;
            }

            update(id, updates) {
                const index = this.products.findIndex(p => p.id === id);
                if (index !== -1) {
                    this.products[index] = { ...this.products[index], ...updates };
                    this.save();
                    return this.products[index];
                }
                return null;
            }

            delete(id) {
                this.products = this.products.filter(p => p.id !== id);
                this.save();
            }

            getLowStockProducts() {
                return this.products.filter(p => p.quantity <= p.threshold && p.quantity > 0);
            }

            getOutOfStockProducts() {
                return this.products.filter(p => p.quantity === 0);
            }

            getTotalValue() {
                return this.products.reduce((sum, p) => sum + (p.price * p.quantity), 0);
            }
        }

        // ==================== App Controller ====================
        const store = new InventoryStore();
        let currentFilter = 'all';
        let currentSort = { field: 'name', direction: 'asc' };
        let searchQuery = '';

        // Initialize
        document.addEventListener('DOMContentLoaded', () => {
            renderTable();
            updateStats();
            updateAlerts();
            setupEventListeners();
        });

        function setupEventListeners() {
            // Search
            document.getElementById('searchInput').addEventListener('input', (e) => {
                searchQuery = e.target.value.toLowerCase();
                renderTable();
            });

            // Filter buttons
            document.querySelectorAll('.filter-btn').forEach(btn => {
                btn.addEventListener('click', () => {
                    document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
                    btn.classList.add('active');
                    currentFilter = btn.dataset.filter;
                    renderTable();
                });
            });

            // Close modal on overlay click
            document.getElementById('productModal').addEventListener('click', (e) => {
                if (e.target === e.currentTarget) closeModal();
            });

            document.getElementById('deleteModal').addEventListener('click', (e) => {
                if (e.target === e.currentTarget) closeDeleteModal();
            });

            // Keyboard shortcuts
            document.addEventListener('keydown', (e) => {
                if (e.key === 'Escape') {
                    closeModal();
                    closeDeleteModal();
                }
            });
        }

        // ==================== Rendering ====================
        function renderTable() {
            let products = store.getAll();

            // Apply search filter
            if (searchQuery) {
                products = products.filter(p =>
                    p.name.toLowerCase().includes(searchQuery) ||
                    p.sku.toLowerCase().includes(searchQuery) ||
                    p.category.toLowerCase().includes(searchQuery)
                );
            }

            // Apply status filter
            switch (currentFilter) {
                case 'low':
                    products = products.filter(p => p.quantity > 0 && p.quantity <= p.threshold);
                    break;
                case 'out':
                    products = products.filter(p => p.quantity === 0);
                    break;
                case 'ok':
                    products = products.filter(p => p.quantity > p.threshold);
                    break;
            }

            // Apply sorting
            products.sort((a, b) => {
                let valA = a[currentSort.field];
                let valB = b[currentSort.field];

                if (typeof valA === 'string') {
                    valA = valA.toLowerCase();
                    valB = valB.toLowerCase();
                }

                if (currentSort.direction === 'asc') {
                    return valA > valB ? 1 : valA < valB ? -1 : 0;
                } else {
                    return valA < valB ? 1 : valA > valB ? -1 : 0;
                }
            });

            const tbody = document.getElementById('productTableBody');
            const emptyState = document.getElementById('emptyState');

            if (products.length === 0) {
                tbody.innerHTML = '';
                emptyState.style.display = 'block';
                document.getElementById('productTable').querySelector('thead').style.display = 'none';
            } else {
                emptyState.style.display = 'none';
                document.getElementById('productTable').querySelector('thead').style.display = '';
                tbody.innerHTML = products.map(product => renderRow(product)).join('');
            }
        }

        function renderRow(product) {
            const status = getStockStatus(product);
            const rowClass = product.quantity <= product.threshold && product.quantity > 0 ? 'low-stock' : (product.quantity === 0 ? 'low-stock' : '');

            return `
                <tr class="${rowClass}">
                    <td>
                        <div class="product-name">${escapeHtml(product.name)}</div>
                        <div class="product-sku">${escapeHtml(product.sku || 'No SKU')}</div>
                    </td>
                    <td><span class="category-tag">${escapeHtml(product.category)}</span></td>
                    <td><span class="price">$${product.price.toFixed(2)}</span></td>
                    <td><strong>${product.quantity}</strong></td>
                    <td>
                        <input type="number" class="threshold-input" value="${product.threshold}" min="0"
                            onchange="updateThreshold(${product.id}, this.value)"
                            title="Low stock threshold">
                    </td>
                    <td><span class="stock-badge ${status.class}">${status.icon} ${status.label}</span></td>
                    <td>
                        <div class="actions">
                            <button class="action-btn" onclick="openEditModal(${product.id})" title="Edit">✏️</button>
                            <button class="action-btn delete" onclick="confirmDelete(${product.id})" title="Delete">🗑️</button>
                        </div>
                    </td>
                </tr>
            `;
        }

        function getStockStatus(product) {
            if (product.quantity === 0) {
                return { class: 'stock-out', icon: '🚫', label: 'Out of Stock' };
            } else if (product.quantity <= Math.ceil(product.threshold * 0.5)) {
                return { class: 'stock-critical', icon: '🔴', label: 'Critical' };
            } else if (product.quantity <= product.threshold) {
                return { class: 'stock-low', icon: '🟡', label: 'Low Stock' };
            } else {
                return { class: 'stock-ok', icon: '🟢', label: 'In Stock' };
            }
        }

        function updateStats() {
            const products = store.getAll();
            document.getElementById('totalProducts').textContent = products.length;
            document.getElementById('totalValue').textContent = '$' + store.getTotalValue().toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
            const alertCount = store.getLowStockProducts().length + store.getOutOfStockProducts().length;
            document.getElementById('lowStockCount').textContent = alertCount;
        }

        function updateAlerts() {
            const lowStock = store.getLowStockProducts();
            const outOfStock = store.getOutOfStockProducts();
            const allAlerts = [...outOfStock, ...lowStock];

            const banner = document.getElementById('alertBanner');
            const list = document.getElementById('alertList');

            if (allAlerts.length > 0) {
                banner.classList.add('show');
                list.innerHTML = allAlerts.map(p => {
                    if (p.quantity === 0) {
                        return `<li><strong>${escapeHtml(p.name)}</strong> is OUT OF STOCK!</li>`;
                    }
                    return `<li><strong>${escapeHtml(p.name)}</strong> — Only ${p.quantity} left (threshold: ${p.threshold})</li>`;
                }).join('');
            } else {
                banner.classList.remove('show');
            }
        }

        // ==================== CRUD Operations ====================
        function openAddModal() {
            document.getElementById('modalTitle').textContent = 'Add New Product';
            document.getElementById('productForm').reset();
            document.getElementById('productId').value = '';
            document.getElementById('productThreshold').value = '10';
            document.getElementById('productModal').classList.add('show');
            document.getElementById('productName').focus();
        }

        function openEditModal(id) {
            const product = store.getById(id);
            if (!product) return;

            document.getElementById('modalTitle').textContent = 'Edit Product';
            document.getElementById('productId').value = product.id;
            document.getElementById('productName').value = product.name;
            document.getElementById('productSKU').value = product.sku || '';
            document.getElementById('productCategory').value = product.category;
            document.getElementById('productPrice').value = product.price;
            document.getElementById('productQuantity').value = product.quantity;
            document.getElementById('productThreshold').value = product.threshold;
            document.getElementById('productDescription').value = product.description || '';
            document.getElementById('productModal').classList.add('show');
        }

        function closeModal() {
            document.getElementById('productModal').classList.remove('show');
        }

        function saveProduct(event) {
            event.preventDefault();

            const id = document.getElementById('productId').value;
            const productData = {
                name: document.getElementById('productName').value.trim(),
                sku: document.getElementById('productSKU').value.trim(),
                category: document.getElementById('productCategory').value,
                price: parseFloat(document.getElementById('productPrice').value),
                quantity: parseInt(document.getElementById('productQuantity').value),
                threshold: parseInt(document.getElementById('productThreshold').value) || 10,
                description: document.getElementById('productDescription').value.trim()
            };

            if (id) {
                // Update existing
                store.update(parseInt(id), productData);
                showToast(`"${productData.name}" has been updated successfully.`, 'success');
            } else {
                // Add new
                store.add(productData);
                showToast(`"${productData.name}" has been added to inventory.`, 'success');
            }

            closeModal();
            renderTable();
            updateStats();
            updateAlerts();
        }

        function confirmDelete(id) {
            const product = store.getById(id);
            if (!product) return;

            document.getElementById('deleteProductName').textContent = product.name;
            document.getElementById('deleteModal').classList.add('show');

            document.getElementById('confirmDeleteBtn').onclick = () => {
                store.delete(id);
                closeDeleteModal();
                renderTable();
                updateStats();
                updateAlerts();
                showToast(`"${product.name}" has been deleted.`, 'error');
            };
        }

        function closeDeleteModal() {
            document.getElementById('deleteModal').classList.remove('show');
        }

        function updateThreshold(id, value) {
            const threshold = parseInt(value) || 0;
            store.update(id, { threshold });
            renderTable();
            updateAlerts();
            showToast('Threshold updated.', 'success');
        }

        // ==================== Sorting ====================
        function sortTable(field) {
            if (currentSort.field === field) {
                currentSort.direction = currentSort.direction === 'asc' ? 'desc' : 'asc';
            } else {
                currentSort.field = field;
                currentSort.direction = 'asc';
            }
            renderTable();
        }

        // ==================== Utilities ====================
        function escapeHtml(text) {
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        function showToast(message, type = 'success') {
            const container = document.getElementById('toastContainer');
            const toast = document.createElement('div');
            toast.className = `toast ${type}`;

            const icons = { success: '✅', error: '❌', warning: '⚠️' };
            toast.innerHTML = `<span>${icons[type] || '✅'}</span><span>${message}</span>`;

            container.appendChild(toast);

            setTimeout(() => {
                toast.style.opacity = '0';
                toast.style.transform = 'translateX(100%)';
                toast.style.transition = 'all 0.3s ease';
                setTimeout(() => toast.remove(), 300);
            }, 3000);
        }
    </script>
</body>
</html>
```

## Features Overview

| Feature | Description |
|---------|-------------|
| **Add Products** | Click "Add Product" to open a form with name, SKU, category, price, quantity, threshold, and description fields |
| **Edit Products** | Click the ✏️ button on any row to modify product details |
| **Delete Products** | Click the 🗑️ button with a confirmation dialog to prevent accidental deletion |
| **Low Stock Alerts** | A banner appears at the top when any product falls below its threshold |
| **Inline Threshold Editing** | Adjust the alert threshold directly in the table |
| **Search** | Real-time search by product name, SKU, or category |
| **Filter** | Filter by All, Low Stock, Out of Stock, or In Stock |
| **Sort** | Click column headers to sort ascending/descending |
| **Dashboard Stats** | Header shows total products, total inventory value, and alert count |
| **Data Persistence** | All data is saved to `localStorage` and persists across page reloads |
| **Toast Notifications** | Visual feedback for all CRUD operations |
| **Responsive Design** | Works on desktop, tablet, and mobile screens |

## How to Run

1. Copy the entire code above into a file named `inventory.html`
2. Open the file in any modern web browser (Chrome, Firefox, Edge, Safari)
3. The system loads with sample data so you can immediately explore all features
4. All changes are automatically saved to your browser's local storage

