  color: white;
  border-radius: 6px;
  cursor: pointer;
  font-size: 13px;
  transition: all 0.2s;
}
.btn-primary:hover { background: #ff5a7a; }
.btn-secondary {
  padding: 8px 20px;
  background: var(--bg-card);
