  width: 8px;
  height: 8px;
  background: var(--warning);
  border-radius: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  cursor: pointer;
  z-index: 5;
}
</style>
</head>
<body>

<!-- ========== TOP TOOLBAR ========== -->
<div class="toolbar">
