        <button class="shape-btn" onclick="addShape('rect')"><span class="icon">▬</span>Rectangle</button>
        <button class="shape-btn" onclick="addShape('circle')"><span class="icon">●</span>Circle</button>
        <button class="shape-btn" onclick="addShape('triangle')"><span class="icon">▲</span>Triangle</button>
        <button class="shape-btn" onclick="addShape('star')"><span class="icon">★</span>Star</button>
        <button class="shape-btn" onclick="addShape('line')"><span class="icon">╱</span>Line</button>
        <button class="shape-btn" onclick="addShape('arrow')"><span class="icon">➤</span>Arrow</button>
        <button class="shape-btn" onclick="addShape('heart')"><span class="icon">♥</span>Heart</button>
        <button class="shape-btn" onclick="addShape('diamond')"><span class="icon">◆</span>Diamond</button>
        <button class="shape-btn" onclick="addShape('text')"><span class="icon">T</span>Text</button>
