        <button class="effect-btn" onclick="addEffect('fadeIn')">Fade In</button>
        <button class="effect-btn" onclick="addEffect('fadeOut')">Fade Out</button>
        <button class="effect-btn" onclick="addEffect('slideLeft')">Slide Left</button>
        <button class="effect-btn" onclick="addEffect('slideRight')">Slide Right</button>
        <button class="effect-btn" onclick="addEffect('slideUp')">Slide Up</button>
        <button class="effect-btn" onclick="addEffect('slideDown')">Slide Down</button>
        <button class="effect-btn" onclick="addEffect('scaleIn')">Scale In</button>
        <button class="effect-btn" onclick="addEffect('scaleOut')">Scale Out</button>
        <button class="effect-btn" onclick="addEffect('rotate')">Rotate</button>
        <button class="effect-btn" onclick="addEffect('bounce')">Bounce</button>
        <button class="effect-btn" onclick="addEffect('shake')">Shake</button>
        <button class="effect-btn" onclick="addEffect('pulse')">Pulse</button>
