</div>

<!-- ========== TIMELINE ========== -->
<div class="timeline-container">
  <div class="timeline-header">
    <button class="play-btn" id="playBtn" onclick="togglePlay()">▶</button>
    <button class="tool-btn" onclick="stopPlayback()">⏹</button>
