<!-- ========== EXPORT MODAL ========== -->
<div class="modal-overlay" id="exportModal">
  <div class="modal">
    <h2>📹 Export Video</h2>
    <div class="prop-row">
      <label>Format</label>
      <select id="exportFormat">
        <option value="webm">WebM (VP8)</option>
        <option value="mp4">MP4 (if supported)</option>
      </select>
    </div>
    <div class="prop-row">
      <label>Quality</label>
      <select id="exportQuality">
        <option value="2500000">Low (2.5 Mbps)</option>
        <option value="5000000" selected>Medium (5 Mbps)</option>
        <option value="10000000">High (10 Mbps)</option>
      </select>
    </div>
    <div class="prop-row">
      <label>Resolution</label>
      <select id="exportRes">
        <option value="800x500">800 × 500 (Original)</option>
        <option value="1280x720">1280 × 720 (HD)</option>
        <option value="1920x1080">1920 × 1080 (Full HD)</option>
      </select>
    </div>
    <div class="progress-bar" id="exportProgress"><div class="fill" id="exportFill"></div></div>
    <div class="export-status" id="exportStatus"></div>
    <div class="modal-actions">
      <button class="btn-secondary" onclick="closeExportModal()">Cancel</button>
      <button class="btn-primary" id="exportBtn" onclick="startExport()">🎬 Start Export</button>
    </div>
  </div>
