<script>
// ============================================================
// CORE STATE
// ============================================================
const canvas = document.getElementById('mainCanvas');
const ctx = canvas.getContext('2d');

let shapes = [];
let selectedShapeId = null;
let currentTool = 'select';
let isPlaying = false;
let currentTime = 0;
let totalDuration = 5;
let fps = 30;
let canvasBg = '#ffffff';
let timelineZoom = 150; // pixels per second
let animFrameId = null;
let lastFrameTime = 0;
let shapeIdCounter = 0;
let undoStack = [];
let redoStack = [];
let isDragging = false;
let dragOffsetX = 0, dragOffsetY = 0;
let isDrawingPath = false;
let pathPoints = [];

// Color palette for track bars
const trackColors = [
  '#e94560','#4ecca3','#f0a500','#533483','#00b4d8',
  '#e76f51','#2a9d8f','#e9c46a','#264653','#f4a261'
];

// ============================================================
// SHAPE CLASS
// ============================================================
class Shape {
  constructor(type, x, y) {
    this.id = ++shapeIdCounter;
    this.type = type;
    this.name = type.charAt(0).toUpperCase() + type.slice(1) + ' ' + this.id;
    this.x = x;
    this.y = y;
    this.width = type === 'line' || type === 'arrow' ? 150 : 100;
    this.height = type === 'line' || type === 'arrow' ? 4 : 100;
    this.rotation = 0;
    this.scaleX = 1;
    this.scaleY = 1;
    this.opacity = 1;
    this.fillColor = trackColors[this.id % trackColors.length];
    this.strokeColor = '#333333';
    this.strokeWidth = 2;
    this.text = type === 'text' ? 'Hello' : '';
    this.fontSize = 32;

    // Animation properties
    this.animStart = 0;
    this.animDuration = 1;
    this.animDelay = 0;
    this.effects = [];
    this.animPath = []; // Array of {x, y} for custom path
    this.easing = 'easeInOut';

    // Store original position for animations
    this.origX = x;
    this.origY = y;
    this.origOpacity = 1;
    this.origScaleX = 1;
    this.origScaleY = 1;
    this.origRotation = 0;

    this.visible = true;
    this.colorIndex = this.id % trackColors.length;
  }
}

// ============================================================
// EASING FUNCTIONS
// ============================================================
const easings = {
  linear: t => t,
  easeIn: t => t * t * t,
  easeOut: t => 1 - Math.pow(1 - t, 3),
  easeInOut: t => t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2,
  bounce: t => {
    const n1 = 7.5625, d1 = 2.75;
    if (t < 1 / d1) return n1 * t * t;
    if (t < 2 / d1) return n1 * (t -= 1.5 / d1) * t + 0.75;
    if (t < 2.5 / d1) return n1 * (t -= 2.25 / d1) * t + 0.9375;
    return n1 * (t -= 2.625 / d1) * t + 0.984375;
  },
  elastic: t => {
    if (t === 0 || t === 1) return t;
    return -Math.pow(2, 10 * t - 10) * Math.sin((t * 10 - 10.75) * (2 * Math.PI / 3));
  }
};

// ============================================================
// ADD SHAPE
// ============================================================
function addShape(type) {
  saveUndo();
  const cx = canvas.width / 2;
  const cy = canvas.height / 2;
  const shape = new Shape(type, cx - 50, cy - 50);
  shape.animDuration = Math.min(2, totalDuration);
  shapes.push(shape);
  selectedShapeId = shape.id;
  refreshUI();
  renderFrame(currentTime);
}

// ============================================================
// SHAPE RENDERING
// ============================================================
function drawShape(ctx, shape, time) {
  if (!shape.visible) return;

  // Calculate animation progress
  const anim = computeAnimation(shape, time);
  if (anim === null) return; // Before animation start

  ctx.save();
  ctx.globalAlpha = anim.opacity;
  ctx.translate(anim.x + shape.width * anim.scaleX / 2, anim.y + shape.height * anim.scaleY / 2);
  ctx.rotate(anim.rotation * Math.PI / 180);
  ctx.scale(anim.scaleX, anim.scaleY);
  ctx.translate(-shape.width / 2, -shape.height / 2);

  ctx.fillStyle = shape.fillColor;
  ctx.strokeStyle = shape.strokeColor;
  ctx.lineWidth = shape.strokeWidth;

  switch (shape.type) {
    case 'rect':
      ctx.beginPath();
      ctx.roundRect(0, 0, shape.width, shape.height, 6);
      ctx.fill();
      if (shape.strokeWidth > 0) ctx.stroke();
      break;

    case 'circle':
      ctx.beginPath();
      ctx.ellipse(shape.width / 2, shape.height / 2, shape.width / 2, shape.height / 2, 0, 0, Math.PI * 2);
      ctx.fill();
      if (shape.strokeWidth > 0) ctx.stroke();
      break;

    case 'triangle':
      ctx.beginPath();
      ctx.moveTo(shape.width / 2, 0);
      ctx.lineTo(shape.width, shape.height);
      ctx.lineTo(0, shape.height);
      ctx.closePath();
      ctx.fill();
      if (shape.strokeWidth > 0) ctx.stroke();
      break;

    case 'star':
      drawStar(ctx, shape.width / 2, shape.height / 2, 5, shape.width / 2, shape.width / 4);
      ctx.fill();
      if (shape.strokeWidth > 0) ctx.stroke();
      break;

    case 'line':
      ctx.beginPath();
      ctx.moveTo(0, shape.height / 2);
      ctx.lineTo(shape.width, shape.height / 2);
      ctx.strokeStyle = shape.fillColor;
      ctx.lineWidth = Math.max(shape.strokeWidth, 3);
      ctx.stroke();
      break;

    case 'arrow':
      ctx.beginPath();
      ctx.moveTo(0, shape.height / 2);
      ctx.lineTo(shape.width - 20, shape.height / 2);
      ctx.strokeStyle = shape.fillColor;
      ctx.lineWidth = Math.max(shape.strokeWidth, 3);
      ctx.stroke();
      // Arrowhead
      ctx.beginPath();
      ctx.moveTo(shape.width, shape.height / 2);
      ctx.lineTo(shape.width - 20, shape.height / 2 - 12);
      ctx.lineTo(shape.width - 20, shape.height / 2 + 12);
      ctx.closePath();
      ctx.fillStyle = shape.fillColor;
      ctx.fill();
      break;

    case 'heart':
      drawHeart(ctx, shape.width / 2, shape.height / 2, shape.width / 2);
      ctx.fill();
      if (shape.strokeWidth > 0) ctx.stroke();
      break;

    case 'diamond':
      ctx.beginPath();
      ctx.moveTo(shape.width / 2, 0);
      ctx.lineTo(shape.width, shape.height / 2);
      ctx.lineTo(shape.width / 2, shape.height);
      ctx.lineTo(0, shape.height / 2);
      ctx.closePath();
      ctx.fill();
      if (shape.strokeWidth > 0) ctx.stroke();
      break;

    case 'text':
      ctx.font = `bold ${shape.fontSize}px 'Segoe UI', sans-serif`;
      ctx.fillStyle = shape.fillColor;
      ctx.textBaseline = 'top';
      ctx.fillText(shape.text, 0, 0);
      // Update width/height based on text measurement
      const metrics = ctx.measureText(shape.text);
      shape.width = metrics.width || 100;
      shape.height = shape.fontSize * 1.2;
      break;
  }

  ctx.restore();
}

function drawStar(ctx, cx, cy, spikes, outerR, innerR) {
  let rot = Math.PI / 2 * 3;
  let step = Math.PI / spikes;
  ctx.beginPath();
  ctx.moveTo(cx, cy - outerR);
  for (let i = 0; i < spikes; i++) {
    ctx.lineTo(cx + Math.cos(rot) * outerR, cy + Math.sin(rot) * outerR);
    rot += step;
    ctx.lineTo(cx + Math.cos(rot) * innerR, cy + Math.sin(rot) * innerR);
    rot += step;
  }
  ctx.lineTo(cx, cy - outerR);
  ctx.closePath();
}

function drawHeart(ctx, cx, cy, size) {
  ctx.beginPath();
  const topY = cy - size * 0.4;
  ctx.moveTo(cx, cy + size * 0.6);
  ctx.bezierCurveTo(cx - size * 1.2, cy - size * 0.2, cx - size * 0.6, topY - size * 0.6, cx, topY + size * 0.2);
  ctx.bezierCurveTo(cx + size * 0.6, topY - size * 0.6, cx + size * 1.2, cy - size * 0.2, cx, cy + size * 0.6);
  ctx.closePath();
}

// ============================================================
// ANIMATION COMPUTATION
// ============================================================
function computeAnimation(shape, time) {
  const startTime = shape.animDelay;
  const endTime = startTime + shape.animDuration;

  // Before animation starts
  if (time < startTime) {
    // Check if any fadeIn-type effect should hide the shape initially
    const hasFadeIn = shape.effects.some(e => ['fadeIn','scaleIn','slideLeft','slideRight','slideUp','slideDown'].includes(e));
    if (hasFadeIn) return null;
    return {
      x: shape.x, y: shape.y,
      opacity: shape.opacity,
      scaleX: shape.scaleX, scaleY: shape.scaleY,
      rotation: shape.rotation
    };
  }

  // After animation ends - hold final state
  let t = Math.min((time - startTime) / shape.animDuration, 1);
  const easeFn = easings[shape.easing] || easings.easeInOut;
  const et = easeFn(t);

  let result = {
    x: shape.x,
    y: shape.y,
    opacity: shape.opacity,
    scaleX: shape.scaleX,
    scaleY: shape.scaleY,
    rotation: shape.rotation
  };

  // Apply custom animation path
  if (shape.animPath.length >= 2) {
    const pathProgress = et;
    const totalLen = getPathLength(shape.animPath);
    const targetLen = pathProgress * totalLen;
    const pt = getPointAtLength(shape.animPath, targetLen);
    result.x = pt.x - shape.width / 2;
    result.y = pt.y - shape.height / 2;
  }

  // Apply effects
  for (const effect of shape.effects) {
    switch (effect) {
      case 'fadeIn':
        result.opacity = et * shape.opacity;
        break;
      case 'fadeOut':
        result.opacity = (1 - et) * shape.opacity;
        break;
      case 'slideLeft':
        result.x = shape.x - 200 * (1 - et);
        break;
      case 'slideRight':
        result.x = shape.x + 200 * (1 - et);
        break;
      case 'slideUp':
        result.y = shape.y - 200 * (1 - et);
        break;
      case 'slideDown':
        result.y = shape.y + 200 * (1 - et);
        break;
      case 'scaleIn':
        result.scaleX = et * shape.scaleX;
        result.scaleY = et * shape.scaleY;
        break;
      case 'scaleOut':
        result.scaleX = (1 - et) * shape.scaleX;
        result.scaleY = (1 - et) * shape.scaleY;
        break;
      case 'rotate':
        result.rotation = shape.rotation + 360 * et;
        break;
      case 'bounce':
        const bounceT = easings.bounce(t);
        result.y = shape.y - 100 * (1 - bounceT);
        break;
      case 'shake':
        if (t < 1) {
          const shakeAmp = 10 * (1 - t);
          result.x += Math.sin(t * 50) * shakeAmp;
          result.y += Math.cos(t * 37) * shakeAmp;
        }
        break;
      case 'pulse':
        const pulseScale = 1 + 0.15 * Math.sin(t * Math.PI * 4);
        result.scaleX *= pulseScale;
        result.scaleY *= pulseScale;
        break;
      case 'spin':
        result.rotation = shape.rotation + 720 * et;
        break;
      case 'swing':
        result.rotation = shape.rotation + 15 * Math.sin(t * Math.PI * 3) * (1 - t);
        break;
    }
  }

  return result;
}

function getPathLength(points) {
  let len = 0;
  for (let i = 1; i < points.length; i++) {
    const dx = points[i].x - points[i-1].x;
    const dy = points[i].y - points[i-1].y;
    len += Math.sqrt(dx*dx + dy*dy);
  }
  return len;
}

function getPointAtLength(points, targetLen) {
  let len = 0;
  for (let i = 1; i < points.length; i++) {
    const dx = points[i].x - points[i-1].x;
    const dy = points[i].y - points[i-1].y;
    const segLen = Math.sqrt(dx*dx + dy*dy);
    if (len + segLen >= targetLen) {
      const t = (targetLen - len) / segLen;
      return {
        x: points[i-1].x + dx * t,
        y: points[i-1].y + dy * t
      };
    }
    len += segLen;
  }
  return points[points.length - 1];
}

// ============================================================
// RENDER FRAME
// ============================================================
function renderFrame(time) {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Background
  ctx.fillStyle = canvasBg;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Draw all shapes in order
  for (const shape of shapes) {
    drawShape(ctx, shape, time);
  }

  // Draw selection highlight (only when not exporting)
  if (!isExporting && selectedShapeId) {
    const sel = shapes.find(s => s.id === selectedShapeId);
    if (sel) {
      const anim = computeAnimation(sel, time);
      if (anim) {
        ctx.save();
        ctx.strokeStyle = '#e94560';
        ctx.lineWidth = 2;
        ctx.setLineDash([5, 3]);
        ctx.strokeRect(anim.x - 4, anim.y - 4, sel.width * anim.scaleX + 8, sel.height * anim.scaleY + 8);
        ctx.setLineDash([]);

        // Draw animation path if exists
        if (sel.animPath.length >= 2) {
          ctx.beginPath();
          ctx.strokeStyle = 'rgba(233,69,96,0.5)';
          ctx.lineWidth = 2;
          ctx.setLineDash([4, 4]);
          ctx.moveTo(sel.animPath[0].x, sel.animPath[0].y);
          for (let i = 1; i < sel.animPath.length; i++) {
            ctx.lineTo(sel.animPath[i].x, sel.animPath[i].y);
          }
          ctx.stroke();
          ctx.setLineDash([]);

          // Draw path points
          for (const pt of sel.animPath) {
            ctx.beginPath();
            ctx.arc(pt.x, pt.y, 4, 0, Math.PI * 2);
            ctx.fillStyle = '#e94560';
            ctx.fill();
          }
        }

        ctx.restore();
      }
    }
  }
}

// ============================================================
// PLAYBACK
// ============================================================
function togglePlay() {
  if (isPlaying) {
    pausePlayback();
  } else {
    startPlayback();
  }
}

function startPlayback() {
  if (isPlaying) return;
  isPlaying = true;
  document.getElementById('playBtn').textContent = '⏸';
  lastFrameTime = performance.now();
  animFrameId = requestAnimationFrame(playLoop);
}

function pausePlayback() {
  isPlaying = false;
  document.getElementById('playBtn').textContent = '▶';
  if (animFrameId) cancelAnimationFrame(animFrameId);
}

function stopPlayback() {
  pausePlayback();
  currentTime = 0;
  updateTimeDisplay();
  updatePlayhead();
  renderFrame(currentTime);
}

function playLoop(timestamp) {
  if (!isPlaying) return;

  const delta = (timestamp - lastFrameTime) / 1000;
  lastFrameTime = timestamp;
  currentTime += delta;

  if (currentTime >= totalDuration) {
    currentTime = 0; // Loop
  }

  renderFrame(currentTime);
  updateTimeDisplay();
  updatePlayhead();

  animFrameId = requestAnimationFrame(playLoop);
}

function updateTimeDisplay() {
  const cur = formatTime(currentTime);
  const tot = formatTime(totalDuration);
  document.getElementById('timeDisplay').textContent = `${cur} / ${tot}`;
}

function formatTime(seconds) {
  const m = Math.floor(seconds / 60).toString().padStart(2, '0');
  const s = Math.floor(seconds % 60).toString().padStart(2, '0');
  const ms = Math.floor((seconds % 1) * 100).toString().padStart(2, '0');
  return `${m}:${s}.${ms}`;
}

function updatePlayhead() {
  const playhead = document.getElementById('playhead');
  playhead.style.left = (currentTime * timelineZoom) + 'px';
}

// ============================================================
// CANVAS INTERACTION
// ============================================================
canvas.addEventListener('mousedown', (e) => {
  const rect = canvas.getBoundingClientRect();
  const mx = e.clientX - rect.left;
  const my = e.clientY - rect.top;

  if (currentTool === 'path') {
    // Drawing animation path
    const sel = getSelectedShape();
    if (sel) {
      isDrawingPath = true;
      sel.animPath = [{ x: mx, y: my }];
      renderFrame(currentTime);
    }
    return;
  }

  // Select tool - find shape under cursor (reverse order for top-most)
  let found = null;
  for (let i = shapes.length - 1; i >= 0; i--) {
    const s = shapes[i];
    const anim = computeAnimation(s, currentTime);
    if (!anim) continue;
    if (mx >= anim.x && mx <= anim.x + s.width * anim.scaleX &&
        my >= anim.y && my <= anim.y + s.height * anim.scaleY) {
      found = s;
      break;
    }
  }

  if (found) {
    selectedShapeId = found.id;
    isDragging = true;
    const anim = computeAnimation(found, currentTime);
    dragOffsetX = mx - anim.x;
    dragOffsetY = my - anim.y;
  } else {
    selectedShapeId = null;
  }

  refreshUI();
  renderFrame(currentTime);
});

canvas.addEventListener('mousemove', (e) => {
  const rect = canvas.getBoundingClientRect();
  const mx = e.clientX - rect.left;
  const my = e.clientY - rect.top;

  if (isDrawingPath) {
    const sel = getSelectedShape();
    if (sel) {
      sel.animPath.push({ x: mx, y: my });
      renderFrame(currentTime);
    }
    return;
  }

  if (isDragging && selectedShapeId) {
    const sel = getSelectedShape();
    if (sel) {
      sel.x = mx - dragOffsetX;
      sel.y = my - dragOffsetY;
      renderFrame(currentTime);
      updateShapeProps();
    }
  }
});

canvas.addEventListener('mouseup', () => {
  if (isDrawingPath) {
    isDrawingPath = false;
    // Simplify path (keep every Nth point)
    const sel = getSelectedShape();
    if (sel && sel.animPath.length > 10) {
      const simplified = [sel.animPath[0]];
      const step = Math.max(1, Math.floor(sel.animPath.length / 30));
      for (let i = step; i < sel.animPath.length - 1; i += step) {
        simplified.push(sel.animPath[i]);
      }
      simplified.push(sel.animPath[sel.animPath.length - 1]);
      sel.animPath = simplified;
    }
    renderFrame(currentTime);
  }
  isDragging = false;
});

