// TOOL MANAGEMENT
// ============================================================
function setTool(tool) {
  currentTool = tool;
  document.querySelectorAll('.toolbar-group .tool-btn').forEach(b => b.classList.remove('active'));
  document.getElementById(tool + 'Tool')?.classList.add('active');
  canvas.style.cursor = tool === 'path' ? 'crosshair' : 'default';
}

// ============================================================
// EFFECTS
// ============================================================
function addEffect(effectName) {
  const sel = getSelectedShape();
  if (!sel) {
    alert('Please select a shape first!');
    return;
  }
  saveUndo();
  if (!sel.effects.includes(effectName)) {
    sel.effects.push(effectName);
  }
  refreshUI();
  renderFrame(currentTime);
}

function removeEffect(effectName) {
  const sel = getSelectedShape();
  if (!sel) return;
  saveUndo();
  sel.effects = sel.effects.filter(e => e !== effectName);
  refreshUI();
  renderFrame(currentTime);
}

// ============================================================
// UI REFRESH
// ============================================================
function refreshUI() {
  updateLayerList();
  updateShapeProps();
  updateAnimProps();
  updateTimeline();
}

function getSelectedShape() {
  return shapes.find(s => s.id === selectedShapeId) || null;
}

// ---- Layer List ----
function updateLayerList() {
  const list = document.getElementById('layerList');
  list.innerHTML = '';
  for (let i = shapes.length - 1; i >= 0; i--) {
    const s = shapes[i];
    const div = document.createElement('div');
    div.className = 'layer-item' + (s.id === selectedShapeId ? ' selected' : '');
    div.innerHTML = `
      <span class="layer-icon">${getShapeIcon(s.type)}</span>
      <span class="layer-name">${s.name}</span>
      <span class="layer-actions">
        <button onclick="event.stopPropagation();toggleVisibility(${s.id})" title="Toggle visibility">${s.visible ? '👁' : '🚫'}</button>
        <button onclick="event.stopPropagation();moveLayer(${s.id},1)" title="Move up">↑</button>
        <button onclick="event.stopPropagation();moveLayer(${s.id},-1)" title="Move down">↓</button>
        <button onclick="event.stopPropagation();deleteShape(${s.id})" title="Delete">✕</button>
      </span>
    `;
    div.addEventListener('click', () => {
      selectedShapeId = s.id;
      refreshUI();
      renderFrame(currentTime);
    });
    list.appendChild(div);
  }
}

function getShapeIcon(type) {
  const icons = { rect:'▬', circle:'●', triangle:'▲', star:'★', line:'╱', arrow:'➤', heart:'♥', diamond:'◆', text:'T' };
  return icons[type] || '■';
}

function toggleVisibility(id) {
  const s = shapes.find(s => s.id === id);
  if (s) { s.visible = !s.visible; refreshUI(); renderFrame(currentTime); }
}

function moveLayer(id, dir) {
  const idx = shapes.findIndex(s => s.id === id);
  const newIdx = idx + dir;
  if (newIdx < 0 || newIdx >= shapes.length) return;
  saveUndo();
  [shapes[idx], shapes[newIdx]] = [shapes[newIdx], shapes[idx]];
  refreshUI();
  renderFrame(currentTime);
}

function deleteShape(id) {
  saveUndo();
  shapes = shapes.filter(s => s.id !== id);
  if (selectedShapeId === id) selectedShapeId = null;
  refreshUI();
  renderFrame(currentTime);
}

function deleteSelected() {
  if (selectedShapeId) deleteShape(selectedShapeId);
}

function duplicateSelected() {
  const sel = getSelectedShape();
  if (!sel) return;
  saveUndo();
  const dup = new Shape(sel.type, sel.x + 20, sel.y + 20);
  Object.assign(dup, {
    width: sel.width, height: sel.height,
    rotation: sel.rotation, scaleX: sel.scaleX, scaleY: sel.scaleY,
    opacity: sel.opacity, fillColor: sel.fillColor, strokeColor: sel.strokeColor,
    strokeWidth: sel.strokeWidth, text: sel.text, fontSize: sel.fontSize,
    animStart: sel.animStart, animDuration: sel.animDuration, animDelay: sel.animDelay,
    effects: [...sel.effects], animPath: sel.animPath.map(p => ({...p})),
    easing: sel.easing
  });
  dup.name = sel.name + ' copy';
  shapes.push(dup);
  selectedShapeId = dup.id;
  refreshUI();
  renderFrame(currentTime);
}

