// ============================================================
// TIMELINE
// ============================================================
function updateTimeline() {
  updateTimelineLabels();
  updateTimelineTracks();
  drawRuler();
  updatePlayhead();
}

function updateTimelineLabels() {
  const container = document.getElementById('timelineLabels');
  container.innerHTML = '';
  for (const s of shapes) {
    const div = document.createElement('div');
    div.className = 'timeline-label' + (s.id === selectedShapeId ? ' selected' : '');
    div.textContent = s.name;
    div.addEventListener('click', () => {
      selectedShapeId = s.id;
      refreshUI();
      renderFrame(currentTime);
    });
    container.appendChild(div);
  }
}

function updateTimelineTracks() {
  const container = document.getElementById('trackRows');
  container.innerHTML = '';
  const totalWidth = totalDuration * timelineZoom;

  for (const s of shapes) {
    const row = document.createElement('div');
    row.className = 'track-row';
    row.style.width = totalWidth + 'px';

    // Animation bar
    const bar = document.createElement('div');
    bar.className = 'track-bar';
    bar.style.left = (s.animDelay * timelineZoom) + 'px';
    bar.style.width = (s.animDuration * timelineZoom) + 'px';
    bar.style.background = trackColors[s.colorIndex];
    bar.textContent = s.effects.length > 0 ? s.effects.join(', ') : s.name;
    bar.title = `${s.name}: ${s.animDelay}s - ${s.animDelay + s.animDuration}s`;

    // Make bar draggable for repositioning delay
    bar.addEventListener('mousedown', (e) => {
      e.stopPropagation();
      selectedShapeId = s.id;
      const startX = e.clientX;
      const startDelay = s.animDelay;

      const onMove = (ev) => {
        const dx = ev.clientX - startX;
        s.animDelay = Math.max(0, startDelay + dx / timelineZoom);
        s.animDelay = Math.round(s.animDelay * 10) / 10;
        updateTimeline();
        updateAnimProps();
      };
      const onUp = () => {
        document.removeEventListener('mousemove', onMove);
        document.removeEventListener('mouseup', onUp);
      };
      document.addEventListener('mousemove', onMove);
      document.addEventListener('mouseup', onUp);
    });

    row.appendChild(bar);
    container.appendChild(row);
  }
}

function drawRuler() {
  const rulerCanvas = document.getElementById('rulerCanvas');
  const tracksEl = document.getElementById('timelineTracks');
  const totalWidth = totalDuration * timelineZoom;
  rulerCanvas.width = totalWidth;
  rulerCanvas.height = 20;
  rulerCanvas.style.width = totalWidth + 'px';

  const rctx = rulerCanvas.getContext('2d');
  rctx.fillStyle = '#1a1a2e';
  rctx.fillRect(0, 0, totalWidth, 20);

  rctx.fillStyle = '#999';
  rctx.font = '10px monospace';
  rctx.strokeStyle = '#444';

  for (let t = 0; t <= totalDuration; t += 0.5) {
    const x = t * timelineZoom;
    const isMajor = t % 1 === 0;
    rctx.beginPath();
    rctx.moveTo(x, isMajor ? 0 : 10);
    rctx.lineTo(x, 20);
    rctx.stroke();
    if (isMajor) {
      rctx.fillText(t + 's', x + 3, 12);
    }
  }
}

function updateTimelineZoom() {
  timelineZoom = +document.getElementById('timelineZoom').value;
  updateTimeline();
}

// Timeline click to seek
document.getElementById('timelineTracks').addEventListener('mousedown', (e) => {
  if (e.target.classList.contains('track-bar')) return;
  const rect = document.getElementById('timelineTracks').getBoundingClientRect();
  const x = e.clientX - rect.left + document.getElementById('timelineTracks').scrollLeft;
  currentTime = Math.max(0, Math.min(totalDuration, x / timelineZoom));
  updateTimeDisplay();
  updatePlayhead();
  renderFrame(currentTime);
});

