// ============================================================
// UNDO / REDO
// ============================================================
function saveUndo() {
  undoStack.push(JSON.stringify(shapes.map(s => ({...s, animPath: [...s.animPath], effects: [...s.effects]}))));
  if (undoStack.length > 50) undoStack.shift();
  redoStack = [];
}

function undoAction() {
  if (undoStack.length === 0) return;
  redoStack.push(JSON.stringify(shapes.map(s => ({...s, animPath: [...s.animPath], effects: [...s.effects]}))));
  const state = JSON.parse(undoStack.pop());
  shapes = state.map(s => {
    const shape = new Shape(s.type, s.x, s.y);
    Object.assign(shape, s);
    return shape;
  });
  refreshUI();
  renderFrame(currentTime);
}

function redoAction() {
  if (redoStack.length === 0) return;
  undoStack.push(JSON.stringify(shapes.map(s => ({...s, animPath: [...s.animPath], effects: [...s.effects]}))));
  const state = JSON.parse(redoStack.pop());
  shapes = state.map(s => {
    const shape = new Shape(s.type, s.x, s.y);
    Object.assign(shape, s);
    return shape;
  });
  refreshUI();
  renderFrame(currentTime);
}

// ============================================================
// VIDEO EXPORT
// ============================================================
let isExporting = false;

function showExportModal() {
  document.getElementById('exportModal').classList.add('show');
  document.getElementById('exportProgress').classList.remove('show');
  document.getElementById('exportStatus').textContent = '';
  document.getElementById('exportBtn').disabled = false;
  document.getElementById('exportBtn').textContent = '🎬 Start Export';
}

function closeExportModal() {
  if (isExporting) return;
  document.getElementById('exportModal').classList.remove('show');
}

async function startExport() {
  isExporting = true;
  const btn = document.getElementById('exportBtn');
  btn.disabled = true;
  btn.textContent = 'Exporting...';

  const progressBar = document.getElementById('exportProgress');
  const progressFill = document.getElementById('exportFill');
  const statusEl = document.getElementById('exportStatus');
  progressBar.classList.add('show');

  // Get export settings
  const quality = +document.getElementById('exportQuality').value;
  const resStr = document.getElementById('exportRes').value;
  const [expW, expH] = resStr.split('x').map(Number);

  // Create offscreen canvas for export
  const expCanvas = document.createElement('canvas');
  expCanvas.width = expW;
  expCanvas.height = expH;
  const expCtx = expCanvas.getContext('2d');

  // Setup MediaRecorder
  const stream = expCanvas.captureStream(fps);
  let mimeType = 'video/webm;codecs=vp8';
  if (document.getElementById('exportFormat').value === 'mp4') {
    if (MediaRecorder.isTypeSupported('video/mp4')) {
      mimeType = 'video/mp4';
    } else if (MediaRecorder.isTypeSupported('video/webm;codecs=h264')) {
      mimeType = 'video/webm;codecs=h264';
    }
  }

  const recorder = new MediaRecorder(stream, {
    mimeType: mimeType,
    videoBitsPerSecond: quality
  });

  const chunks = [];
  recorder.ondataavailable = (e) => { if (e.data.size > 0) chunks.push(e.data); };

  recorder.onstop = () => {
    const blob = new Blob(chunks, { type: mimeType });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `motion-graphics-${Date.now()}.${mimeType.includes('mp4') ? 'mp4' : 'webm'}`;
    a.click();
    URL.revokeObjectURL(url);

    isExporting = false;
    btn.textContent = '✅ Done! Export Again?';
    btn.disabled = false;
    statusEl.textContent = 'Export complete! File downloaded.';
    renderFrame(currentTime); // Re-render with selection highlights
  };

  // Pause any current playback
  pausePlayback();

  recorder.start();
  statusEl.textContent = 'Recording frames...';

  const totalFrames = Math.ceil(totalDuration * fps);
  const frameDuration = 1 / fps;

  // Render each frame
  for (let frame = 0; frame < totalFrames; frame++) {
    const time = frame * frameDuration;

    // Clear and render
    expCtx.clearRect(0, 0, expW, expH);

    // Scale if resolution differs
    const scaleX = expW / canvas.width;
    const scaleY = expH / canvas.height;
    expCtx.save();
    expCtx.scale(scaleX, scaleY);

    // Background
    expCtx.fillStyle = canvasBg;
    expCtx.fillRect(0, 0, canvas.width, canvas.height);

    // Draw shapes
    for (const shape of shapes) {
      drawShape(expCtx, shape, time);
    }

    expCtx.restore();

    // Update progress
    const progress = ((frame + 1) / totalFrames) * 100;
    progressFill.style.width = progress + '%';
    statusEl.textContent = `Rendering frame ${frame + 1} / ${totalFrames} (${Math.round(progress)}%)`;

    // Wait for next frame interval to let MediaRecorder capture
    await new Promise(r => setTimeout(r, 1000 / fps));
  }

  // Small delay then stop
  await new Promise(r => setTimeout(r, 200));
  recorder.stop();
}

// ============================================================
// KEYBOARD SHORTCUTS
// ============================================================
document.addEventListener('keydown', (e) => {
  if (e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT') return;

  switch (e.key) {
    case 'Delete':
    case 'Backspace':
      deleteSelected();
      break;
    case ' ':
      e.preventDefault();
      togglePlay();
      break;
    case 'd':
      if (e.ctrlKey || e.metaKey) {
        e.preventDefault();
        duplicateSelected();
      }
      break;
    case 'z':
      if (e.ctrlKey || e.metaKey) {
        e.preventDefault();
        if (e.shiftKey) redoAction();
        else undoAction();
      }
      break;
    case 'v':
      setTool('select');
      break;
    case 'p':
      setTool('path');
      break;
  }
});

