        // ============================================================
        // STATUS CALCULATION
        // ============================================================

        /**
         * Calculate the maintenance status of a device.
         * Returns: { status: 'normal'|'warning'|'overdue', daysRemaining: number, hoursRemaining: number, message: string }
         */
        function calculateStatus(device) {
            const today = new Date();
            today.setHours(0, 0, 0, 0);

            if (device.cycleType === 'days') {
                // Calendar-day based maintenance cycle
                const lastDate = device.lastMaintenanceDate
                    ? new Date(device.lastMaintenanceDate)
                    : new Date(device.registrationDate);
                lastDate.setHours(0, 0, 0, 0);

                const nextDue = new Date(lastDate);
                nextDue.setDate(nextDue.getDate() + device.cycleValue);

                const diffTime = nextDue.getTime() - today.getTime();
                const daysRemaining = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

                if (daysRemaining < 0) {
                    return {
                        status: 'overdue',
                        daysRemaining: daysRemaining,
                        message: `Overdue by ${Math.abs(daysRemaining)} day(s)`
                    };
                } else if (daysRemaining <= 7) {
                    return {
                        status: 'warning',
                        daysRemaining: daysRemaining,
                        message: `Due in ${daysRemaining} day(s)`
                    };
                } else {
                    return {
                        status: 'normal',
                        daysRemaining: daysRemaining,
                        message: `${daysRemaining} day(s) remaining`
                    };
                }
            } else {
                // Operating-hours based maintenance cycle
                const lastHours = device.lastMaintenanceHours || 0;
                const nextDueHours = lastHours + device.cycleValue;
                const currentHours = device.currentHours || 0;
                const hoursRemaining = nextDueHours - currentHours;

                // Estimate days based on average daily usage
                let avgDailyHours = 8; // default assumption
                if (device.records && device.records.length >= 2) {
                    const sorted = [...device.records].sort((a, b) => new Date(a.date) - new Date(b.date));
                    const first = sorted[0];
                    const last = sorted[sorted.length - 1];
                    const daySpan = (new Date(last.date) - new Date(first.date)) / (1000 * 60 * 60 * 24);
                    if (daySpan > 0) {
                        avgDailyHours = Math.max(1, (last.hours - first.hours) / daySpan);
                    }
                }

                const estimatedDays = Math.ceil(hoursRemaining / avgDailyHours);

                if (hoursRemaining < 0) {
                    return {
                        status: 'overdue',
                        daysRemaining: estimatedDays,
                        hoursRemaining: hoursRemaining,
                        message: `Overdue by ${Math.abs(hoursRemaining)} hour(s)`
                    };
                } else if (estimatedDays <= 7) {
                    return {
                        status: 'warning',
                        daysRemaining: estimatedDays,
                        hoursRemaining: hoursRemaining,
                        message: `~${hoursRemaining}h remaining (~${estimatedDays}d)`
                    };
                } else {
                    return {
                        status: 'normal',
                        daysRemaining: estimatedDays,
                        hoursRemaining: hoursRemaining,
                        message: `${hoursRemaining}h remaining (~${estimatedDays}d)`
                    };
                }
            }
        }

        // ============================================================
        // RENDERING
        // ============================================================

        /** Main render function: renders device cards and updates stats */
        function renderDevices() {
            const grid = document.getElementById('deviceGrid');
            const searchTerm = document.getElementById('searchInput').value.toLowerCase();

            // Filter and search
            let filtered = devices.filter(d => {
                const statusInfo = calculateStatus(d);
                const matchesFilter = currentFilter === 'all' || statusInfo.status === currentFilter;
                const matchesSearch = !searchTerm ||
                    d.name.toLowerCase().includes(searchTerm) ||
                    d.type.toLowerCase().includes(searchTerm) ||
                    (d.serialNumber && d.serialNumber.toLowerCase().includes(searchTerm));
                return matchesFilter && matchesSearch;
            });

            // Update stats
            let normalCount = 0, warningCount = 0, overdueCount = 0;
            devices.forEach(d => {
                const s = calculateStatus(d).status;
                if (s === 'normal') normalCount++;
                else if (s === 'warning') warningCount++;
                else overdueCount++;
            });
            document.getElementById('statNormal').textContent = normalCount;
            document.getElementById('statWarning').textContent = warningCount;
            document.getElementById('statOverdue').textContent = overdueCount;

            // Render cards
            if (filtered.length === 0) {
                grid.innerHTML = `
                    <div class="empty-state" style="grid-column: 1 / -1;">
                        <div class="icon">📭</div>
                        <h3>${devices.length === 0 ? 'No Devices Registered' : 'No Matching Devices'}</h3>
                        <p>${devices.length === 0 ? 'Click "Register Device" to add your first device.' : 'Try adjusting your search or filter.'}</p>
                    </div>
                `;
                return;
            }

            grid.innerHTML = filtered.map(device => {
                const statusInfo = calculateStatus(device);
                const s = statusInfo.status;
                const lastDate = device.lastMaintenanceDate || 'Never';
                const recordCount = device.records ? device.records.length : 0;

                return `
                    <div class="device-card" onclick="openDetailModal('${device.id}')">
                        <div class="card-status-bar ${s}"></div>
                        <div class="card-body">
                            <div class="card-header">
                                <div>
                                    <div class="device-name">${escapeHtml(device.name)}</div>
                                    <div class="device-type">${escapeHtml(device.type)}${device.serialNumber ? ' · ' + escapeHtml(device.serialNumber) : ''}</div>
                                </div>
                                <span class="status-tag ${s}">${s === 'normal' ? '✓ Normal' : s === 'warning' ? '⚠ Due Soon' : '✕ Overdue'}</span>
                            </div>
                            <div class="card-info">
                                <div class="info-item">
                                    <span class="label">Cycle</span>
                                    <span class="value">Every ${device.cycleValue} ${device.cycleType === 'days' ? 'days' : 'hours'}</span>
                                </div>
                                <div class="info-item">
                                    <span class="label">Last Service</span>
                                    <span class="value">${lastDate === 'Never' ? 'Never' : formatDate(lastDate)}</span>
                                </div>
                                <div class="info-item">
                                    <span class="label">Op. Hours</span>
                                    <span class="value">${(device.currentHours || 0).toLocaleString()}h</span>
                                </div>
                                <div class="info-item">
                                    <span class="label">Records</span>
                                    <span class="value">${recordCount} maintenance(s)</span>
                                </div>
                            </div>
                        </div>
                        <div class="card-footer">
                            <span class="days-remaining ${s}">${statusInfo.message}</span>
                            <span>Click for details →</span>
                        </div>
                    </div>
                `;
            }).join('');
        }

        // ============================================================
        // DEVICE REGISTRATION
        // ============================================================

        function openAddDeviceModal() {
            document.getElementById('addDeviceForm').reset();
            document.getElementById('registrationDate').value = new Date().toISOString().split('T')[0];
            openModal('addDeviceModal');
        }

        function addDevice(e) {
            e.preventDefault();

            const device = {
                id: 'dev_' + Date.now(),
                name: document.getElementById('deviceName').value.trim(),
                type: document.getElementById('deviceType').value,
                serialNumber: document.getElementById('serialNumber').value.trim(),
                registrationDate: document.getElementById('registrationDate').value,
                cycleType: document.getElementById('cycleType').value,
                cycleValue: parseInt(document.getElementById('cycleValue').value),
                currentHours: parseInt(document.getElementById('currentHours').value) || 0,
                lastMaintenanceDate: document.getElementById('lastMaintenanceDate').value || '',
                lastMaintenanceHours: parseInt(document.getElementById('lastMaintenanceHours').value) || 0,
                records: []
            };

            devices.push(device);
            saveDevices(devices);
            closeModal('addDeviceModal');
            renderDevices();
            showToast('Device registered successfully!', 'success');
        }

        // ============================================================
        // DEVICE DETAIL VIEW
        // ============================================================

        function openDetailModal(deviceId) {
            currentDeviceId = deviceId;
            const device = devices.find(d => d.id === deviceId);
            if (!device) return;

            const statusInfo = calculateStatus(device);
            const s = statusInfo.status;

            document.getElementById('detailTitle').textContent = device.name;

            const statusIcons = { normal: '✅', warning: '⚠️', overdue: '🚨' };
            const statusLabels = { normal: 'Normal Operation', warning: 'Maintenance Due Soon', overdue: 'Maintenance Overdue' };

            let historyHtml = '';
            if (device.records && device.records.length > 0) {
                const sorted = [...device.records].sort((a, b) => new Date(b.date) - new Date(a.date));
                historyHtml = sorted.map(rec => `
                    <div class="history-item">
                        <div class="history-item-header">
                            <span class="history-date">📅 ${formatDate(rec.date)}</span>
                            <span class="history-personnel">👤 ${escapeHtml(rec.personnel)}</span>
                        </div>
                        ${rec.hours !== undefined ? `<div style="font-size:12px;color:#888;margin-bottom:4px;">⏱ Hours: ${rec.hours.toLocaleString()}h</div>` : ''}
                        ${rec.consumables && rec.consumables.length > 0 ? `
                            <div class="history-consumables">
                                🔧 Consumables: ${rec.consumables.map(c => `<span>${escapeHtml(c)}</span>`).join('')}
                            </div>
                        ` : ''}
                        ${rec.notes ? `<div class="history-notes">"${escapeHtml(rec.notes)}"</div>` : ''}
                    </div>
                `).join('');
            } else {
                historyHtml = '<div class="no-history">📋 No maintenance records yet</div>';
            }

            document.getElementById('detailBody').innerHTML = `
                <!-- Status Banner -->
                <div class="detail-status-banner ${s}">
                    <span class="status-icon">${statusIcons[s]}</span>
                    <div class="status-text">
                        <h3>${statusLabels[s]}</h3>
                        <p>${statusInfo.message}</p>
                    </div>
                </div>

                <!-- Info Grid -->
                <div class="detail-info-grid">
                    <div class="detail-info-card">
                        <div class="label">Device Type</div>
                        <div class="value" style="font-size:14px;">${escapeHtml(device.type)}</div>
                    </div>
                    <div class="detail-info-card">
                        <div class="label">Serial Number</div>
                        <div class="value" style="font-size:14px;">${device.serialNumber ? escapeHtml(device.serialNumber) : 'N/A'}</div>
                    </div>
                    <div class="detail-info-card">
                        <div class="label">Registered</div>
                        <div class="value" style="font-size:14px;">${formatDate(device.registrationDate)}</div>
                    </div>
                    <div class="detail-info-card">
                        <div class="label">Maintenance Cycle</div>
                        <div class="value" style="font-size:14px;">${device.cycleValue} ${device.cycleType === 'days' ? 'Days' : 'Hours'}</div>
                    </div>
                    <div class="detail-info-card">
                        <div class="label">Current Hours</div>
                        <div class="value">${(device.currentHours || 0).toLocaleString()}h</div>
                    </div>
                    <div class="detail-info-card">
                        <div class="label">Last Maintenance</div>
                        <div class="value" style="font-size:14px;">${device.lastMaintenanceDate ? formatDate(device.lastMaintenanceDate) : 'Never'}</div>
                    </div>
                </div>

                <!-- Update Operating Hours -->
                <div style="margin-bottom:24px;">
                    <div class="section-title">⏱ Update Operating Hours</div>
                    <div class="hours-update-row">
                        <div class="form-group">
                            <input type="number" id="updateHoursInput" min="0" value="${device.currentHours || 0}" placeholder="Current operating hours">
                        </div>
                        <button class="btn-update-hours" onclick="updateOperatingHours()">Update</button>
                    </div>
                </div>

                <!-- Maintenance History -->
                <div class="section-title">📋 Maintenance History (${device.records ? device.records.length : 0})</div>
                <div class="history-list">${historyHtml}</div>

                <!-- Add Record Button -->
                <button class="btn-submit" onclick="openAddMaintenanceModal()">＋ Add Maintenance Record</button>
            `;

            openModal('detailModal');
        }

        /** Update the current operating hours for a device */
        function updateOperatingHours() {
            const device = devices.find(d => d.id === currentDeviceId);
            if (!device) return;

            const newHours = parseInt(document.getElementById('updateHoursInput').value);
            if (isNaN(newHours) || newHours < 0) {
                showToast('Please enter a valid number of hours.', 'error');
                return;
            }

            device.currentHours = newHours;
            saveDevices(devices);
            openDetailModal(currentDeviceId); // refresh detail view
            renderDevices();
            showToast('Operating hours updated!', 'success');
        }

        /** Delete the currently viewed device */
        function deleteCurrentDevice() {
            if (!currentDeviceId) return;
            const device = devices.find(d => d.id === currentDeviceId);
            if (!device) return;

            if (confirm(`Are you sure you want to delete "${device.name}"?\nThis action cannot be undone.`)) {
                devices = devices.filter(d => d.id !== currentDeviceId);
                saveDevices(devices);
                closeModal('detailModal');
                renderDevices();
                showToast('Device deleted.', 'success');
                currentDeviceId = null;
            }
        }

        // ============================================================
        // MAINTENANCE RECORDS
        // ============================================================

        function openAddMaintenanceModal() {
            document.getElementById('addMaintenanceForm').reset();
            document.getElementById('maintenanceDate').value = new Date().toISOString().split('T')[0];

            // Pre-fill current hours
            const device = devices.find(d => d.id === currentDeviceId);
            if (device) {
                document.getElementById('maintenanceHours').value = device.currentHours || 0;
            }

            tempConsumables = [];
            renderConsumableTags();
            openModal('addMaintenanceModal');
        }

        function addConsumableTag() {
            const input = document.getElementById('consumableInput');
            const value = input.value.trim();
            if (value) {
                tempConsumables.push(value);
                input.value = '';
                renderConsumableTags();
                input.focus();
            }
        }

        function removeConsumableTag(index) {
            tempConsumables.splice(index, 1);
            renderConsumableTags();
        }

        function renderConsumableTags() {
            const container = document.getElementById('consumablesTags');
            container.innerHTML = tempConsumables.map((c, i) => `
                <div class="consumable-tag">
                    ${escapeHtml(c)}
                    <span class="remove-tag" onclick="removeConsumableTag(${i})">✕</span>
                </div>
            `).join('');
        }

        function addMaintenanceRecord(e) {
            e.preventDefault();

            const device = devices.find(d => d.id === currentDeviceId);
            if (!device) return;

            const record = {
                id: 'rec_' + Date.now(),
                date: document.getElementById('maintenanceDate').value,
                personnel: document.getElementById('maintenancePersonnel').value.trim(),
                hours: parseInt(document.getElementById('maintenanceHours').value) || 0,
                consumables: [...tempConsumables],
                notes: document.getElementById('maintenanceNotes').value.trim()
            };

            // Initialize records array if needed
            if (!device.records) device.records = [];
            device.records.push(record);

            // Update last maintenance info
            device.lastMaintenanceDate = record.date;
            if (record.hours > 0) {
                device.lastMaintenanceHours = record.hours;
                // Also update current hours if the maintenance hours are higher
                if (record.hours > (device.currentHours || 0)) {
                    device.currentHours = record.hours;
                }
            }

            saveDevices(devices);
            closeModal('addMaintenanceModal');
            openDetailModal(currentDeviceId); // refresh detail view
            renderDevices();
            showToast('Maintenance record added!', 'success');
        }

        // ============================================================
        // FILTER
        // ============================================================

        function setFilter(filter, btn) {
            currentFilter = filter;
            document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
            btn.classList.add('active');
            renderDevices();
        }

        // ============================================================
        // MODAL HELPERS
        // ============================================================

        function openModal(id) {
            document.getElementById(id).classList.add('active');
            document.body.style.overflow = 'hidden';
        }

        function closeModal(id) {
            document.getElementById(id).classList.remove('active');
            // Restore scroll if no other modals are open
            const anyOpen = document.querySelector('.modal-overlay.active');
            if (!anyOpen) document.body.style.overflow = '';
        }

        // Close modal on overlay click
        document.querySelectorAll('.modal-overlay').forEach(overlay => {
            overlay.addEventListener('click', function(e) {
                if (e.target === this) {
                    this.classList.remove('active');
                    const anyOpen = document.querySelector('.modal-overlay.active');
                    if (!anyOpen) document.body.style.overflow = '';
                }
            });
        });

        // Close modal on Escape key
        document.addEventListener('keydown', function(e) {
            if (e.key === 'Escape') {
                const modals = document.querySelectorAll('.modal-overlay.active');
                if (modals.length > 0) {
                    modals[modals.length - 1].classList.remove('active');
                    const anyOpen = document.querySelector('.modal-overlay.active');
                    if (!anyOpen) document.body.style.overflow = '';
                }
            }
        });

        // Allow Enter key to add consumable tag
        document.getElementById('consumableInput').addEventListener('keydown', function(e) {
            if (e.key === 'Enter') {
                e.preventDefault();
                addConsumableTag();
            }
        });

        // ============================================================
        // UTILITY FUNCTIONS
        // ============================================================

        /** Format date string to readable format */
        function formatDate(dateStr) {
            if (!dateStr) return 'N/A';
            const d = new Date(dateStr);
            return d.toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
        }

        /** Escape HTML to prevent XSS */
        function escapeHtml(text) {
            if (!text) return '';
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        /** Show a toast notification */
        function showToast(message, type = 'success') {
            const toast = document.createElement('div');
            toast.className = `toast ${type}`;
            toast.textContent = message;
            document.body.appendChild(toast);
            setTimeout(() => toast.remove(), 3000);
        }

        /** Update cycle label hints (optional enhancement) */
        function updateCycleLabels() {
            // Could update placeholder text based on cycle type
        }

        // ============================================================
        // INITIALIZATION
        // ============================================================

        // Set default date for registration form
        document.getElementById('registrationDate').value = new Date().toISOString().split('T')[0];

        // Initial render
        renderDevices();
    </script>
</body>
</html>
```

## Key Features

| Feature | Description |
|---|---|
| **Device Registration** | Register devices with name, type, serial number, and maintenance cycle (calendar days or operating hours) |
| **Color-Coded Status** | 🟢 Green = Normal, 🟡 Yellow = Due within 7 days, 🔴 Red = Overdue |
| **Smart Calculations** | Automatically calculates status based on last maintenance date + cycle value vs. current date/hours |
| **Maintenance History** | Full history with date, personnel, consumables used, and notes |
| **Add Records** | Add new maintenance records with tag-based consumable input |
| **Search & Filter** | Search by name/type/serial; filter by status |
| **Operating Hours** | Update current operating hours directly from the detail view |
| **Data Persistence** | All data saved to `localStorage` — survives page refreshes |
| **Demo Data** | 6 pre-loaded devices with sample maintenance records |
| **Responsive** | Works on desktop and mobile screens |

## How to Run

1. **Save** the code above as `index.html`
2. **Open** it in any modern browser (Chrome, Firefox, Edge, Safari)
3. The app loads with **6 demo devices** showing all three status colors
4. Click any device card to view details and maintenance history
5. Use **"+ Register Device"** to add new devices
6. Use **"＋ Add Maintenance Record"** inside a device detail view to log maintenance

