                <div class="timeline-tracks" id="timelineTracks">
                    <div class="playhead" id="playhead" style="left:0px;"></div>
                </div>
            </div>
        </div>
    </div>

    <!-- ========== Export Modal ========== -->
    <div class="modal-overlay" id="exportModal">
        <div class="modal">
            <h2>⬇ Export Video</h2>
            <div class="modal-field">
                <label>Resolution</label>
                <select id="exportResolution">
                    <option value="1920x1080">1920 × 1080 (Full HD)</option>
                    <option value="1280x720" selected>1280 × 720 (HD)</option>
                    <option value="854x480">854 × 480 (SD)</option>
                    <option value="640x360">640 × 360</option>
                </select>
            </div>
            <div class="modal-field">
                <label>Format</label>
                <select id="exportFormat">
                    <option value="webm">WebM (VP8)</option>
                    <option value="mp4">MP4 (H.264) - if supported</option>
                </select>
            </div>
            <div class="modal-field">
                <label>Frame Rate</label>
                <select id="exportFPS">
                    <option value="24">24 fps</option>
                    <option value="30" selected>30 fps</option>
                    <option value="60">60 fps</option>
                </select>
            </div>
            <div class="export-progress" id="exportProgress">
                <div class="progress-bar">
                    <div class="progress-fill" id="progressFill"></div>
                </div>
                <div class="progress-text" id="progressText">Preparing...</div>
            </div>
            <div class="modal-actions">
                <button class="btn btn-secondary" id="btnCancelExport">Cancel</button>
                <button class="btn btn-primary" id="btnStartExport">Start Export</button>
            </div>
        </div>
    </div>

    <!-- ========== Context Menu ========== -->
    <div class="context-menu" id="contextMenu">
        <div class="context-menu-item" data-action="duplicate">📋 Duplicate</div>
        <div class="context-menu-item" data-action="split">✂ Split at Playhead</div>
        <div class="context-menu-item danger" data-action="delete">🗑 Delete</div>
    </div>

    <!-- ========== Toast Container ========== -->
    <div class="toast-container" id="toastContainer"></div>

    <!-- ========== Hidden video elements for processing ========== -->
    <div id="hiddenVideos" style="position:absolute;top:-9999px;left:-9999px;"></div>

    <script>
    // ================================================================
    // VIDEO EDITING TIMELINE MANAGER - Main Application
    // ================================================================

    (function() {
        'use strict';

        // ========== State Management ==========
        const state = {
            mediaFiles: [],          // Uploaded media files
            tracks: [],              // Timeline tracks
            clips: [],               // Clips on timeline
            selectedClipId: null,    // Currently selected clip
            playheadTime: 0,         // Current playhead position in seconds
            isPlaying: false,        // Playback state
            zoom: 80,                // Pixels per second
            snapEnabled: true,       // Snap to grid
            totalDuration: 30,       // Total timeline duration in seconds
            nextId: 1,               // ID counter
            undoStack: [],           // Undo history
            redoStack: [],           // Redo history
            animationFrameId: null,  // Animation frame ID
            lastFrameTime: 0,        // Last frame timestamp
        };

        // ========== DOM References ==========
        const dom = {
            uploadZone: document.getElementById('uploadZone'),
            fileInput: document.getElementById('fileInput'),
            mediaList: document.getElementById('mediaList'),
            mediaCount: document.getElementById('mediaCount'),
            previewCanvas: document.getElementById('previewCanvas'),
            previewPlaceholder: document.getElementById('previewPlaceholder'),
            previewContainer: document.getElementById('previewContainer'),
            btnPlayPause: document.getElementById('btnPlayPause'),
            btnSkipStart: document.getElementById('btnSkipStart'),
            btnSkipEnd: document.getElementById('btnSkipEnd'),
            btnStepBack: document.getElementById('btnStepBack'),
            btnStepForward: document.getElementById('btnStepForward'),
            timeDisplay: document.getElementById('timeDisplay'),
            trackLabels: document.getElementById('trackLabels'),
            tracksWrapper: document.getElementById('tracksWrapper'),
            timelineTracks: document.getElementById('timelineTracks'),
            timelineRuler: document.getElementById('timelineRuler'),
            rulerCanvas: document.getElementById('rulerCanvas'),
            playhead: document.getElementById('playhead'),
            zoomSlider: document.getElementById('zoomSlider'),
            zoomValue: document.getElementById('zoomValue'),
            btnExport: document.getElementById('btnExport'),
            exportModal: document.getElementById('exportModal'),
            btnStartExport: document.getElementById('btnStartExport'),
            btnCancelExport: document.getElementById('btnCancelExport'),
            exportProgress: document.getElementById('exportProgress'),
            progressFill: document.getElementById('progressFill'),
            progressText: document.getElementById('progressText'),
            btnAddVideoTrack: document.getElementById('btnAddVideoTrack'),
            btnAddAudioTrack: document.getElementById('btnAddAudioTrack'),
            btnSplit: document.getElementById('btnSplit'),
            btnDeleteClip: document.getElementById('btnDeleteClip'),
            btnSnap: document.getElementById('btnSnap'),
            btnUndo: document.getElementById('btnUndo'),
            btnRedo: document.getElementById('btnRedo'),
            contextMenu: document.getElementById('contextMenu'),
            toastContainer: document.getElementById('toastContainer'),
            hiddenVideos: document.getElementById('hiddenVideos'),
        };

        const ctx = dom.previewCanvas.getContext('2d');

        // ========== Utility Functions ==========

        /** Generate unique ID */
        function genId() {
            return state.nextId++;
        }

        /** Format time in MM:SS.mmm */
        function formatTime(seconds) {
            const mins = Math.floor(seconds / 60);
            const secs = Math.floor(seconds % 60);
            const ms = Math.floor((seconds % 1) * 1000);
            return `${String(mins).padStart(2,'0')}:${String(secs).padStart(2,'0')}.${String(ms).padStart(3,'0')}`;
        }

        /** Format duration in short form */
        function formatDuration(seconds) {
            if (seconds < 60) return `${seconds.toFixed(1)}s`;
            const mins = Math.floor(seconds / 60);
            const secs = Math.floor(seconds % 60);
            return `${mins}m ${secs}s`;
        }

        /** Show toast notification */
        function showToast(message, type = 'info') {
            const toast = document.createElement('div');
            toast.className = `toast toast-${type}`;
            toast.textContent = message;
            dom.toastContainer.appendChild(toast);
            setTimeout(() => {
                toast.style.opacity = '0';
                toast.style.transition = 'opacity 0.3s';
                setTimeout(() => toast.remove(), 300);
            }, 3000);
        }

        /** Save state for undo */
        function saveState() {
            const snapshot = JSON.parse(JSON.stringify({
                tracks: state.tracks,
                clips: state.clips,
            }));
            state.undoStack.push(snapshot);
            state.redoStack = [];
            if (state.undoStack.length > 50) state.undoStack.shift();
        }

        /** Undo */
        function undo() {
            if (state.undoStack.length === 0) return;
            const current = JSON.parse(JSON.stringify({
                tracks: state.tracks,
                clips: state.clips,
            }));
            state.redoStack.push(current);
            const prev = state.undoStack.pop();
            state.tracks = prev.tracks;
            state.clips = prev.clips;
            state.selectedClipId = null;
            renderTimeline();
            showToast('Undo', 'info');
        }

        /** Redo */
        function redo() {
            if (state.redoStack.length === 0) return;
            const current = JSON.parse(JSON.stringify({
                tracks: state.tracks,
                clips: state.clips,
            }));
            state.undoStack.push(current);
            const next = state.redoStack.pop();
            state.tracks = next.tracks;
            state.clips = next.clips;
            state.selectedClipId = null;
            renderTimeline();
            showToast('Redo', 'info');
        }

        /** Calculate total timeline duration based on clips */
        function calculateTotalDuration() {
            let maxEnd = 30;
            state.clips.forEach(clip => {
                const end = clip.startTime + clip.duration;
                if (end > maxEnd) maxEnd = end;
            });
            state.totalDuration = maxEnd + 10; // Add 10s padding
        }

        /** Get or create hidden video element for a media file */
        function getVideoElement(mediaId) {
            let el = document.getElementById(`video-${mediaId}`);
            if (!el) {
                const media = state.mediaFiles.find(m => m.id === mediaId);
                if (!media) return null;
                el = document.createElement('video');
                el.id = `video-${mediaId}`;
                el.src = media.url;
                el.preload = 'auto';
                el.muted = true;
                el.playsInline = true;
                dom.hiddenVideos.appendChild(el);
            }
            return el;
        }

        /** Get or create hidden audio element */
        function getAudioElement(mediaId) {
            let el = document.getElementById(`audio-${mediaId}`);
            if (!el) {
                const media = state.mediaFiles.find(m => m.id === mediaId);
                if (!media) return null;
                el = document.createElement('audio');
                el.id = `audio-${mediaId}`;
                el.src = media.url;
                el.preload = 'auto';
                dom.hiddenVideos.appendChild(el);
            }
            return el;
        }

        // ========== Initialize Default Tracks ==========
        function initTracks() {
            state.tracks = [
                { id: genId(), type: 'video', name: 'Video 1' },
                { id: genId(), type: 'video', name: 'Video 2' },
                { id: genId(), type: 'audio', name: 'Audio 1' },
                { id: genId(), type: 'audio', name: 'Audio 2' },
            ];
        }

        // ========== File Upload Handling ==========

        dom.uploadZone.addEventListener('click', () => dom.fileInput.click());

        dom.uploadZone.addEventListener('dragover', (e) => {
            e.preventDefault();
            dom.uploadZone.classList.add('dragover');
        });

        dom.uploadZone.addEventListener('dragleave', () => {
            dom.uploadZone.classList.remove('dragover');
        });

        dom.uploadZone.addEventListener('drop', (e) => {
            e.preventDefault();
            dom.uploadZone.classList.remove('dragover');
            handleFiles(e.dataTransfer.files);
        });

        dom.fileInput.addEventListener('change', (e) => {
            handleFiles(e.target.files);
            e.target.value = '';
        });

        /** Process uploaded files */
        function handleFiles(files) {
            Array.from(files).forEach(file => {
                const isVideo = file.type.startsWith('video/');
                const isAudio = file.type.startsWith('audio/');

                if (!isVideo && !isAudio) {
                    showToast(`Unsupported file: ${file.name}`, 'error');
                    return;
                }

                const url = URL.createObjectURL(file);
                const mediaFile = {
                    id: genId(),
                    name: file.name,
                    type: isVideo ? 'video' : 'audio',
                    url: url,
                    file: file,
                    duration: 0,
                    width: 0,
                    height: 0,
                };

                // Get duration and dimensions
                if (isVideo) {
                    const video = document.createElement('video');
                    video.preload = 'metadata';
                    video.src = url;
                    video.onloadedmetadata = () => {
                        mediaFile.duration = video.duration;
                        mediaFile.width = video.videoWidth;
                        mediaFile.height = video.videoHeight;
                        renderMediaList();
                    };
                } else {
                    const audio = document.createElement('audio');
                    audio.preload = 'metadata';
                    audio.src = url;
                    audio.onloadedmetadata = () => {
                        mediaFile.duration = audio.duration;
                        renderMediaList();
                    };
                }

                state.mediaFiles.push(mediaFile);
            });

            renderMediaList();
            showToast(`Added ${files.length} file(s) to library`, 'success');
        }

        // ========== Media List Rendering ==========

        function renderMediaList() {
            dom.mediaList.innerHTML = '';
            dom.mediaCount.textContent = `${state.mediaFiles.length} items`;

            state.mediaFiles.forEach(media => {
                const item = document.createElement('div');
                item.className = 'media-item';
                item.draggable = true;
                item.dataset.mediaId = media.id;

                const thumbnail = document.createElement('div');
                thumbnail.className = 'media-thumbnail';

                if (media.type === 'video') {
                    // Create a small video preview
                    const vid = document.createElement('video');
                    vid.src = media.url;
                    vid.muted = true;
                    vid.preload = 'metadata';
                    vid.addEventListener('loadeddata', () => {
                        vid.currentTime = 0.1;
                    });
                    thumbnail.appendChild(vid);
                } else {
                    thumbnail.textContent = '🎵';
                }

                const info = document.createElement('div');
                info.className = 'media-info';
                info.innerHTML = `
                    <div class="media-name" title="${media.name}">${media.name}</div>
                    <div class="media-meta">${media.type === 'video' ? '🎬' : '🎵'} ${media.duration ? formatDuration(media.duration) : 'Loading...'}</div>
                `;

                const removeBtn = document.createElement('button');
                removeBtn.className = 'media-remove';
                removeBtn.textContent = '×';
                removeBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    removeMediaFile(media.id);
                });

                item.appendChild(thumbnail);
                item.appendChild(info);
                item.appendChild(removeBtn);

                // Drag start for adding to timeline
                item.addEventListener('dragstart', (e) => {
                    e.dataTransfer.setData('mediaId', media.id);
                    e.dataTransfer.setData('type', 'newClip');
                    item.classList.add('dragging');
                });

                item.addEventListener('dragend', () => {
                    item.classList.remove('dragging');
                });

                dom.mediaList.appendChild(item);
            });
        }

        /** Remove media file from library */
        function removeMediaFile(mediaId) {
            // Remove associated clips
            state.clips = state.clips.filter(c => c.mediaId !== mediaId);
            state.mediaFiles = state.mediaFiles.filter(m => m.id !== mediaId);

            // Clean up hidden elements
            const vidEl = document.getElementById(`video-${mediaId}`);
            if (vidEl) vidEl.remove();
            const audEl = document.getElementById(`audio-${mediaId}`);
            if (audEl) audEl.remove();

            renderMediaList();
            renderTimeline();
            showToast('Media removed', 'info');
        }

        // ========== Track Management ==========

        function addTrack(type) {
            saveState();
            const count = state.tracks.filter(t => t.type === type).length + 1;
            state.tracks.push({
                id: genId(),
                type: type,
                name: `${type === 'video' ? 'Video' : 'Audio'} ${count}`,
            });
            renderTimeline();
            showToast(`Added ${type} track`, 'success');
        }

        dom.btnAddVideoTrack.addEventListener('click', () => addTrack('video'));
        dom.btnAddAudioTrack.addEventListener('click', () => addTrack('audio'));

        // ========== Timeline Rendering ==========

        function renderTimeline() {
            calculateTotalDuration();
            renderTrackLabels();
            renderTracks();
            renderRuler();
            updatePlayhead();
            updateTimeDisplay();
        }

        /** Render track labels on the left side */
        function renderTrackLabels() {
            dom.trackLabels.innerHTML = '';

            state.tracks.forEach(track => {
                const label = document.createElement('div');
                label.className = `track-label ${track.type}-track`;
                label.innerHTML = `
                    <span class="track-label-icon">${track.type === 'video' ? '🎬' : '🎵'}</span>
                    <span>${track.name}</span>
                `;
                dom.trackLabels.appendChild(label);
            });

            // Add track buttons
            const addVideoBtn = document.createElement('div');
            addVideoBtn.className = 'add-track-btn';
            addVideoBtn.textContent = '+ Video Track';
            addVideoBtn.addEventListener('click', () => addTrack('video'));
            dom.trackLabels.appendChild(addVideoBtn);

            const addAudioBtn = document.createElement('div');
            addAudioBtn.className = 'add-track-btn';
            addAudioBtn.textContent = '+ Audio Track';
            addAudioBtn.addEventListener('click', () => addTrack('audio'));
            dom.trackLabels.appendChild(addAudioBtn);
        }

        /** Render timeline tracks and clips */
        function renderTracks() {
            // Remove old tracks (keep playhead)
            const existingTracks = dom.timelineTracks.querySelectorAll('.timeline-track');
            existingTracks.forEach(t => t.remove());

            const totalWidth = state.totalDuration * state.zoom;

            state.tracks.forEach((track, trackIndex) => {
                const trackEl = document.createElement('div');
                trackEl.className = `timeline-track ${track.type}-track`;
                trackEl.dataset.trackId = track.id;
                trackEl.style.width = `${totalWidth}px`;

                // Drop zone for new clips
                trackEl.addEventListener('dragover', (e) => {
                    e.preventDefault();
                    trackEl.classList.add('drag-over');
                });

                trackEl.addEventListener('dragleave', () => {
                    trackEl.classList.remove('drag-over');
                });

                trackEl.addEventListener('drop', (e) => {
                    e.preventDefault();
                    trackEl.classList.remove('drag-over');
                    handleTimelineDrop(e, track.id, trackIndex);
                });

                // Click to deselect
                trackEl.addEventListener('mousedown', (e) => {
                    if (e.target === trackEl) {
                        state.selectedClipId = null;
                        renderClipsSelection();
                    }
                });

                // Render clips on this track
                const trackClips = state.clips.filter(c => c.trackId === track.id);
                trackClips.forEach(clip => {
                    const clipEl = createClipElement(clip);
                    trackEl.appendChild(clipEl);
                });

                dom.timelineTracks.appendChild(trackEl);
            });

            // Update timeline tracks width
            dom.timelineTracks.style.width = `${totalWidth}px`;
        }

        /** Create a clip DOM element */
        function createClipElement(clip) {
            const media = state.mediaFiles.find(m => m.id === clip.mediaId);
            const clipEl = document.createElement('div');
            clipEl.className = `timeline-clip ${clip.type}-clip ${clip.id === state.selectedClipId ? 'selected' : ''}`;
            clipEl.dataset.clipId = clip.id;
            clipEl.style.left = `${clip.startTime * state.zoom}px`;
            clipEl.style.width = `${clip.duration * state.zoom}px`;

            // Resize handles
            const resizeLeft = document.createElement('div');
            resizeLeft.className = 'clip-resize-left';
            clipEl.appendChild(resizeLeft);

            const nameSpan = document.createElement('span');
            nameSpan.className = 'clip-name';
            nameSpan.textContent = media ? media.name : 'Unknown';
            clipEl.appendChild(nameSpan);

            const durSpan = document.createElement('span');
            durSpan.className = 'clip-duration';
            durSpan.textContent = formatDuration(clip.duration);
            clipEl.appendChild(durSpan);

            const resizeRight = document.createElement('div');
            resizeRight.className = 'clip-resize-right';
            clipEl.appendChild(resizeRight);

            // Click to select
            clipEl.addEventListener('mousedown', (e) => {
                if (e.target.classList.contains('clip-resize-left') || 
                    e.target.classList.contains('clip-resize-right')) {
                    startClipResize(e, clip);
                    return;
                }
                e.stopPropagation();
                state.selectedClipId = clip.id;
                renderClipsSelection();
                startClipDrag(e, clip);
            });

            // Right-click context menu
            clipEl.addEventListener('contextmenu', (e) => {
                e.preventDefault();
                state.selectedClipId = clip.id;
                renderClipsSelection();
                showContextMenu(e.clientX, e.clientY, clip);
            });

            return clipEl;
        }

        /** Update clip selection visuals */
        function renderClipsSelection() {
            document.querySelectorAll('.timeline-clip').forEach(el => {
                const clipId = parseInt(el.dataset.clipId);
                el.classList.toggle('selected', clipId === state.selectedClipId);
            });
        }

        /** Handle dropping media onto timeline */
        function handleTimelineDrop(e, trackId, trackIndex) {
            const type = e.dataTransfer.getData('type');

            if (type === 'newClip') {
                const mediaId = parseInt(e.dataTransfer.getData('mediaId'));
                const media = state.mediaFiles.find(m => m.id === mediaId);
                if (!media) return;

                // Check track type compatibility
                const track = state.tracks.find(t => t.id === trackId);
                if (!track) return;

                if (track.type === 'video' && media.type !== 'video') {
                    showToast('Audio files can only go on audio tracks', 'error');
                    return;
                }
                if (track.type === 'audio' && media.type !== 'audio') {
                    showToast('Video files can only go on video tracks', 'error');
                    return;
                }

                // Calculate start time from drop position
                const rect = e.currentTarget.getBoundingClientRect();
                const scrollLeft = dom.tracksWrapper.scrollLeft;
                const x = e.clientX - rect.left + scrollLeft;
                let startTime = x / state.zoom;

                // Snap to nearest 0.5 second
                if (state.snapEnabled) {
                    startTime = Math.round(startTime * 2) / 2;
                }
                startTime = Math.max(0, startTime);

                saveState();

                const clip = {
                    id: genId(),
                    mediaId: mediaId,
                    trackId: trackId,
                    type: media.type,
                    startTime: startTime,
                    duration: media.duration || 5,
                    trimStart: 0,
                    trimEnd: media.duration || 5,
                };

                state.clips.push(clip);
                renderTimeline();
                showToast(`Added "${media.name}" to timeline`, 'success');
            }
        }

        // ========== Clip Dragging (Repositioning) ==========

        function startClipDrag(e, clip) {
            e.preventDefault();
            const startX = e.clientX;
            const startY = e.clientY;
            const origStartTime = clip.startTime;
            const origTrackId = clip.trackId;
            let moved = false;

            const clipEl = document.querySelector(`[data-clip-id="${clip.id}"]`);
            if (clipEl) clipEl.classList.add('dragging');

            function onMouseMove(moveE) {
                const dx = moveE.clientX - startX;
                const dy = moveE.clientY - startY;

                if (Math.abs(dx) > 3 || Math.abs(dy) > 3) moved = true;

                if (moved) {
                    let newStartTime = origStartTime + dx / state.zoom;
                    if (state.snapEnabled) {
                        newStartTime = Math.round(newStartTime * 2) / 2;
                    }
                    newStartTime = Math.max(0, newStartTime);
                    clip.startTime = newStartTime;

                    // Check if moved to different track
                    const trackEls = document.querySelectorAll('.timeline-track');
                    trackEls.forEach(trackEl => {
                        const rect = trackEl.getBoundingClientRect();
                        if (moveE.clientY >= rect.top && moveE.clientY <= rect.bottom) {
                            const newTrackId = parseInt(trackEl.dataset.trackId);
                            const newTrack = state.tracks.find(t => t.id === newTrackId);
                            if (newTrack && newTrack.type === clip.type) {
                                clip.trackId = newTrackId;
                            }
                        }
                    });

                    renderTimeline();
                }
            }

            function onMouseUp() {
                document.removeEventListener('mousemove', onMouseMove);
                document.removeEventListener('mouseup', onMouseUp);
                if (clipEl) clipEl.classList.remove('dragging');

                if (moved) {
                    saveState();
                    renderTimeline();
                }
            }

            document.addEventListener('mousemove', onMouseMove);
            document.addEventListener('mouseup', onMouseUp);
        }

        // ========== Clip Resizing ==========

        function startClipResize(e, clip) {
            e.preventDefault();
            e.stopPropagation();
            const isLeft = e.target.classList.contains('clip-resize-left');
            const startX = e.clientX;
            const origStart = clip.startTime;
            const origDuration = clip.duration;
            const origTrimStart = clip.trimStart;
            const media = state.mediaFiles.find(m => m.id === clip.mediaId);
            const maxDuration = media ? media.duration : 999;

            function onMouseMove(moveE) {
                const dx = moveE.clientX - startX;
                const dt = dx / state.zoom;

                if (isLeft) {
                    // Resize from left (trim start)
                    let newStart = origStart + dt;
                    let newTrimStart = origTrimStart + dt;
                    let newDuration = origDuration - dt;

                    if (state.snapEnabled) {
                        newStart = Math.round(newStart * 2) / 2;
                    }

                    newStart = Math.max(0, newStart);
                    newTrimStart = Math.max(0, newTrimStart);
                    newDuration = origDuration + (origStart - newStart);

                    if (newDuration >= 0.5 && newTrimStart <= maxDuration - 0.5) {
                        clip.startTime = newStart;
                        clip.duration = newDuration;
                        clip.trimStart = newTrimStart;
                    }
                } else {
                    // Resize from right (trim end)
                    let newDuration = origDuration + dt;
                    if (state.snapEnabled) {
                        newDuration = Math.round(newDuration * 2) / 2;
                    }
                    newDuration = Math.max(0.5, Math.min(newDuration, maxDuration - clip.trimStart));
                    clip.duration = newDuration;
                }

                renderTimeline();
            }

            function onMouseUp() {
                document.removeEventListener('mousemove', onMouseMove);
                document.removeEventListener('mouseup', onMouseUp);
                saveState();
            }

            document.addEventListener('mousemove', onMouseMove);
            document.addEventListener('mouseup', onMouseUp);
        }

        // ========== Ruler Rendering ==========

        function renderRuler() {
            const canvas = dom.rulerCanvas;
            const totalWidth = state.totalDuration * state.zoom;
            canvas.width = totalWidth;
            canvas.height = 24;

            const rctx = canvas.getContext('2d');
            rctx.clearRect(0, 0, canvas.width, canvas.height);
            rctx.fillStyle = '#1a1a2e';
            rctx.fillRect(0, 0, canvas.width, canvas.height);

            // Determine interval based on zoom
            let interval = 1;
            if (state.zoom < 30) interval = 5;
            else if (state.zoom < 60) interval = 2;
            else if (state.zoom > 150) interval = 0.5;

            const subInterval = interval / 4;

            for (let t = 0; t <= state.totalDuration; t += subInterval) {
                const x = t * state.zoom;
                const isMajor = Math.abs(t % interval) < 0.001 || Math.abs(t % interval - interval) < 0.001;

                rctx.beginPath();
                rctx.moveTo(x, isMajor ? 8 : 14);
                rctx.lineTo(x, 24);
                rctx.strokeStyle = isMajor ? '#666' : '#444';
                rctx.lineWidth = isMajor ? 1 : 0.5;
                rctx.stroke();

                if (isMajor) {
                    rctx.fillStyle = '#999';
                    rctx.font = '10px sans-serif';
                    rctx.fillText(formatTime(t), x + 3, 10);
                }
            }
        }

        // ========== Playhead ==========

        function updatePlayhead() {
            const x = state.playheadTime * state.zoom;
            dom.playhead.style.left = `${x}px`;
            dom.playhead.style.height = `${state.tracks.length * 50 + 24}px`;
        }

        // Click on ruler to move playhead
        dom.timelineRuler.addEventListener('mousedown', (e) => {
            const rect = dom.timelineRuler.getBoundingClientRect();
            const scrollLeft = dom.tracksWrapper.scrollLeft;
            const x = e.clientX - rect.left + scrollLeft;
            state.playheadTime = Math.max(0, x / state.zoom);
            updatePlayhead();
            updateTimeDisplay();
            renderPreview();

            // Allow dragging
            function onMove(moveE) {
                const mx = moveE.clientX - rect.left + dom.tracksWrapper.scrollLeft;
                state.playheadTime = Math.max(0, mx / state.zoom);
                updatePlayhead();
                updateTimeDisplay();
                renderPreview();
            }

            function onUp() {
                document.removeEventListener('mousemove', onMove);
                document.removeEventListener('mouseup', onUp);
            }

            document.addEventListener('mousemove', onMove);
            document.addEventListener('mouseup', onUp);
        });

        // ========== Time Display ==========

        function updateTimeDisplay() {
            const total = getTotalClipsDuration();
            dom.timeDisplay.textContent = `${formatTime(state.playheadTime)} / ${formatTime(total)}`;
        }

        function getTotalClipsDuration() {
            let maxEnd = 0;
            state.clips.forEach(clip => {
                const end = clip.startTime + clip.duration;
                if (end > maxEnd) maxEnd = end;
            });
            return maxEnd;
        }

        // ========== Zoom Control ==========

        dom.zoomSlider.addEventListener('input', (e) => {
            state.zoom = parseInt(e.target.value);
            dom.zoomValue.textContent = `${state.zoom}px/s`;
            renderTimeline();
        });

        // ========== Snap Toggle ==========

        dom.btnSnap.addEventListener('click', () => {
            state.snapEnabled = !state.snapEnabled;
            dom.btnSnap.style.background = state.snapEnabled ? 'var(--accent)' : '';
            dom.btnSnap.style.color = state.snapEnabled ? 'white' : '';
            showToast(`Snap ${state.snapEnabled ? 'enabled' : 'disabled'}`, 'info');
        });

        // Initialize snap button state
        dom.btnSnap.style.background = 'var(--accent)';
        dom.btnSnap.style.color = 'white';

        // ========== Playback Controls ==========

        dom.btnPlayPause.addEventListener('click', togglePlayback);
        dom.btnSkipStart.addEventListener('click', () => {
            state.playheadTime = 0;
            updatePlayhead();
            updateTimeDisplay();
            renderPreview();
        });
        dom.btnSkipEnd.addEventListener('click', () => {
            state.playheadTime = getTotalClipsDuration();
            updatePlayhead();
            updateTimeDisplay();
            renderPreview();
        });
        dom.btnStepBack.addEventListener('click', () => {
            state.playheadTime = Math.max(0, state.playheadTime - 1/30);
            updatePlayhead();
            updateTimeDisplay();
            renderPreview();
        });
        dom.btnStepForward.addEventListener('click', () => {
            state.playheadTime += 1/30;
            updatePlayhead();
            updateTimeDisplay();
            renderPreview();
        });

        function togglePlayback() {
            if (state.isPlaying) {
                stopPlayback();
            } else {
                startPlayback();
            }
        }

        function startPlayback() {
            if (state.clips.length === 0) {
                showToast('Add clips to the timeline first', 'error');
                return;
            }

            state.isPlaying = true;
            dom.btnPlayPause.textContent = '⏸';
            state.lastFrameTime = performance.now();

            // Start all active video/audio elements
            syncMediaElements();

            function animate(now) {
                if (!state.isPlaying) return;

                const delta = (now - state.lastFrameTime) / 1000;
                state.lastFrameTime = now;
                state.playheadTime += delta;

                const totalDuration = getTotalClipsDuration();
                if (state.playheadTime >= totalDuration) {
                    state.playheadTime = 0;
                    stopPlayback();
                    renderPreview();
                    return;
                }

                updatePlayhead();
                updateTimeDisplay();
                renderPreview();

                // Auto-scroll timeline
                const playheadX = state.playheadTime * state.zoom;
                const wrapperRect = dom.tracksWrapper.getBoundingClientRect();
                const scrollLeft = dom.tracksWrapper.scrollLeft;
                if (playheadX > scrollLeft + wrapperRect.width - 50) {
                    dom.tracksWrapper.scrollLeft = playheadX - 100;
                }

                state.animationFrameId = requestAnimationFrame(animate);
            }

            state.animationFrameId = requestAnimationFrame(animate);
        }

        function stopPlayback() {
            state.isPlaying = false;
            dom.btnPlayPause.textContent = '▶';
            if (state.animationFrameId) {
                cancelAnimationFrame(state.animationFrameId);
                state.animationFrameId = null;
            }

            // Pause all media elements
            document.querySelectorAll('#hiddenVideos video, #hiddenVideos audio').forEach(el => {
                el.pause();
            });
        }

        /** Sync media elements to current playhead time */
        function syncMediaElements() {
            // Pause all first
            document.querySelectorAll('#hiddenVideos video, #hiddenVideos audio').forEach(el => {
                el.pause();
            });

            // Find active clips at current time
            state.clips.forEach(clip => {
                const clipStart = clip.startTime;
                const clipEnd = clip.startTime + clip.duration;

                if (state.playheadTime >= clipStart && state.playheadTime < clipEnd) {
                    const mediaTime = clip.trimStart + (state.playheadTime - clipStart);

                    if (clip.type === 'video') {
                        const vid = getVideoElement(clip.mediaId);
                        if (vid) {
                            vid.currentTime = mediaTime;
                            vid.play().catch(() => {});
                        }
                    } else {
                        const aud = getAudioElement(clip.mediaId);
                        if (aud) {
                            aud.currentTime = mediaTime;
                            aud.play().catch(() => {});
                        }
                    }
                }
            });
        }

        // ========== Preview Rendering ==========

        function renderPreview() {
            const canvas = dom.previewCanvas;
            const w = canvas.width;
            const h = canvas.height;

            // Clear canvas
            ctx.fillStyle = '#000';
            ctx.fillRect(0, 0, w, h);

            if (state.clips.length === 0) {
                dom.previewPlaceholder.classList.remove('hidden');
                return;
            }

            dom.previewPlaceholder.classList.add('hidden');

            // Find video clips active at current time (render from bottom track to top)
            const videoTracks = state.tracks.filter(t => t.type === 'video');
            let rendered = false;

            // Render from last track to first (top tracks overlay bottom)
            for (let i = videoTracks.length - 1; i >= 0; i--) {
                const track = videoTracks[i];
                const trackClips = state.clips.filter(c => c.trackId === track.id);

                for (const clip of trackClips) {
                    const clipStart = clip.startTime;
                    const clipEnd = clip.startTime + clip.duration;

                    if (state.playheadTime >= clipStart && state.playheadTime < clipEnd) {
                        const mediaTime = clip.trimStart + (state.playheadTime - clipStart);
                        const vid = getVideoElement(clip.mediaId);

                        if (vid && vid.readyState >= 2) {
                            // Set video time if not playing (for scrubbing)
                            if (!state.isPlaying) {
                                vid.currentTime = mediaTime;
                            }

                            // Draw video frame to canvas
                            const vw = vid.videoWidth || w;
                            const vh = vid.videoHeight || h;
                            const scale = Math.min(w / vw, h / vh);
                            const dw = vw * scale;
                            const dh = vh * scale;
                            const dx = (w - dw) / 2;
                            const dy = (h - dh) / 2;

                            ctx.drawImage(vid, dx, dy, dw, dh);
                            rendered = true;
                        }
                    }
                }
            }

            if (!rendered) {
                // Show frame indicator
                ctx.fillStyle = '#333';
                ctx.fillRect(0, 0, w, h);
                ctx.fillStyle = '#666';
                ctx.font = '16px sans-serif';
                ctx.textAlign = 'center';
                ctx.fillText('No video at current time', w/2, h/2);
                ctx.textAlign = 'start';
            }
        }

        // ========== Clip Operations ==========

        /** Split clip at playhead */
        function splitClip() {
            if (!state.selectedClipId) {
                showToast('Select a clip to split', 'error');
                return;
            }

            const clip = state.clips.find(c => c.id === state.selectedClipId);
            if (!clip) return;

            const splitTime = state.playheadTime;
            if (splitTime <= clip.startTime || splitTime >= clip.startTime + clip.duration) {
                showToast('Move playhead inside the clip to split', 'error');
                return;
            }

            saveState();

            const offset = splitTime - clip.startTime;
            const newClip = {
                id: genId(),
                mediaId: clip.mediaId,
                trackId: clip.trackId,
                type: clip.type,
                startTime: splitTime,
                duration: clip.duration - offset,
                trimStart: clip.trimStart + offset,
                trimEnd: clip.trimEnd,
            };

            clip.duration = offset;
            clip.trimEnd = clip.trimStart + offset;

            state.clips.push(newClip);
            renderTimeline();
            showToast('Clip split successfully', 'success');
        }

        /** Delete selected clip */
        function deleteClip() {
            if (!state.selectedClipId) {
                showToast('Select a clip to delete', 'error');
                return;
            }

            saveState();
            state.clips = state.clips.filter(c => c.id !== state.selectedClipId);
            state.selectedClipId = null;
            renderTimeline();
            showToast('Clip deleted', 'info');
        }

        /** Duplicate selected clip */
        function duplicateClip() {
            if (!state.selectedClipId) return;

            const clip = state.clips.find(c => c.id === state.selectedClipId);
            if (!clip) return;

            saveState();

            const newClip = {
                ...clip,
                id: genId(),
                startTime: clip.startTime + clip.duration,
            };

            state.clips.push(newClip);
            state.selectedClipId = newClip.id;
            renderTimeline();
            showToast('Clip duplicated', 'success');
        }

        dom.btnSplit.addEventListener('click', splitClip);
        dom.btnDeleteClip.addEventListener('click', deleteClip);
        dom.btnUndo.addEventListener('click', undo);
        dom.btnRedo.addEventListener('click', redo);

        // ========== Context Menu ==========

        function showContextMenu(x, y, clip) {
            dom.contextMenu.style.left = `${x}px`;
            dom.contextMenu.style.top = `${y}px`;
            dom.contextMenu.classList.add('active');
            dom.contextMenu._clip = clip;
        }

        document.addEventListener('click', () => {
            dom.contextMenu.classList.remove('active');
        });

        dom.contextMenu.querySelectorAll('.context-menu-item').forEach(item => {
            item.addEventListener('click', () => {
                const action = item.dataset.action;
                const clip = dom.contextMenu._clip;
                if (!clip) return;

                switch(action) {
                    case 'duplicate':
