        // ========== Keyboard Shortcuts ==========

        document.addEventListener('keydown', (e) => {
            // Space: Play/Pause
            if (e.code === 'Space' && e.target === document.body) {
                e.preventDefault();
                togglePlayback();
            }

            // Delete/Backspace: Delete clip
            if ((e.code === 'Delete' || e.code === 'Backspace') && e.target === document.body) {
                e.preventDefault();
                deleteClip();
            }

            // Ctrl+Z: Undo
            if (e.ctrlKey && e.code === 'KeyZ') {
                e.preventDefault();
                undo();
            }

            // Ctrl+Y: Redo
            if (e.ctrlKey && e.code === 'KeyY') {
                e.preventDefault();
                redo();
            }

            // Ctrl+D: Duplicate
            if (e.ctrlKey && e.code === 'KeyD') {
                e.preventDefault();
                duplicateClip();
            }

            // S: Split
            if (e.code === 'KeyS' && !e.ctrlKey && e.target === document.body) {
                e.preventDefault();
                splitClip();
            }

            // Left/Right arrows: Step
            if (e.code === 'ArrowLeft' && e.target === document.body) {
                e.preventDefault();
                state.playheadTime = Math.max(0, state.playheadTime - (e.shiftKey ? 1 : 1/30));
                updatePlayhead();
                updateTimeDisplay();
                renderPreview();
            }
            if (e.code === 'ArrowRight' && e.target === document.body) {
                e.preventDefault();
                state.playheadTime += (e.shiftKey ? 1 : 1/30);
                updatePlayhead();
                updateTimeDisplay();
                renderPreview();
            }

            // Home: Go to start
            if (e.code === 'Home' && e.target === document.body) {
                e.preventDefault();
                state.playheadTime = 0;
                updatePlayhead();
                updateTimeDisplay();
                renderPreview();
            }

            // End: Go to end
            if (e.code === 'End' && e.target === document.body) {
                e.preventDefault();
                state.playheadTime = getTotalClipsDuration();
                updatePlayhead();
                updateTimeDisplay();
                renderPreview();
            }
        });

        // ========== Export Functionality ==========

        dom.btnExport.addEventListener('click', () => {
            if (state.clips.length === 0) {
                showToast('Add clips to the timeline before exporting', 'error');
                return;
            }
            dom.exportModal.classList.add('active');
            dom.exportProgress.classList.remove('active');
            dom.btnStartExport.disabled = false;
        });

        dom.btnCancelExport.addEventListener('click', () => {
            dom.exportModal.classList.remove('active');
        });

        dom.btnStartExport.addEventListener('click', startExport);

        async function startExport() {
            dom.btnStartExport.disabled = true;
            dom.exportProgress.classList.add('active');
            dom.progressFill.style.width = '0%';
            dom.progressText.textContent = 'Preparing export...';

            const resolution = document.getElementById('exportResolution').value.split('x');
            const exportWidth = parseInt(resolution[0]);
            const exportHeight = parseInt(resolution[1]);
            const fps = parseInt(document.getElementById('exportFPS').value);
            const format = document.getElementById('exportFormat').value;

            // Create export canvas
            const exportCanvas = document.createElement('canvas');
            exportCanvas.width = exportWidth;
            exportCanvas.height = exportHeight;
            const exportCtx = exportCanvas.getContext('2d');

            const totalDuration = getTotalClipsDuration();
            const totalFrames = Math.ceil(totalDuration * fps);

            // Setup MediaRecorder
            const stream = exportCanvas.captureStream(fps);

            // Add audio tracks to stream if available
            const audioCtx = new AudioContext();
            const audioDestination = audioCtx.createMediaStreamDestination();
            let hasAudio = false;

            const audioClips = state.clips.filter(c => c.type === 'audio');
            const audioElements = [];

            for (const clip of audioClips) {
                const aud = getAudioElement(clip.mediaId);
                if (aud) {
                    try {
                        const source = audioCtx.createMediaElementSource(aud);
                        source.connect(audioDestination);
                        source.connect(audioCtx.destination);
                        audioElements.push({ element: aud, clip: clip });
                        hasAudio = true;
                    } catch(err) {
                        // Element might already be connected
                        console.warn('Audio connection issue:', err);
                    }
                }
            }

            // Also add audio from video clips
            const videoClips = state.clips.filter(c => c.type === 'video');
            for (const clip of videoClips) {
                const vid = getVideoElement(clip.mediaId);
                if (vid) {
                    try {
                        const source = audioCtx.createMediaElementSource(vid);
                        source.connect(audioDestination);
                        source.connect(audioCtx.destination);
                        audioElements.push({ element: vid, clip: clip });
                        hasAudio = true;
                    } catch(err) {
                        console.warn('Video audio connection issue:', err);
                    }
                }
            }

            // Combine video and audio streams
            if (hasAudio) {
                audioDestination.stream.getAudioTracks().forEach(track => {
                    stream.addTrack(track);
                });
            }

            // Determine MIME type
            let mimeType = 'video/webm;codecs=vp8';
            if (format === 'mp4' && MediaRecorder.isTypeSupported('video/mp4;codecs=h264')) {
                mimeType = 'video/mp4;codecs=h264';
            } else if (MediaRecorder.isTypeSupported('video/webm;codecs=vp9')) {
                mimeType = 'video/webm;codecs=vp9';
            }

            const recorder = new MediaRecorder(stream, {
                mimeType: mimeType,
                videoBitsPerSecond: 5000000,
            });

            const chunks = [];
            recorder.ondataavailable = (e) => {
                if (e.data.size > 0) chunks.push(e.data);
            };

            recorder.onstop = () => {
                const blob = new Blob(chunks, { type: mimeType });
                const url = URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = url;
                a.download = `export_${Date.now()}.${format === 'mp4' ? 'mp4' : 'webm'}`;
                a.click();
                URL.revokeObjectURL(url);

                dom.progressFill.style.width = '100%';
                dom.progressText.textContent = 'Export complete! Downloading...';
                showToast('Video exported successfully!', 'success');

                setTimeout(() => {
                    dom.exportModal.classList.remove('active');
                }, 1500);

                // Cleanup audio
                audioCtx.close();
            };

            recorder.start();

            // Start all audio elements
            audioElements.forEach(({ element, clip }) => {
                element.currentTime = clip.trimStart;
                element.muted = false;
            });

            // Render frames
            const frameDuration = 1000 / fps;
            let currentFrame = 0;

            // Pre-load all video elements
            const videoLoadPromises = [];
            state.clips.filter(c => c.type === 'video').forEach(clip => {
                const vid = getVideoElement(clip.mediaId);
                if (vid) {
                    vid.muted = true;
                    const p = new Promise(resolve => {
                        if (vid.readyState >= 2) resolve();
                        else {
                            vid.onloadeddata = resolve;
                            vid.load();
                        }
                    });
                    videoLoadPromises.push(p);
                }
            });

            await Promise.all(videoLoadPromises);

            dom.progressText.textContent = 'Rendering frames...';

            // Play audio elements
            audioElements.forEach(({ element }) => {
                element.play().catch(() => {});
            });

            function renderExportFrame() {
                if (currentFrame >= totalFrames) {
                    recorder.stop();
                    audioElements.forEach(({ element }) => element.pause());
                    return;
                }

                const time = currentFrame / fps;
                const progress = (currentFrame / totalFrames) * 100;
                dom.progressFill.style.width = `${progress}%`;
                dom.progressText.textContent = `Rendering: ${Math.round(progress)}% (${currentFrame}/${totalFrames} frames)`;

                // Clear
                exportCtx.fillStyle = '#000';
                exportCtx.fillRect(0, 0, exportWidth, exportHeight);

                // Render video tracks
                const videoTracks = state.tracks.filter(t => t.type === 'video');
                for (let i = videoTracks.length - 1; i >= 0; i--) {
                    const track = videoTracks[i];
                    const trackClips = state.clips.filter(c => c.trackId === track.id);

                    for (const clip of trackClips) {
                        if (time >= clip.startTime && time < clip.startTime + clip.duration) {
                            const mediaTime = clip.trimStart + (time - clip.startTime);
                            const vid = getVideoElement(clip.mediaId);

                            if (vid && vid.readyState >= 2) {
                                vid.currentTime = mediaTime;

                                const vw = vid.videoWidth || exportWidth;
                                const vh = vid.videoHeight || exportHeight;
                                const scale = Math.min(exportWidth / vw, exportHeight / vh);
                                const dw = vw * scale;
                                const dh = vh * scale;
                                const dx = (exportWidth - dw) / 2;
                                const dy = (exportHeight - dh) / 2;

                                exportCtx.drawImage(vid, dx, dy, dw, dh);
                            }
                        }
                    }
                }

                currentFrame++;

                // Use setTimeout to allow video elements to seek
                setTimeout(renderExportFrame, frameDuration / 4);
            }

            renderExportFrame();
        }

        // ========== Demo Data (Mock) ==========

        function loadDemoData() {
            // Create mock media files using canvas-generated videos
            createMockMedia('Sample Video 1', 'video', 5, '#4a90d9', 'V1');
            createMockMedia('Sample Video 2', 'video', 8, '#e94560', 'V2');
            createMockMedia('Background Music', 'audio', 15, '#50c878', '♪');
            createMockMedia('Sound Effect', 'audio', 3, '#f39c12', '🔊');
        }

        function createMockMedia(name, type, duration, color, label) {
            // Create a canvas-based mock video
            const canvas = document.createElement('canvas');
            canvas.width = 640;
            canvas.height = 360;
            const mctx = canvas.getContext('2d');

            // Draw a colorful frame
            mctx.fillStyle = color;
            mctx.fillRect(0, 0, 640, 360);
            mctx.fillStyle = 'white';
            mctx.font = 'bold 48px sans-serif';
            mctx.textAlign = 'center';
            mctx.textBaseline = 'middle';
            mctx.fillText(label, 320, 160);
            mctx.font = '24px sans-serif';
            mctx.fillText(name, 320, 220);

            // Create a blob URL from canvas for thumbnail
            const thumbnailUrl = canvas.toDataURL('image/png');

            // For actual playback, we'll use a MediaRecorder to create a real video blob
            if (type === 'video') {
                createMockVideoBlob(name, duration, color, label).then(url => {
                    const mediaFile = {
                        id: genId(),
                        name: name,
                        type: 'video',
                        url: url,
                        duration: duration,
                        width: 640,
                        height: 360,
                        thumbnailUrl: thumbnailUrl,
                    };
                    state.mediaFiles.push(mediaFile);
                    renderMediaList();
                });
            } else {
                // For audio, create a silent audio blob
                createMockAudioBlob(name, duration).then(url => {
                    const mediaFile = {
                        id: genId(),
                        name: name,
                        type: 'audio',
                        url: url,
                        duration: duration,
                    };
                    state.mediaFiles.push(mediaFile);
                    renderMediaList();
                });
            }
        }

        async function createMockVideoBlob(name, duration, color, label) {
            const canvas = document.createElement('canvas');
            canvas.width = 640;
            canvas.height = 360;
            const mctx = canvas.getContext('2d');

            const stream = canvas.captureStream(30);
            const recorder = new MediaRecorder(stream, { mimeType: 'video/webm' });
            const chunks = [];

            return new Promise((resolve) => {
                recorder.ondataavailable = (e) => {
                    if (e.data.size > 0) chunks.push(e.data);
                };

                recorder.onstop = () => {
                    const blob = new Blob(chunks, { type: 'video/webm' });
                    resolve(URL.createObjectURL(blob));
                };

                recorder.start();

                let frame = 0;
                const totalFrames = duration * 30;

                function drawFrame() {
                    const t = frame / 30;

                    // Animated background
                    const hue = (t * 30) % 360;
                    mctx.fillStyle = color;
                    mctx.fillRect(0, 0, 640, 360);

                    // Animated circle
                    mctx.beginPath();
                    mctx.arc(320 + Math.sin(t * 2) * 100, 180 + Math.cos(t * 3) * 50, 40, 0, Math.PI * 2);
                    mctx.fillStyle = 'rgba(255,255,255,0.3)';
                    mctx.fill();

                    // Text
                    mctx.fillStyle = 'white';
                    mctx.font = 'bold 48px sans-serif';
                    mctx.textAlign = 'center';
                    mctx.textBaseline = 'middle';
                    mctx.fillText(label, 320, 140);

                    mctx.font = '24px sans-serif';
                    mctx.fillText(name, 320, 200);

                    mctx.font = '18px sans-serif';
                    mctx.fillStyle = 'rgba(255,255,255,0.7)';
                    mctx.fillText(`Time: ${t.toFixed(1)}s / ${duration}s`, 320, 260);

                    // Progress bar
                    mctx.fillStyle = 'rgba(255,255,255,0.2)';
                    mctx.fillRect(120, 300, 400, 10);
                    mctx.fillStyle = 'rgba(255,255,255,0.8)';
                    mctx.fillRect(120, 300, 400 * (t / duration), 10);

                    frame++;
                    if (frame < totalFrames) {
                        requestAnimationFrame(drawFrame);
                    } else {
                        recorder.stop();
                    }
                }

                drawFrame();
            });
        }

        async function createMockAudioBlob(name, duration) {
            // Create a simple audio using AudioContext and OscillatorNode
            const audioCtx = new OfflineAudioContext(1, 44100 * duration, 44100);
            const oscillator = audioCtx.createOscillator();
            const gainNode = audioCtx.createGain();

            oscillator.type = 'sine';
            oscillator.frequency.setValueAtTime(440, 0);
            // Create a simple melody
            for (let i = 0; i < duration; i++) {
                const freq = 220 + (i % 4) * 110;
                oscillator.frequency.setValueAtTime(freq, i);
            }

            gainNode.gain.setValueAtTime(0.3, 0);
            gainNode.gain.setValueAtTime(0, duration - 0.1);

            oscillator.connect(gainNode);
            gainNode.connect(audioCtx.destination);
            oscillator.start(0);
            oscillator.stop(duration);

            const audioBuffer = await audioCtx.startRendering();

            // Convert AudioBuffer to WAV blob
            const wavBlob = audioBufferToWav(audioBuffer);
            return URL.createObjectURL(wavBlob);
        }

        function audioBufferToWav(buffer) {
            const numChannels = buffer.numberOfChannels;
            const sampleRate = buffer.sampleRate;
            const format = 1; // PCM
            const bitDepth = 16;
            const bytesPerSample = bitDepth / 8;
            const blockAlign = numChannels * bytesPerSample;
            const dataLength = buffer.length * blockAlign;
            const headerLength = 44;
            const totalLength = headerLength + dataLength;

            const arrayBuffer = new ArrayBuffer(totalLength);
            const view = new DataView(arrayBuffer);

            // WAV header
            writeString(view, 0, 'RIFF');
            view.setUint32(4, totalLength - 8, true);
            writeString(view, 8, 'WAVE');
            writeString(view, 12, 'fmt ');
            view.setUint32(16, 16, true);
            view.setUint16(20, format, true);
            view.setUint16(22, numChannels, true);
            view.setUint32(24, sampleRate, true);
            view.setUint32(28, sampleRate * blockAlign, true);
            view.setUint16(32, blockAlign, true);
            view.setUint16(34, bitDepth, true);
            writeString(view, 36, 'data');
            view.setUint32(40, dataLength, true);

            // Write audio data
            const channelData = buffer.getChannelData(0);
            let offset = 44;
            for (let i = 0; i < buffer.length; i++) {
                const sample = Math.max(-1, Math.min(1, channelData[i]));
                view.setInt16(offset, sample < 0 ? sample * 0x8000 : sample * 0x7FFF, true);
                offset += 2;
            }

            return new Blob([arrayBuffer], { type: 'audio/wav' });
        }

        function writeString(view, offset, string) {
            for (let i = 0; i < string.length; i++) {
                view.setUint8(offset + i, string.charCodeAt(i));
            }
        }

        // ========== Initialize Application ==========

        function init() {
            initTracks();
            renderTimeline();
            renderPreview();

            // Load demo data
            showToast('Loading demo media files...', 'info');
            loadDemoData();

            // After demo loads, add some clips to timeline
            setTimeout(() => {
                if (state.mediaFiles.length >= 2) {
                    const videoMedia = state.mediaFiles.filter(m => m.type === 'video');
                    const audioMedia = state.mediaFiles.filter(m => m.type === 'audio');
                    const videoTracks = state.tracks.filter(t => t.type === 'video');
                    const audioTracks = state.tracks.filter(t => t.type === 'audio');

                    if (videoMedia.length >= 1 && videoTracks.length >= 1) {
                        state.clips.push({
                            id: genId(),
                            mediaId: videoMedia[0].id,
                            trackId: videoTracks[0].id,
                            type: 'video',
                            startTime: 0,
                            duration: videoMedia[0].duration || 5,
                            trimStart: 0,
                            trimEnd: videoMedia[0].duration || 5,
                        });
                    }

                    if (videoMedia.length >= 2 && videoTracks.length >= 1) {
                        state.clips.push({
                            id: genId(),
                            mediaId: videoMedia[1].id,
                            trackId: videoTracks[0].id,
                            type: 'video',
                            startTime: (videoMedia[0].duration || 5) + 0.5,
                            duration: videoMedia[1].duration || 8,
                            trimStart: 0,
                            trimEnd: videoMedia[1].duration || 8,
                        });
                    }

                    if (audioMedia.length >= 1 && audioTracks.length >= 1) {
                        state.clips.push({
                            id: genId(),
                            mediaId: audioMedia[0].id,
                            trackId: audioTracks[0].id,
                            type: 'audio',
                            startTime: 0,
                            duration: audioMedia[0].duration || 15,
                            trimStart: 0,
                            trimEnd: audioMedia[0].duration || 15,
                        });
                    }

                    renderTimeline();
                    showToast('Demo project loaded! Press Space to play.', 'success');
                }
            }, 3000);
        }

        // Start the application
        init();

    })();
    </script>
</body>
</html>
