<script>
(() => {
  // ---------- DOM Elements ----------
  const uploadArea   = document.getElementById('uploadArea');
  const fileInput    = document.getElementById('fileInput');
  const fileInfo     = document.getElementById('fileInfo');
  const delaySlider  = document.getElementById('delayTime');
  const delayValue   = document.getElementById('delayValue');
  const intSlider    = document.getElementById('intensity');
  const intValue     = document.getElementById('intensityValue');
  const mixSlider    = document.getElementById('mix');
  const mixValue     = document.getElementById('mixValue');
  const canvas       = document.getElementById('waveform');
  const ctx          = canvas.getContext('2d');
  const playOrigBtn  = document.getElementById('playOriginalBtn');
  const applyBtn     = document.getElementById('applyBtn');
  const playProcBtn  = document.getElementById('playProcessedBtn');
  const downloadBtn  = document.getElementById('downloadBtn');
  const statusEl     = document.getElementById('status');

  // ---------- State ----------
  let audioCtx       = null;
  let originalBuffer = null;
  let processedBuffer= null;
  let currentSource  = null;
  let isPlaying      = false;

  // ---------- Helpers ----------
  const showStatus = (msg, type = 'info') => {
    statusEl.textContent = msg;
    statusEl.className = 'status show ' + type;
  };
  const hideStatus = () => { statusEl.className = 'status'; };

  const ensureAudioCtx = () => {
    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    return audioCtx;
  };

  // ---------- Slider UI ----------
  delaySlider.addEventListener('input', () => {
    delayValue.textContent = parseFloat(delaySlider.value).toFixed(2) + ' s';
  });
  intSlider.addEventListener('input', () => {
    intValue.textContent = Math.round(parseFloat(intSlider.value) * 100) + '%';
  });
  mixSlider.addEventListener('input', () => {
    mixValue.textContent = Math.round(parseFloat(mixSlider.value) * 100) + '%';
  });

  // ---------- File Upload ----------
  uploadArea.addEventListener('click', () => fileInput.click());
  uploadArea.addEventListener('dragover', e => {
    e.preventDefault();
    uploadArea.classList.add('dragover');
  });
  uploadArea.addEventListener('dragleave', () => uploadArea.classList.remove('dragover'));
  uploadArea.addEventListener('drop', e => {
    e.preventDefault();
    uploadArea.classList.remove('dragover');
    if (e.dataTransfer.files.length) handleFile(e.dataTransfer.files[0]);
  });
  fileInput.addEventListener('change', e => {
    if (e.target.files.length) handleFile(e.target.files[0]);
  });

  async function handleFile(file) {
    if (!file.type.startsWith('audio/') && !/\.(mp3|wav|ogg|m4a|flac|aac)$/i.test(file.name)) {
      showStatus('Please select a valid audio file.', 'error');
      return;
    }
    hideStatus();
    showStatus('Loading audio file...', 'info');
    try {
      const arrayBuffer = await file.arrayBuffer();
      const ctx = ensureAudioCtx();
      originalBuffer = await ctx.decodeAudioData(arrayBuffer);
      processedBuffer = null;

      fileInfo.classList.add('show');
      fileInfo.innerHTML =
        `<strong>${file.name}</strong> — ` +
        `${(file.size / 1024 / 1024).toFixed(2)} MB, ` +
        `${originalBuffer.duration.toFixed(2)}s, ` +
        `${originalBuffer.sampleRate} Hz, ` +
        `${originalBuffer.numberOfChannels} ch`;

      drawWaveform(originalBuffer);
      playOrigBtn.disabled = false;
      applyBtn.disabled    = false;
      playProcBtn.disabled = true;
      downloadBtn.disabled = true;
      showStatus('Audio loaded. Adjust parameters and click "Apply Echo".', 'success');
    } catch (err) {
      console.error(err);
      showStatus('Failed to decode audio: ' + err.message, 'error');
    }
  }

  // ---------- Waveform Drawing ----------
  function drawWaveform(buffer) {
    const width  = canvas.width;
    const height = canvas.height;
    ctx.clearRect(0, 0, width, height);
    ctx.fillStyle = '#f8f9fa';
    ctx.fillRect(0, 0, width, height);

    const data = buffer.getChannelData(0);
    const step = Math.ceil(data.length / width);
    const amp  = height / 2;

    ctx.strokeStyle = '#667eea';
    ctx.lineWidth   = 1;
    ctx.beginPath();
    for (let i = 0; i < width; i++) {
      let min = 1.0, max = -1.0;
      for (let j = 0; j < step; j++) {
        const v = data[i * step + j] || 0;
        if (v < min) min = v;
        if (v > max) max = v;
      }
      ctx.moveTo(i, (1 + min) * amp);
      ctx.lineTo(i, (1 + max) * amp);
    }
    ctx.stroke();
  }

  // ---------- Playback ----------
  function stopPlayback() {
    if (currentSource) {
      try { currentSource.stop(); } catch (_) {}
      currentSource = null;
    }
    isPlaying = false;
  }

  function playBuffer(buffer, btn) {
    if (!buffer) return;
    stopPlayback();
    const ctx = ensureAudioCtx();
    const src = ctx.createBufferSource();
    src.buffer = buffer;
    src.connect(ctx.destination);
    src.onended = () => {
      isPlaying = false;
      btn.textContent = btn.dataset.label;
    };
    src.start();
    currentSource = src;
    isPlaying = true;
    btn.dataset.label = btn.textContent;
    btn.textContent = '■ Stop';
  }

  playOrigBtn.addEventListener('click', () => {
    if (isPlaying) stopPlayback();
    else playBuffer(originalBuffer, playOrigBtn);
  });
  playProcBtn.addEventListener('click', () => {
    if (isPlaying) stopPlayback();
    else playBuffer(processedBuffer, playProcBtn);
  });

  // ---------- Apply Echo (Offline Rendering) ----------
  applyBtn.addEventListener('click', async () => {
    if (!originalBuffer) return;
    stopPlayback();
    applyBtn.disabled = true;
    showStatus('Rendering echo effect...', 'info');

    const delaySec  = parseFloat(delaySlider.value);
    const feedback  = parseFloat(intSlider.value);
    const wetMix    = parseFloat(mixSlider.value);
    const dryMix    = 1 - wetMix;

    // Extra tail so echoes decay fully
    const tail = Math.max(3, delaySec * 10);
    const length = Math.ceil((originalBuffer.duration + tail) * originalBuffer.sampleRate);

    try {
      const offline = new OfflineAudioContext(
        originalBuffer.numberOfChannels,
        length,
        originalBuffer.sampleRate
      );

      const src = offline.createBufferSource();
      src.buffer = originalBuffer;

      // Dry path
      const dryGain = offline.createGain();
      dryGain.gain.value = dryMix;

      // Wet path: delay + feedback loop
      const delayNode = offline.createDelay(5.0);
      delayNode.delayTime.value = delaySec;

      const fbGain = offline.createGain();
      fbGain.gain.value = feedback;

      const wetGain = offline.createGain();
      wetGain.gain.value = wetMix;

      // Routing
      src.connect(dryGain);
      dryGain.connect(offline.destination);

      src.connect(delayNode);
      delayNode.connect(fbGain);
      fbGain.connect(delayNode);   // feedback loop
      delayNode.connect(wetGain);
      wetGain.connect(offline.destination);

      src.start(0);

      processedBuffer = await offline.startRendering();
      drawWaveform(processedBuffer);
      playProcBtn.disabled = false;
      downloadBtn.disabled = false;
      showStatus('Echo applied! Preview or download the result.', 'success');
    } catch (err) {
      console.error(err);
      showStatus('Render failed: ' + err.message, 'error');
    } finally {
      applyBtn.disabled = false;
    }
  });

  // ---------- WAV Encoding & Download ----------
  function encodeWAV(buffer) {
    const numCh     = buffer.numberOfChannels;
    const sampleRate= buffer.sampleRate;
    const format    = 1; // PCM
    const bitDepth  = 16;
    const channels  = [];
    for (let i = 0; i < numCh; i++) channels.push(buffer.getChannelData(i));

    const numSamples = buffer.length;
    const bytesPerSample = bitDepth / 8;
    const blockAlign = numCh * bytesPerSample;
    const dataSize = numSamples * blockAlign;
    const bufferSize = 44 + dataSize;
    const ab = new ArrayBuffer(bufferSize);
    const view = new DataView(ab);

    const writeStr = (offset, str) => {
      for (let i = 0; i < str.length; i++) view.setUint8(offset + i, str.charCodeAt(i));
    };

    writeStr(0, 'RIFF');
    view.setUint32(4, 36 + dataSize, true);
    writeStr(8, 'WAVE');
    writeStr(12, 'fmt ');
    view.setUint32(16, 16, true);
    view.setUint16(20, format, true);
    view.setUint16(22, numCh, true);
    view.setUint32(24, sampleRate, true);
    view.setUint32(28, sampleRate * blockAlign, true);
    view.setUint16(32, blockAlign, true);
    view.setUint16(34, bitDepth, true);
    writeStr(36, 'data');
    view.setUint32(40, dataSize, true);

    let offset = 44;
    for (let i = 0; i < numSamples; i++) {
      for (let ch = 0; ch < numCh; ch++) {
        let s = Math.max(-1, Math.min(1, channels[ch][i]));
        s = s < 0 ? s * 0x8000 : s * 0x7FFF;
        view.setInt16(offset, s, true);
        offset += 2;
      }
    }
    return new Blob([ab], { type: 'audio/wav' });
  }

  downloadBtn.addEventListener('click', () => {
    if (!processedBuffer) return;
    const blob = encodeWAV(processedBuffer);
    const url  = URL.createObjectURL(blob);
    const a    = document.createElement('a');
    a.href = url;
    a.download = 'echo_output.wav';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    showStatus('Download started.', 'success');
  });
})();
</script>
</body>
</html>
```

## How to Use

1. **Save** the code above as `index.html`.
2. **Open** it in a modern browser (Chrome, Edge, Firefox, Safari).
3. **Upload** an audio file (MP3, WAV, OGG, M4A, FLAC) by clicking or dragging.
4. **Adjust** the three parameters:
   - **Delay Time** (0.01 – 1.0 s): time between echoes.
   - **Echo Intensity** (0 – 90%): feedback amount — higher = more repetitions.
   - **Wet/Dry Mix**: balance between original and echoed signal.
5. Click **✨ Apply Echo** to render the effect (uses `OfflineAudioContext` for sample-accurate output).
6. **Preview** with ▶ Play Original / ▶ Play Processed.
7. Click **⬇ Download WAV** to save the processed audio.

## Technical Highlights

- **Pure front-end** — no server, no dependencies, no build step.
- **Web Audio API** graph: `Source → Delay → Feedback Gain → Delay (loop) → Wet Gain → Destination`, mixed with a dry path.
- **OfflineAudioContext** renders the full processed buffer (including a decay tail) so the downloaded file contains the complete echo.
- **Custom WAV encoder** (16-bit PCM, proper RIFF headers) since browsers don't natively export audio.
- **Waveform visualization** drawn on `<canvas>` for both original and processed audio.
- **Drag-and-drop** upload with file validation and friendly status messages.

