      Shortcuts: <span class="kbd">Space</span> play/pause · <span class="kbd">←/→</span> ±5s · <span class="kbd">↑/↓</span> offset ±50ms
    </div>
  </section>

  <!-- RIGHT: Stage -->
  <section class="panel">
    <h2>Live Lyrics</h2>
    <div class="stage">
      <div class="lyrics-viewport">
        <div class="lyrics-track" id="track">
          <div class="empty">Load an audio file and an LRC file to begin.</div>
        </div>
