<div class="toast" id="toast"></div>

<script>
/* =========================================================
   Karaoke Sync Engine
   ========================================================= */
const $ = (s)=>document.querySelector(s);
const audio = $('#audio');
const track = $('#track');
const progressBar = $('#progressBar');
const offsetVal = $('#offsetVal');
const toastEl = $('#toast');

let state = {
  lines: [],          // [{time, text, words:[{time,text}]}]
  meta: {},           // {ti, ar, al, offset}
  offset: 0,          // user offset in ms
  fileOffset: 0,      // offset tag from LRC
  activeIndex: -1,
  resyncMode: false,
  resyncIndex: 0,
  lrcFilename: 'lyrics.lrc',
};

/* ---------- Toast ---------- */
let toastTimer;
function toast(msg){
  toastEl.textContent = msg;
  toastEl.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(()=>toastEl.classList.remove('show'), 1800);
}

/* ---------- File drop wiring ---------- */
function wireDrop(dropEl, inputEl, handler){
  dropEl.addEventListener('click', ()=>inputEl.click());
  ['dragenter','dragover'].forEach(ev=>dropEl.addEventListener(ev,e=>{
    e.preventDefault(); dropEl.classList.add('drag');
  }));
  ['dragleave','drop'].forEach(ev=>dropEl.addEventListener(ev,e=>{
    e.preventDefault(); dropEl.classList.remove('drag');
  }));
  dropEl.addEventListener('drop', e=>{
    const f = e.dataTransfer.files[0]; if(f) handler(f);
  });
  inputEl.addEventListener('change', e=>{
    const f = e.target.files[0]; if(f) handler(f);
  });
}

wireDrop($('#audioDrop'), $('#audioInput'), loadAudio);
wireDrop($('#lrcDrop'),   $('#lrcInput'),   loadLRC);

/* ---------- Audio ---------- */
function loadAudio(file){
  const url = URL.createObjectURL(file);
  audio.src = url;
  $('#audioMeta').innerHTML = `<b>File:</b> ${file.name}<br><b>Size:</b> ${(file.size/1024/1024).toFixed(2)} MB`;
  toast('Audio loaded');
}

/* ---------- LRC Parser ----------
   Supports:
     [mm:ss.xx] text
     [mm:ss.xx] word1<mm:ss.xx> word2<mm:ss.xx> word3   (enhanced)
     ID tags: [ti:...] [ar:...] [al:...] [offset:...]
----------------------------------- */
function parseLRC(text){
  const lines = text.split(/\r?\n/);
  const meta = {};
  const out = [];
  const lineRe = /\[(\d{1,3}):(\d{2})(?:[.:](\d{1,3}))?\]/g;
  const wordRe = /<(\d{1,3}):(\d{2})(?:[.:](\d{1,3}))?>/g;

  const toSec = (m,s,ms)=> Number(m)*60 + Number(s) + (Number(ms||0) / ( (ms||'').length===3?1000:100 ));

  for(const raw of lines){
    // ID tags
    const id = raw.match(/^\s*\[([a-zA-Z#]+):(.*)\]\s*$/);
    if(id && !/\d{1,3}:\d{2}/.test(raw)){
      meta[id[1].toLowerCase()] = id[2].trim();
      continue;
    }
    // Find all timestamps in line
    const stamps = [];
    let m; lineRe.lastIndex=0;
    while((m = lineRe.exec(raw)) !== null){
      stamps.push({ t: toSec(m[1],m[2],m[3]), idx: m.index, len: m[0].length });
    }
    if(!stamps.length) continue;

    // Text after last timestamp
    const last = stamps[stamps.length-1];
    let textPart = raw.slice(last.idx + last.len);

    // Parse word-level timestamps inside textPart
    const words = [];
    let wLast = 0, wMatch; wordRe.lastIndex=0;
    const wStamps = [];
    while((wMatch = wordRe.exec(textPart)) !== null){
      wStamps.push({ t: toSec(wMatch[1],wMatch[2],wMatch[3]), idx: wMatch.index, len: wMatch[0].length });
    }
    if(wStamps.length){
      // Text before first word-stamp belongs to the line start
      const pre = textPart.slice(0, wStamps[0].idx);
      if(pre.trim()) words.push({ time: last.t, text: pre });
      for(let i=0;i<wStamps.length;i++){
        const ws = wStamps[i];
        const next = wStamps[i+1];
        const seg = textPart.slice(ws.idx + ws.len, next ? next.idx : textPart.length);
        if(seg.length) words.push({ time: ws.t, text: seg });
      }
    }

    const plainText = textPart.replace(wordRe,'').trim();
    // Each timestamp prefix creates a line (for multi-time tags)
    for(const s of stamps){
      out.push({
        time: s.t,
        text: plainText,
        words: words.length ? words.map(w=>({ time: w.time - last.t + s.t, text: w.text })) : null
      });
    }
  }
  out.sort((a,b)=>a.time-b.time);
  return { meta, lines: out };
}

function loadLRC(file){
  const reader = new FileReader();
  reader.onload = e=>{
    const { meta, lines } = parseLRC(e.target.result);
    state.meta = meta;
    state.lines = lines;
    state.fileOffset = Number(meta.offset||0);
    state.offset = 0;
    state.activeIndex = -1;
    state.lrcFilename = file.name.replace(/\.[^.]+$/,'') + '.lrc';
    renderLines();
    updateOffsetUI();
    $('#lrcMeta').innerHTML =
      `<b>Title:</b> ${meta.ti||'—'}<br>`+
      `<b>Artist:</b> ${meta.ar||'—'}<br>`+
      `<b>Album:</b> ${meta.al||'—'}<br>`+
      `<b>Lines:</b> ${lines.length} · <b>File offset:</b> ${state.fileOffset} ms`;
    toast(`Loaded ${lines.length} lyric lines`);
  };
  reader.readAsText(file, 'utf-8');
}

/* ---------- Render ---------- */
function renderLines(){
  track.innerHTML = '';
  if(!state.lines.length){
    track.innerHTML = '<div class="empty">No lyrics loaded.</div>';
    return;
  }
  state.lines.forEach((ln,i)=>{
    const div = document.createElement('div');
    div.className = 'line';
    div.dataset.index = i;
    if(ln.words && ln.words.length){
      ln.words.forEach((w,wi)=>{
        const span = document.createElement('span');
        span.className = 'word';
        span.dataset.wi = wi;
        const fill = document.createElement('span');
        fill.className = 'fill';
        fill.textContent = w.text;
        span.appendChild(fill);
        span.appendChild(document.createTextNode(w.text));
        div.appendChild(span);
      });
    } else {
      div.textContent = ln.text || '♪';
    }
    track.appendChild(div);
  });
}

/* ---------- Sync loop ---------- */
function currentOffsetSec(){
  return (state.offset + state.fileOffset) / 1000;
}

function updateSync(){
  if(!audio.duration) return;
  const t = audio.currentTime + currentOffsetSec();
  // progress
  progressBar.style.width = (audio.currentTime / audio.duration * 100).toFixed(2) + '%';

  // find active line
  let idx = -1;
  for(let i=0;i<state.lines.length;i++){
    if(state.lines[i].time <= t) idx = i; else break;
  }
  if(idx !== state.activeIndex){
    state.activeIndex = idx;
    const nodes = track.querySelectorAll('.line');
    nodes.forEach((n,i)=>{
      n.classList.remove('active','past');
      if(i < idx) n.classList.add('past');
      else if(i === idx) n.classList.add('active');
    });
    // scroll
    if(idx >= 0 && nodes[idx]){
      const vp = track.parentElement;
      const nodeTop = nodes[idx].offsetTop;
      const target = -nodeTop; // center via translateY (track top is 50%)
      track.style.transform = `translateY(${target}px)`;
    }
  }
  // word-level fill
  if(idx >= 0){
    const line = state.lines[idx];
    const nextTime = state.lines[idx+1] ? state.lines[idx+1].time : (line.time + 5);
    const lineDur = Math.max(0.1, nextTime - line.time);
    const lineProgress = Math.min(1, Math.max(0, (t - line.time) / lineDur));
    const activeNode = track.querySelector('.line.active');
    if(activeNode){
      if(line.words && line.words.length){
        const wordNodes = activeNode.querySelectorAll('.word');
        line.words.forEach((w,wi)=>{
          const wn = wordNodes[wi]; if(!wn) return;
          const wStart = w.time - line.time;
          const wEnd = (line.words[wi+1] ? line.words[wi+1].time : nextTime) - line.time;
          const wDur = Math.max(0.05, wEnd - wStart);
          const localT = t - line.time;
          let pct = 0;
          if(localT >= wEnd) pct = 100;
          else if(localT > wStart) pct = ((localT - wStart)/wDur)*100;
          wn.querySelector('.fill').style.width = pct.toFixed(1)+'%';
          wn.classList.toggle('done', pct >= 99.5);
        });
      } else {
        // character-level fallback: wrap chars once
        if(!activeNode.dataset.split){
          const chars = (line.text||'♪').split('');
          activeNode.innerHTML = '';
          chars.forEach(ch=>{
            const s = document.createElement('span');
            s.className = 'word';
            const f = document.createElement('span');
            f.className = 'fill'; f.textContent = ch;
            s.appendChild(f);
            s.appendChild(document.createTextNode(ch));
            activeNode.appendChild(s);
          });
          activeNode.dataset.split = '1';
        }
        const wordNodes = activeNode.querySelectorAll('.word');
        const n = wordNodes.length;
        wordNodes.forEach((wn,i)=>{
          const startP = i/n, endP = (i+1)/n;
          let pct = 0;
          if(lineProgress >= endP) pct = 100;
          else if(lineProgress > startP) pct = ((lineProgress-startP)/(endP-startP))*100;
          wn.querySelector('.fill').style.width = pct.toFixed(1)+'%';
          wn.classList.toggle('done', pct >= 99.5);
        });
      }
    }
  }
}

audio.addEventListener('timeupdate', updateSync);
audio.addEventListener('seeked', ()=>{
  // force re-render of active line chars
  const a = track.querySelector('.line.active'); if(a) delete a.dataset.split;
  state.activeIndex = -2; updateSync();
});

/* ---------- Offset controls ---------- */
document.querySelectorAll('button[data-delta]').forEach(b=>{
  b.addEventListener('click', ()=>{
    state.offset += Number(b.dataset.delta);
    updateOffsetUI(); updateSync();
  });
});
$('#resetOffset').addEventListener('click', ()=>{
  state.offset = 0; updateOffsetUI(); updateSync();
});
function updateOffsetUI(){
  const total = state.offset + state.fileOffset;
  offsetVal.textContent = (total>=0?'+':'') + total + ' ms';
}

/* ---------- Manual re-sync ----------
   Press the resync button, then press SPACE at the moment
   each line should start. Advances line by line.
----------------------------------- */
$('#resyncBtn').addEventListener('click', ()=>{
  if(!state.lines.length) return toast('Load lyrics first');
  state.resyncMode = !state.resyncMode;
  state.resyncIndex = 0;
  $('#resyncBtn').textContent = state.resyncMode ? '■ Stop re-sync' : 'Manual re-sync';
  if(state.resyncMode){
    audio.pause(); audio.currentTime = 0;
    toast('Re-sync: press SPACE when each line is sung');
    highlightResyncLine();
  }
});
function highlightResyncLine(){
  const nodes = track.querySelectorAll('.line');
  nodes.forEach(n=>n.style.outline='');
  if(state.resyncIndex < nodes.length){
    nodes[state.resyncIndex].style.outline = '2px solid var(--accent2)';
    nodes[state.resyncIndex].scrollIntoView({block:'center',behavior:'smooth'});
  }
}
function stampResync(){
  if(!state.resyncMode) return;
  if(state.resyncIndex >= state.lines.length){
    state.resyncMode = false;
    $('#resyncBtn').textContent = 'Manual re-sync';
    toast('Re-sync complete — export your LRC');
    return;
  }
  state.lines[state.resyncIndex].time = audio.currentTime;
  state.resyncIndex++;
  highlightResyncLine();
}

/* ---------- Export ---------- */
function fmtTime(sec){
  if(sec < 0) sec = 0;
  const m = Math.floor(sec/60);
  const s = Math.floor(sec%60);
  const cs = Math.floor((sec - Math.floor(sec))*100);
  return `[${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}.${String(cs).padStart(2,'0')}]`;
}
function buildLRC(){
  const out = [];
  if(state.meta.ti) out.push(`[ti:${state.meta.ti}]`);
  if(state.meta.ar) out.push(`[ar:${state.meta.ar}]`);
  if(state.meta.al) out.push(`[al:${state.meta.al}]`);
  // Bake offset into file offset tag
  const totalOffset = state.offset + state.fileOffset;
  out.push(`[offset:${totalOffset}]`);
  out.push('');
  for(const ln of state.lines){
    let text = ln.text;
    if(ln.words && ln.words.length){
      text = ln.words.map(w => `<${fmtTime(w.time).slice(1,-1)}>${w.text}`).join('');
      // strip leading bracket artifact: we want <mm:ss.xx>word
      text = ln.words.map(w => {
        const t = w.time;
        const m = Math.floor(t/60), s=Math.floor(t%60), cs=Math.floor((t-Math.floor(t))*100);
        return `<${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}.${String(cs).padStart(2,'0')}>${w.text}`;
      }).join('');
    }
    out.push(`${fmtTime(ln.time)}${text}`);
  }
  return out.join('\n');
}
$('#exportBtn').addEventListener('click', ()=>{
  if(!state.lines.length) return toast('Nothing to export');
  const blob = new Blob([buildLRC()], {type:'text/plain;charset=utf-8'});
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = state.lrcFilename;
  a.click();
  URL.revokeObjectURL(a.href);
  toast('LRC exported');
});

/* ---------- Keyboard ---------- */
document.addEventListener('keydown', e=>{
  if(e.target.tagName === 'INPUT') return;
  if(e.code === 'Space'){
    e.preventDefault();
    if(state.resyncMode) stampResync();
    else audio.paused ? audio.play() : audio.pause();
  } else if(e.code === 'ArrowLeft'){
    audio.currentTime = Math.max(0, audio.currentTime - 5);
  } else if(e.code === 'ArrowRight'){
    audio.currentTime = Math.min(audio.duration||0, audio.currentTime + 5);
  } else if(e.code === 'ArrowUp'){
    e.preventDefault(); state.offset += 50; updateOffsetUI(); updateSync();
  } else if(e.code === 'ArrowDown'){
    e.preventDefault(); state.offset -= 50; updateOffsetUI(); updateSync();
  }
});

/* ---------- Demo LRC (optional auto-load for quick preview) ---------- */
const DEMO_LRC =
`[ti:Demo Song]
