                        const n = Math.floor(sides);
                        const area = (n * sideLength * sideLength) / (4 * Math.tan(Math.PI / n));
                        const perimeter = n * sideLength;
                        const apothem = sideLength / (2 * Math.tan(Math.PI / n));
                        return {
