<script>
(() => {
  // ---------- Audio engine (Web Audio API for sample-accurate scheduling) ----------
  let audioCtx = null;
  const ensureCtx = () => {
    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    if (audioCtx.state === 'suspended') audioCtx.resume();
    return audioCtx;
  };

  // Short percussive beep. `accent` boosts pitch/volume for downbeats.
  function playBeep(time, accent = false) {
    const ctx = audioCtx;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.value = accent ? 1200 : 800;
    gain.gain.setValueAtTime(0.0001, time);
    gain.gain.exponentialRampToValueAtTime(accent ? 0.6 : 0.35, time + 0.005);
    gain.gain.exponentialRampToValueAtTime(0.0001, time + 0.08);
    osc.connect(gain).connect(ctx.destination);
    osc.start(time);
    osc.stop(time + 0.1);
  }

  // ---------- State ----------
  const state = {
    mode: null,           // 'listen' | 'practice'
    scheduledBeats: [],   // { time (audioCtx seconds), index }
    userTaps: [],         // audioCtx seconds
    timers: [],           // setTimeout ids for UI updates
    running: false,
  };

  // ---------- DOM ----------
  const $ = id => document.getElementById(id);
  const bpmInput = $('bpm'), bpmVal = $('bpmVal');
  const beatsInput = $('beats'), countinInput = $('countin');
  const listenBtn = $('listenBtn'), practiceBtn = $('practiceBtn'), stopBtn = $('stopBtn');
  const pad = $('pad'), dots = $('dots');
  const resultsPanel = $('resultsPanel'), scoreBig = $('scoreBig'), grade = $('grade'), resultsBody = $('resultsBody');

  bpmInput.addEventListener('input', () => bpmVal.textContent = bpmInput.value);

  // ---------- Build dot indicators ----------
  function buildDots(n) {
    dots.innerHTML = '';
    for (let i = 0; i < n; i++) {
      const d = document.createElement('div');
      d.className = 'dot';
      d.textContent = i + 1;
      dots.appendChild(d);
    }
  }

  // ---------- Schedule a run ----------
  function scheduleRun(mode) {
    stop();
    const ctx = ensureCtx();
    const bpm = parseInt(bpmInput.value, 10);
    const beatCount = Math.max(4, Math.min(32, parseInt(beatsInput.value, 10) || 8));
    const countIn = Math.max(0, Math.min(4, parseInt(countinInput.value, 10) || 0));
    const interval = 60 / bpm;

    state.mode = mode;
    state.running = true;
    state.scheduledBeats = [];
    state.userTaps = [];
    buildDots(beatCount);
    resultsPanel.style.display = 'none';
    pad.disabled = mode !== 'practice';

    // Start slightly in the future to avoid clicks from scheduling latency
    const startTime = ctx.currentTime + 0.15;

    // Count-in (silent or accented beeps, not scored)
    for (let i = 0; i < countIn; i++) {
      playBeep(startTime + i * interval, i === 0);
    }

    // Main beats
    const firstBeatTime = startTime + countIn * interval;
    for (let i = 0; i < beatCount; i++) {
      const t = firstBeatTime + i * interval;
      state.scheduledBeats.push({ time: t, index: i });
      if (mode === 'listen') playBeep(t, i === 0);
      else playBeep(t, false); // quiet reference click during practice too (optional: remove for "silent" practice)

      // UI pulse scheduled via setTimeout relative to now
      const delayMs = (t - ctx.currentTime) * 1000;
      state.timers.push(setTimeout(() => pulseDot(i), Math.max(0, delayMs)));
    }

    // End-of-run scoring
    const endTime = firstBeatTime + beatCount * interval + 0.3;
    const endDelay = (endTime - ctx.currentTime) * 1000;
    state.timers.push(setTimeout(() => finishRun(), Math.max(0, endDelay)));
  }

  function pulseDot(i) {
    const dotEls = dots.children;
    if (!dotEls[i]) return;
    dotEls[i].classList.add('active');
    setTimeout(() => dotEls[i].classList.remove('active'), 140);
  }

  // ---------- Tap handling ----------
  function handleTap() {
    if (!state.running || state.mode !== 'practice') return;
    const ctx = ensureCtx();
    const t = ctx.currentTime;
    state.userTaps.push(t);

    // Visual + audio feedback
    pad.classList.add('pressed');
    setTimeout(() => pad.classList.remove('pressed'), 80);
    playBeep(t, false);
  }

  pad.addEventListener('pointerdown', e => { e.preventDefault(); handleTap(); });
  window.addEventListener('keydown', e => {
    if (e.code === 'Space' && !e.repeat) { e.preventDefault(); handleTap(); }
  });

  // ---------- Scoring ----------
  // For each expected beat, find the closest user tap within a tolerance window.
  // Each tap can only match one beat (greedy nearest, processed in order).
  function scoreRun() {
    const tolerance = 0.25; // seconds; beyond this = miss
    const taps = state.userTaps.slice().sort((a, b) => a - b);
    const used = new Array(taps.length).fill(false);
    const results = [];

    for (const beat of state.scheduledBeats) {
      let bestIdx = -1, bestDelta = Infinity;
      for (let i = 0; i < taps.length; i++) {
        if (used[i]) continue;
        const d = Math.abs(taps[i] - beat.time);
        if (d < bestDelta) { bestDelta = d; bestIdx = i; }
      }
      let rating, deltaMs;
      if (bestIdx === -1 || bestDelta > tolerance) {
        rating = 'miss'; deltaMs = null;
      } else {
        used[bestIdx] = true;
        deltaMs = Math.round((taps[bestIdx] - beat.time) * 1000);
        const abs = Math.abs(deltaMs);
        if (abs <= 30) rating = 'perfect';
        else if (abs <= 60) rating = 'good';
        else if (abs <= 110) rating = 'ok';
        else rating = 'miss';
      }
      results.push({ index: beat.index, expected: beat.time, actual: bestIdx >= 0 && used[bestIdx] ? taps[bestIdx] : null, deltaMs, rating });
    }

    // Overall score: perfect=100, good=80, ok=50, miss=0, averaged
    const weights = { perfect: 100, good: 75, ok: 45, miss: 0 };
    const total = results.reduce((s, r) => s + weights[r.rating], 0);
    const score = Math.round(total / results.length);

    let g = 'D';
    if (score >= 95) g = 'S — Perfect';
    else if (score >= 85) g = 'A — Excellent';
    else if (score >= 70) g = 'B — Good';
    else if (score >= 50) g = 'C — Needs work';
    else g = 'D — Keep practicing';

    return { results, score, grade: g };
  }

  function renderResults({ results, score, grade: g }) {
    resultsPanel.style.display = 'block';
    scoreBig.textContent = score;
    grade.textContent = g;
    resultsBody.innerHTML = '';
    const t0 = state.scheduledBeats[0]?.time ?? 0;
    const fmt = t => (t == null ? '—' : ((t - t0).toFixed(3) + 's'));
    results.forEach(r => {
      // Update dot color
      const dot = dots.children[r.index];
      if (dot) dot.classList.add(r.rating);

      const tr = document.createElement('tr');
      tr.innerHTML = `
        <td>#${r.index + 1}</td>
        <td>${fmt(r.expected)}</td>
        <td>${fmt(r.actual)}</td>
        <td>${r.deltaMs == null ? '—' : (r.deltaMs > 0 ? '+' : '') + r.deltaMs + ' ms'}</td>
        <td><span class="tag ${r.rating}">${r.rating.toUpperCase()}</span></td>
      `;
      resultsBody.appendChild(tr);
    });
  }

  function finishRun() {
    if (!state.running) return;
    if (state.mode === 'practice') {
      renderResults(scoreRun());
    }
    state.running = false;
    pad.disabled = true;
  }

  function stop() {
    state.running = false;
    state.timers.forEach(clearTimeout);
    state.timers = [];
    pad.disabled = true;
  }

  // ---------- Button wiring ----------
  listenBtn.addEventListener('click', () => scheduleRun('listen'));
  practiceBtn.addEventListener('click', () => scheduleRun('practice'));
  stopBtn.addEventListener('click', stop);
})();
</script>
</body>
</html>
```

## How the Scoring Works

| Component | Detail |
|---|---|
| **Timing reference** | `audioContext.currentTime` — the same clock that schedules the beeps, so measurement and playback share zero drift. |
| **Matching** | For each expected beat, the nearest unused tap within a 250 ms window is paired (greedy nearest-neighbor). |
| **Per-beat rating** | Perfect ≤ 30 ms · Good ≤ 60 ms · OK ≤ 110 ms · Miss > 110 ms or no tap |
| **Overall score** | Weighted average: Perfect = 100, Good = 75, OK = 45, Miss = 0 |
| **Grade** | S (≥95) · A (≥85) · B (≥70) · C (≥50) · D (<50) |

## Suggested Practice Progression
1. Start at **60 BPM, 8 beats** — focus on consistency.
2. Move to **90 BPM** — typical pop tempo.
3. Try **120–140 BPM** — tests fine motor timing.
4. Set **Count-in = 0** to train internal pulse without a lead-in.
5. For advanced training, edit the `playBeep` call inside `scheduleRun` (the `else` branch) to silence the reference during practice — pure internal-timing mode.

