    def upload(self, local_path: Path, remote_name: str) -> bool: pass

    @abstractmethod
    def download(self, remote_name: str, local_path: Path) -> bool: pass

    @abstractmethod
    def list_backups(self) -> List[str]: pass

    @abstractmethod
    def delete(self, remote_name: str) -> bool: pass

class LocalStorage(StorageBackend):
    def __init__(self, base_dir: str):
        self.base_dir = Path(base_dir)
        self.base_dir.mkdir(parents=True, exist_ok=True)

    def upload(self, local_path: Path, remote_name: str) -> bool:
        try:
            shutil.copy2(local_path, self.base_dir / remote_name)
            return True
        except Exception as e:
            logging.error(f"Local upload failed: {e}")
            return False

    def download(self, remote_name: str, local_path: Path) -> bool:
        try:
            shutil.copy2(self.base_dir / remote_name, local_path)
            return True
        except Exception as e:
            logging.error(f"Local download failed: {e}")
            return False

    def list_backups(self) -> List[str]:
        return sorted([f.name for f in self.base_dir.glob("backup_*.zip")])

    def delete(self, remote_name: str) -> bool:
        try:
            (self.base_dir / remote_name).unlink()
            return True
        except Exception as e:
            logging.error(f"Local delete failed: {e}")
            return False

class S3Storage(StorageBackend):
    def __init__(self, bucket: str, prefix: str = ""):
        if not BOTO3_AVAILABLE:
            raise ImportError("boto3 is required for S3. Install via `pip install boto3`.")
        self.bucket = bucket
        self.prefix = prefix
        # Uses AWS CLI credentials or Environment Variables automatically
        self.s3 = boto3.client('s3') 

    def _get_key(self, name: str) -> str:
        return f"{self.prefix}/{name}" if self.prefix else name

    def upload(self, local_path: Path, remote_name: str) -> bool:
        try:
            self.s3.upload_file(str(local_path), self.bucket, self._get_key(remote_name))
            return True
        except Exception as e:
            logging.error(f"S3 upload failed: {e}")
            return False

    def download(self, remote_name: str, local_path: Path) -> bool:
        try:
            self.s3.download_file(self.bucket, self._get_key(remote_name), str(local_path))
            return True
        except Exception as e:
            logging.error(f"S3 download failed: {e}")
            return False

    def list_backups(self) -> List[str]:
        try:
            response = self.s3.list_objects_v2(Bucket=self.bucket, Prefix=self.prefix)
            if 'Contents' not in response:
                return []
            return sorted([obj['Key'].split('/')[-1] for obj in response['Contents'] if obj['Key'].endswith('.zip')])
        except Exception as e:
            logging.error(f"S3 list failed: {e}")
            return []

    def delete(self, remote_name: str) -> bool:
        try:
            self.s3.delete_object(Bucket=self.bucket, Key=self._get_key(remote_name))
            return True
        except Exception as e:
            logging.error(f"S3 delete failed: {e}")
            return False

# ==========================================
# Core Backup Engine
# ==========================================
class BackupManager:
    def __init__(self, config_path: str = "backup_config.json"):
        self.config_path = Path(config_path)
        self.config = self._load_config()
        self.storage = self._init_storage()
        self.temp_dir = Path(".backup_temp")
        self.temp_dir.mkdir(exist_ok=True)

    def _load_config(self) -> Dict[str, Any]:
        default_config = {
            "sources": [],
            "storage": {"type": "local", "local_dir": "./backups"},
            "schedule": "daily",  # Options: hourly, daily, or "HH:MM"
            "max_versions": 5
        }
        if self.config_path.exists():
            with open(self.config_path, 'r', encoding='utf-8') as f:
                loaded = json.load(f)
                default_config.update(loaded)
        else:
            self._save_config(default_config)
        return default_config

    def _save_config(self, config: Dict[str, Any] = None):
        if config is None: config = self.config
        with open(self.config_path, 'w', encoding='utf-8') as f:
            json.dump(config, f, indent=4)

    def _init_storage(self) -> StorageBackend:
        stype = self.config["storage"]["type"]
        if stype == "local":
            return LocalStorage(self.config["storage"]["local_dir"])
        elif stype == "s3":
            return S3Storage(
                bucket=self.config["storage"]["bucket"],
                prefix=self.config["storage"].get("prefix", "")
            )
        raise ValueError(f"Unsupported storage type: {stype}")

    def add_source(self, path: str):
        p = str(Path(path).resolve())
        if p not in self.config["sources"]:
            self.config["sources"].append(p)
            self._save_config()
            logging.info(f"Added source: {p}")

    def remove_source(self, path: str):
        p = str(Path(path).resolve())
        if p in self.config["sources"]:
            self.config["sources"].remove(p)
            self._save_config()
            logging.info(f"Removed source: {p}")

    def create_backup(self):
        if not self.config["sources"]:
            logging.warning("No sources configured. Skipping backup.")
            return

        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        backup_name = f"backup_{timestamp}.zip"
        temp_zip = self.temp_dir / backup_name

        logging.info(f"Starting backup: {backup_name}")
        try:
            with zipfile.ZipFile(temp_zip, 'w', zipfile.ZIP_DEFLATED) as zf:
                for source in self.config["sources"]:
                    source_path = Path(source)
                    if not source_path.exists():
                        logging.warning(f"Source not found, skipping: {source}")
                        continue

                    if source_path.is_file():
                        zf.write(source_path, arcname=source_path.name)
                    else:
                        for file in source_path.rglob('*'):
                            if file.is_file():
                                # Preserve folder structure
                                arcname = file.relative_to(source_path.parent)
                                zf.write(file, arcname=arcname)

            logging.info("Compression completed. Uploading...")
            if self.storage.upload(temp_zip, backup_name):
                logging.info("Upload successful.")
                self._cleanup_old_versions()
            else:
                logging.error("Upload failed.")

        except Exception as e:
            logging.error(f"Backup process failed: {e}")
        finally:
            if temp_zip.exists():
                temp_zip.unlink()

    def _cleanup_old_versions(self):
        max_v = self.config.get("max_versions", 5)
        versions = self.storage.list_backups()
        if len(versions) > max_v:
            to_delete = versions[:-max_v]
            for v in to_delete:
                logging.info(f"Deleting old version: {v}")
                self.storage.delete(v)

    def list_versions(self):
        versions = self.storage.list_backups()
        if not versions:
            logging.info("No backups found.")
            return
        click.echo("Available backups:")
        for i, v in enumerate(versions):
            click.echo(f"[{i}] {v}")

    def restore(self, version_index: int, target_dir: str):
        versions = self.storage.list_backups()
        if not versions or version_index >= len(versions) or version_index < 0:
            logging.error("Invalid version index.")
            return

        backup_name = versions[version_index]
        target_path = Path(target_dir)
        target_path.mkdir(parents=True, exist_ok=True)
        temp_zip = self.temp_dir / backup_name

        logging.info(f"Downloading {backup_name}...")
        if self.storage.download(backup_name, temp_zip):
            logging.info(f"Extracting to {target_path}...")
            try:
                with zipfile.ZipFile(temp_zip, 'r') as zf:
                    zf.extractall(target_path)
                logging.info("Restore completed successfully.")
            except Exception as e:
                logging.error(f"Extraction failed: {e}")
            finally:
                if temp_zip.exists():
                    temp_zip.unlink()

    def start_scheduler(self):
        sched = self.config.get("schedule", "daily")
        if sched == "hourly":
            schedule.every().hour.do(self.create_backup)
        elif sched == "daily":
            schedule.every().day.at("02:00").do(self.create_backup)
        else:
            schedule.every().day.at(sched).do(self.create_backup)

        logging.info(f"Scheduler started. Running {sched}. Press Ctrl+C to exit.")
        while True:
            schedule.run_pending()
            time.sleep(60)

# ==========================================
# CLI Interface
# ==========================================
@click.group()
def cli():
    """Auto Backup Tool with Version Management"""
    pass

@cli.command()
@click.argument('path', type=click.Path(exists=True))
def add(path):
    """Add a file or directory to backup sources."""
    mgr = BackupManager()
    mgr.add_source(path)

@cli.command()
@click.argument('path', type=click.Path())
def remove(path):
    """Remove a source from backup list."""
    mgr = BackupManager()
    mgr.remove_source(str(Path(path).resolve()))

@cli.command()
def backup():
    """Trigger a manual backup immediately."""
    mgr = BackupManager()
    mgr.create_backup()

@cli.command(name="list")
def list_versions():
    """List all available backup versions."""
    mgr = BackupManager()
    mgr.list_versions()

@cli.command()
@click.argument('index', type=int)
@click.argument('target', type=click.Path())
def restore(index, target):
    """Restore a specific backup version by index to target directory."""
    mgr = BackupManager()
    mgr.restore(index, target)

@cli.command()
def start():
    """Start the background scheduler for automatic backups."""
    mgr = BackupManager()
    mgr.start_scheduler()

@cli.command()
@click.option('--type', type=click.Choice(['local', 's3']), default='local', help="Storage type")
@click.option('--dir', default='./backups', help="Local directory for local storage")
@click.option('--bucket', help="S3 bucket name")
@click.option('--schedule', default='daily', help="Schedule: hourly, daily, or HH:MM")
@click.option('--versions', default=5, help="Max versions to keep")
def config(type, dir, bucket, schedule, versions):
    """Configure backup settings."""
    mgr = BackupManager()
    mgr.config["storage"]["type"] = type
    if type == 'local':
        mgr.config["storage"]["local_dir"] = dir
    elif type == 's3':
        if not bucket:
            click.echo("Bucket name is required for S3.")
            return
        mgr.config["storage"]["bucket"] = bucket
    mgr.config["schedule"] = schedule
    mgr.config["max_versions"] = versions
    mgr._save_config()
    mgr.storage = mgr._init_storage() 
    click.echo("Configuration updated successfully.")

if __name__ == '__main__':
    cli()
```

### 3. Usage Guide

#### Step 1: Configure the Tool
Set up your storage destination, retention policy, and schedule.
```bash
# Configure Local Storage, keep 3 versions, run daily at 02:00 AM
python backup_tool.py config --type local --dir ./my_secure_backups --versions 3 --schedule daily

# OR Configure Cloud Storage (AWS S3)
python backup_tool.py config --type s3 --bucket my-company-backups --schedule "14:30"
```
*(Note: For S3, ensure your AWS credentials are configured via `aws configure` or environment variables).*

#### Step 2: Select Data to Backup
Add the folders or files you want to protect (e.g., Notes, Task Lists, Code).
```bash
python backup_tool.py add ~/Documents/MyNotes
python backup_tool.py add ~/Projects/TaskList.json
```

#### Step 3: Run Backups
**Manual Backup:**
```bash
python backup_tool.py backup
```
**Automatic Background Backup:**
```bash
python backup_tool.py start
```
*(You can run this inside a `tmux`/`screen` session, or set it up as a Systemd service / Windows Task Scheduler task).*

#### Step 4: Version Management & Recovery
**View available versions:**
```bash
python backup_tool.py list
# Output:
# [0] backup_20231024_020000.zip
# [1] backup_20231025_020000.zip
```
**Restore a specific version:**
```bash
# Restore version index [1] to a new recovery folder
python backup_tool.py restore 1 ./recovered_data
```

### Architecture Highlights
1. **Strategy Pattern for Storage**: Easily switch between Local and S3 storage without changing the core backup logic. Extensible to Google Drive/Dropbox by adding new classes.
2. **Atomic Versioning**: Backups are compressed into `.zip` archives with timestamps. This guarantees that a backup is either fully successful or fails cleanly without corrupting existing versions.
3. **Automated Retention Policy**: Automatically deletes the oldest backups based on the `max_versions` configuration to prevent storage overflow.
4. **Directory Structure Preservation**: Uses `pathlib` and relative archiving to ensure that when you restore data, your folder hierarchies remain perfectly intact.

