        shipGroup.add(engineGlow);

        // Engine light
        const engineLight = new THREE.PointLight(0x00aaff, 2, 10);
        engineLight.position.set(0, 0, 2);
        shipGroup.add(engineLight);

        // Shield bubble (invisible until hit)
        const shieldGeom = new THREE.SphereGeometry(3, 32, 32);
        const shieldMat = new THREE.MeshPhongMaterial({
            color: 0x00ffff,
            emissive: 0x004444,
            transparent: true,
            opacity: 0,
            side: THREE.DoubleSide,
            wireframe: true
        });
        shieldMesh = new THREE.Mesh(shieldGeom, shieldMat);
        shipGroup.add(shieldMesh);

        shipGroup.position.set(0, 0, 0);
        scene.add(shipGroup);
        spaceship = shipGroup;
    }

    // ============ ASTEROID CREATION ============
    function createAsteroid(position) {
        const size = 1 + Math.random() * 3;
        const geometry = new THREE.IcosahedronGeometry(size, 1);

        // Deform vertices for rocky look
        const positions = geometry.attributes.position;
        for (let i = 0; i < positions.count; i++) {
            const x = positions.getX(i);
            const y = positions.getY(i);
            const z = positions.getZ(i);
            const offset = 0.7 + Math.random() * 0.6;
            positions.setXYZ(i, x * offset, y * offset, z * offset);
        }
        geometry.computeVertexNormals();

        const hue = 0.05 + Math.random() * 0.1;
        const material = new THREE.MeshPhongMaterial({
            color: new THREE.Color().setHSL(hue, 0.3, 0.3),
            emissive: new THREE.Color().setHSL(hue, 0.2, 0.05),
            flatShading: true,
            shininess: 10
        });

        const asteroid = new THREE.Mesh(geometry, material);
        asteroid.position.copy(position || getRandomSpawnPosition());
        asteroid.castShadow = true;

        // Random rotation
        asteroid.userData = {
            rotSpeed: new THREE.Vector3(
                (Math.random() - 0.5) * 0.05,
                (Math.random() - 0.5) * 0.05,
                (Math.random() - 0.5) * 0.05
            ),
            velocity: new THREE.Vector3(
                (Math.random() - 0.5) * CONFIG.asteroidSpeed,
                (Math.random() - 0.5) * CONFIG.asteroidSpeed * 0.5,
                (Math.random() - 0.5) * CONFIG.asteroidSpeed
            ),
            size: size,
            health: Math.ceil(size)
        };

        scene.add(asteroid);
        asteroids.push(asteroid);
        return asteroid;
    }

    function getRandomSpawnPosition() {
        const angle = Math.random() * Math.PI * 2;
        const distance = 80 + Math.random() * 60;
        const height = (Math.random() - 0.5) * 40;

        return new THREE.Vector3(
            spaceship.position.x + Math.cos(angle) * distance,
            spaceship.position.y + height,
            spaceship.position.z + Math.sin(angle) * distance
        );
    }

    // ============ BULLET CREATION ============
    function createBullet() {
        if (shootCooldown > 0) return;
        shootCooldown = CONFIG.shootCooldown;

        // Calculate shooting direction based on mouse position
        const raycaster = new THREE.Raycaster();
        raycaster.setFromCamera(new THREE.Vector2(mouse.x, mouse.y), camera);

        const direction = raycaster.ray.direction.clone();

        // Create bullet from ship position
        const bulletGeom = new THREE.SphereGeometry(0.15, 8, 8);
        const bulletMat = new THREE.MeshBasicMaterial({
            color: 0xff4444,
            emissive: 0xff0000
        });
        const bullet = new THREE.Mesh(bulletGeom, bulletMat);

        // Start position slightly in front of ship
        const startPos = spaceship.position.clone().add(direction.clone().multiplyScalar(3));
        bullet.position.copy(startPos);

        // Add trail light
        const bulletLight = new THREE.PointLight(0xff4444, 1, 5);
        bullet.add(bulletLight);

        bullet.userData = {
            velocity: direction.multiplyScalar(CONFIG.bulletSpeed),
            lifetime: CONFIG.bulletLifetime
        };

        scene.add(bullet);
        bullets.push(bullet);

        // Muzzle flash effect
        createMuzzleFlash(startPos);
    }

    function createMuzzleFlash(position) {
        const flashGeom = new THREE.SphereGeometry(0.5, 8, 8);
        const flashMat = new THREE.MeshBasicMaterial({
            color: 0xffaa00,
            transparent: true,
            opacity: 1
        });
        const flash = new THREE.Mesh(flashGeom, flashMat);
        flash.position.copy(position);
        flash.userData = { lifetime: 5 };
        scene.add(flash);
        particles.push(flash);
    }

    // ============ ASTEROID FRAGMENTATION ============
    function fragmentAsteroid(asteroid) {
        const pos = asteroid.position.clone();
        const size = asteroid.userData.size;
        const fragmentSize = size * 0.3;

        // Create fragments
        for (let i = 0; i < CONFIG.fragmentCount; i++) {
            const geom = new THREE.TetrahedronGeometry(fragmentSize * (0.3 + Math.random() * 0.7), 0);
            const mat = new THREE.MeshPhongMaterial({
                color: new THREE.Color().setHSL(0.05 + Math.random() * 0.1, 0.4, 0.3),
                emissive: new THREE.Color().setHSL(0.05, 0.3, 0.1),
                flatShading: true
            });
            const fragment = new THREE.Mesh(geom, mat);
            fragment.position.copy(pos);

            // Random outward velocity
            const velocity = new THREE.Vector3(
                (Math.random() - 0.5) * 2,
                (Math.random() - 0.5) * 2,
                (Math.random() - 0.5) * 2
            );

            fragment.userData = {
                velocity: velocity,
                rotSpeed: new THREE.Vector3(
                    (Math.random() - 0.5) * 0.2,
                    (Math.random() - 0.5) * 0.2,
                    (Math.random() - 0.5) * 0.2
                ),
                lifetime: 60 + Math.random() * 60
            };

            scene.add(fragment);
            fragments.push(fragment);
        }

        // Explosion particles
        createExplosionParticles(pos, size);

        // Explosion flash light
        const flashLight = new THREE.PointLight(0xff8800, 5, 30);
        flashLight.position.copy(pos);
        scene.add(flashLight);
        explosionFlashes.push({ light: flashLight, lifetime: 20 });

        // Remove original asteroid
        scene.remove(asteroid);
        const index = asteroids.indexOf(asteroid);
        if (index > -1) asteroids.splice(index, 1);
    }

    function createExplosionParticles(position, size) {
        const particleCount = 20;
        for (let i = 0; i < particleCount; i++) {
            const geom = new THREE.SphereGeometry(0.1 + Math.random() * 0.2, 4, 4);
            const color = Math.random() > 0.5 ? 0xff6600 : 0xffaa00;
            const mat = new THREE.MeshBasicMaterial({
                color: color,
                transparent: true,
                opacity: 1
            });
            const particle = new THREE.Mesh(geom, mat);
            particle.position.copy(position);

            const velocity = new THREE.Vector3(
                (Math.random() - 0.5) * 3,
                (Math.random() - 0.5) * 3,
                (Math.random() - 0.5) * 3
            );

            particle.userData = {
                velocity: velocity,
                lifetime: 30 + Math.random() * 30,
                maxLifetime: 60
            };

            scene.add(particle);
            particles.push(particle);
        }
    }

    // ============ SHIELD HIT EFFECT ============
    function triggerShieldHit() {
        shieldHitEffect = 30;
        shield -= CONFIG.shieldDamage;

        // Screen flash
        const hitFlash = document.getElementById('hit-flash');
        hitFlash.style.background = 'rgba(255, 0, 0, 0.3)';
        setTimeout(() => {
            hitFlash.style.background = 'rgba(255, 0, 0, 0)';
        }, 100);

        // Shield visual
        shieldMesh.material.opacity = 0.6;

        // Create shield impact particles
        for (let i = 0; i < 10; i++) {
            const geom = new THREE.SphereGeometry(0.1, 4, 4);
            const mat = new THREE.MeshBasicMaterial({
                color: 0x00ffff,
                transparent: true,
                opacity: 1
            });
            const particle = new THREE.Mesh(geom, mat);
            const angle = Math.random() * Math.PI * 2;
            const height = (Math.random() - 0.5) * 2;
            particle.position.set(
                spaceship.position.x + Math.cos(angle) * 3,
                spaceship.position.y + height,
                spaceship.position.z + Math.sin(angle) * 3
            );
            particle.userData = {
                velocity: new THREE.Vector3(
                    Math.cos(angle) * 0.5,
                    (Math.random() - 0.5) * 0.5,
                    Math.sin(angle) * 0.5
                ),
                lifetime: 20
            };
            scene.add(particle);
            particles.push(particle);
        }

        if (shield <= 0) {
            shield = 0;
            endGame();
        }

        updateHUD();
    }

    // ============ GAME OVER ============
    function endGame() {
        gameOver = true;
        document.getElementById('game-over').style.display = 'block';
        document.exitPointerLock && document.exitPointerLock();
    }

    function restartGame() {
        // Remove all asteroids
        asteroids.forEach(a => scene.remove(a));
        asteroids = [];

        // Remove all bullets
        bullets.forEach(b => scene.remove(b));
        bullets = [];

        // Remove all fragments
        fragments.forEach(f => scene.remove(f));
        fragments = [];

        // Remove all particles
        particles.forEach(p => scene.remove(p));
        particles = [];

        // Remove explosion flashes
        explosionFlashes.forEach(f => scene.remove(f.light));
        explosionFlashes = [];

        // Reset state
        score = 0;
        shield = CONFIG.shieldMax;
        gameOver = false;
        frameCount = 0;
        shootCooldown = 0;
        shieldHitEffect = 0;

        // Reset ship position
        spaceship.position.set(0, 0, 0);
        spaceship.rotation.set(0, 0, 0);

        document.getElementById('game-over').style.display = 'none';
        updateHUD();

        // Re-lock pointer
        renderer.domElement.requestPointerLock();
    }

    // ============ HUD UPDATE ============
    function updateHUD() {
        document.getElementById('score').textContent = `SCORE: ${score}`;

        const shieldPercent = (shield / CONFIG.shieldMax) * 100;
        const shieldBar = document.getElementById('shield-bar');
        shieldBar.style.width = shieldPercent + '%';

        // Color based on shield level
        if (shieldPercent > 60) {
            shieldBar.style.background = 'linear-gradient(90deg, #0f0, #0a0)';
            document.getElementById('shield-container').style.borderColor = '#0f0';
            document.getElementById('shield-container').style.boxShadow = '0 0 10px #0f0';
        } else if (shieldPercent > 30) {
            shieldBar.style.background = 'linear-gradient(90deg, #ff0, #aa0)';
            document.getElementById('shield-container').style.borderColor = '#ff0';
            document.getElementById('shield-container').style.boxShadow = '0 0 10px #ff0';
        } else {
            shieldBar.style.background = 'linear-gradient(90deg, #f00, #a00)';
            document.getElementById('shield-container').style.borderColor = '#f00';
            document.getElementById('shield-container').style.boxShadow = '0 0 10px #f00';
        }

        document.getElementById('shield-text').textContent = `SHIELD: ${Math.round(shieldPercent)}%`;
    }

    // ============ EVENT LISTENERS ============
    function setupEventListeners() {
        // Keyboard
        document.addEventListener('keydown', (e) => {
            keys[e.key.toLowerCase()] = true;
            if (e.key.toLowerCase() === 'r' && gameOver) {
                restartGame();
            }
        });
        document.addEventListener('keyup', (e) => {
            keys[e.key.toLowerCase()] = false;
        });

        // Mouse
        document.addEventListener('mousemove', (e) => {
            if (document.pointerLockElement === renderer.domElement) {
                mouse.x += e.movementX * 0.002;
                mouse.y += e.movementY * 0.002;
                mouse.y = Math.max(-1, Math.min(1, mouse.y));
            }
        });

        document.addEventListener('mousedown', (e) => {
            if (e.button === 0) {
                mouse.clicked = true;
                if (!document.pointerLockElement) {
                    renderer.domElement.requestPointerLock();
                }
            }
        });

        document.addEventListener('mouseup', (e) => {
            if (e.button === 0) mouse.clicked = false;
        });

        // Window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });
    }

    // ============ UPDATE FUNCTIONS ============
    function updateShip() {
        if (gameOver) return;

        const speed = CONFIG.shipSpeed * (keys[' '] ? CONFIG.boostMultiplier : 1);

        // Get camera-relative directions
        const forward = new THREE.Vector3(0, 0, -1);
        forward.applyQuaternion(camera.quaternion);
        forward.y = 0;
        forward.normalize();

        const right = new THREE.Vector3(1, 0, 0);
        right.applyQuaternion(camera.quaternion);
        right.y = 0;
        right.normalize();

        // Movement
        if (keys['w']) spaceship.position.add(forward.clone().multiplyScalar(speed));
        if (keys['s']) spaceship.position.add(forward.clone().multiplyScalar(-speed));
        if (keys['a']) spaceship.position.add(right.clone().multiplyScalar(-speed));
        if (keys['d']) spaceship.position.add(right.clone().multiplyScalar(speed));

        // Ship rotation based on mouse (yaw)
        spaceship.rotation.y = -mouse.x;

        // Slight tilt based on movement
        const targetRoll = 0;
        let roll = 0;
        if (keys['a']) roll = 0.3;
        if (keys['d']) roll = -0.3;
        spaceship.rotation.z += (roll - spaceship.rotation.z) * 0.1;

        // Pitch based on vertical mouse
        spaceship.rotation.x = mouse.y * 0.3;

        // Engine glow effect
        const boostActive = keys[' '];
        const targetScale = boostActive ? 2.0 : 1.0;
        engineGlow.scale.z += (targetScale - engineGlow.scale.z) * 0.1;
        engineGlow.material.opacity = 0.5 + Math.sin(frameCount * 0.3) * 0.3;

        // Shield effect decay
        if (shieldHitEffect > 0) {
            shieldHitEffect--;
            shieldMesh.material.opacity = shieldHitEffect / 30 * 0.6;
            shieldMesh.rotation.y += 0.2;
            shieldMesh.rotation.x += 0.1;
        } else {
            shieldMesh.material.opacity *= 0.95;
        }

        // Shield regeneration
        if (shield < CONFIG.shieldMax) {
            shield += CONFIG.shieldRegenRate;
            if (shield > CONFIG.shieldMax) shield = CONFIG.shieldMax;
            updateHUD();
        }

        // Shooting
        if (mouse.clicked) {
            createBullet();
        }
        if (shootCooldown > 0) shootCooldown--;
    }

    function updateCamera() {
        // Third-person camera following ship
        const offset = new THREE.Vector3(0, CONFIG.cameraHeight, CONFIG.cameraDistance);

        // Rotate offset based on ship rotation
        offset.applyAxisAngle(new THREE.Vector3(0, 1, 0), spaceship.rotation.y);

        const targetPos = spaceship.position.clone().add(offset);

        // Smooth camera follow
        camera.position.lerp(targetPos, CONFIG.cameraSmoothness);

        // Look at ship
        const lookTarget = spaceship.position.clone();
        lookTarget.y += 1;
        camera.lookAt(lookTarget);
    }

    function updateAsteroids() {
        // Spawn new asteroids
        if (frameCount % CONFIG.asteroidSpawnRate === 0 && asteroids.length < CONFIG.maxAsteroids) {
            createAsteroid();
        }

        // Update existing asteroids
        for (let i = asteroids.length - 1; i >= 0; i--) {
            const asteroid = asteroids[i];

            // Move
            asteroid.position.add(asteroid.userData.velocity);

            // Rotate
            asteroid.rotation.x += asteroid.userData.rotSpeed.x;
            asteroid.rotation.y += asteroid.userData.rotSpeed.y;
            asteroid.rotation.z += asteroid.userData.rotSpeed.z;

            // Check collision with ship
            const distToShip = asteroid.position.distanceTo(spaceship.position);
            if (distToShip < asteroid.userData.size + 2) {
                triggerShieldHit();
                fragmentAsteroid(asteroid);
                continue;
            }

            // Remove if too far
            const distFromOrigin = asteroid.position.distanceTo(spaceship.position);
            if (distFromOrigin > 200) {
                scene.remove(asteroid);
                asteroids.splice(i, 1);
            }
        }
    }

    function updateBullets() {
        for (let i = bullets.length - 1; i >= 0; i--) {
            const bullet = bullets[i];

            // Move bullet
            bullet.position.add(bullet.userData.velocity);
            bullet.userData.lifetime--;

            // Check collision with asteroids
            let hit = false;
            for (let j = asteroids.length - 1; j >= 0; j--) {
                const asteroid = asteroids[j];
                const dist = bullet.position.distanceTo(asteroid.position);

                if (dist < asteroid.userData.size + 0.5) {
                    asteroid.userData.health--;

                    if (asteroid.userData.health <= 0) {
                        // Destroy asteroid
                        fragmentAsteroid(asteroid);
                        score += Math.round(asteroid.userData.size * 10);
                        updateHUD();
                    } else {
                        // Hit but not destroyed - flash effect
                        asteroid.material.emissive.setHex(0xff4400);
                        setTimeout(() => {
                            if (asteroid.material) {
                                asteroid.material.emissive.setHSL(0.05, 0.2, 0.05);
                            }
                        }, 100);
                    }

                    hit = true;
                    break;
                }
            }

            if (hit || bullet.userData.lifetime <= 0) {
                scene.remove(bullet);
                bullets.splice(i, 1);
            }
        }
    }

    function updateFragments() {
        for (let i = fragments.length - 1; i >= 0; i--) {
            const fragment = fragments[i];

            // Move
            fragment.position.add(fragment.userData.velocity);

            // Slow down
            fragment.userData.velocity.multiplyScalar(0.98);

            // Rotate
            fragment.rotation.x += fragment.userData.rotSpeed.x;
            fragment.rotation.y += fragment.userData.rotSpeed.y;
            fragment.rotation.z += fragment.userData.rotSpeed.z;

            // Lifetime
            fragment.userData.lifetime--;

            // Fade out
            if (fragment.userData.lifetime < 20) {
                fragment.material.opacity = fragment.userData.lifetime / 20;
                fragment.material.transparent = true;
            }

            if (fragment.userData.lifetime <= 0) {
                scene.remove(fragment);
                fragments.splice(i, 1);
            }
        }
    }

    function updateParticles() {
        for (let i = particles.length - 1; i >= 0; i--) {
            const particle = particles[i];

            if (particle.userData.velocity) {
                particle.position.add(particle.userData.velocity);
                particle.userData.velocity.multiplyScalar(0.95);
            }

            particle.userData.lifetime--;

            // Fade
            if (particle.material.transparent) {
                particle.material.opacity = Math.max(0, particle.userData.lifetime / (particle.userData.maxLifetime || 30));
            }

            // Scale down
            const scale = Math.max(0.01, particle.userData.lifetime / 30);
            particle.scale.setScalar(scale);

            if (particle.userData.lifetime <= 0) {
                scene.remove(particle);
                particles.splice(i, 1);
            }
        }
    }

    function updateExplosionFlashes() {
        for (let i = explosionFlashes.length - 1; i >= 0; i--) {
            const flash = explosionFlashes[i];
            flash.lifetime--;
            flash.light.intensity = (flash.lifetime / 20) * 5;

            if (flash.lifetime <= 0) {
                scene.remove(flash.light);
                explosionFlashes.splice(i, 1);
            }
        }
    }

    function updateDynamicLighting() {
        const time = frameCount * 0.01;

        dynamicLights.forEach((item, index) => {
            if (item.type === 'point') {
                // Orbiting point lights
                const phase = item.phase + time;
                const radius = 30 + Math.sin(time * 0.5 + index) * 10;
                item.light.position.x = spaceship.position.x + Math.cos(phase) * radius;
                item.light.position.z = spaceship.position.z + Math.sin(phase) * radius;
                item.light.position.y = Math.sin(phase * 0.7) * 15;

                // Pulsing intensity
                item.light.intensity = 1.5 + Math.sin(time * 2 + index * 2) * 0.5;

                // Color shifting
                const hue = (time * 0.02 + index * 0.33) % 1;
                item.light.color.setHSL(hue, 0.8, 0.5);
            }
        });

        // Rotate star field slowly
        if (stars) {
            stars.rotation.y += 0.0001;
            stars.rotation.x += 0.00005;
        }
    }

    // ============ MAIN ANIMATION LOOP ============
    function animate() {
        requestAnimationFrame(animate);

        if (!gameOver) {
            frameCount++;
            updateShip();
            updateAsteroids();
            updateBullets();
            updateFragments();
            updateParticles();
            updateExplosionFlashes();
            updateDynamicLighting();
        }

        updateCamera();
        renderer.render(scene, camera);
    }

    // ============ START GAME ============
    init();
    updateHUD();

    // Spawn initial asteroids
    for (let i = 0; i < 10; i++) {
        createAsteroid();
    }
    </script>
</body>
</html>
```

## How to Run

1. Save the code above as `index.html`
2. Open it in any modern web browser (Chrome, Firefox, Edge)
3. Click on the screen to lock your mouse pointer and start playing

## Controls

| Key | Action |
|-----|--------|
| **W/A/S/D** | Move spaceship (forward/left/back/right) |
| **Mouse** | Aim / Look around |
| **Left Click** | Shoot |
| **Space** | Speed boost |
| **R** | Restart (after game over) |

## Features Implemented

1. **Third-person camera** — Smoothly follows the spaceship from behind with lerp-based interpolation
2. **Shield impact effects** — Wireframe shield bubble appears on hit, screen flashes red, cyan particles burst outward
3. **Asteroid fragmentation** — Asteroids break into tetrahedron fragments with explosion particles and flash lighting
4. **Dynamic lighting** — Orbiting colored point lights that shift hue over time, explosion flash lights, engine glow
5. **Score system** — Points based on asteroid size
6. **Shield regeneration** — Slowly regenerates over time
7. **Star field** — 3000 colored stars with nebula clouds
8. **Engine effects** — Glowing engine with boost visual feedback
9. **HUD** — Score display, color-coded shield bar, crosshair

To build a robust Task Scheduler in a browser environment that interacts with the System Notification Center and executes custom JavaScript (like `location.reload()`), we must use the **Web Notifications API** combined with a time-evaluation engine.

Below is a complete, professional, and fully executable single-file HTML application. It includes the `TaskScheduler` engine, a modern UI dashboard to manage tasks, and an execution log.

### ⚠️ Important Architectural Notes
1. **Browser Throttling**: Browsers throttle `setInterval` in inactive/background tabs to roughly once per minute. If the tab is closed, the scheduler stops. For *true* background persistence, a **Service Worker** with Web Push is required. However, since your use case involves DOM manipulation (`location.reload()`), an in-page scheduler is the correct approach.
2. **Security**: Executing string-based JS snippets requires `new Function()`. This carries XSS risks if the input comes from untrusted users. In this local dashboard, it is safe, but never expose this to unsanitized external input.
3. **User Gesture**: Browsers require a user click to grant Notification permissions. The UI includes a button to handle this.

