<script>
/**
 * Professional Task Scheduler Engine
 */
class TaskScheduler {
    constructor() {
        this.tasks = new Map();
        this.ticker = null;
        this.onExecuteCallback = null; // For UI logging
        this._startTicker();
    }

    _startTicker() {
        // Tick every 5 seconds to balance accuracy and CPU usage
        this.ticker = setInterval(() => this._tick(), 5000);
        this._tick(); // Initial check
    }

    addTask(config) {
        const task = {
            id: `task_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`,
            name: config.name || 'Unnamed Task',
            schedule: config.schedule,
            notification: config.notification,
            actionSnippet: config.actionSnippet,
            lastExecuted: null
        };
        this.tasks.set(task.id, task);
        return task.id;
    }

    removeTask(id) {
        this.tasks.delete(id);
    }

    forceExecute(id) {
        const task = this.tasks.get(id);
        if (task) this._execute(task, new Date(), true);
    }

    _tick() {
        const now = new Date();
        for (const [id, task] of this.tasks.entries()) {
            if (this._shouldExecute(task, now)) {
                this._execute(task, now, false);
            }
        }
    }

    _shouldExecute(task, now) {
        const schedule = task.schedule;
        const last = task.lastExecuted;

        if (schedule.type === 'daily') {
            if (now.getHours() === schedule.hour && now.getMinutes() === schedule.minute) {
                return last !== now.toDateString();
            }
        } 
        else if (schedule.type === 'hourly') {
            if (now.getMinutes() === schedule.minute) {
                const currentHourKey = now.toDateString() + now.getHours();
                return last !== currentHourKey;
            }
        } 
        else if (schedule.type === 'interval') {
            if (!last) return true;
            return (now.getTime() - last.getTime()) >= schedule.ms;
        }
        return false;
    }

    _execute(task, now, isForced) {
        // 1. Update State
        if (task.schedule.type === 'daily') task.lastExecuted = now.toDateString();
        else if (task.schedule.type === 'hourly') task.lastExecuted = now.toDateString() + now.getHours();
        else task.lastExecuted = new Date(now);

        const triggerType = isForced ? 'MANUAL TRIGGER' : 'SCHEDULED';

        // 2. System Notification
        if (Notification.permission === "granted" && task.notification) {
            const n = new Notification(task.notification.title, {
                body: task.notification.body,
                icon: 'https://cdn-icons-png.flaticon.com/512/1827/1827392.png' // Clock icon
            });
            n.onclick = () => window.focus();
        }

        // 3. Execute JS Snippet
        let execSuccess = true;
        try {
            if (task.actionSnippet && task.actionSnippet.trim() !== '') {
                // Using new Function to execute string snippets safely in local scope
                const fn = new Function(task.actionSnippet);
                fn();
            }
        } catch (e) {
            execSuccess = false;
            console.error(`[Scheduler] Error in task ${task.name}:`, e);
        }

        // 4. Callback for UI Logging
        if (this.onExecuteCallback) {
            this.onExecuteCallback(task, now, triggerType, execSuccess);
        }
    }
}

// ==========================================
// UI & Controller Logic
// ==========================================

const scheduler = new TaskScheduler();
const logBox = document.getElementById('log-box');
const taskListUI = document.getElementById('task-list');
const permStatus = document.getElementById('perm-status');

// Logging setup
scheduler.onExecuteCallback = (task, time, type, success) => {
    const timeStr = time.toLocaleTimeString();
    const status = success ? '✅' : '❌';
    const logEntry = document.createElement('div');
    logEntry.className = 'log-entry';
    logEntry.innerHTML = `<span class="log-time">[${timeStr}]</span> <strong>${task.name}</strong> (${type}) ${status}`;
    logBox.prepend(logEntry);
};

// Notification Permission Handling
function updatePermUI() {
    const perm = Notification.permission;
    permStatus.textContent = perm.toUpperCase();
    permStatus.className = `status-badge status-${perm}`;
    document.getElementById('btn-perm').style.display = perm === 'granted' ? 'none' : 'inline-block';
}

document.getElementById('btn-perm').addEventListener('click', async () => {
    if ("Notification" in window) {
        await Notification.requestPermission();
        updatePermUI();
    } else {
        alert("Your browser does not support system notifications.");
    }
});
updatePermUI();

// Render Tasks UI
function renderTasks() {
    taskListUI.innerHTML = '';
    if (scheduler.tasks.size === 0) {
        taskListUI.innerHTML = '<p style="color: #6b7280; text-align: center;">No active tasks.</p>';
        return;
    }

    scheduler.tasks.forEach((task) => {
        let scheduleStr = '';
        if (task.schedule.type === 'daily') scheduleStr = `Daily at ${task.schedule.hour}:${String(task.schedule.minute).padStart(2, '0')}`;
        if (task.schedule.type === 'hourly') scheduleStr = `Hourly at min ${task.schedule.minute}`;
        if (task.schedule.type === 'interval') scheduleStr = `Every ${task.schedule.ms / 1000}s`;

        const div = document.createElement('div');
        div.className = 'task-item';
        div.innerHTML = `
            <div>
                <strong>${task.name}</strong><br>
                <small style="color: #6b7280;">${scheduleStr}</small>
            </div>
            <div>
                <button class="btn-primary btn-sm" onclick="triggerManual('${task.id}')">Run</button>
                <button class="btn-danger btn-sm" onclick="deleteTask('${task.id}')">Del</button>
            </div>
        `;
        taskListUI.appendChild(div);
    });
}

// Global functions for UI buttons
window.triggerManual = (id) => scheduler.forceExecute(id);
window.deleteTask = (id) => {
    scheduler.removeTask(id);
    renderTasks();
};

// Add Task Form Handler
document.getElementById('btn-add').addEventListener('click', () => {
    const name = document.getElementById('task-name').value || 'Unnamed Task';
    const type = document.getElementById('task-type').value;
    const val = parseInt(document.getElementById('task-value').value, 10);
    const msg = document.getElementById('task-msg').value || 'Task Executed';
    const action = document.getElementById('task-action').value;

    let schedule = {};
    if (type === 'daily') schedule = { type: 'daily', hour: val, minute: 0 };
    else if (type === 'hourly') schedule = { type: 'hourly', minute: val };
    else schedule = { type: 'interval', ms: val * 1000 };

    scheduler.addTask({
        name: name,
        schedule: schedule,
        notification: { title: name, body: msg },
        actionSnippet: action
    });

    renderTasks();

    // Reset form
    document.getElementById('task-name').value = '';
    document.getElementById('task-msg').value = '';
});

document.getElementById('btn-clear-log').addEventListener('click', () => {
    logBox.innerHTML = '';
});

// ==========================================
// Initialize with Demo Tasks
// ==========================================
scheduler.addTask({
    name: 'Hourly Time Announcement',
    schedule: { type: 'hourly', minute: 0 }, // Triggers at the top of every hour
    notification: { title: 'Hourly Chime', body: 'A new hour has begun.' },
    actionSnippet: 'console.log("Hourly chime executed");'
});

scheduler.addTask({
    name: 'Daily 9:00 AM Reminder',
    schedule: { type: 'daily', hour: 9, minute: 0 },
    notification: { title: 'Good Morning!', body: 'It is 9:00 AM. Time to start the day.' },
    actionSnippet: 'console.log("9 AM Daily Trigger");'
});

// Added a 15-second interval task so you can test it immediately without waiting!
scheduler.addTask({
    name: 'Test Interval (15s)',
    schedule: { type: 'interval', ms: 15000 },
    notification: { title: 'Test Ping', body: 'This triggers every 15 seconds.' },
    actionSnippet: 'console.log("15s Interval Ping");'
});

renderTasks();
</script>

</body>
