uniform float uHeightScale;

out vec3 vWorldPos;
out vec2 vUV;
out vec3 vNormal;
out float vHeight;

void main() {
vec2 uv = aUV;
float h = texture(uHeightmap, uv).r;
vec3 pos = aPosition;
pos.y = h * uHeightScale;

// Calculate normal from heightmap
float texel = 1.0 / ${TERRAIN_RES.toFixed(1)};
float hL = texture(uHeightmap, uv + vec2(-texel, 0)).r * uHeightScale;
float hR = texture(uHeightmap, uv + vec2(texel, 0)).r * uHeightScale;
float hD = texture(uHeightmap, uv + vec2(0, -texel)).r * uHeightScale;
float hU = texture(uHeightmap, uv + vec2(0, texel)).r * uHeightScale;
vNormal = normalize(vec3(hL - hR, 2.0 * texel * uTerrainScale, hD - hU));

vWorldPos = pos;
vUV = uv;
vHeight = h;
gl_Position = uProjection * uView * vec4(pos, 1.0);
