const terrainFS = `#version 300 es
precision highp float;
in vec3 vWorldPos;
in vec2 vUV;
in vec3 vNormal;
in float vHeight;

uniform vec3 uLightDir;
uniform vec3 uCameraPos;
uniform sampler2D uWaterMap;
uniform float uTime;

out vec4 fragColor;

void main() {
vec3 N = normalize(vNormal);
vec3 L = normalize(uLightDir);
float diff = max(dot(N, L), 0.0);
float amb = 0.25;

// Terrain coloring based on height and slope
float slope = 1.0 - N.y;
vec3 grass = vec3(0.2, 0.45, 0.15);
vec3 dirt = vec3(0.45, 0.32, 0.2);
vec3 rock = vec3(0.5, 0.48, 0.45);
vec3 snow = vec3(0.9, 0.92, 0.95);

vec3 color = grass;
if (vHeight > 0.6) color = mix(grass, rock, (vHeight - 0.6) / 0.2);
if (vHeight > 0.8) color = mix(rock, snow, (vHeight - 0.8) / 0.2);
if (slope > 0.4) color = mix(color, rock, min((slope - 0.4) / 0.3, 1.0));
if (vHeight < 0.2) color = mix(dirt, color, vHeight / 0.2);

// Crater darkening
float crater = smoothstep(0.0, 0.15, vHeight);
color *= mix(0.4, 1.0, crater);

vec3 lighting = color * (amb + diff * 0.75);

// Specular
vec3 V = normalize(uCameraPos - vWorldPos);
vec3 H = normalize(L + V);
float spec = pow(max(dot(N, H), 0.0), 32.0);
lighting += spec * 0.15;

