// ============================================================
// TERRAIN GENERATION
// ============================================================
const TERRAIN_RES = 256;
const TERRAIN_SIZE = 200;
const HEIGHT_SCALE = 25;
const perlin = new PerlinNoise(42);

let heightData = new Float32Array(TERRAIN_RES * TERRAIN_RES);
let waterData = new Float32Array(TERRAIN_RES * TERRAIN_RES);

function generateTerrain() {
for (let z = 0; z < TERRAIN_RES; z++) {
for (let x = 0; x < TERRAIN_RES; x++) {
const nx = x / TERRAIN_RES * 4;
const nz = z / TERRAIN_RES * 4;
let h = perlin.fbm(nx, nz, 6, 2.0, 0.5) * 0.5 + 0.5;
// Add some ridges
h += Math.abs(perlin.fbm(nx * 2 + 10, nz * 2 + 10, 4)) * 0.15;
// Flatten center area for gameplay
const cx = (x / TERRAIN_RES - 0.5) * 2;
const cz = (z / TERRAIN_RES - 0.5) * 2;
const centerDist = Math.sqrt(cx*cx + cz*cz);
if (centerDist < 0.3) {
h = h * (centerDist / 0.3) + 0.35 * (1 - centerDist / 0.3);
}
h = Math.max(0, Math.min(1, h));
heightData[z * TERRAIN_RES + x] = h;
}
}
}

function getTerrainHeight(wx, wz) {
const u = (wx / TERRAIN_SIZE + 0.5);
const v = (wz / TERRAIN_SIZE + 0.5);
if (u < 0 || u > 1 || v < 0 || v > 1) return 0;
const fx = u * (TERRAIN_RES - 1);
const fz = v * (TERRAIN_RES - 1);
const ix = Math.floor(fx), iz = Math.floor(fz);
const dx = fx - ix, dz = fz - iz;
const ix1 = Math.min(ix + 1, TERRAIN_RES - 1);
const iz1 = Math.min(iz + 1, TERRAIN_RES - 1);
const h00 = heightData[iz * TERRAIN_RES + ix];
const h10 = heightData[iz * TERRAIN_RES + ix1];
const h01 = heightData[iz1 * TERRAIN_RES + ix];
const h11 = heightData[iz1 * TERRAIN_RES + ix1];
return (h00*(1-dx)*(1-dz) + h10*dx*(1-dz) + h01*(1-dx)*dz + h11*dx*dz) * HEIGHT_SCALE;
}

function getWaterLevel(wx, wz) {
const u = (wx / TERRAIN_SIZE + 0.5);
const v = (wz / TERRAIN_SIZE + 0.5);
if (u < 0 || u > 1 || v < 0 || v > 1) return 0;
const ix = Math.floor(u * (TERRAIN_RES - 1));
const iz = Math.floor(v * (TERRAIN_RES - 1));
return waterData[iz * TERRAIN_RES + ix];
}

// Create terrain mesh
function createTerrainMesh() {
const verts = [];
const uvs = [];
const indices = [];
const step = TERRAIN_SIZE / (TERRAIN_RES - 1);

for (let z = 0; z < TERRAIN_RES; z++) {
for (let x = 0; x < TERRAIN_RES; x++) {
const wx = (x / (TERRAIN_RES - 1) - 0.5) * TERRAIN_SIZE;
const wz = (z / (TERRAIN_RES - 1) - 0.5) * TERRAIN_SIZE;
const h = heightData[z * TERRAIN_RES + x] * HEIGHT_SCALE;
verts.push(wx, h, wz);
uvs.push(x / (TERRAIN_RES - 1), z / (TERRAIN_RES - 1));
}
}

for (let z = 0; z < TERRAIN_RES - 1; z++) {
for (let x = 0; x < TERRAIN_RES - 1; x++) {
const i = z * TERRAIN_RES + x;
indices.push(i, i + TERRAIN_RES, i + 1);
indices.push(i + 1, i + TERRAIN_RES, i + TERRAIN_RES + 1);
}
}

const vao = gl.createVertexArray();
gl.bindVertexArray(vao);

const vbo = gl.createBuffer();
gl.bindBuffer(gl.ARRAY_BUFFER, vbo);
gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(verts), gl.STATIC_DRAW);
gl.enableVertexAttribArray(0);
gl.vertexAttribPointer(0, 3, gl.FLOAT, false, 0, 0);

const uvbo = gl.createBuffer();
gl.bindBuffer(gl.ARRAY_BUFFER, uvbo);
gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(uvs), gl.STATIC_DRAW);
gl.enableVertexAttribArray(1);
gl.vertexAttribPointer(1, 2, gl.FLOAT, false, 0, 0);

const ibo = gl.createBuffer();
gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, ibo);
gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, new Uint32Array(indices), gl.STATIC_DRAW);

gl.bindVertexArray(null);
return { vao, count: indices.length };
}

// Heightmap texture
let heightmapTex, watermapTex;

function createDataTexture(data) {
const tex = gl.createTexture();
gl.bindTexture(gl.TEXTURE_2D, tex);
gl.texImage2D(gl.TEXTURE_2D, 0, gl.R32F, TERRAIN_RES, TERRAIN_RES, 0, gl.RED, gl.FLOAT, data);
gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
return tex;
}

function updateTexture(tex, data) {
gl.bindTexture(gl.TEXTURE_2D, tex);
gl.texSubImage2D(gl.TEXTURE_2D, 0, 0, 0, TERRAIN_RES, TERRAIN_RES, gl.RED, gl.FLOAT, data);
}

// ============================================================
// TERRAIN DESTRUCTION
// ============================================================
function createCrater(wx, wz, radius, depth) {
const u = (wx / TERRAIN_SIZE + 0.5);
const v = (wz / TERRAIN_SIZE + 0.5);
const cx = u * (TERRAIN_RES - 1);
const cz = v * (TERRAIN_RES - 1);
const r = radius / TERRAIN_SIZE * TERRAIN_RES;
const ri = Math.ceil(r);

for (let dz = -ri; dz <= ri; dz++) {
for (let dx = -ri; dx <= ri; dx++) {
const px = Math.round(cx + dx);
const pz = Math.round(cz + dz);
if (px < 0 || px >= TERRAIN_RES || pz < 0 || pz >= TERRAIN_RES) continue;
const dist = Math.sqrt(dx*dx + dz*dz);
if (dist > r) continue;
// Gaussian falloff for realistic crater
const falloff = Math.exp(-(dist * dist) / (r * r * 0.3));
const idx = pz * TERRAIN_RES + px;
heightData[idx] = Math.max(0, heightData[idx] - depth * falloff / HEIGHT_SCALE);
}
}
updateTexture(heightmapTex, heightData);
rebuildTerrainMesh();
}

let terrainMesh;
function rebuildTerrainMesh() {
// Rebuild vertex positions
const verts = [];
for (let z = 0; z < TERRAIN_RES; z++) {
for (let x = 0; x < TERRAIN_RES; x++) {
const wx = (x / (TERRAIN_RES - 1) - 0.5) * TERRAIN_SIZE;
const wz = (z / (TERRAIN_RES - 1) - 0.5) * TERRAIN_SIZE;
const h = heightData[z * TERRAIN_RES + x] * HEIGHT_SCALE;
verts.push(wx, h, wz);
}
}
gl.bindVertexArray(terrainMesh.vao);
const vbo = gl.createBuffer();
gl.bindBuffer(gl.ARRAY_BUFFER, vbo);
gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(verts), gl.STATIC_DRAW);
gl.enableVertexAttribArray(0);
gl.vertexAttribPointer(0, 3, gl.FLOAT, false, 0, 0);
gl.bindVertexArray(null);
}

// ============================================================
// FLUID SIMULATION
// ============================================================
const FLUID_ITERATIONS = 4;

function simulateFluid(dt) {
const newData = new Float32Array(waterData);
const flow = new Float32Array(TERRAIN_RES * TERRAIN_RES);

for (let iter = 0; iter < FLUID_ITERATIONS; iter++) {
for (let z = 1; z < TERRAIN_RES - 1; z++) {
for (let x = 1; x < TERRAIN_RES - 1; x++) {
const idx = z * TERRAIN_RES + x;
const waterH = waterData[idx];
if (waterH < 0.001) continue;

const totalH = waterH + heightData[idx];
const neighbors = [
idx - 1, idx + 1,
idx - TERRAIN_RES, idx + TERRAIN_RES
];

let totalDiff = 0;
const diffs = [];
for (const ni of neighbors) {
const nTotalH = waterData[ni] + heightData[ni];
const diff = totalH - nTotalH;
diffs.push(Math.max(0, diff));
totalDiff += Math.max(0, diff);
}

if (totalDiff > 0) {
const maxFlow = waterH * 0.25;
for (let n = 0; n < 4; n++) {
const amount = Math.min(diffs[n] / totalDiff * maxFlow, maxFlow * 0.25);
flow[idx] -= amount;
flow[neighbors[n]] += amount;
}
}

// Evaporation
newData[idx] = Math.max(0, waterData[idx] + flow[idx] - 0.0001);
flow[idx] = 0;
for (const ni of neighbors) flow[ni] = 0;
}
}
waterData.set(newData);
}
updateTexture(watermapTex, waterData);
}

