// ============================================================
// ENEMY AI
// ============================================================
function spawnEnemy() {
const angle = Math.random() * Math.PI * 2;
const dist = 40 + Math.random() * 40;
const ex = Math.cos(angle) * dist;
const ez = Math.sin(angle) * dist;
const ey = getTerrainHeight(ex, ez);

enemies.push({
x: ex, y: ey, z: ez,
vx: 0, vy: 0, vz: 0,
health: 30 + wave * 10,
maxHealth: 30 + wave * 10,
speed: 4 + wave * 0.5,
shootTimer: Math.random() * 2,
shootInterval: 2.5 - Math.min(wave * 0.2, 1.5),
state: 'patrol',
patrolAngle: Math.random() * Math.PI * 2,
patrolTimer: 0,
alertRange: 35,
color: [0.8, 0.2, 0.15],
hitFlash: 0
});
}

function updateEnemies(dt) {
for (let i = enemies.length - 1; i >= 0; i--) {
const e = enemies[i];
const dx = player.x - e.x;
const dz = player.z - e.z;
const dist = Math.sqrt(dx*dx + dz*dz);

// Water slowdown
const waterLevel = getWaterLevel(e.x, e.z);
const waterSlow = waterLevel > 0.05 ? 0.4 : 1.0;

e.hitFlash = Math.max(0, e.hitFlash - dt * 3);

if (dist < e.alertRange) {
e.state = 'chase';
}

if (e.state === 'chase') {
const nx = dx / dist, nz = dz / dist;
if (dist > 10) {
e.vx = nx * e.speed * waterSlow;
e.vz = nz * e.speed * waterSlow;
} else {
e.vx *= 0.9;
e.vz *= 0.9;
}

// Shoot at player
e.shootTimer -= dt;
if (e.shootTimer <= 0 && dist < e.alertRange) {
e.shootTimer = e.shootInterval;
// Enemy bullet
const bSpeed = 40;
const aimY = player.y + 1.5;
const dy = aimY - (e.y + 1.5);
const bDist = Math.sqrt(dx*dx + dy*dy + dz*dz);
bullets.push({
x: e.x, y: e.y + 1.5, z: e.z,
vx: (dx/bDist) * bSpeed,
vy: (dy/bDist) * bSpeed,
vz: (dz/bDist) * bSpeed,
life: 3,
damage: 8 + wave * 2,
isEnemy: true,
trail: []
});
}
} else {
// Patrol
e.patrolTimer -= dt;
if (e.patrolTimer <= 0) {
e.patrolAngle += (Math.random() - 0.5) * 2;
e.patrolTimer = 2 + Math.random() * 3;
}
e.vx = Math.cos(e.patrolAngle) * e.speed * 0.3 * waterSlow;
e.vz = Math.sin(e.patrolAngle) * e.speed * 0.3 * waterSlow;
}

e.x += e.vx * dt;
e.z += e.vz * dt;
e.y = getTerrainHeight(e.x, e.z);

// Keep in bounds
const bound = TERRAIN_SIZE * 0.45;
e.x = Math.max(-bound, Math.min(bound, e.x));
e.z = Math.max(-bound, Math.min(bound, e.z));

// Check if dead
if (e.health <= 0) {
score += 100;
// Death particles
for (let p = 0; p < 15; p++) {
particles.push({
x: e.x, y: e.y + 1, z: e.z,
vx: (Math.random()-0.5)*8,
vy: Math.random()*8+2,
vz: (Math.random()-0.5)*8,
life: 1.5, maxLife: 1.5,
color: [0.8, 0.2, 0.1],
size: 0.3
});
}
enemies.splice(i, 1);
}
}

// Wave management
if (enemies.length === 0) {
wave++;
const count = 3 + wave * 2;
for (let i = 0; i < count; i++) {
setTimeout(() => spawnEnemy(), i * 500);
}
}
}

// ============================================================
// BULLET & PARTICLE SYSTEM
// ============================================================
function shootBullet() {
if (player.ammo <= 0 || player.reloading || player.shootCooldown > 0) return;
player.ammo--;
player.shootCooldown = 0.1;

const dirX = -Math.sin(player.yaw) * Math.cos(player.pitch);
const dirY = Math.sin(player.pitch);
const dirZ = -Math.cos(player.yaw) * Math.cos(player.pitch);
const speed = 80;

bullets.push({
x: player.x, y: player.y + 1.7, z: player.z,
vx: dirX * speed, vy: dirY * speed, vz: dirZ * speed,
life: 3, damage: 25, isEnemy: false,
trail: []
});

// Muzzle flash particles
for (let i = 0; i < 5; i++) {
particles.push({
x: player.x + dirX * 1.5,
y: player.y + 1.7 + dirY * 1.5,
z: player.z + dirZ * 1.5,
vx: dirX * 10 + (Math.random()-0.5)*5,
vy: dirY * 10 + (Math.random()-0.5)*5,
vz: dirZ * 10 + (Math.random()-0.5)*5,
life: 0.2, maxLife: 0.2,
color: [1, 0.8, 0.2],
size: 0.2
});
}

if (player.ammo <= 0 && player.reserve > 0) reload();
}

function reload() {
if (player.reloading || player.ammo === player.maxAmmo || player.reserve <= 0) return;
player.reloading = true;
player.reloadTime = 1.5;
}

function updateBullets(dt) {
for (let i = bullets.length - 1; i >= 0; i--) {
const b = bullets[i];
b.trail.push({x: b.x, y: b.y, z: b.z});
if (b.trail.length > 8) b.trail.shift();

b.x += b.vx * dt;
b.y += b.vy * dt;
b.z += b.vz * dt;
b.vy -= 9.8 * dt; // gravity
b.life -= dt;

if (b.life <= 0) { bullets.splice(i, 1); continue; }

// Terrain collision
const th = getTerrainHeight(b.x, b.z);
if (b.y <= th) {
// Create crater
createCrater(b.x, b.z, 3 + Math.random() * 2, 2 + Math.random());

// Impact particles
for (let p = 0; p < 10; p++) {
particles.push({
x: b.x, y: th + 0.1, z: b.z,
vx: (Math.random()-0.5)*10,
vy: Math.random()*8+2,
vz: (Math.random()-0.5)*10,
life: 1, maxLife: 1,
color: [0.5, 0.4, 0.3],
size: 0.2
});
}

// Check water container hits
for (const wc of waterContainers) {
if (!wc.broken) {
const d = Math.sqrt((b.x-wc.x)**2 + (b.z-wc.z)**2);
if (d < wc.radius + 2) breakContainer(wc);
}
}

bullets.splice(i, 1);
continue;
}

// Enemy collision (player bullets)
if (!b.isEnemy) {
for (const e of enemies) {
const dx = b.x - e.x, dy = b.y - (e.y + 1), dz = b.z - e.z;
if (dx*dx + dy*dy + dz*dz < 2.5) {
e.health -= b.damage;
e.hitFlash = 1;
e.state = 'chase';
// Hit particles
for (let p = 0; p < 5; p++) {
particles.push({
x: b.x, y: b.y, z: b.z,
vx: (Math.random()-0.5)*6,
vy: Math.random()*4,
vz: (Math.random()-0.5)*6,
life: 0.5, maxLife: 0.5,
color: [1, 0.3, 0.1],
size: 0.15
});
}
bullets.splice(i, 1);
break;
}
}
}

// Player collision (enemy bullets)
if (b.isEnemy) {
const dx = b.x - player.x, dy = b.y - (player.y + 1), dz = b.z - player.z;
if (dx*dx + dy*dy + dz*dz < 2) {
player.health -= b.damage;
bullets.splice(i, 1);
if (player.health <= 0) {
gameOver = true;
document.getElementById('gameOver').style.display = 'block';
document.getElementById('finalScore').textContent = `Score: ${score} | Wave: ${wave}`;
document.exitPointerLock();
}
}
}

// Water container collision
for (const wc of waterContainers) {
if (!wc.broken) {
const dx = b.x - wc.x, dz = b.z - wc.z;
const dy = b.y - (wc.y + wc.height/2);
if (dx*dx + dz*dz < wc.radius*wc.radius && Math.abs(dy) < wc.height/2) {
breakContainer(wc);
bullets.splice(i, 1);
break;
}
}
}

// Out of bounds
const bound = TERRAIN_SIZE * 0.5;
if (Math.abs(b.x) > bound || Math.abs(b.z) > bound) {
bullets.splice(i, 1);
}
}
}

function updateParticles(dt) {
for (let i = particles.length - 1; i >= 0; i--) {
const p = particles[i];
p.x += p.vx * dt;
p.y += p.vy * dt;
p.z += p.vz * dt;
p.vy -= 15 * dt;
p.life -= dt;
if (p.life <= 0) particles.splice(i, 1);
}
}

// ============================================================
// PLAYER UPDATE
// ============================================================
function updatePlayer(dt) {
if (gameOver) return;

// Water check
const waterLevel = getWaterLevel(player.x, player.z);
player.inWater = waterLevel > 0.05;
const speedMult = player.inWater ? 0.45 : 1.0;

// Movement
let mx = 0, mz = 0;
if (keys['w'] || keys['arrowup']) { mx -= Math.sin(player.yaw); mz -= Math.cos(player.yaw); }
if (keys['s'] || keys['arrowdown']) { mx += Math.sin(player.yaw); mz += Math.cos(player.yaw); }
if (keys['a'] || keys['arrowleft']) { mx -= Math.cos(player.yaw); mz += Math.sin(player.yaw); }
if (keys['d'] || keys['arrowright']) { mx += Math.cos(player.yaw); mz -= Math.sin(player.yaw); }

const len = Math.sqrt(mx*mx + mz*mz);
if (len > 0) { mx /= len; mz /= len; }

player.vx = mx * player.speed * speedMult;
player.vz = mz * player.speed * speedMult;

// Gravity & jump
player.vy -= 25 * dt;
if ((keys[' '] || keys['space']) && player.grounded) {
player.vy = player.inWater ? 6 : 10;
player.grounded = false;
}

player.x += player.vx * dt;
player.y += player.vy * dt;
player.z += player.vz * dt;

// Terrain collision
const th = getTerrainHeight(player.x, player.z);
if (player.y < th) {
player.y = th;
player.vy = 0;
player.grounded = true;
}

// Bounds
const bound = TERRAIN_SIZE * 0.45;
player.x = Math.max(-bound, Math.min(bound, player.x));
player.z = Math.max(-bound, Math.min(bound, player.z));

// Shooting
player.shootCooldown = Math.max(0, player.shootCooldown - dt);
if (mouseDown && !player.reloading) shootBullet();

// Reload
if (player.reloading) {
player.reloadTime -= dt;
if (player.reloadTime <= 0) {
const needed = player.maxAmmo - player.ammo;
const available = Math.min(needed, player.reserve);
player.ammo += available;
player.reserve -= available;
player.reloading = false;
}
}

// Water splash when moving in water
if (player.inWater && len > 0 && Math.random() < 0.3) {
particles.push({
x: player.x + (Math.random()-0.5),
y: getTerrainHeight(player.x, player.z) + 0.1,
z: player.z + (Math.random()-0.5),
vx: (Math.random()-0.5)*2,
vy: Math.random()*3+1,
vz: (Math.random()-0.5)*2,
life: 0.5, maxLife: 0.5,
color: [0.3, 0.6, 0.9],
size: 0.15
});
}
}

// ============================================================
// RENDERING
// ============================================================
const lightDir = [0.5, 0.8, 0.3];

function render() {
gl.clearColor(0.6, 0.7, 0.8, 1);
gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
gl.enable(gl.DEPTH_TEST);
gl.enable(gl.CULL_FACE);

const aspect = canvas.width / canvas.height;
const proj = mat4Perspective(Math.PI / 3, aspect, 0.1, 500);

const eyeX = player.x;
const eyeY = player.y + 1.7;
const eyeZ = player.z;
const lookX = eyeX - Math.sin(player.yaw) * Math.cos(player.pitch);
const lookY = eyeY + Math.sin(player.pitch);
const lookZ = eyeZ - Math.cos(player.yaw) * Math.cos(player.pitch);
const view = mat4LookAt([eyeX, eyeY, eyeZ], [lookX, lookY, lookZ], [0, 1, 0]);

// Draw sky
gl.depthMask(false);
gl.cullFace(gl.FRONT);
gl.useProgram(skyProg);
gl.uniformMatrix4fv(gl.getUniformLocation(skyProg, 'uProjection'), false, proj);
gl.uniformMatrix4fv(gl.getUniformLocation(skyProg, 'uView'), false, view);
gl.uniform3fv(gl.getUniformLocation(skyProg, 'uLightDir'), lightDir);
gl.bindVertexArray(skyMesh.vao);
gl.drawElements(gl.TRIANGLES, skyMesh.count, gl.UNSIGNED_SHORT, 0);
gl.depthMask(true);
gl.cullFace(gl.BACK);

// Draw terrain
gl.useProgram(terrainProg);
gl.uniformMatrix4fv(gl.getUniformLocation(terrainProg, 'uProjection'), false, proj);
gl.uniformMatrix4fv(gl.getUniformLocation(terrainProg, 'uView'), false, view);
gl.uniform3fv(gl.getUniformLocation(terrainProg, 'uLightDir'), lightDir);
gl.uniform3f(gl.getUniformLocation(terrainProg, 'uCameraPos'), eyeX, eyeY, eyeZ);
gl.uniform1f(gl.getUniformLocation(terrainProg, 'uTerrainScale'), TERRAIN_SIZE);
gl.uniform1f(gl.getUniformLocation(terrainProg, 'uHeightScale'), HEIGHT_SCALE);
gl.uniform1f(gl.getUniformLocation(terrainProg, 'uTime'), gameTime);

gl.activeTexture(gl.TEXTURE0);
gl.bindTexture(gl.TEXTURE_2D, heightmapTex);
gl.uniform1i(gl.getUniformLocation(terrainProg, 'uHeightmap'), 0);

gl.activeTexture(gl.TEXTURE1);
gl.bindTexture(gl.TEXTURE_2D, watermapTex);
gl.uniform1i(gl.getUniformLocation(terrainProg, 'uWaterMap'), 1);

gl.bindVertexArray(terrainMesh.vao);
gl.drawElements(gl.TRIANGLES, terrainMesh.count, gl.UNSIGNED_INT, 0);

// Draw entities
gl.useProgram(entityProg);
gl.uniformMatrix4fv(gl.getUniformLocation(entityProg, 'uProjection'), false, proj);
gl.uniformMatrix4fv(gl.getUniformLocation(entityProg, 'uView'), false, view);
gl.uniform3fv(gl.getUniformLocation(entityProg, 'uLightDir'), lightDir);
gl.uniform3f(gl.getUniformLocation(entityProg, 'uCameraPos'), eyeX, eyeY, eyeZ);

// Draw water containers
for (const wc of waterContainers) {
if (wc.broken) continue;
let model = mat4Identity();
model = mat4Translate(model, wc.x, wc.y + wc.height/2, wc.z);
model = mat4Scale(model, wc.radius*2, wc.height, wc.radius*2);
gl.uniformMatrix4fv(gl.getUniformLocation(entityProg, 'uModel'), false, model);
gl.uniform3fv(gl.getUniformLocation(entityProg, 'uColor'), wc.color);
gl.uniform1f(gl.getUniformLocation(entityProg, 'uEmissive'), 0);
gl.bindVertexArray(cylinderMesh.vao);
gl.drawElements(gl.TRIANGLES, cylinderMesh.count, gl.UNSIGNED_SHORT, 0);

// Water level indicator
if (wc.water > 0) {
const wh = (wc.water / 50) * wc.height * 0.8;
let wmodel = mat4Identity();
wmodel = mat4Translate(wmodel, wc.x, wc.y + wh/2 + 0.1, wc.z);
wmodel = mat4Scale(wmodel, wc.radius*1.8, wh, wc.radius*1.8);
gl.uniformMatrix4fv(gl.getUniformLocation(entityProg, 'uModel'), false, wmodel);
gl.uniform3f(gl.getUniformLocation(entityProg, 'uColor'), 0.1, 0.3, 0.7);
gl.uniform1f(gl.getUniformLocation(entityProg, 'uEmissive'), 0.1);
gl.bindVertexArray(cylinderMesh.vao);
gl.drawElements(gl.TRIANGLES, cylinderMesh.count, gl.UNSIGNED_SHORT, 0);
}
}

// Draw enemies
for (const e of enemies) {
// Body
let model = mat4Identity();
model = mat4Translate(model, e.x, e.y + 1, e.z);
model = mat4Scale(model, 1.2, 2, 0.8);
gl.uniformMatrix4fv(gl.getUniformLocation(entityProg, 'uModel'), false, model);
const flash = e.hitFlash;
gl.uniform3f(gl.getUniformLocation(entityProg, 'uColor'),
e.color[0] + flash * 0.5, e.color[1] * (1-flash), e.color[2] * (1-flash));
gl.uniform1f(gl.getUniformLocation(entityProg, 'uEmissive'), flash * 0.5);
gl.bindVertexArray(boxMesh.vao);
gl.drawElements(gl.TRIANGLES, boxMesh.count, gl.UNSIGNED_SHORT, 0);

// Head
model = mat4Identity();
model = mat4Translate(model, e.x, e.y + 2.3, e.z);
model = mat4Scale(model, 0.6, 0.6, 0.6);
gl.uniformMatrix4fv(gl.getUniformLocation(entityProg, 'uModel'), false, model);
gl.uniform3f(gl.getUniformLocation(entityProg, 'uColor'),
0.9 + flash*0.1, 0.7*(1-flash), 0.6*(1-flash));
gl.uniform1f(gl.getUniformLocation(entityProg, 'uEmissive'), 0);
gl.bindVertexArray(sphereMesh.vao);
gl.drawElements(gl.TRIANGLES, sphereMesh.count, gl.UNSIGNED_SHORT, 0);

// Health bar
if (e.health < e.maxHealth) {
const hpRatio = e.health / e.maxHealth;
model = mat4Identity();
model = mat4Translate(model, e.x, e.y + 3, e.z);
model = mat4Scale(model, hpRatio * 1.5, 0.15, 0.05);
gl.uniformMatrix4fv(gl.getUniformLocation(entityProg, 'uModel'), false, model);
gl.uniform3f(gl.getUniformLocation(entityProg, 'uColor'), 1-hpRatio, hpRatio, 0);
gl.uniform1f(gl.getUniformLocation(entityProg, 'uEmissive'), 0.3);
gl.bindVertexArray(boxMesh.vao);
gl.drawElements(gl.TRIANGLES, boxMesh.count, gl.UNSIGNED_SHORT, 0);
}
}

// Draw bullets
for (const b of bullets) {
let model = mat4Identity();
model = mat4Translate(model, b.x, b.y, b.z);
model = mat4Scale(model, 0.15, 0.15, 0.15);
gl.uniformMatrix4fv(gl.getUniformLocation(entityProg, 'uModel'), false, model);
gl.uniform3f(gl.getUniformLocation(entityProg, 'uColor'),
b.isEnemy ? 1 : 1, b.isEnemy ? 0.3 : 0.8, b.isEnemy ? 0.1 : 0.2);
gl.uniform1f(gl.getUniformLocation(entityProg, 'uEmissive'), 1.0);
gl.bindVertexArray(sphereMesh.vao);
gl.drawElements(gl.TRIANGLES, sphereMesh.count, gl.UNSIGNED_SHORT, 0);

// Bullet trail
for (let t = 0; t < b.trail.length; t++) {
const tr = b.trail[t];
const alpha = t / b.trail.length;
let tm = mat4Identity();
tm = mat4Translate(tm, tr.x, tr.y, tr.z);
tm = mat4Scale(tm, 0.06 * alpha, 0.06 * alpha, 0.06 * alpha);
gl.uniformMatrix4fv(gl.getUniformLocation(entityProg, 'uModel'), false, tm);
gl.uniform3f(gl.getUniformLocation(entityProg, 'uColor'),
1 * alpha, 0.7 * alpha, 0.2 * alpha);
gl.uniform1f(gl.getUniformLocation(entityProg, 'uEmissive'), alpha);
gl.bindVertexArray(sphereMesh.vao);
gl.drawElements(gl.TRIANGLES, sphereMesh.count, gl.UNSIGNED_SHORT, 0);
}
}

// Draw particles
for (const p of particles) {
const alpha = p.life / p.maxLife;
let model = mat4Identity();
model = mat4Translate(model, p.x, p.y, p.z);
model = mat4Scale(model, p.size * alpha, p.size * alpha, p.size * alpha);
gl.uniformMatrix4fv(gl.getUniformLocation(entityProg, 'uModel'), false, model);
gl.uniform3f(gl.getUniformLocation(entityProg, 'uColor'),
p.color[0], p.color[1], p.color[2]);
gl.uniform1f(gl.getUniformLocation(entityProg, 'uEmissive'), alpha * 0.5);
gl.bindVertexArray(sphereMesh.vao);
gl.drawElements(gl.TRIANGLES, sphereMesh.count, gl.UNSIGNED_SHORT, 0);
}
}

// ============================================================
// MINIMAP
// ============================================================
const minimapCanvas = document.getElementById('minimap');
const mctx = minimapCanvas.getContext('2d');

function drawMinimap() {
const w = minimapCanvas.width, h = minimapCanvas.height;
mctx.fillStyle = '#111';
mctx.fillRect(0, 0, w, h);

const scale = w / TERRAIN_SIZE;
const ox = w / 2, oy = h / 2;

// Terrain heightmap
const imgData = mctx.createImageData(w, h);
for (let y = 0; y < h; y++) {
for (let x = 0; x < w; x++) {
const wx = (x - ox) / scale;
const wz = (y - oy) / scale;
const th = getTerrainHeight(wx, wz) / HEIGHT_SCALE;
const wl = getWaterLevel(wx, wz);
const idx = (y * w + x) * 4;
if (wl > 0.05) {
imgData.data[idx] = 20;
imgData.data[idx+1] = 60 + wl * 200;
imgData.data[idx+2] = 150;
} else {
const v = Math.floor(th * 120 + 30);
imgData.data[idx] = v * 0.6;
imgData.data[idx+1] = v;
imgData.data[idx+2] = v * 0.4;
}
imgData.data[idx+3] = 255;
}
}
mctx.putImageData(imgData, 0, 0);

// Water containers
for (const wc of waterContainers) {
if (wc.broken) continue;
mctx.fillStyle = '#48f';
mctx.beginPath();
mctx.arc(ox + wc.x * scale, oy + wc.z * scale, 3, 0, Math.PI * 2);
mctx.fill();
}

// Enemies
mctx.fillStyle = '#f33';
for (const e of enemies) {
mctx.beginPath();
mctx.arc(ox + e.x * scale, oy + e.z * scale, 2, 0, Math.PI * 2);
mctx.fill();
}

// Player
mctx.fillStyle = '#0f0';
mctx.beginPath();
mctx.arc(ox + player.x * scale, oy + player.z * scale, 3, 0, Math.PI * 2);
mctx.fill();

// Player direction
mctx.strokeStyle = '#0f0';
mctx.lineWidth = 1;
mctx.beginPath();
mctx.moveTo(ox + player.x * scale, oy + player.z * scale);
mctx.lineTo(
ox + (player.x - Math.sin(player.yaw) * 8) * scale,
oy + (player.z - Math.cos(player.yaw) * 8) * scale
);
mctx.stroke();
}

// ============================================================
// UI UPDATE
// ============================================================
function updateUI() {
const hpPct = player.health / player.maxHealth;
const bars = Math.floor(hpPct * 20);
const hpBar = '█'.repeat(bars) + '░'.repeat(20 - bars);
const hpColor = hpPct > 0.5 ? '#0f0' : hpPct > 0.25 ? '#ff0' : '#f00';
document.getElementById('health').innerHTML =
`HP: <span style="color:${hpColor}">${hpBar}</span> ${Math.ceil(player.health)}`;

const ammoText = player.reloading ?
`RELOADING... ${Math.ceil(player.reloadTime * 10)/10}s` :
`AMMO: ${player.ammo} / ${player.reserve}`;
document.getElementById('ammo').textContent = ammoText;
document.getElementById('score').textContent = `SCORE: ${score}`;
document.getElementById('wave').textContent = `WAVE: ${wave} | Enemies: ${enemies.length}`;

const waterStatus = player.inWater ? '🌊 IN WATER - SPEED REDUCED' : '';
document.getElementById('waterStatus').textContent = waterStatus;
document.getElementById('waterStatus').style.color = '#4af';
}

// ============================================================
// INPUT HANDLING
// ============================================================
document.addEventListener('keydown', e => {
keys[e.key.toLowerCase()] = true;
if (e.key.toLowerCase() === 'r') reload();
if (e.key.toLowerCase() === 'e') {
// Interact with nearby containers
for (const wc of waterContainers) {
if (!wc.broken) {
const d = Math.sqrt((player.x-wc.x)**2 + (player.z-wc.z)**2);
if (d < 4) breakContainer(wc);
}
}
}
});
document.addEventListener('keyup', e => { keys[e.key.toLowerCase()] = false; });

canvas.addEventListener('click', () => {
if (!gameOver) canvas.requestPointerLock();
});

document.addEventListener('pointerlockchange', () => {
// Pointer lock changed
});

document.addEventListener('mousemove', e => {
if (document.pointerLockElement === canvas) {
player.yaw += e.movementX * 0.002;
player.pitch -= e.movementY * 0.002;
player.pitch = Math.max(-Math.PI/2.5, Math.min(Math.PI/2.5, player.pitch));
}
});

document.addEventListener('mousedown', e => {
if (e.button === 0) mouseDown = true;
});
document.addEventListener('mouseup', e => {
if (e.button === 0) mouseDown = false;
});

window.addEventListener('resize', () => {
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;
gl.viewport(0, 0, canvas.width, canvas.height);
});

// ============================================================
// GAME INIT & LOOP
// ============================================================
function initGame() {
generateTerrain();
heightmapTex = createDataTexture(heightData);
watermapTex = createDataTexture(waterData);
terrainMesh = createTerrainMesh();
boxMesh = createBoxGeometry();
sphereMesh = createSphereGeometry();
cylinderMesh = createCylinderGeometry();
skyMesh = createSkyMesh();
spawnWaterContainers();

// Initial enemies
for (let i = 0; i < 5; i++) spawnEnemy();

// Place player
player.x = 0;
player.z = 0;
player.y = getTerrainHeight(0, 0);
}

let lastTime = 0;
let fluidTimer = 0;
let minimapTimer = 0;

function gameLoop(time) {
const dt = Math.min((time - lastTime) / 1000, 0.05);
lastTime = time;
gameTime += dt;

if (!gameOver) {
updatePlayer(dt);
updateEnemies(dt);
updateBullets(dt);
updateParticles(dt);

// Fluid simulation at lower rate
fluidTimer += dt;
if (fluidTimer > 0.1) {
simulateFluid(fluidTimer);
fluidTimer = 0;
}
}

render();

// Minimap at lower rate
minimapTimer += dt;
if (minimapTimer > 0.2) {
drawMinimap();
minimapTimer = 0;
}

updateUI();
requestAnimationFrame(gameLoop);
}

function restartGame() {
gameOver = false;
document.getElementById('gameOver').style.display = 'none';
player.health = 100;
player.ammo = 30;
player.reserve = 90;
player.reloading = false;
score = 0;
wave = 1;
enemies = [];
bullets = [];
particles = [];
waterData.fill(0);

generateTerrain();
updateTexture(heightmapTex, heightData);
updateTexture(watermapTex, waterData);
rebuildTerrainMesh();
spawnWaterContainers();

player.x = 0; player.z = 0;
player.y = getTerrainHeight(0, 0);
player.vx = 0; player.vy = 0; player.vz = 0;

for (let i = 0; i < 5; i++) spawnEnemy();
canvas.requestPointerLock();
}

// Check for OES_texture_float_linear
const ext = gl.getExtension('OES_texture_float_linear');
if (!ext) {
// Fallback: use R16F if R32F linear filtering not available
console.warn('Float linear filtering not available, using nearest');
}

// Enable uint32 indices
gl.getExtension('OES_element_index_uint');

initGame();
requestAnimationFrame(gameLoop);
</script>
</body>
</html>
```

## Key Features Implemented

### 🏔️ Perlin Noise Terrain
- **6-octave FBM** (Fractal Brownian Motion) for realistic terrain
- Ridge noise overlay for mountain features
- Flattened center area for gameplay balance
- Bilinear interpolation for smooth height sampling

### 💥 Terrain Destruction
- **Gaussian falloff craters** — bullets create smooth, realistic depressions
- Heightmap texture updated on GPU in real-time
- Terrain mesh rebuilt dynamically after impacts
- Crater darkening in the shader for visual depth

### 🌊 Fluid Simulation
- **Grid-based water flow** — water spreads based on height differentials
- Water containers that can be shot or interacted with (E key)
- Water affects movement speed (45% slowdown for both player and enemies)
- Water rendering with animated waves and specular highlights
- Gradual evaporation system

### 🎮 Gameplay Systems
- **Wave-based enemy AI** with patrol/chase states
- Enemies shoot back with visible bullet trails
- Cover system — destroy terrain to eliminate enemy cover
- Health, ammo, reload mechanics
- Minimap with real-time terrain/water/enemy display

### 🎨 WebGL Rendering
- Custom GLSL shaders for terrain, entities, sky, and particles
- **Phong lighting** with specular highlights
- Distance fog for atmosphere
- Procedural sky with sun
- Particle system for impacts, muzzle flash, water splashes, and death effects

### Controls
| Key | Action |
|-----|--------|
| WASD | Move |
| Mouse | Aim |
| Click | Shoot |
| R | Reload |
| Space | Jump |
| E | Break nearby water container |

# Online Webpage Screenshot Tool

A full-stack web application that captures webpage screenshots using **Node.js + Express + Puppeteer** on the backend and a polished UI on the frontend.

