## 2. `server.js` — Backend (Express + Puppeteer)

```javascript
const express = require('express');
const puppeteer = require('puppeteer');
const cors = require('cors');
const path = require('path');
const fs = require('fs');
const { v4: uuidv4 } = require('uuid');

const app = express();
const PORT = process.env.PORT || 3000;

// Middleware
app.use(cors());
app.use(express.json());
app.use(express.static(path.join(__dirname, 'public')));

// Ensure screenshots directory exists
const SCREENSHOTS_DIR = path.join(__dirname, 'screenshots');
if (!fs.existsSync(SCREENSHOTS_DIR)) {
    fs.mkdirSync(SCREENSHOTS_DIR, { recursive: true });
}

// Browser pool for better performance
let browserInstance = null;

async function getBrowser() {
    if (!browserInstance || !browserInstance.isConnected()) {
        browserInstance = await puppeteer.launch({
            headless: 'new',
            args: [
                '--no-sandbox',
                '--disable-setuid-sandbox',
                '--disable-dev-shm-usage',
                '--disable-gpu',
                '--disable-extensions',
                '--disable-background-networking',
                '--disable-default-apps',
                '--disable-sync',
                '--disable-translate',
                '--metrics-recording-only',
                '--no-first-run',
                '--safebrowsing-disable-auto-update'
            ]
        });
    }
    return browserInstance;
}

// Validate URL
function isValidUrl(string) {
    try {
        const url = new URL(string);
        return url.protocol === 'http:' || url.protocol === 'https:';
    } catch (_) {
        return false;
    }
}

// Normalize URL - add https:// if missing
function normalizeUrl(url) {
    url = url.trim();
    if (!url.startsWith('http://') && !url.startsWith('https://')) {
        url = 'https://' + url;
    }
    return url;
}

/**
 * POST /api/screenshot
 * Captures a screenshot of the given URL
 * 
 * Body: { url, width, height, fullPage, deviceType }
 */
app.post('/api/screenshot', async (req, res) => {
    const {
        url: rawUrl,
        width = 1280,
        height = 800,
        fullPage = false,
        deviceType = 'desktop',
        thumbnailWidth = 480
    } = req.body;

    // Validate URL
    const url = normalizeUrl(rawUrl || '');
    if (!isValidUrl(url)) {
        return res.status(400).json({
            success: false,
            error: 'Invalid URL. Please enter a valid URL starting with http:// or https://'
        });
    }

    // Device presets
    const devicePresets = {
        desktop: { width: 1920, height: 1080, userAgent: 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36' },
        tablet: { width: 768, height: 1024, userAgent: 'Mozilla/5.0 (iPad; CPU OS 16_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/16.0 Safari/605.1.15' },
        mobile: { width: 375, height: 812, userAgent: 'Mozilla/5.0 (iPhone; CPU iPhone OS 16_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/16.0 Mobile/15E148 Safari/604.1' }
    };

    const device = devicePresets[deviceType] || devicePresets.desktop;
    const viewportWidth = parseInt(width) || device.width;
    const viewportHeight = parseInt(height) || device.height;

    let page = null;

    try {
        const browser = await getBrowser();
        page = await browser.newPage();

        // Set viewport and user agent
        await page.setViewport({
            width: viewportWidth,
            height: viewportHeight,
            deviceScaleFactor: 2  // Retina quality
        });
        await page.setUserAgent(device.userAgent);

        // Block heavy resources for faster loading
        await page.setRequestInterception(true);
        page.on('request', (request) => {
            const resourceType = request.resourceType();
            if (['font', 'media'].includes(resourceType)) {
                request.abort();
            } else {
                request.continue();
            }
        });

        // Navigate to URL
        await page.goto(url, {
            waitUntil: 'networkidle2',
            timeout: 30000
        });

        // Wait a bit for any lazy-loaded content
        await new Promise(resolve => setTimeout(resolve, 1500));

        // Generate unique filename
        const screenshotId = uuidv4();
        const fullFilename = `${screenshotId}_full.png`;
        const thumbFilename = `${screenshotId}_thumb.png`;
        const fullPath = path.join(SCREENSHOTS_DIR, fullFilename);
        const thumbPath = path.join(SCREENSHOTS_DIR, thumbFilename);

        // Take full screenshot
        const fullScreenshotBuffer = await page.screenshot({
            fullPage: fullPage,
            type: 'png',
            encoding: 'binary'
        });

        // Save full screenshot
        fs.writeFileSync(fullPath, fullScreenshotBuffer);

        // Create thumbnail using a second screenshot with clip
        const thumbPage = await browser.newPage();
        await thumbPage.setViewport({
            width: viewportWidth,
            height: viewportHeight,
            deviceScaleFactor: 1
        });
        await thumbPage.setUserAgent(device.userAgent);

        await thumbPage.setRequestInterception(true);
        thumbPage.on('request', (request) => {
            const resourceType = request.resourceType();
            if (['font', 'media'].includes(resourceType)) {
                request.abort();
            } else {
                request.continue();
            }
        });

        await thumbPage.goto(url, {
            waitUntil: 'networkidle2',
            timeout: 30000
        });
        await new Promise(resolve => setTimeout(resolve, 1000));

        // Capture thumbnail (viewport-sized crop)
        const thumbBuffer = await thumbPage.screenshot({
            fullPage: false,
            type: 'png',
            encoding: 'binary',
            clip: {
                x: 0,
                y: 0,
                width: viewportWidth,
                height: viewportHeight
            }
        });

        fs.writeFileSync(thumbPath, thumbBuffer);
        await thumbPage.close();

        // Get page title
        const pageTitle = await page.title() || url;

        await page.close();

        // Return result
        res.json({
            success: true,
            data: {
                id: screenshotId,
                url: url,
                title: pageTitle,
                viewport: { width: viewportWidth, height: viewportHeight },
                deviceType: deviceType,
                fullImage: `/screenshots/${fullFilename}`,
                thumbnail: `/screenshots/${thumbFilename}`,
                timestamp: new Date().toISOString()
            }
        });

    } catch (error) {
        console.error('Screenshot error:', error.message);

        if (page) {
            try { await page.close(); } catch (e) { /* ignore */ }
        }

        let errorMessage = 'Failed to capture screenshot.';
        if (error.message.includes('net::ERR_NAME_NOT_RESOLVED')) {
            errorMessage = 'Domain not found. Please check the URL.';
        } else if (error.message.includes('net::ERR_CONNECTION_REFUSED')) {
            errorMessage = 'Connection refused. The website may be down.';
        } else if (error.message.includes('Navigation timeout')) {
            errorMessage = 'Page load timed out. The website may be too slow.';
        } else if (error.message.includes('net::ERR_CERT')) {
            errorMessage = 'SSL certificate error. The website may have security issues.';
        }

        res.status(500).json({
            success: false,
            error: errorMessage
        });
    }
});

// Serve screenshots statically
app.use('/screenshots', express.static(SCREENSHOTS_DIR));

/**
 * GET /api/screenshot/:id/download
 * Download a screenshot file
 */
app.get('/api/screenshot/:filename/download', (req, res) => {
    const filename = req.params.filename;
    const filePath = path.join(SCREENSHOTS_DIR, filename);

    if (!fs.existsSync(filePath)) {
        return res.status(404).json({ success: false, error: 'File not found' });
    }

    res.download(filePath, `screenshot_${Date.now()}.png`);
});

/**
 * DELETE /api/screenshots/cleanup
 * Clean up old screenshots (older than 1 hour)
 */
app.delete('/api/screenshots/cleanup', (req, res) => {
    const now = Date.now();
    const oneHour = 60 * 60 * 1000;
    let deletedCount = 0;

    fs.readdirSync(SCREENSHOTS_DIR).forEach(file => {
        const filePath = path.join(SCREENSHOTS_DIR, file);
        const stats = fs.statSync(filePath);
        if (now - stats.mtimeMs > oneHour) {
            fs.unlinkSync(filePath);
            deletedCount++;
        }
    });

    res.json({ success: true, deleted: deletedCount });
});

// Health check
app.get('/api/health', (req, res) => {
    res.json({
        status: 'ok',
        browserConnected: browserInstance ? browserInstance.isConnected() : false,
        uptime: process.uptime()
    });
});

// Graceful shutdown
process.on('SIGINT', async () => {
    console.log('\nShutting down gracefully...');
    if (browserInstance) {
        await browserInstance.close();
    }
    process.exit(0);
});

process.on('SIGTERM', async () => {
    if (browserInstance) {
        await browserInstance.close();
    }
    process.exit(0);
});

// Start server
app.listen(PORT, () => {
    console.log(`
╔══════════════════════════════════════════════════╗
║   📸 Webpage Screenshot Tool                     ║
║   Server running at http://localhost:${PORT}        ║
║   Press Ctrl+C to stop                           ║
╚══════════════════════════════════════════════════╝
    `);
});
