.device-btn {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 8px 14px;
    background: none;
    border: none;
    border-radius: 6px;
    color: var(--text-secondary);
    font-size: 0.82rem;
    font-weight: 500;
    font-family: inherit;
    cursor: pointer;
    transition: var(--transition);
}

.device-btn:hover {
    color: var(--text-primary);
    background: rgba(99, 102, 241, 0.1);
}

.device-btn.active {
    background: var(--primary);
    color: white;
    box-shadow: 0 2px 8px var(--primary-glow);
}

.device-btn svg {
    display: flex;
}

/* Toggle */
.toggle-group {
    display: flex;
    align-items: center;
}

.toggle {
    display: flex;
    align-items: center;
    gap: 10px;
    cursor: pointer;
    user-select: none;
}

.toggle input {
    display: none;
}

.toggle-slider {
    width: 44px;
    height: 24px;
    background: var(--bg-input);
    border: 1px solid var(--border);
    border-radius: 12px;
    position: relative;
    transition: var(--transition);
}

.toggle-slider::after {
    content: '';
    position: absolute;
    width: 18px;
    height: 18px;
    background: var(--text-muted);
    border-radius: 50%;
    top: 2px;
    left: 2px;
    transition: var(--transition);
}

.toggle input:checked + .toggle-slider {
    background: var(--primary);
    border-color: var(--primary);
}

.toggle input:checked + .toggle-slider::after {
    transform: translateX(20px);
    background: white;
}

.toggle-label {
    font-size: 0.85rem;
    color: var(--text-secondary);
    font-weight: 500;
}

/* Size Inputs */
.size-inputs {
    display: flex;
    align-items: center;
    gap: 6px;
}

.size-input {
    width: 72px;
    padding: 8px 10px;
    background: var(--bg-input);
    border: 1px solid var(--border);
    border-radius: 6px;
    color: var(--text-primary);
    font-size: 0.85rem;
    font-family: inherit;
    text-align: center;
    outline: none;
    transition: var(--transition);
}

.size-input:focus {
    border-color: var(--primary);
    box-shadow: 0 0 0 3px var(--primary-glow);
}

.size-input::placeholder {
    color: var(--text-muted);
}

.size-separator {
    color: var(--text-muted);
    font-size: 0.85rem;
}

/* ============================================
   Loading State
   ============================================ */
.loading-state {
    text-align: center;
    padding: 60px 20px;
    animation: fadeIn 0.3s ease;
}

.loader {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 24px;
}

.loader-camera {
    color: var(--primary-light);
    animation: pulse 2s ease-in-out infinite;
}

@keyframes pulse {
    0%, 100% { opacity: 1; transform: scale(1); }
    50% { opacity: 0.6; transform: scale(0.95); }
}

.loader-bar {
    width: 240px;
    height: 4px;
    background: var(--bg-input);
    border-radius: 2px;
    overflow: hidden;
}

.loader-bar-fill {
    height: 100%;
    background: linear-gradient(90deg, var(--primary), var(--accent));
    border-radius: 2px;
    animation: loading 2s ease-in-out infinite;
}

@keyframes loading {
    0% { width: 0%; margin-left: 0; }
    50% { width: 60%; margin-left: 20%; }
    100% { width: 0%; margin-left: 100%; }
}

.loading-text {
    font-size: 1.1rem;
    font-weight: 600;
    color: var(--text-primary);
    margin-top: 8px;
}

.loading-dots::after {
    content: '';
    animation: dots 1.5s steps(4, end) infinite;
}

@keyframes dots {
    0% { content: ''; }
    25% { content: '.'; }
    50% { content: '..'; }
    75% { content: '...'; }
}

.loading-subtext {
    font-size: 0.9rem;
    color: var(--text-muted);
    margin-top: 4px;
}

/* ============================================
   Error State
   ============================================ */
.error-state {
    text-align: center;
    padding: 48px 20px;
    animation: fadeIn 0.3s ease;
}

.error-icon {
    color: var(--error);
    margin-bottom: 16px;
    display: inline-flex;
}

.error-text {
    font-size: 1.05rem;
    color: var(--text-secondary);
    margin-bottom: 20px;
    max-width: 400px;
    margin-left: auto;
    margin-right: auto;
}

.retry-btn {
    padding: 10px 24px;
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: var(--radius-sm);
    color: var(--text-primary);
    font-size: 0.9rem;
    font-weight: 500;
    font-family: inherit;
    cursor: pointer;
    transition: var(--transition);
}

.retry-btn:hover {
    border-color: var(--primary);
    background: var(--bg-card-hover);
}

/* ============================================
   Result Section
   ============================================ */
.result-section {
    animation: fadeIn 0.5s ease;
}

.result-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 20px;
    margin-bottom: 24px;
    flex-wrap: wrap;
}

.result-title {
    font-size: 1.4rem;
    font-weight: 700;
    color: var(--success);
    display: flex;
    align-items: center;
    gap: 8px;
}

.result-title::before {
    content: '✓';
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    background: var(--success);
    color: white;
    border-radius: 50%;
    font-size: 0.85rem;
    font-weight: 700;
}

.result-url {
    font-size: 0.85rem;
    color: var(--text-muted);
    margin-top: 4px;
    word-break: break-all;
}

.result-actions {
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
}

.action-btn {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 10px 18px;
    border: 1px solid var(--border);
    border-radius: var(--radius-sm);
    font-size: 0.85rem;
    font-weight: 500;
    font-family: inherit;
    cursor: pointer;
    transition: var(--transition);
}

.action-btn svg {
    display: flex;
}

.action-btn-primary {
    background: linear-gradient(135deg, var(--primary), var(--primary-dark));
    color: white;
    border-color: transparent;
}

.action-btn-primary:hover {
    box-shadow: 0 4px 16px var(--primary-glow);
    transform: translateY(-1px);
}

.action-btn-secondary {
    background: var(--bg-card);
    color: var(--text-primary);
}

.action-btn-secondary:hover {
    border-color: var(--primary);
    background: var(--bg-card-hover);
}

.action-btn-ghost {
    background: transparent;
    color: var(--text-secondary);
}

.action-btn-ghost:hover {
    color: var(--text-primary);
    border-color: var(--border-hover);
}

/* ============================================
   Screenshot Preview (Browser Frame)
   ============================================ */
.screenshot-preview {
    margin-bottom: 32px;
}

.browser-frame {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    overflow: hidden;
    box-shadow: var(--shadow-lg);
}

.browser-bar {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 12px 18px;
    background: var(--bg-secondary);
    border-bottom: 1px solid var(--border);
}

.browser-dots {
    display: flex;
    gap: 7px;
}

.dot {
    width: 12px;
    height: 12px;
    border-radius: 50%;
}

.dot-red { background: #ff5f57; }
.dot-yellow { background: #febc2e; }
.dot-green { background: #28c840; }

.browser-url-bar {
    flex: 1;
    padding: 6px 14px;
    background: var(--bg-input);
    border-radius: 6px;
    font-size: 0.8rem;
    color: var(--text-muted);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.browser-content {
    background: #fff;
    max-height: 500px;
    overflow-y: auto;
}

.browser-content::-webkit-scrollbar {
    width: 8px;
}

.browser-content::-webkit-scrollbar-track {
    background: var(--bg-secondary);
}

.browser-content::-webkit-scrollbar-thumb {
    background: var(--text-muted);
    border-radius: 4px;
}

.screenshot-img {
    width: 100%;
    display: block;
}

/* ============================================
   Thumbnail Section
   ============================================ */
.section-subtitle {
    font-size: 0.85rem;
    font-weight: 600;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin-bottom: 14px;
}

.thumbnail-section {
    margin-bottom: 40px;
}

.thumbnail-card {
    display: inline-block;
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: var(--radius-md);
    overflow: hidden;
    box-shadow: var(--shadow-sm);
    transition: var(--transition);
    max-width: 320px;
}

.thumbnail-card:hover {
    border-color: var(--border-hover);
    transform: translateY(-2px);
    box-shadow: var(--shadow-md);
}

.thumbnail-img {
    width: 100%;
    display: block;
}

/* ============================================
   History Section
   ============================================ */
.history-section {
    margin-top: 48px;
    padding-top: 32px;
    border-top: 1px solid var(--border);
}

.history-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
    gap: 16px;
}

.history-item {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: var(--radius-md);
    overflow: hidden;
    cursor: pointer;
    transition: var(--transition);
}

.history-item:hover {
    border-color: var(--border-hover);
    transform: translateY(-2px);
    box-shadow: var(--shadow-md);
}

.history-item img {
    width: 100%;
    height: 120px;
    object-fit: cover;
    display: block;
}

.history-item-info {
    padding: 10px 12px;
}

.history-item-title {
    font-size: 0.8rem;
    font-weight: 500;
    color: var(--text-primary);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.history-item-url {
    font-size: 0.7rem;
    color: var(--text-muted);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    margin-top: 2px;
}

/* ============================================
   Footer
   ============================================ */
.footer {
    text-align: center;
    padding: 32px 0 16px;
    color: var(--text-muted);
    font-size: 0.82rem;
}

/* ============================================
   Utility
   ============================================ */
.hidden {
    display: none !important;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(12px); }
    to { opacity: 1; transform: translateY(0); }
}

/* ============================================
   Responsive
   ============================================ */
@media (max-width: 768px) {
    .container {
        padding: 24px 16px;
    }

    .logo h1 {
        font-size: 1.8rem;
    }

    .url-input-group {
        flex-wrap: wrap;
        padding: 12px;
    }

    .url-input {
        width: 100%;
        order: 1;
    }

    .url-icon {
        order: 0;
    }

    .capture-btn {
        width: 100%;
        justify-content: center;
        order: 2;
        padding: 14px;
    }

    .options-row {
        flex-direction: column;
        gap: 16px;
    }

    .result-header {
        flex-direction: column;
    }

    .result-actions {
        width: 100%;
    }

    .action-btn {
        flex: 1;
        justify-content: center;
    }

    .device-btn span {
        display: none;
    }

    .device-btn {
        padding: 8px 12px;
    }
}

@media (max-width: 480px) {
    .history-grid {
        grid-template-columns: repeat(2, 1fr);
    }
}
