## 5. `public/app.js` — Frontend Logic

```javascript
/**
 * WebShot — Frontend Application Logic
 */
(function () {
    'use strict';

    // ============================================
    // DOM Elements
    // ============================================
    const $ = (sel) => document.querySelector(sel);
    const $$ = (sel) => document.querySelectorAll(sel);

    const urlInput = $('#urlInput');
    const captureBtn = $('#captureBtn');
    const fullPageToggle = $('#fullPageToggle');
    const widthInput = $('#widthInput');
    const heightInput = $('#heightInput');
    const deviceBtns = $$('.device-btn');

    const loadingState = $('#loadingState');
    const loadingSubtext = $('#loadingSubtext');
    const errorState = $('#errorState');
    const errorText = $('#errorText');
    const retryBtn = $('#retryBtn');

    const resultSection = $('#resultSection');
    const resultTitle = $('#resultTitle');
    const resultUrl = $('#resultUrl');
    const screenshotImage = $('#screenshotImage');
    const thumbnailImage = $('#thumbnailImage');
    const browserUrlBar = $('#browserUrlBar');

    const downloadFullBtn = $('#downloadFullBtn');
    const downloadThumbBtn = $('#downloadThumbBtn');
    const newCaptureBtn = $('#newCaptureBtn');

    const historySection = $('#historySection');
    const historyGrid = $('#historyGrid');

    // ============================================
    // State
    // ============================================
    let currentDevice = 'desktop';
    let currentResult = null;
    let history = JSON.parse(localStorage.getItem('webshot_history') || '[]');

    // ============================================
    // Loading Messages
    // ============================================
    const loadingMessages = [
        'Navigating to page...',
        'Waiting for content to load...',
        'Rendering the page...',
        'Capturing screenshot...',
        'Processing image...',
        'Almost done...'
    ];

    // ============================================
    // Event Listeners
    // ============================================

    // Device selector
    deviceBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            deviceBtns.forEach(b => b.classList.remove('active'));
            btn.classList.add('active');
            currentDevice = btn.dataset.device;

            // Clear custom size when switching device
            widthInput.value = '';
            heightInput.value = '';
        });
    });

    // Capture button
    captureBtn.addEventListener('click', handleCapture);

    // Enter key
    urlInput.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') {
            handleCapture();
        }
    });

    // Retry button
    retryBtn.addEventListener('click', handleCapture);

    // Download buttons
    downloadFullBtn.addEventListener('click', () => {
        if (currentResult) {
            downloadFile(currentResult.fullImage, `screenshot_full_${Date.now()}.png`);
        }
    });

    downloadThumbBtn.addEventListener('click', () => {
        if (currentResult) {
            downloadFile(currentResult.thumbnail, `screenshot_thumb_${Date.now()}.png`);
        }
    });

    // New capture
    newCaptureBtn.addEventListener('click', () => {
        showInputState();
        urlInput.focus();
        urlInput.select();
    });

    // ============================================
    // Core Functions
    // ============================================

    async function handleCapture() {
        const url = urlInput.value.trim();

        if (!url) {
            urlInput.focus();
            shakeElement(urlInput.closest('.url-input-group'));
            return;
        }

        // Show loading
        showLoadingState();
        startLoadingMessages();

        // Build request body
        const body = {
            url: url,
            fullPage: fullPageToggle.checked,
            deviceType: currentDevice
        };

        // Custom dimensions
        const customWidth = parseInt(widthInput.value);
        const customHeight = parseInt(heightInput.value);
        if (customWidth && customWidth >= 320) body.width = customWidth;
        if (customHeight && customHeight >= 240) body.height = customHeight;

        try {
            const response = await fetch('/api/screenshot', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(body)
            });

            const data = await response.json();

            if (!response.ok || !data.success) {
                throw new Error(data.error || 'Failed to capture screenshot');
            }

            // Success!
            currentResult = data.data;
            showResult(data.data);
            addToHistory(data.data);

        } catch (error) {
            showError(error.message);
        } finally {
            stopLoadingMessages();
        }
    }

    // ============================================
    // UI State Management
    // ============================================

    function showInputState() {
        loadingState.classList.add('hidden');
        errorState.classList.add('hidden');
        resultSection.classList.add('hidden');
    }

    function showLoadingState() {
        captureBtn.disabled = true;
        loadingState.classList.remove('hidden');
        errorState.classList.add('hidden');
        resultSection.classList.add('hidden');
    }

    function showError(message) {
        captureBtn.disabled = false;
        loadingState.classList.add('hidden');
        errorState.classList.remove('hidden');
        resultSection.classList.add('hidden');
        errorText.textContent = message;
    }

    function showResult(data) {
        captureBtn.disabled = false;
        loadingState.classList.add('hidden');
        errorState.classList.add('hidden');
        resultSection.classList.remove('hidden');

        // Populate result
        resultTitle.textContent = 'Screenshot Captured!';
        resultUrl.textContent = data.url;
        browserUrlBar.textContent = data.url;

        // Load images with cache busting
        const timestamp = Date.now();
        screenshotImage.src = `${data.fullImage}?t=${timestamp}`;
        thumbnailImage.src = `${data.thumbnail}?t=${timestamp}`;

        // Scroll to result
        resultSection.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }

    // ============================================
    // Loading Messages Animation
    // ============================================
    let loadingInterval = null;
    let messageIndex = 0;

    function startLoadingMessages() {
        messageIndex = 0;
        loadingSubtext.textContent = loadingMessages[0];
        loadingInterval = setInterval(() => {
            messageIndex = (messageIndex + 1) % loadingMessages.length;
            loadingSubtext.style.opacity = '0';
            setTimeout(() => {
                loadingSubtext.textContent = loadingMessages[messageIndex];
                loadingSubtext.style.opacity = '1';
            }, 200);
        }, 3000);
    }

    function stopLoadingMessages() {
        if (loadingInterval) {
            clearInterval(loadingInterval);
            loadingInterval = null;
        }
    }

    // ============================================
    // History Management
    // ============================================

    function addToHistory(data) {
        const entry = {
            id: data.id,
            url: data.url,
            title: data.title,
            thumbnail: data.thumbnail,
            fullImage: data.fullImage,
            timestamp: data.timestamp
        };

        // Add to beginning, limit to 12
        history.unshift(entry);
        if (history.length > 12) history = history.slice(0, 12);

        localStorage.setItem('webshot_history', JSON.stringify(history));
        renderHistory();
    }

    function renderHistory() {
        if (history.length === 0) {
            historySection.classList.add('hidden');
            return;
        }

        historySection.classList.remove('hidden');
        historyGrid.innerHTML = '';

        history.forEach(entry => {
            const item = document.createElement('div');
            item.className = 'history-item';
            item.innerHTML = `
                <img src="${entry.thumbnail}" alt="${entry.title}" loading="lazy"
                     onerror="this.src='data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 width=%22200%22 height=%22120%22><rect fill=%22%231e1e42%22 width=%22200%22 height=%22120%22/><text fill=%22%2364748b%22 x=%2250%25%22 y=%2250%25%22 text-anchor=%22middle%22 dy=%22.3em%22 font-size=%2212%22>Expired</text></svg>'">
                <div class="history-item-info">
                    <div class="history-item-title">${escapeHtml(entry.title || 'Untitled')}</div>
                    <div class="history-item-url">${escapeHtml(entry.url)}</div>
                </div>
            `;

            item.addEventListener('click', () => {
                currentResult = entry;
                showResult(entry);
            });

            historyGrid.appendChild(item);
        });
    }

    // ============================================
    // Download Helper
    // ============================================

    function downloadFile(url, filename) {
        // Extract the actual filename from the URL path
        const pathFilename = url.split('/').pop().split('?')[0];
        const downloadUrl = `/api/screenshot/${pathFilename}/download`;

        const a = document.createElement('a');
        a.href = downloadUrl;
        a.download = filename;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
    }

    // ============================================
    // Utilities
    // ============================================

    function escapeHtml(text) {
        const div = document.createElement('div');
        div.textContent = text;
        return div.innerHTML;
    }

    function shakeElement(el) {
        el.style.animation = 'none';
        el.offsetHeight; // Trigger reflow
        el.style.animation = 'shake 0.5s ease';
        setTimeout(() => { el.style.animation = ''; }, 500);
    }

    // Add shake keyframes dynamically
    const shakeStyle = document.createElement('style');
    shakeStyle.textContent = `
        @keyframes shake {
            0%, 100% { transform: translateX(0); }
            20% { transform: translateX(-8px); }
            40% { transform: translateX(8px); }
            60% { transform: translateX(-4px); }
            80% { transform: translateX(4px); }
        }
    `;
    document.head.appendChild(shakeStyle);

    // ============================================
    // Initialize
    // ============================================
    renderHistory();
    urlInput.focus();

    // Add transition to loading subtext
    loadingSubtext.style.transition = 'opacity 0.2s ease';

})();
