├── package.json
├── server.js
├── database.js
├── middleware/
│   └── auth.js
├── routes/
│   ├── auth.js
│   ├── users.js
│   ├── projects.js
│   └── documents.js
├── services/
│   └── apiDocGenerator.js
└── public/
    └── index.html
```

