## 3. `database.js` — SQLite schema & seed

```javascript
const Database = require('better-sqlite3');
const bcrypt = require('bcryptjs');
const path = require('path');

const db = new Database(path.join(__dirname, 'docmanager.db'));
db.pragma('journal_mode = WAL');
db.pragma('foreign_keys = ON');

db.exec(`
  CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    username TEXT UNIQUE NOT NULL,
    password_hash TEXT NOT NULL,
    role TEXT NOT NULL DEFAULT 'member',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );

  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    description TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );

  CREATE TABLE IF NOT EXISTS project_members (
    project_id INTEGER NOT NULL,
    user_id INTEGER NOT NULL,
    role TEXT NOT NULL DEFAULT 'viewer',
    PRIMARY KEY (project_id, user_id),
    FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
  );

  CREATE TABLE IF NOT EXISTS documents (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL,
    title TEXT NOT NULL,
    type TEXT NOT NULL DEFAULT 'spec',
    content TEXT NOT NULL DEFAULT '',
    current_version INTEGER NOT NULL DEFAULT 1,
    created_by INTEGER NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE,
    FOREIGN KEY (created_by) REFERENCES users(id)
  );

  CREATE TABLE IF NOT EXISTS document_versions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    document_id INTEGER NOT NULL,
    version INTEGER NOT NULL,
    content TEXT NOT NULL,
    change_note TEXT,
    created_by INTEGER NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (document_id) REFERENCES documents(id) ON DELETE CASCADE,
    FOREIGN KEY (created_by) REFERENCES users(id),
    UNIQUE(document_id, version)
  );
`);

// Seed default admin
const existing = db.prepare('SELECT id FROM users WHERE username = ?').get('admin');
if (!existing) {
  const hash = bcrypt.hashSync('admin123', 10);
  db.prepare('INSERT INTO users (username, password_hash, role) VALUES (?, ?, ?)')
    .run('admin', hash, 'admin');
}

module.exports = db;
```

## 4. `middleware/auth.js`

```javascript
const jwt = require('jsonwebtoken');
const SECRET = process.env.JWT_SECRET || 'dev-secret-change-me';

function authenticate(req, res, next) {
  const header = req.headers.authorization || '';
  const token = header.startsWith('Bearer ') ? header.slice(7) : null;
  if (!token) return res.status(401).json({ error: 'Authentication required' });
  try {
    req.user = jwt.verify(token, SECRET);
    next();
  } catch {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

function requireAdmin(req, res, next) {
  if (req.user.role !== 'admin') return res.status(403).json({ error: 'Admin only' });
  next();
}

module.exports = { authenticate, requireAdmin, SECRET };
```

## 5. `services/apiDocGenerator.js` — Auto-generate API docs from YAML/JSON

```javascript
const yaml = require('js-yaml');

/**
 * Accepts a YAML or JSON string describing API endpoints and returns Markdown.
 * Schema:
 *   title: User Service API
 *   version: 1.0.0
 *   baseUrl: https://api.example.com
 *   endpoints:
 *     - method: GET
 *       path: /users
 *       summary: List users
 *       description: Returns a paginated list of users.
 *       parameters:
 *         - name: page
 *           in: query
 *           type: integer
 *           required: false
 *           description: Page number
 *       responses:
 *         200: { description: OK, body: "{ \"users\": [] }" }
 *         401: { description: Unauthorized }
 */
function generateApiDoc(input) {
  let spec;
  try { spec = yaml.load(input); }
  catch { spec = JSON.parse(input); }

  const lines = [];
  lines.push(`# ${spec.title || 'API Documentation'}`);
  if (spec.version) lines.push(`**Version:** ${spec.version}  `);
  if (spec.baseUrl) lines.push(`**Base URL:** \`${spec.baseUrl}\`  `);
  lines.push('');
  lines.push('---');
  lines.push('');
  lines.push('## Endpoints');
  lines.push('');

  for (const ep of spec.endpoints || []) {
    lines.push(`### \`${ep.method.toUpperCase()} ${ep.path}\``);
    if (ep.summary) lines.push(`**${ep.summary}**`);
    if (ep.description) lines.push('');
    if (ep.description) lines.push(ep.description);
    lines.push('');

    if (ep.parameters && ep.parameters.length) {
      lines.push('#### Parameters');
      lines.push('| Name | In | Type | Required | Description |');
      lines.push('|------|----|------|----------|-------------|');
      for (const p of ep.parameters) {
        lines.push(`| ${p.name} | ${p.in} | ${p.type || 'string'} | ${p.required ? 'Yes' : 'No'} | ${p.description || ''} |`);
      }
      lines.push('');
    }

    if (ep.requestBody) {
      lines.push('#### Request Body');
      lines.push('```json');
      lines.push(typeof ep.requestBody === 'string' ? ep.requestBody : JSON.stringify(ep.requestBody, null, 2));
      lines.push('```');
      lines.push('');
    }

    if (ep.responses) {
      lines.push('#### Responses');
      for (const [code, r] of Object.entries(ep.responses)) {
        lines.push(`- **${code}** — ${r.description || ''}`);
        if (r.body) {
          lines.push('  ```json');
          lines.push('  ' + r.body.split('\n').join('\n  '));
          lines.push('  ```');
        }
      }
      lines.push('');
    }
    lines.push('---');
    lines.push('');
  }

  lines.push(`*Auto-generated on ${new Date().toISOString()}*`);
  return lines.join('\n');
}

module.exports = { generateApiDoc };
```

## 6. `routes/auth.js`

```javascript
const express = require('express');
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const db = require('../database');
const { SECRET, authenticate } = require('../middleware/auth');

const router = express.Router();

router.post('/register', (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) return res.status(400).json({ error: 'Missing fields' });
  const exists = db.prepare('SELECT id FROM users WHERE username = ?').get(username);
  if (exists) return res.status(409).json({ error: 'Username taken' });
  const hash = bcrypt.hashSync(password, 10);
  const info = db.prepare('INSERT INTO users (username, password_hash) VALUES (?, ?)').run(username, hash);
  const token = jwt.sign({ id: info.lastInsertRowid, username, role: 'member' }, SECRET, { expiresIn: '7d' });
  res.json({ token, user: { id: info.lastInsertRowid, username, role: 'member' } });
});

router.post('/login', (req, res) => {
  const { username, password } = req.body;
  const user = db.prepare('SELECT * FROM users WHERE username = ?').get(username);
  if (!user || !bcrypt.compareSync(password, user.password_hash)) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }
  const token = jwt.sign({ id: user.id, username: user.username, role: user.role }, SECRET, { expiresIn: '7d' });
  res.json({ token, user: { id: user.id, username: user.username, role: user.role } });
});

router.get('/me', authenticate, (req, res) => {
  res.json({ user: req.user });
});

module.exports = router;
```

