## 8. `routes/projects.js` — Projects + team membership

```javascript
const express = require('express');
const db = require('../database');
const { authenticate, requireAdmin } = require('../middleware/auth');

const router = express.Router();

function isProjectMember(userId, projectId) {
  const user = db.prepare('SELECT role FROM users WHERE id = ?').get(userId);
  if (user && user.role === 'admin') return 'admin';
  const m = db.prepare('SELECT role FROM project_members WHERE project_id = ? AND user_id = ?').get(projectId, userId);
  return m ? m.role : null;
}

function requireProjectRole(...roles) {
  return (req, res, next) => {
    const role = isProjectMember(req.user.id, req.params.id);
    if (!role) return res.status(403).json({ error: 'No access' });
    if (!roles.includes(role) && role !== 'admin') return res.status(403).json({ error: 'Insufficient role' });
    req.projectRole = role;
    next();
  };
}

router.get('/', authenticate, (req, res) => {
  let projects;
  if (req.user.role === 'admin') {
    projects = db.prepare('SELECT * FROM projects ORDER BY created_at DESC').all();
  } else {
    projects = db.prepare(`
      SELECT p.* FROM projects p
      JOIN project_members pm ON pm.project_id = p.id
      WHERE pm.user_id = ? ORDER BY p.created_at DESC
    `).all(req.user.id);
  }
  res.json({ projects });
});

router.post('/', authenticate, (req, res) => {
  const { name, description } = req.body;
  if (!name) return res.status(400).json({ error: 'Name required' });
  const info = db.prepare('INSERT INTO projects (name, description) VALUES (?, ?)').run(name, description || '');
  // Creator becomes owner
  db.prepare('INSERT INTO project_members (project_id, user_id, role) VALUES (?, ?, ?)')
    .run(info.lastInsertRowid, req.user.id, 'owner');
  res.json({ project: { id: info.lastInsertRowid, name, description } });
});

router.get('/:id', authenticate, requireProjectRole('viewer', 'editor', 'owner'), (req, res) => {
  const project = db.prepare('SELECT * FROM projects WHERE id = ?').get(req.params.id);
  const members = db.prepare(`
    SELECT u.id, u.username, u.role AS user_role, pm.role AS project_role
    FROM project_members pm JOIN users u ON u.id = pm.user_id
    WHERE pm.project_id = ?
  `).all(req.params.id);
  const documents = db.prepare('SELECT id, title, type, current_version, updated_at FROM documents WHERE project_id = ? ORDER BY updated_at DESC')
    .all(req.params.id);
  res.json({ project, members, documents });
});

router.delete('/:id', authenticate, requireProjectRole('owner'), (req, res) => {
  db.prepare('DELETE FROM projects WHERE id = ?').run(req.params.id);
  res.json({ ok: true });
});

// Admin assigns members
router.post('/:id/members', authenticate, (req, res) => {
  const role = isProjectMember(req.user.id, req.params.id);
  if (req.user.role !== 'admin' && role !== 'owner') return res.status(403).json({ error: 'Only owner/admin' });
  const { user_id, role: memberRole } = req.body;
  if (!['viewer', 'editor', 'owner'].includes(memberRole)) return res.status(400).json({ error: 'Invalid role' });
  db.prepare(`
    INSERT INTO project_members (project_id, user_id, role) VALUES (?, ?, ?)
    ON CONFLICT(project_id, user_id) DO UPDATE SET role = excluded.role
  `).run(req.params.id, user_id, memberRole);
  res.json({ ok: true });
});

router.delete('/:id/members/:userId', authenticate, (req, res) => {
  const role = isProjectMember(req.user.id, req.params.id);
  if (req.user.role !== 'admin' && role !== 'owner') return res.status(403).json({ error: 'Only owner/admin' });
  db.prepare('DELETE FROM project_members WHERE project_id = ? AND user_id = ?')
    .run(req.params.id, req.params.userId);
  res.json({ ok: true });
});

module.exports = router;
```

## 9. `routes/documents.js` — Docs, Markdown, versioning, API generator

```javascript
const express = require('express');
const db = require('../database');
const { authenticate } = require('../middleware/auth');
const { generateApiDoc } = require('../services/apiDocGenerator');

const router = express.Router();

function canEdit(userId, projectId) {
  const u = db.prepare('SELECT role FROM users WHERE id = ?').get(userId);
  if (u && u.role === 'admin') return true;
  const m = db.prepare('SELECT role FROM project_members WHERE project_id = ? AND user_id = ?').get(projectId, userId);
  return m && (m.role === 'editor' || m.role === 'owner');
}

function canView(userId, projectId) {
  if (canEdit(userId, projectId)) return true;
  const m = db.prepare('SELECT role FROM project_members WHERE project_id = ? AND user_id = ?').get(projectId, userId);
  return !!m;
}

router.post('/project/:projectId', authenticate, (req, res) => {
  if (!canEdit(req.user.id, req.params.projectId)) return res.status(403).json({ error: 'No edit access' });
  const { title, type, content } = req.body;
  if (!title) return res.status(400).json({ error: 'Title required' });
  const info = db.prepare(`
    INSERT INTO documents (project_id, title, type, content, created_by)
    VALUES (?, ?, ?, ?, ?)
  `).run(req.params.projectId, title, type || 'spec', content || '', req.user.id);

  db.prepare(`
    INSERT INTO document_versions (document_id, version, content, change_note, created_by)
    VALUES (?, 1, ?, ?, ?)
  `).run(info.lastInsertRowid, content || '', 'Initial version', req.user.id);

  res.json({ document: { id: info.lastInsertRowid, title, type, version: 1 } });
});

router.get('/:id', authenticate, (req, res) => {
  const doc = db.prepare('SELECT * FROM documents WHERE id = ?').get(req.params.id);
  if (!doc) return res.status(404).json({ error: 'Not found' });
  if (!canView(req.user.id, doc.project_id)) return res.status(403).json({ error: 'No access' });
  const versions = db.prepare(`
    SELECT dv.id, dv.version, dv.change_note, dv.created_at, u.username
    FROM document_versions dv JOIN users u ON u.id = dv.created_by
    WHERE dv.document_id = ? ORDER BY dv.version DESC
  `).all(req.params.id);
  res.json({ document: doc, versions });
});

router.put('/:id', authenticate, (req, res) => {
  const doc = db.prepare('SELECT * FROM documents WHERE id = ?').get(req.params.id);
  if (!doc) return res.status(404).json({ error: 'Not found' });
  if (!canEdit(req.user.id, doc.project_id)) return res.status(403).json({ error: 'No edit access' });

  const { title, content, change_note } = req.body;
  const newVersion = doc.current_version + 1;

  const txn = db.transaction(() => {
    db.prepare(`
      UPDATE documents SET title = COALESCE(?, title), content = ?, current_version = ?, updated_at = CURRENT_TIMESTAMP
      WHERE id = ?
    `).run(title || null, content, newVersion, req.params.id);

    db.prepare(`
      INSERT INTO document_versions (document_id, version, content, change_note, created_by)
      VALUES (?, ?, ?, ?, ?)
    `).run(req.params.id, newVersion, content, change_note || '', req.user.id);
  });
  txn();

  res.json({ ok: true, version: newVersion });
});

router.get('/:id/version/:version', authenticate, (req, res) => {
  const v = db.prepare(`
    SELECT dv.*, u.username FROM document_versions dv
    JOIN users u ON u.id = dv.created_by
    WHERE dv.document_id = ? AND dv.version = ?
  `).get(req.params.id, req.params.version);
  if (!v) return res.status(404).json({ error: 'Version not found' });
  res.json({ version: v });
});

// Restore a previous version (creates a new version with old content)
router.post('/:id/restore/:version', authenticate, (req, res) => {
  const doc = db.prepare('SELECT * FROM documents WHERE id = ?').get(req.params.id);
  if (!doc) return res.status(404).json({ error: 'Not found' });
  if (!canEdit(req.user.id, doc.project_id)) return res.status(403).json({ error: 'No edit access' });

  const old = db.prepare('SELECT * FROM document_versions WHERE document_id = ? AND version = ?')
    .get(req.params.id, req.params.version);
  if (!old) return res.status(404).json({ error: 'Version not found' });

  const newVersion = doc.current_version + 1;
  const txn = db.transaction(() => {
    db.prepare('UPDATE documents SET content = ?, current_version = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?')
      .run(old.content, newVersion, req.params.id);
    db.prepare(`
      INSERT INTO document_versions (document_id, version, content, change_note, created_by)
      VALUES (?, ?, ?, ?, ?)
    `).run(req.params.id, newVersion, old.content, `Restored from v${req.params.version}`, req.user.id);
  });
  txn();
  res.json({ ok: true, version: newVersion });
});

router.delete('/:id', authenticate, (req, res) => {
  const doc = db.prepare('SELECT * FROM documents WHERE id = ?').get(req.params.id);
  if (!doc) return res.status(404).json({ error: 'Not found' });
  if (!canEdit(req.user.id, doc.project_id)) return res.status(403).json({ error: 'No edit access' });
  db.prepare('DELETE FROM documents WHERE id = ?').run(req.params.id);
  res.json({ ok: true });
});

// Auto-generate API documentation from YAML/JSON spec
router.post('/generate-api', authenticate, (req, res) => {
  try {
    const { spec, projectId, title } = req.body;
    if (!spec) return res.status(400).json({ error: 'spec required' });
    const markdown = generateApiDoc(spec);

    if (projectId) {
      if (!canEdit(req.user.id, projectId)) return res.status(403).json({ error: 'No edit access' });
      const info = db.prepare(`
        INSERT INTO documents (project_id, title, type, content, created_by)
        VALUES (?, ?, 'api', ?, ?)
      `).run(projectId, title || 'API Documentation', markdown, req.user.id);
      db.prepare(`
        INSERT INTO document_versions (document_id, version, content, change_note, created_by)
        VALUES (?, 1, ?, 'Auto-generated from API spec', ?)
      `).run(info.lastInsertRowid, markdown, req.user.id);
      return res.json({ markdown, documentId: info.lastInsertRowid });
    }
    res.json({ markdown });
  } catch (e) {
    res.status(400).json({ error: 'Invalid spec: ' + e.message });
  }
});

module.exports = router;
```

