### 2. 后端核心代码 (`main.py`)
后端提供了 RESTful API，包含用户查询接口和管理员鉴权接口。系统启动时会自动初始化 SQLite 数据库并生成 Mock 数据。

```python
import json
import os
from datetime import datetime
from enum import Enum
from typing import List, Optional

from fastapi import FastAPI, Depends, HTTPException, Query, Header, Request
from fastapi.responses import FileResponse
from pydantic import BaseModel, ConfigDict, Field
from sqlalchemy import create_engine, Column, Integer, String, Enum as SQLEnum, Text, ForeignKey, DateTime, Boolean
from sqlalchemy.orm import sessionmaker, Session, declarative_base, relationship

# ================= 数据库配置 =================
SQLALCHEMY_DATABASE_URL = "sqlite:///./lab_instruments.db"
engine = create_engine(SQLALCHEMY_DATABASE_URL, connect_args={"check_same_thread": False})
SessionLocal = sessionmaker(autocommit=False, autoflush=False, bind=engine)
Base = declarative_base()

# ================= 枚举与模型 =================
class InstrumentStatus(str, Enum):
    AVAILABLE = "available"
    OCCUPIED = "occupied"
    MAINTENANCE = "maintenance"

class Instrument(Base):
    __tablename__ = "instruments"
    id = Column(Integer, primary_key=True, index=True)
    name = Column(String, index=True, nullable=False)
    category = Column(String, index=True, nullable=False)
    model_number = Column(String, nullable=False)
    specs = Column(Text, nullable=False)  # 存储 JSON 格式的详细参数
    status = Column(SQLEnum(InstrumentStatus), default=InstrumentStatus.AVAILABLE)
    created_at = Column(DateTime, default=datetime.utcnow)

    maintenance_logs = relationship("MaintenanceLog", back_populates="instrument", cascade="all, delete-orphan")

class MaintenanceLog(Base):
    __tablename__ = "maintenance_logs"
    id = Column(Integer, primary_key=True, index=True)
    instrument_id = Column(Integer, ForeignKey("instruments.id"))
    issue_description = Column(Text, nullable=False)
    start_date = Column(DateTime, default=datetime.utcnow)
    end_date = Column(DateTime, nullable=True)
    is_resolved = Column(Boolean, default=False)

    instrument = relationship("Instrument", back_populates="maintenance_logs")

# ================= Pydantic Schemas =================
class MaintenanceLogResponse(BaseModel):
    model_config = ConfigDict(from_attributes=True)
    id: int
    issue_description: str
    start_date: datetime
    end_date: Optional[datetime]
    is_resolved: bool

class InstrumentResponse(BaseModel):
    model_config = ConfigDict(from_attributes=True)
    id: int
    name: str
    category: str
    model_number: str
    specs: dict
    status: InstrumentStatus
    created_at: datetime
    maintenance_logs: List[MaintenanceLogResponse] = []

class InstrumentCreate(BaseModel):
    name: str
    category: str
    model_number: str
    specs: dict
    status: InstrumentStatus = InstrumentStatus.AVAILABLE

class InstrumentUpdate(BaseModel):
    name: Optional[str] = None
    category: Optional[str] = None
    model_number: Optional[str] = None
    specs: Optional[dict] = None
    status: Optional[InstrumentStatus] = None

class MaintenanceCreate(BaseModel):
    issue_description: str

# ================= 依赖注入 =================
def get_db():
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()

ADMIN_TOKEN = "lab_admin_2024"  # 演示用管理员 Token

def verify_admin(x_admin_token: Optional[str] = Header(None)):
    if x_admin_token != ADMIN_TOKEN:
        raise HTTPException(status_code=401, detail="Invalid or missing admin token")
    return True

# ================= FastAPI 应用 =================
app = FastAPI(title="Laboratory Instrument Management System")

@app.on_event("startup")
def startup_event():
    Base.metadata.create_all(bind=engine)
    db = SessionLocal()
    if db.query(Instrument).count() == 0:
        # 初始化 Mock 数据
        mock_specs_1 = json.dumps({"Resolution": "0.1 nm", "Magnification": "Up to 1,000,000x", "Voltage": "200 kV"})
        mock_specs_2 = json.dumps({"Wavelength Range": "190-1100 nm", "Bandwidth": "0.5 nm", "Light Source": "Deuterium & Tungsten"})

        db.add_all([
            Instrument(name="Transmission Electron Microscope", category="Microscopy", model_number="TEM-2024X", specs=mock_specs_1, status=InstrumentStatus.AVAILABLE),
            Instrument(name="UV-Vis Spectrophotometer", category="Spectroscopy", model_number="UV-3600", specs=mock_specs_2, status=InstrumentStatus.OCCUPIED),
            Instrument(name="Centrifuge", category="Separation", model_number="CF-500", specs=json.dumps({"Max Speed": "15000 rpm", "Capacity": "500 mL"}), status=InstrumentStatus.MAINTENANCE)
        ])
        db.commit()
    db.close()

@app.get("/")
def read_index():
    return FileResponse("index.html")

# --- 公共接口 ---
@app.get("/api/instruments", response_model=List[InstrumentResponse])
def search_instruments(
    search: Optional[str] = Query(None, description="Search by name or category"),
    status: Optional[InstrumentStatus] = Query(None),
    db: Session = Depends(get_db)
):
    query = db.query(Instrument)
    if search:
        query = query.filter(
            (Instrument.name.ilike(f"%{search}%")) | 
            (Instrument.category.ilike(f"%{search}%"))
        )
    if status:
        query = query.filter(Instrument.status == status)

    instruments = query.all()
    # 解析 JSON specs
    for inst in instruments:
        if isinstance(inst.specs, str):
            inst.specs = json.loads(inst.specs)
    return instruments

@app.get("/api/instruments/{instrument_id}", response_model=InstrumentResponse)
def get_instrument(instrument_id: int, db: Session = Depends(get_db)):
    inst = db.query(Instrument).filter(Instrument.id == instrument_id).first()
    if not inst:
        raise HTTPException(status_code=404, detail="Instrument not found")
    if isinstance(inst.specs, str):
        inst.specs = json.loads(inst.specs)
    return inst

# --- 管理员接口 ---
@app.post("/api/instruments", response_model=InstrumentResponse, dependencies=[Depends(verify_admin)])
def create_instrument(payload: InstrumentCreate, db: Session = Depends(get_db)):
    new_inst = Instrument(
        name=payload.name,
        category=payload.category,
        model_number=payload.model_number,
        specs=json.dumps(payload.specs),
        status=payload.status
    )
    db.add(new_inst)
    db.commit()
    db.refresh(new_inst)
    new_inst.specs = json.loads(new_inst.specs)
    return new_inst

@app.put("/api/instruments/{instrument_id}", response_model=InstrumentResponse, dependencies=[Depends(verify_admin)])
def update_instrument(instrument_id: int, payload: InstrumentUpdate, db: Session = Depends(get_db)):
    inst = db.query(Instrument).filter(Instrument.id == instrument_id).first()
    if not inst:
        raise HTTPException(status_code=404, detail="Instrument not found")

    update_data = payload.model_dump(exclude_unset=True)
    if "specs" in update_data:
        update_data["specs"] = json.dumps(update_data["specs"])

    for key, value in update_data.items():
        setattr(inst, key, value)

    db.commit()
    db.refresh(inst)
    if isinstance(inst.specs, str):
        inst.specs = json.loads(inst.specs)
    return inst

@app.post("/api/instruments/{instrument_id}/maintenance", response_model=MaintenanceLogResponse, dependencies=[Depends(verify_admin)])
def add_maintenance(instrument_id: int, payload: MaintenanceCreate, db: Session = Depends(get_db)):
    inst = db.query(Instrument).filter(Instrument.id == instrument_id).first()
    if not inst:
        raise HTTPException(status_code=404, detail="Instrument not found")

    log = MaintenanceLog(instrument_id=instrument_id, issue_description=payload.issue_description)
    inst.status = InstrumentStatus.MAINTENANCE  # 自动更改状态为维护中
    db.add(log)
    db.commit()
    db.refresh(log)
    return log

@app.put("/api/maintenance/{log_id}/resolve", response_model=MaintenanceLogResponse, dependencies=[Depends(verify_admin)])
def resolve_maintenance(log_id: int, db: Session = Depends(get_db)):
    log = db.query(MaintenanceLog).filter(MaintenanceLog.id == log_id).first()
    if not log:
        raise HTTPException(status_code=404, detail="Log not found")

    log.is_resolved = True
    log.end_date = datetime.utcnow()

    # 检查是否还有其他未解决的维护记录，如果没有，则恢复为可用状态
    unresolved = db.query(MaintenanceLog).filter(
        MaintenanceLog.instrument_id == log.instrument_id,
        MaintenanceLog.is_resolved == False,
        MaintenanceLog.id != log_id
    ).count()

    if unresolved == 0:
        inst = db.query(Instrument).filter(Instrument.id == log.instrument_id).first()
        inst.status = InstrumentStatus.AVAILABLE

    db.commit()
    db.refresh(log)
    return log

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=8000)
```

