    <input type="file" id="fileInput" accept="video/*" />
    <button id="sampleBtn">🎞️ Use Sample</button>
    <button id="importBtn">📥 Import Project</button>
    <input type="file" id="importInput" accept="application/json" />
    <button id="exportBtn" class="primary">💾 Export Project</button>
  </div>
</header>

<main>
  <section class="left">
    <div class="video-wrap">
      <video id="video" crossorigin="anonymous" playsinline></video>
      <div class="placeholder" id="placeholder">
        <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5">
          <rect x="2" y="5" width="20" height="14" rx="2"/>
          <path d="M10 9l5 3-5 3V9z" fill="currentColor"/>
        </svg>
        <div>Load a video to begin</div>
      </div>
    </div>

    <div class="timeline-panel">
      <div class="time-row">
        <span id="curTime">00:00.000</span>
        <span id="durTime">00:00.000</span>
      </div>
      <div class="timeline" id="timeline">
        <div class="progress" id="progress"></div>
        <div class="playhead" id="playhead" style="left:0"></div>
      </div>
      <div class="controls-row">
        <button id="playBtn">▶ Play</button>
        <button id="backBtn" title="Previous bookmark">⏮ Prev</button>
        <button id="fwdBtn" title="Next bookmark">Next ⏭</button>
        <span class="spacer"></span>
        <button id="addBtn" class="primary">＋ Add Bookmark <span class="kbd">M</span></button>
        <button id="clearBtn" class="danger">🗑 Clear All</button>
      </div>
    </div>
  </section>

  <aside class="right">
    <div class="right-header">
      <h2>Bookmarks</h2>
      <span class="count" id="count">0</span>
    </div>
    <div class="bookmark-list" id="bookmarkList">
      <div class="empty" id="emptyState">
        <svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5">
          <path d="M19 21l-7-5-7 5V5a2 2 0 012-2h10a2 2 0 012 2z"/>
        </svg>
        <div>No bookmarks yet.<br/>Press <span class="kbd">M</span> or click "Add Bookmark".</div>
      </div>
    </div>
  </aside>
</main>

<div class="toast" id="toast"></div>

<script>
(() => {
  const video = document.getElementById('video');
  const placeholder = document.getElementById('placeholder');
  const timeline = document.getElementById('timeline');
  const progress = document.getElementById('progress');
  const playhead = document.getElementById('playhead');
  const curTimeEl = document.getElementById('curTime');
  const durTimeEl = document.getElementById('durTime');
  const playBtn = document.getElementById('playBtn');
  const addBtn = document.getElementById('addBtn');
  const backBtn = document.getElementById('backBtn');
  const fwdBtn = document.getElementById('fwdBtn');
  const clearBtn = document.getElementById('clearBtn');
  const exportBtn = document.getElementById('exportBtn');
  const importBtn = document.getElementById('importBtn');
  const importInput = document.getElementById('importInput');
  const fileInput = document.getElementById('fileInput');
  const sampleBtn = document.getElementById('sampleBtn');
  const listEl = document.getElementById('bookmarkList');
  const emptyState = document.getElementById('emptyState');
  const countEl = document.getElementById('count');
  const toastEl = document.getElementById('toast');

  const SAMPLE_URL = 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/BigBuckBunny.mp4';

  let bookmarks = []; // { id, time, note, thumbnail (dataURL) }
  let activeId = null;
  let videoLoaded = false;
  let currentVideoName = 'untitled';

  // ---------- Utilities ----------
  function fmtTime(sec) {
    if (!isFinite(sec) || sec < 0) sec = 0;
    const h = Math.floor(sec / 3600);
    const m = Math.floor((sec % 3600) / 60);
    const s = Math.floor(sec % 60);
    const ms = Math.floor((sec - Math.floor(sec)) * 1000);
    const pad = n => String(n).padStart(2, '0');
    return h > 0
      ? `${h}:${pad(m)}:${pad(s)}.${String(ms).padStart(3,'0')}`
      : `${pad(m)}:${pad(s)}.${String(ms).padStart(3,'0')}`;
  }
  function uid() { return 'bm_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 7); }
  function toast(msg, type='') {
    toastEl.textContent = msg;
    toastEl.className = 'toast show ' + type;
    clearTimeout(toast._t);
    toast._t = setTimeout(() => toastEl.className = 'toast ' + type, 2200);
  }

  // ---------- Video loading ----------
  function loadVideo(src, name='video') {
    video.src = src;
    currentVideoName = name;
    video.load();
    placeholder.style.display = 'none';
    videoLoaded = false;
  }
  video.addEventListener('loadedmetadata', () => {
    videoLoaded = true;
    durTimeEl.textContent = fmtTime(video.duration);
    renderMarkers();
    toast('Video loaded: ' + currentVideoName, 'ok');
  });
  video.addEventListener('error', () => {
    toast('Failed to load video', 'err');
  });

  fileInput.addEventListener('change', e => {
    const f = e.target.files[0];
    if (!f) return;
    const url = URL.createObjectURL(f);
    loadVideo(url, f.name);
  });
  sampleBtn.addEventListener('click', () => loadVideo(SAMPLE_URL, 'BigBuckBunny.mp4'));

  // ---------- Playback ----------
  video.addEventListener('play', () => playBtn.textContent = '⏸ Pause');
  video.addEventListener('pause', () => playBtn.textContent = '▶ Play');
  playBtn.addEventListener('click', () => {
    if (!videoLoaded) return toast('Load a video first', 'err');
    if (video.paused) video.play(); else video.pause();
  });

  video.addEventListener('timeupdate', updatePlayhead);
  function updatePlayhead() {
    if (!video.duration) return;
    const pct = (video.currentTime / video.duration) * 100;
    playhead.style.left = pct + '%';
    progress.style.width = pct + '%';
    curTimeEl.textContent = fmtTime(video.currentTime);
  }

  timeline.addEventListener('click', e => {
    if (!videoLoaded) return;
    const rect = timeline.getBoundingClientRect();
    const pct = (e.clientX - rect.left) / rect.width;
    video.currentTime = Math.max(0, Math.min(video.duration, pct * video.duration));
  });

  // ---------- Thumbnail capture ----------
  async function captureThumbnail(time) {
    return new Promise((resolve) => {
      const wasPaused = video.paused;
      const originalTime = video.currentTime;
      const canvas = document.createElement('canvas');

      const onSeeked = () => {
        video.removeEventListener('seeked', onSeeked);
        canvas.width = video.videoWidth || 320;
        canvas.height = video.videoHeight || 180;
        const ctx = canvas.getContext('2d');
        try {
          ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
          const dataUrl = canvas.toDataURL('image/jpeg', 0.7);
          // restore
          video.currentTime = originalTime;
          resolve(dataUrl);
        } catch (err) {
          // CORS or tainted canvas
          video.currentTime = originalTime;
          resolve(null);
        }
      };
      video.addEventListener('seeked', onSeeked);
      video.currentTime = time;
    });
  }

  // ---------- Bookmarks ----------
  async function addBookmark() {
    if (!videoLoaded) return toast('Load a video first', 'err');
    const time = video.currentTime;
    toast('Capturing thumbnail…');
    const thumb = await captureThumbnail(time);
    const bm = {
      id: uid(),
      time,
      note: `Bookmark at ${fmtTime(time)}`,
      thumbnail: thumb
    };
    bookmarks.push(bm);
    bookmarks.sort((a,b) => a.time - b.time);
    activeId = bm.id;
    renderAll();
    toast('Bookmark added', 'ok');
  }
  addBtn.addEventListener('click', addBookmark);

  function deleteBookmark(id) {
    bookmarks = bookmarks.filter(b => b.id !== id);
    if (activeId === id) activeId = null;
    renderAll();
  }

  function jumpTo(id) {
    const bm = bookmarks.find(b => b.id === id);
    if (!bm) return;
    activeId = id;
    video.currentTime = bm.time;
    renderAll();
  }

  function navigate(dir) {
    if (!bookmarks.length) return toast('No bookmarks', 'err');
    if (!videoLoaded) return;
    const cur = video.currentTime;
    let target = null;
    if (dir > 0) {
      target = bookmarks.find(b => b.time > cur + 0.05);
      if (!target) target = bookmarks[0];
    } else {
      for (let i = bookmarks.length - 1; i >= 0; i--) {
        if (bookmarks[i].time < cur - 0.05) { target = bookmarks[i]; break; }
      }
      if (!target) target = bookmarks[bookmarks.length - 1];
    }
    jumpTo(target.id);
  }
  backBtn.addEventListener('click', () => navigate(-1));
  fwdBtn.addEventListener('click', () => navigate(1));

  clearBtn.addEventListener('click', () => {
    if (!bookmarks.length) return;
    if (confirm('Delete all bookmarks?')) {
      bookmarks = []; activeId = null; renderAll();
      toast('All bookmarks cleared');
    }
  });

  // ---------- Rendering ----------
  function renderAll() {
    renderMarkers();
    renderList();
    countEl.textContent = bookmarks.length;
  }

  function renderMarkers() {
    // remove existing markers
    timeline.querySelectorAll('.marker').forEach(m => m.remove());
    if (!video.duration) return;
    bookmarks.forEach(bm => {
      const m = document.createElement('div');
      m.className = 'marker' + (bm.id === activeId ? ' active' : '');
      m.style.left = (bm.time / video.duration * 100) + '%';
      const tip = document.createElement('div');
      tip.className = 'tip';
      tip.textContent = fmtTime(bm.time);
      m.appendChild(tip);
      m.addEventListener('click', e => {
        e.stopPropagation();
        jumpTo(bm.id);
      });
      timeline.appendChild(m);
    });
  }

  function renderList() {
    listEl.querySelectorAll('.bookmark').forEach(el => el.remove());
    if (!bookmarks.length) {
      emptyState.style.display = 'block';
      return;
    }
    emptyState.style.display = 'none';
    bookmarks.forEach((bm, idx) => {
      const card = document.createElement('div');
      card.className = 'bookmark' + (bm.id === activeId ? ' active' : '');
      card.innerHTML = `
        <div class="bm-top">
          ${bm.thumbnail
            ? `<img class="bm-thumb" src="${bm.thumbnail}" alt="thumb"/>`
            : `<div class="bm-thumb" style="display:flex;align-items:center;justify-content:center;color:var(--muted);font-size:11px;">No thumb</div>`}
          <div class="bm-meta">
            <div>
              <span class="bm-time">${fmtTime(bm.time)}</span>
              <span class="bm-index">#${idx + 1}</span>
            </div>
            <textarea class="bm-note" placeholder="Add a note…">${escapeHtml(bm.note || '')}</textarea>
          </div>
        </div>
        <div class="bm-actions">
          <button data-act="jump">▶ Go to</button>
          <button data-act="retake">📷 Retake</button>
          <button data-act="del" class="danger">🗑 Delete</button>
        </div>
      `;
      // events
      card.querySelector('.bm-time').addEventListener('click', () => jumpTo(bm.id));
      const thumbEl = card.querySelector('.bm-thumb');
      if (thumbEl && thumbEl.tagName === 'IMG') thumbEl.addEventListener('click', () => jumpTo(bm.id));
      card.querySelector('.bm-note').addEventListener('input', e => {
        bm.note = e.target.value;
      });
      card.querySelectorAll('.bm-actions button').forEach(btn => {
        btn.addEventListener('click', async () => {
          const act = btn.dataset.act;
          if (act === 'jump') jumpTo(bm.id);
          else if (act === 'del') deleteBookmark(bm.id);
          else if (act === 'retake') {
            if (!videoLoaded) return toast('Load a video first', 'err');
            toast('Retaking thumbnail…');
            const t = await captureThumbnail(bm.time);
            if (t) { bm.thumbnail = t; renderAll(); toast('Thumbnail updated', 'ok'); }
            else toast('Could not capture (CORS?)', 'err');
          }
        });
      });
      listEl.appendChild(card);
    });
  }

  function escapeHtml(s) {
    return (s || '').replace(/[&<>"']/g, c => ({
      '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'
    }[c]));
  }

  // ---------- Export / Import ----------
  exportBtn.addEventListener('click', () => {
    if (!bookmarks.length) return toast('No bookmarks to export', 'err');
    const project = {
      version: 1,
      exportedAt: new Date().toISOString(),
      video: {
        name: currentVideoName,
        duration: video.duration || null,
        source: video.src.startsWith('blob:') ? '(local file)' : video.src
      },
      bookmarks: bookmarks.map((b, i) => ({
        index: i + 1,
        id: b.id,
        time: b.time,
        timeFormatted: fmtTime(b.time),
        note: b.note,
        thumbnail: b.thumbnail
      }))
    };
    const blob = new Blob([JSON.stringify(project, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = (currentVideoName.replace(/\.[^.]+$/, '') || 'project') + '.vmarks.json';
    document.body.appendChild(a); a.click(); a.remove();
    URL.revokeObjectURL(url);
    toast('Project exported', 'ok');
  });

  importBtn.addEventListener('click', () => importInput.click());
  importInput.addEventListener('change', async e => {
    const f = e.target.files[0];
    if (!f) return;
    try {
      const text = await f.text();
      const data = JSON.parse(text);
      if (!data.bookmarks || !Array.isArray(data.bookmarks)) throw new Error('Invalid project file');
      bookmarks = data.bookmarks.map(b => ({
        id: b.id || uid(),
        time: Number(b.time),
        note: b.note || '',
        thumbnail: b.thumbnail || null
      })).filter(b => isFinite(b.time)).sort((a,b) => a.time - b.time);
      activeId = null;
      renderAll();
      toast(`Imported ${bookmarks.length} bookmarks`, 'ok');
    } catch (err) {
      toast('Import failed: ' + err.message, 'err');
    }
    importInput.value = '';
  });

  // ---------- Keyboard shortcuts ----------
  document.addEventListener('keydown', e => {
    if (e.target.tagName === 'TEXTAREA' || e.target.tagName === 'INPUT') return;
    if (e.key === 'm' || e.key === 'M') { e.preventDefault(); addBookmark(); }
    else if (e.key === ' ') { e.preventDefault(); playBtn.click(); }
    else if (e.key === 'ArrowLeft') { video.currentTime = Math.max(0, video.currentTime - 5); }
    else if (e.key === 'ArrowRight') { video.currentTime = Math.min(video.duration || 0, video.currentTime + 5); }
    else if (e.key === '[') { navigate(-1); }
    else if (e.key === ']') { navigate(1); }
  });

  // initial render
  renderAll();
})();
</script>
</body>
</html>
```

## Features Overview

| Feature | How to use |
|---|---|
| **Load video** | Click **📁 Load Video** (local file) or **🎞️ Use Sample** (Big Buck Bunny) |
| **Add bookmark** | Click **＋ Add Bookmark** or press **`M`** — captures current frame as thumbnail |
| **Timeline markers** | Colored dots on the timeline; hover for timestamp, click to jump |
| **Edit notes** | Each bookmark card has an editable textarea |
| **Navigate** | **⏮ Prev / Next ⏭** buttons, or press **`[` / `]`** |
| **Retake thumbnail** | Per-bookmark **📷 Retake** button re-captures the frame |
| **Export project** | **💾 Export Project** downloads a `.vmarks.json` file with all bookmarks, notes, and base64 thumbnails |
| **Import project** | **📥 Import Project** restores bookmarks from a previously exported JSON |

## Keyboard Shortcuts

- **`Space`** — Play / Pause
- **`M`** — Add bookmark at current time
- **`←` / `→`** — Seek ±5 seconds
- **`[` / `]`** — Jump to previous / next bookmark

## Exported Project File Format

```json
{
  "version": 1,
  "exportedAt": "2025-01-15T10:30:00.000Z",
  "video": { "name": "clip.mp4", "duration": 124.5, "source": "..." },
  "bookmarks": [
    {
      "index": 1,
      "id": "bm_...",
      "time": 12.345,
      "timeFormatted": "00:12.345",
      "note": "Key scene begins",
      "thumbnail": "data:image/jpeg;base64,..."
    }
  ]
}
```

## Notes

- Thumbnails are captured via an offscreen `<canvas>` drawing the current video frame. For remote videos, the server must send proper CORS headers (`Access-Control-Allow-Origin`), otherwise the canvas becomes tainted and the thumbnail will be blank — the **Retake** button lets you retry after loading a local copy.
- The project JSON is fully self-contained: thumbnails are embedded as base64 data URLs, so the file can be shared or archived independently of the original video.

