### 2. Backend Implementation (`server.js`)

Create `server.js` in the root directory. This server handles chunk receiving, temporary storage, and final file merging.

```javascript
const express = require('express');
const multer = require('multer');
const cors = require('cors');
const path = require('path');
const fs = require('fs-extra');

const app = express();
app.use(cors());
app.use(express.json());
app.use(express.static('public')); // Serve frontend

// Ensure base directories exist
const TEMP_DIR = path.join(__dirname, 'temp');
const FILE_DIR = path.join(__dirname, 'file');
fs.ensureDirSync(TEMP_DIR);
fs.ensureDirSync(FILE_DIR);

// Multer configuration for dynamic chunk storage
const storage = multer.diskStorage({
    destination: (req, file, cb) => {
        const hash = req.body.hash;
        const chunkDir = path.join(TEMP_DIR, hash);
        fs.ensureDirSync(chunkDir);
        cb(null, chunkDir);
    },
    filename: (req, file, cb) => {
        // Use the chunk index as the filename
        cb(null, req.body.index);
    }
});
const upload = multer({ storage });

/**
 * @route POST /upload-chunk
 * @desc Receive a single file chunk
 */
app.post('/upload-chunk', upload.single('chunk'), (req, res) => {
    try {
        if (!req.file) {
            return res.status(400).json({ error: 'Chunk file is missing' });
        }
        res.json({ success: true, message: `Chunk ${req.body.index} uploaded` });
    } catch (error) {
        res.status(500).json({ error: 'Server error during chunk upload' });
    }
});

/**
 * @route POST /merge-chunks
 * @desc Merge chunks into the final file
 */
app.post('/merge-chunks', async (req, res) => {
    const { hash, filename, totalChunks } = req.body;
    const chunkDir = path.join(TEMP_DIR, hash);
    const filePath = path.join(FILE_DIR, filename);

    try {
        // Verify all chunks exist
        for (let i = 0; i < totalChunks; i++) {
            const chunkPath = path.join(chunkDir, `${i}`);
            if (!await fs.pathExists(chunkPath)) {
                return res.status(400).json({ error: `Missing chunk ${i}` });
            }
        }

        // Merge chunks sequentially using streams/promises to avoid high memory usage
        const writeStream = fs.createWriteStream(filePath);

        for (let i = 0; i < totalChunks; i++) {
            const chunkPath = path.join(chunkDir, `${i}`);
            const data = await fs.readFile(chunkPath);
            writeStream.write(data);
        }

        writeStream.end();

        writeStream.on('finish', async () => {
            // Cleanup temporary chunk directory
            await fs.remove(chunkDir);
            res.json({ success: true, message: 'File merged successfully', path: filePath });
        });

        writeStream.on('error', (err) => {
            res.status(500).json({ error: 'Error merging file' });
        });

    } catch (error) {
        res.status(500).json({ error: 'Server error during merge' });
    }
});

/**
 * @route GET /verify
 * @desc Check if file or chunks already exist (for quick upload / resume)
 */
app.get('/verify', async (req, res) => {
    const { hash, filename } = req.query;
    const filePath = path.join(FILE_DIR, filename);

    // 1. Check if file already exists (Quick Upload / 秒传)
    if (await fs.pathExists(filePath)) {
        return res.json({ shouldUpload: false, message: 'File already exists' });
    }

    // 2. Check existing chunks (Resume Upload / 断点续传)
    const chunkDir = path.join(TEMP_DIR, hash);
    let uploadedChunks = [];
    if (await fs.pathExists(chunkDir)) {
        const files = await fs.readdir(chunkDir);
        uploadedChunks = files.map(f => parseInt(f, 10));
    }

    res.json({ shouldUpload: true, uploadedChunks });
});

const PORT = 3000;
app.listen(PORT, () => {
    console.log(`Server running on http://localhost:${PORT}`);
});
```

### 3. Frontend Implementation (`public/index.html`)

Create `index.html` inside the `public` folder. This interface calculates the file MD5 hash, slices the file, manages concurrent uploads, and displays a progress bar.

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Chunk Upload Demo</title>
    <!-- SparkMD5 for calculating file hash -->
    <script src="https://cdnjs.cloudflare.com/ajax/libs/spark-md5/3.0.2/spark-md5.min.js"></script>
    <style>
        body { font-family: Arial, sans-serif; max-width: 600px; margin: 50px auto; padding: 20px; border: 1px solid #ccc; border-radius: 8px; }
        .progress-container { width: 100%; background-color: #f3f3f3; border-radius: 5px; margin-top: 20px; display: none; }
        .progress-bar { width: 0%; height: 30px; background-color: #4caf50; text-align: center; line-height: 30px; color: white; border-radius: 5px; transition: width 0.2s; }
        button { padding: 10px 15px; background-color: #007bff; color: white; border: none; border-radius: 4px; cursor: pointer; margin-top: 10px; }
        button:disabled { background-color: #cccccc; cursor: not-allowed; }
        #status { margin-top: 15px; color: #555; font-weight: bold; }
    </style>
</head>
<body>
    <h2>Chunk File Uploader</h2>
    <input type="file" id="fileInput" />
    <button id="uploadBtn" onclick="startUpload()">Upload</button>

    <div class="progress-container" id="progressContainer">
        <div class="progress-bar" id="progressBar">0%</div>
    </div>
    <div id="status"></div>

    <script>
        const CHUNK_SIZE = 2 * 1024 * 1024; // 2MB per chunk
        const CONCURRENT_LIMIT = 3; // Max concurrent requests

        async function calculateHash(file) {
            return new Promise((resolve) => {
                const blobSlice = File.prototype.slice;
                const chunks = Math.ceil(file.size / CHUNK_SIZE);
                let currentChunk = 0;
                const spark = new SparkMD5.ArrayBuffer();
                const reader = new FileReader();

                reader.onload = (e) => {
                    spark.append(e.target.result);
                    currentChunk++;
                    if (currentChunk < chunks) {
                        loadNext();
                    } else {
                        resolve(spark.end());
                    }
                };

                function loadNext() {
                    const start = currentChunk * CHUNK_SIZE;
                    const end = Math.min(start + CHUNK_SIZE, file.size);
                    reader.readAsArrayBuffer(blobSlice.call(file, start, end));
                }
                loadNext();
            });
        }

        async function startUpload() {
            const fileInput = document.getElementById('fileInput');
            const file = fileInput.files[0];
            if (!file) return alert('Please select a file');

            const uploadBtn = document.getElementById('uploadBtn');
            const status = document.getElementById('status');
            const progressContainer = document.getElementById('progressContainer');
            const progressBar = document.getElementById('progressBar');

            uploadBtn.disabled = true;
            status.innerText = 'Calculating file hash...';
            progressContainer.style.display = 'block';

            // 1. Calculate Hash
            const hash = await calculateHash(file);
            const filename = file.name;
            const totalChunks = Math.ceil(file.size / CHUNK_SIZE);

            // 2. Verify with server (Quick upload / Resume)
            status.innerText = 'Verifying file status...';
            const verifyRes = await fetch(`/verify?hash=${hash}&filename=${encodeURIComponent(filename)}`);
            const verifyData = await verifyRes.json();

            if (!verifyData.shouldUpload) {
                status.innerText = 'File already exists on server (Quick Upload Success)!';
                progressBar.style.width = '100%';
                progressBar.innerText = '100%';
                uploadBtn.disabled = false;
                return;
            }

            const uploadedChunks = verifyData.uploadedChunks || [];

            // 3. Create Chunks and Filter out already uploaded ones
            const tasks = [];
            for (let i = 0; i < totalChunks; i++) {
                if (uploadedChunks.includes(i)) continue; // Skip uploaded chunks

                const start = i * CHUNK_SIZE;
                const end = Math.min(start + CHUNK_SIZE, file.size);
                const chunk = file.slice(start, end);

                tasks.push({ index: i, chunk });
            }

            // 4. Upload Chunks with Concurrency Control
            status.innerText = 'Uploading chunks...';
            let uploadedCount = uploadedChunks.length;
            const updateProgress = () => {
                const percent = Math.round((uploadedCount / totalChunks) * 100);
                progressBar.style.width = `${percent}%`;
                progressBar.innerText = `${percent}%`;
            };
            updateProgress();

            await asyncPool(CONCURRENT_LIMIT, tasks, async (task) => {
                const formData = new FormData();
                formData.append('hash', hash);
                formData.append('index', task.index);
                formData.append('chunk', task.chunk);

                await fetch('/upload-chunk', { method: 'POST', body: formData });
                uploadedCount++;
                updateProgress();
            });

            // 5. Merge Chunks
            status.innerText = 'Merging file on server...';
            const mergeRes = await fetch('/merge-chunks', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ hash, filename, totalChunks })
            });

            const mergeData = await mergeRes.json();
            if (mergeData.success) {
                status.innerText = 'Upload and Merge Successful!';
                progressBar.style.backgroundColor = '#4caf50';
            } else {
                status.innerText = 'Error merging file.';
                progressBar.style.backgroundColor = '#f44336';
            }

            uploadBtn.disabled = false;
        }

        // Concurrency control utility
        async function asyncPool(poolLimit, array, iteratorFn) {
            const ret = [];
            const executing = [];
            for (const item of array) {
                const p = Promise.resolve().then(() => iteratorFn(item));
                ret.push(p);
                if (poolLimit <= array.length) {
                    const e = p.then(() => executing.splice(executing.indexOf(e), 1));
                    executing.push(e);
                    if (executing.length >= poolLimit) {
                        await Promise.race(executing);
                    }
                }
            }
            return Promise.all(ret);
        }
    </script>
</body>
</html>
```

### 4. How to Run and Test

1. Start the Node.js server:
   ```bash
   node server.js
   ```
2. Open your browser and navigate to: `http://localhost:3000`
3. Select a large file (e.g., a video or a large ZIP file > 5MB) to observe the chunking and progress bar in action.
4. Once completed, you will find the fully merged file inside the `./file` directory in your project root.

### Professional Highlights of this Implementation:
1. **MD5 Hashing (SparkMD5)**: Generates a unique identifier for the file based on its content. This enables **Quick Upload (秒传)** (skipping upload if the file already exists) and **Resume Upload (断点续传)** (skipping chunks that were already successfully uploaded).
2. **Concurrency Control (`asyncPool`)**: Browsers limit concurrent HTTP requests to the same domain (usually 6). The frontend uses a custom Promise pool to limit concurrent uploads to `3`, preventing browser queue blocking and server overload.
3. **Stream/Buffer Merging**: The backend reads chunks sequentially and writes them to a `WriteStream`. This prevents Node.js from loading the entire file into RAM, avoiding `Out Of Memory (OOM)` crashes when merging large files (e.g., 2GB+).
4. **Automatic Cleanup**: The `fs-extra` library automatically removes the temporary `temp/{hash}` directory once the file is successfully merged into the `file` directory.

